INSERT INTO `etsy_handmade_raw` VALUES (1, '5000000000', 'Handcrafted Aurora Moonstone Pendant Necklace', '[\"Jewelry\",\"Necklaces\",\"Pendant Necklaces\"]', '55.07', 'USD', 'Delicate handcrafted pendant necklace featuring genuine aurora moonstone set in sterling silver. Wire-wrapped by hand, each piece is unique. Chain length 18 inches with lobster clasp. Comes in a kraft gift box.', '[\"Made to order 3-5 business days\",\"Free USPS First Class shipping\",\"Returns accepted within 30 days\",\"Ships from Asheville, NC\"]', 'https://www.etsy.com/listing/5000000000/handcrafted-aurora-moonstone-pendant-necklace?ref=search_grid', 'ClayCottageStudio', '2026-05-25 22:39:58');
INSERT INTO `etsy_handmade_raw` VALUES (2, '5000000001', 'Custom Name Twilight Gold-Fill Necklace', '[\"Jewelry\",\"Necklaces\",\"Pendant Necklaces\"]', '50.01', 'USD', 'Personalized twilight name necklace hand-stamped on 14k gold-filled disc. Choose font and chain length (16\", 18\", 20\"). Perfect birthday or anniversary gift. Tarnish resistant.', '[\"In stock ships within 1-2 days\",\"Flat rate shipping $3.99\",\"Exchanges only on unused items\",\"Ships from Portland, ME\"]', 'https://www.etsy.com/listing/5000000001/custom-name-twilight-gold-fill-necklace?ref=search_grid', 'WildHoneyHandmade', '2026-05-25 22:39:58');
INSERT INTO `etsy_handmade_raw` VALUES (3, '5000000002', 'Vintage-Style Heather Locket Necklace', '[\"Jewelry\",\"Necklaces\",\"Lockets\"]', '56.09', 'USD', 'Antique-inspired heather brass locket necklace. Opens to hold two small photos. Intricately engraved exterior. Hangs on 24-inch brass chain. Includes velvet pouch.', '[\"Handmade to order 5-7 days\",\"Free shipping on orders over $40\",\"No returns on personalized items\",\"Ships from Santa Fe, NM\"]', 'https://www.etsy.com/listing/5000000002/vintage-style-heather-locket-necklace?ref=search_grid', 'ThePotteryBarn', '2026-05-25 22:39:58');
