INSERT INTO `etsy_sample_raw` VALUES (207, 'https://www.etsy.com/listing/212898205/custom-metal-race-track-art-handmade-in?click_key=f09193af4a457f45a73c82c3decb89461ac65e63%3A212898205&click_sum=02064d97&ga_order=most_relevant&ga_search_type=all&ga_view_type=gallery&ga_search_query=duracell&ref=search_grid-140082-4-2&pro=1&frs=1&bes=1&sts=1&content_source=069046fae64d46d7dcdb36758365fa32064398ce%253A212898205&variation0=607292070&variation1=2782678063', '212898205', 'Custom Metal Race Track Art - Handmade in US, Magnetic Mounts, Local Tracks and Circuits, Man Cave, Sculpture, Ornamental, Wall Decoration', '4.9', '1556', '39', '58', '20', '46.4', 'USD', '[\"https://i.etsystatic.com/10324360/r/il/3ea538/6510692201/il_fullxfull.6510692201_f8a0.jpg\",\"https://i.etsystatic.com/10324360/r/il/e81f94/6006883401/il_fullxfull.6006883401_1q4o.jpg\",\"https://i.etsystatic.com/10324360/r/il/7a29bf/5435098109/il_fullxfull.5435098109_m6kl.jpg\",\"https://i.etsystatic.com/10324360/r/il/370498/5386942904/il_fullxfull.5386942904_qgvl.jpg\",\"https://i.etsystatic.com/10324360/r/il/b26e76/5386942922/il_fullxfull.5386942922_gpcu.jpg\",\"https://i.etsystatic.com/10324360/r/il/7fe1bb/6006875221/il_fullxfull.6006875221_fde0.jpg\",\"https://i.etsystatic.com/10324360/r/il/ed2496/5386942752/il_fullxfull.5386942752_l6wk.jpg\",\"https://i.etsystatic.com/10324360/r/il/98d02a/5386942880/il_fullxfull.5386942880_2bde.jpg\",\"https://i.etsystatic.com/10324360/r/il/6ff922/5435098029/il_fullxfull.5435098029_c7pp.jpg\",\"https://i.etsystatic.com/10324360/r/il/858e17/5958801406/il_fullxfull.5958801406_t3fb.jpg\"]', '[{\"name\":\"Home & Living\",\"url\":\"https://www.etsy.com/c/home-and-living?explicit=1&ref=breadcrumb_listing\"},{\"name\":\"Home Decor\",\"url\":\"https://www.etsy.com/c/home-and-living/home-decor?explicit=1&ref=breadcrumb_listing\"},{\"name\":\"Wall Decor\",\"url\":\"https://www.etsy.com/c/home-and-living/home-decor/wall-decor?explicit=1&ref=breadcrumb_listing\"},{\"name\":\"Wall Hangings\",\"url\":\"https://www.etsy.com/c/home-and-living/home-decor/wall-decor/wall-hangings?explicit=1&ref=breadcrumb_listing\"}]', 'Home Decor', 'Tyler Reed', 'StraightEdgeMetalArt', '', '[\"**During the purchase process, please leave the name of the track you\'d like in the order notes.  If you\'d like the track name attached to the piece and have any other special requests please also leave that in the notes section of the order, thank you!!** If not specified the piece will come without the track name by default. If there\'s a size you\'d like that you do not see, please send me a message.This item is for a single track outline of your choice with magnetic mounting hardware to easily fasten it to any surface you can put a screw into. Other welded bracket options are available upon request. *Local and custom tracks welcome!Custom Hand Made Race Track outline featuring any track you wish with a finish of your choice and three coats of gloss, or satin clear coat.  These are handmade in Manitowoc Wisconsin and I guarantee you\'ll get a quality sign by sending you a proof if requested to approve before anything is cut.   Due to this item being made to order, and handmade there is a stated lead time involved for this listing.  Etsy requires you to select \\\"in stock\\\" when creating a listing, when for most sellers is not the case.  Please message me with any questions on this, expedite options are typically available. Many different paint colors and finishes available upon request*Personal Track Day numbers and even your name can be added, please message me directly.Made from 16 gauge mild steel, not flimsy, this piece is nice and rigid and is perfect for the garage, shop, or home. Instagram: @straightedgemetalart\\n        \\n    \\n    \\n        \\n            Learn more about this item\"]', '[\"Order today to get by Jan 9-18\",\"Returns & exchanges not accepted\",\"Free shipping\",\"Ships from: Manitowoc, WI\"]', '[{\"specification_name\":\"Primary color\",\"specification_values\":\"Select a color; Black; Blue; Brown; Green; Gray; Orange; Pink; Purple; Red; White; Yellow; Silver; Polished w/Clear; Gold; Hammered Black; Hammered Silver; Hammered copper; Custom contact me; Black Metallic; Blue Metallic; Gold Metallic\"},{\"specification_name\":\"Diameter\",\"specification_values\":\"Select a diameter; 16 inches ($42.40); 20 inches; 24 inches ($54.40); 30 inches ($70.40); 36 inches ($114.40); 40 inches ($146.40); 38 inches ($140.00)\"}]', 'null', 'null', '[\"Home & Living\",\"Home Decor\",\"Wall Decor\",\"Wall Hangings\"]', '[{\"date\":\"2024-12-07\",\"rating\":5,\"reviewr_name\":\"nim███oy\",\"the_review\":\"High quality metal track cutout of Silverstone!  Arrived so quickly too!\"},{\"date\":\"2024-12-02\",\"rating\":5,\"reviewr_name\":\"den███t\",\"the_review\":\"I&#39;ve made multiple purchases - every one has been great. Super communication, quality & service!\"},{\"date\":\"2024-11-13\",\"rating\":5,\"reviewr_name\":\"Tif███y B███che███\",\"the_review\":\"Gave as a gift and was very well crafted and high quality.\"},{\"date\":\"2024-11-07\",\"rating\":5,\"reviewr_name\":\"Bry███str███\",\"the_review\":\"This is my second purchase and will definitely be back for more in the future\"}]', '[\"https://i.etsystatic.com/iap/e3e824/6129185787/iap_300x300.6129185787_pgb0lq4x.jpg?version=0\",\"https://i.etsystatic.com/iap/5c1ca6/4076936506/iap_300x300.4076936506_jrvwmnnq.jpg?version=0\",\"https://i.etsystatic.com/iap/149672/3602052259/iap_300x300.3602052259_7fo3ijok.jpg?version=0\",\"https://i.etsystatic.com/iap/31eaca/3302831942/iap_300x300.3302831942_bpmd4c8b.jpg?version=0\",\"https://i.etsystatic.com/iap/6472b7/2472933970/iap_300x300.2472933970_183dnja7.jpg?version=0\",\"https://i.etsystatic.com/iap/6bac18/2373764680/iap_300x300.2373764680_a77hedc6.jpg?version=0\",\"https://i.etsystatic.com/iap/0a9195/2362189262/iap_300x300.2362189262_7ksoekq8.jpg?version=0\",\"https://i.etsystatic.com/iap/f5b944/6552271545/iap_300x300.655227