INSERT INTO `etsy_sample_raw` VALUES (246, 'https://www.etsy.com/listing/942412109/6-walts-worm-jig-euro-nymphs-fly-fishing?click_key=f01f2c3e38c74919beb52cade7fd68dfa8ddb2a9%3A942412109&click_sum=6c670f2f&ga_order=most_relevant&ga_search_type=all&ga_view_type=gallery&ga_search_query=duracell&ref=search_grid-504072-5-42&sts=1&content_source=2d8e55983d41555aa038985ffe72e0019b7e77b0%253A942412109&variation0=2755004193&variation1=1757039971', '942412109', '6 - Walt&#39;s Worm Jig - Euro Nymphs. Fly Fishing Flies. Caddis Flies. Colorado Fishing. Trout Flies. Tungsten. Barbless. Bead Head Nymph.', '5', '748', '7', '20', '0', '20', 'USD', '[\"https://i.etsystatic.com/26202727/r/il/99fe09/5567543496/il_fullxfull.5567543496_bcnr.jpg\",\"https://i.etsystatic.com/26202727/r/il/31b2fd/5615646353/il_fullxfull.5615646353_ayjo.jpg\"]', '[{\"name\":\"Toys & Games\",\"url\":\"https://www.etsy.com/c/toys-and-games?explicit=1&ref=breadcrumb_listing\"},{\"name\":\"Sports & Outdoor Recreation\",\"url\":\"https://www.etsy.com/c/toys-and-games/sports-and-outdoor-games?explicit=1&ref=breadcrumb_listing\"},{\"name\":\"Fishing\",\"url\":\"https://www.etsy.com/c/toys-and-games/sports-and-outdoor-games/fishing?explicit=1&ref=breadcrumb_listing\"}]', 'Sports & Outdoor Recreation', 'Ian', 'ColoradoFlyTyer', '', '[\"This is one of the most popular Euro Nymphing Jigs, especially in the US. It is exceptionally simple for flies these days, with the only flashiness coming from the tungsten bead head. This fly is a common imitation for free caddis larvae which are prolific in most trout streams. It can pass for a variety of other common bugs (scuds, crane fly larvae) and for this reason is popular on the competitive fly fishing scene. Flies like this fish well on their own or in tandem with a variety of other flies. This is tied with lead free wire to help get this fly down in the strike zone.These flies are tied on barbless, black nickel finished, 1x short, wide gape jig hooks. These hooks ride poin