INSERT INTO `etsy_sample_raw` VALUES (248, 'https://www.etsy.com/listing/1144237124/racing-flag-race-flag-wish-bracelet?click_key=c43efc718c0eaba77b16c8aa6802624a0b57b3b9%3A1144237124&click_sum=685d9f40&ga_order=most_relevant&ga_search_type=all&ga_view_type=gallery&ga_search_query=duracell&ref=search_grid-504072-5-46&sts=1&content_source=87ab353839724f0b977a5f52a3ed1bb8fe6e7662%253A1144237124&variation0=2432471945&variation1=4374875723', '1144237124', 'Racing Flag, Race Flag Wish Bracelet, Personalized racing gift, Car racing, Racing Bracelet, Race Flag Gift', '5', '6768', '16', '2.5', '0', '2.5', 'USD', '[\"https://i.etsystatic.com/18067899/r/il/feec94/3589618268/il_fullxfull.3589618268_angv.jpg\",\"https://i.etsystatic.com/18067899/r/il/b87974/3637239647/il_fullxfull.3637239647_3ua0.jpg\",\"https://i.etsystatic.com/18067899/r/il/eb3f50/2236466513/il_fullxfull.2236466513_qw3q.jpg\",\"https://i.etsystatic.com/18067899/r/il/34f572/2188919038/il_fullxfull.2188919038_3tpu.jpg\",\"https://i.etsystatic.com/18067899/r/il/ee59c5/2188919040/il_fullxfull.2188919040_50q2.jpg\",\"https://i.etsystatic.com/18067899/r/il/326ac5/2236466507/il_fullxfull.2236466507_s33r.jpg\",\"https://i.etsystatic.com/18067899/r/il/fb61c3/2492234090/il_fullxfull.2492234090_drfd.jpg\",\"https://i.etsystatic.com/18067899/r/il/02fe86/3636177751/il_fullxfull.3636177751_brfv.jpg\",\"https://i.etsystatic.com/18067899/r/il/4fec10/3639525105/il_fullxfull.3639525105_tkhk.jpg\",\"https://i.etsystatic.com/18067899/r/il/9cd8d6/3591908930/il_fullxfull.3591908930_doch.jpg\"]', '[{\"name\":\"Jewelry\",\"url\":\"https://www.etsy.com/c/jewelry?explicit=1&ref=breadcrumb_listing\"},{\"name\":\"Bracelets\",\"url\":\"https://www.etsy.com/c/jewelry/bracelets?explicit=1&ref=breadcrumb_listing\"},{\"name\":\"Charm Bracelets\",\"url\":\"https://www.etsy.com/c/jewelry/bracelets/charm-bracelets?explicit=1&ref=breadcrumb_listing\"}]', 'Bracelets', 'Mel', 'SalemWishes', '', '[\"Racing Flag Wish Bracelet or AnkletGive the gift 