INSERT INTO `etsy_sample_raw` VALUES (261, 'https://www.etsy.com/listing/1532044152/circuit-of-the-americas-pendant-necklace?click_key=a93aefce9a06a2e854499e3aafe2a24af5c83a61%3A1532044152&click_sum=2c035337&ga_order=most_relevant&ga_search_type=all&ga_view_type=gallery&ga_search_query=duracell&ref=search_grid-912182-4-27&sts=1&content_source=7a7fd77c0daead6d5884cf6071e9d91dcfc18022%253A1532044152&variation0=3752552098', '1532044152', 'Circuit of the Americas Pendant Necklace Gold/Silver with Chain', '4.8', '76', '8', '16', '0', '16', 'USD', '[\"https://i.etsystatic.com/45526673/r/il/53625f/5195438654/il_fullxfull.5195438654_1hyb.jpg\",\"https://i.etsystatic.com/45526673/r/il/2aa375/5243669213/il_fullxfull.5243669213_t2hg.jpg\"]', '[{\"name\":\"Jewelry\",\"url\":\"https://www.etsy.com/c/jewelry?explicit=1&ref=breadcrumb_listing\"},{\"name\":\"Necklaces\",\"url\":\"https://www.etsy.com/c/jewelry/necklaces?explicit=1&ref=breadcrumb_listing\"},{\"name\":\"Pendant Necklaces\",\"url\":\"https://www.etsy.com/c/jewelry/necklaces/pendant-necklaces?explicit=1&ref=breadcrumb_listing\"}]', 'Necklaces', 'Norem Saela', 'TracksideJewelry', '', '[\"This pendant is a perfect way to show off your love for the fast and furious world of racing. The unique piece is crafted with precision and attention to detail, just like the iconic COTA track itself. The Circuit of the Americas (COTA) is a world-class race track located in Austin, Texas, United States. It is known for hosting various motorsport events, including the Formula One United States Grand Prix.COTA\'s layout was specifically designed to encourage overtaking opportunities, with wide run-off areas that allow for closer racing. The track\'s diverse topography, featuring uphill and downhill sections, challenges drivers and teams with varying grip levels and makes strategy crucial during races.\\n        \\n    \\n    \\n        \\n            Learn more about this item\"]', '[\"Order today to get by Dec 20-23\",\"Returns & exchanges accepted within 30 days\",\"Cost to ship: $4.09\",\"Ships from: New Baltimore, MI\"]', '[{\"specification_name\":\"Secondary color\",\"specification_values\":\"Gold; Silver\"}]', 'null', 'null', '[\"Jewelry\",\"Necklaces\",\"Pendant Necklaces\"]', '[{\"date\":\"2024-11-14\",\"rating\":5,\"reviewr_name\":\"Adr███ Sp███\",\"the_review\":\"Great necklace for an F1 fan. One of those &quot;if you know, you know&quot; items. Thank you!\"},{\"date\":\"2024-11-11\",\"rating\":5,\"reviewr_name\":\"Lai███Rog███\",\"the_review\":\"I absolutely love this necklace!! I went to COTA for the first time this year for F1 and I’m already missing being at the track. This was the perfect, subtle way to keep it with me!\"},{\"date\":\"2024-06-19\",\"rating\":5,\"reviewr_name\":\"Jin███ ea███ngs███\",\"the_review\":\"I ordered the wrong track on accident and the amazing seller sent me the right one ❤️\"},{\"date\":\"2024-04-17\",\"rating\":5,\"reviewr_name\":\"Che███ Da███\",\"the_review\":\"Very cute necklace !! Nice quality and perfect size.\"}]', '[\"https://i.etsystatic.com/iap/a8ea4e/6504982074/iap_300x300.6504982074_7yxtrcnr.jpg?version=0\",\"https://i.etsystatic.com/iap/29f6ad/6419991604/iap_300x300.6419991604_ac46p7vv.jpg?version=0\",\"https://i.etsystatic.com/iap/0d24fe/6118701519/iap_300x300.6118701519_feeyzbaa.jpg?version=0\",\"https://i.etsystatic.com/iap/720322/5924966780/iap_300x300.5924966780_erbgo2zu.jpg?version=0\",\"https://i.etsystatic.com/iap/400493/5595756664/iap_300x300.5595756664_42sg189y.jpg?version=0\",\"https://i.etsystatic.com/iap/2deb09/6504984762/iap_300x300.6504984762_9yesvbhs.jpg?version=0\",\"https://i.etsystatic.com/iap/a7c93e/6537110425/iap_300x300.6537110425_si6otb14.jpg?version=0\",\"https://i.etsystatic.com/iap/95a87f/6483848252/iap_300x300.6483848252_2umhk0rt.jpg?version=0\",\"https://i.etsystatic.com/iap/abd676/6451993817/iap_300x300.6451993817_jlc9fjc6.jpg?version=0\",\"https://i.etsystatic.com/iap/65bd51/6395687498/iap_300x300.6395687498_h6brn6