INSERT INTO `etsy_sample_raw` VALUES (262, 'https://www.etsy.com/listing/675413606/rabbit-wish-bracelet-bunny-lover-gift?click_key=6485afb3fec82e472545103db11c5f2a2cbe5fe8%3A675413606&click_sum=060fe804&ga_order=most_relevant&ga_search_type=all&ga_view_type=gallery&ga_search_query=duracell&ref=search_grid-40812-3-14&pro=1&sts=1&content_source=75af162b0f840c63cd28ffd33f1d8022c19c795a%253A675413606&variation0=2450151491', '675413606', 'Rabbit Wish Bracelet, Bunny Lover Gift, Cute Friendship Card, Rabbit Charm Wishlet, Cord Bracelet', '4.9', '14858', '15', '3.91', '10', '3.51', 'USD', '[\"https://i.etsystatic.com/14328602/r/il/0e7442/1853509581/il_fullxfull.1853509581_iaf1.jpg\",\"https://i.etsystatic.com/14328602/r/il/88798b/1853509777/il_fullxfull.1853509777_ddj4.jpg\",\"https://i.etsystatic.com/14328602/r/il/bec157/1853509867/il_fullxfull.1853509867_aw0l.jpg\",\"https://i.etsystatic.com/14328602/r/il/c56791/1853517569/il_fullxfull.1853517569_dqz1.jpg\",\"https://i.etsystatic.com/14328602/r/il/ae77aa/1821935067/il_fullxfull.1821935067_r7um.jpg\",\"https://i.etsystatic.com/14328602/r/il/fbb966/3041812714/il_fullxfull.3041812714_fcpt.jpg\"]', '[{\"name\":\"Jewelry\",\"url\":\"https://www.etsy.com/c/jewelry?explicit=1&ref=breadcrumb_listing\"},{\"name\":\"Bracelets\",\"url\":\"https://www.etsy.com/c/jewelry/bracelets?explicit=1&ref=breadcrumb_listing\"},{\"name\":\"Charm Bracelets\",\"url\":\"https://www.etsy.com/c/jewelry/bracelets/charm-bracelets?explicit=1&ref=breadcrumb_listing\"}]', 'Bracelets', 'Emma', 'TheDreamingBuddha', '', '[\"Rabbit Wish Bracelet, Bunny Lover Gift, Cute Friendship Card, Rabbit Charm Wishlet, Cord Bracelet.This handmade wish bracelet card reads - Saw this and thought of you!Although perfect as a little gift on its own, this little wish bracelet can also be popped into a card or sent along with a present.The idea behind a wish bracelet is that you make a wish as you place it on your wrist. In time, the cord wears out and your wish comes true! This bracelet is meant to be tied on and has no closure.Each bracelet includes a Rabbit charm and is made from quality coloured 1mm waxed cord in a variety of colours. The bracelet is mounted on recycled card, teamed with an envelope and carefully wrapped in a clear cellophane sleeve. The whole package measures 11.5 cm by 9.5 cm.© 2017 - 2024 The Dreaming Buddha® All rights reserved.This design is protected by UK and International copyright laws. No part of the content, image(s), product(s), name(s), and design(s) may be used without permission.* We are a small business and our unique creations take many, many hours to dream up, create, photograph and list. Please don’t copy our things, we defend our brand and products fearlessly.*** ♻️PACKAGING DETAILS♻️ ***All packaging can be recycled.If you have purchased a carded item, the clear sleeve used for protection is biodegradable but not compostable.\\n        \\n    \\n    \\n        \\n            Learn more about this item\"]', '[\"Order today to get by Dec 23-Jan 6\",\"Returns & exchanges accepted within 14 days\",\"Cost to ship: $9.62\\n            \\n    Enjoy free shipping to the US when you spend $35+ at this shop.\",\"Ships from: United Kingdom\"]', '[{\"specification_name\":\"Primary color\",\"specification_values\":\"Select a color; Red; Orange; Yellow; Green; Blue; Turquoise; Pink; Purple; Black; Gray; White; Natural\"}]', 'null', 'null', '[\"Jewelry\",\"Bracelets\",\"Charm Bracelets\"]', '[{\"date\":\"2024-05-30\",\"rating\":5,\"reviewr_name\":\"ale███at2███\",\"the_review\":\"Quick delivery. Lovely gift. Great for any bunny lovers.\"},{\"date\":\"2024-01-10\",\"rating\":5,\"reviewr_name\":\"Bek███Rob███s\",\"the_review\":\"Nice little secret santa gift!\"},{\"date\":\"2023-12-18\",\"rating\":5,\"reviewr_name\":\"Lou\",\"the_review\":\"Exactly as per photo. Quick delivery. Thank you\"},{\"date\":\"2023-02-14\",\"rating\":5,\"reviewr_name\":\"Kelly\",\"the_review\":\"Little gift for my niece to finish her birthday present off she was over the moon lovely little bracelet. Thank you so much. Xxx\"}]', '[\"https://i.etsystatic.com/iap/1ba479/6548760879/iap_300x300.6548760879_c80v4xca.jpg?version=0\",\"https://i.etsystatic.com/iap/d8f3be/6487618566/iap_300x300.6487618566_l61z3sca.jpg?version=0\",\"https://i.etsystatic.com/iap/a9955a/6487252032/iap_300x300.6487252032_dbywxmmz.jpg?version=0\",\"https://i.etsystatic.com/iap/478503/6534554479/iap_300x300.6534554479_gx318lwz.jpg?version=0\",\"https://i.etsystatic.com/iap/4eceac/6483455884/iap_300x300.6483455884_1qzpoeh7.jpg?version=0\",\"https://i.etsystatic.com/iap/cc2639/6416301226/iap_300x300.6416301226_apcw177n.jpg?version=0\",\"https://i.etsystatic.com/iap/aed135/6452075853/iap_300x300.6452075853_pyfurqf4.jpg?version=0\",\"https://i.etsystatic.com/iap/77f9fb/6441496089/iap_300x300.6441496089_mt4ceu2h.jpg?version=0\",\"https://i.etsystatic.com/iap/a7bbe3/6384293328/iap_300x300.6384293328_cbzxxxio.jpg?version=0\",\"https://i.etsystatic.com/iap/7fbd7b/6399293155/iap_300x300.6399293155_8oog6cx4.jpg?version=0\",\"https://i.etsystatic.com/iap/c5425e/6325503312/iap_300x300.6325503312_115duhh0.jpg?version=0\",\"https://i.etsystatic.com/iap/c04d38/6292070542/iap_300x300.6292070542_dkfb8po3.jpg?version=0\",\"https://i.etsystatic.com/iap/2f3df3/6303840889/iap_300x300.6303840889_jc33b0lq.jpg?version=0\",\"https://i.etsystatic.com/iap/fbfd6d/6255645730/iap_300x300.6255645730_nzxjkb5s.jpg?version=0\",\"https://i.etsystatic.com/iap/1ebc59/6303471833/iap_300x300.6303471833_cf1dwozu.jpg?version=0\",\"https://i.etsystatic.com/iap/70cc1c/6298823455/iap_300x300.6298823455_o7e2gfoc.jpg?version=0\",\"https://i.etsystatic.com/iap/1adecd/6249610746/iap_300x300.6249610746_9ltg9b8u.jpg?version=0\",\"https://i.etsystatic.com/iap/4b0577/6290152027/iap_300x300.6290152027_nvuhsdmc.jpg?version=0\",\"https://i.etsystatic.com/iap/9acda7/6290145889/iap_300x300.6290145889_i1lxj3e4.jpg?version=0\",\"https://i.etsystatic.com/iap/5b8e92/6213398424/iap_300x300.