INSERT INTO `etsy_sample_raw` VALUES (350, 'https://www.etsy.com/listing/1405117740/duran-duran-necklace-1980s-inspired?click_key=3cf2c0984bb267cba2848d16ef2b9e540c3e24a2%3A1405117740&click_sum=6841ae72&ga_order=most_relevant&ga_search_type=all&ga_view_type=gallery&ga_search_query=duracell&ref=search_grid-504072-5-15&pro=1&sts=1&content_source=8dc17f8e05182ff848c26a15ed722a2eb4cd7958%253A1405117740&variation0=3263037935', '1405117740', 'Duran Duran Necklace, 1980s Inspired, Retro Duranie Fan, Kitsch Quirky, Customized Rock Star, Celebrity Funky Fun Pendant, Black Angel Wings', '4.9', '2995', '0', '32.26', '25', '24.19', 'USD', '[\"https://i.etsystatic.com/6200968/r/il/90a7c3/5568833466/il_fullxfull.5568833466_g6k2.jpg\",\"https://i.etsystatic.com/6200968/r/il/cba0d4/4683757589/il_fullxfull.4683757589_msb9.jpg\",\"https://i.etsystatic.com/6200968/r/il/daa882/4635508898/il_fullxfull.4635508898_edt9.jpg\",\"https://i.etsystatic.com/6200968/r/il/a2169f/4635507904/il_fullxfull.4635507904_42ce.jpg\",\"https://i.etsystatic.com/6200968/r/il/ed3d80/4683758849/il_fullxfull.4683758849_hkm3.jpg\",\"https://i.etsystatic.com/6200968/r/il/87679e/5568831988/il_fullxfull.5568831988_mqok.jpg\",\"https://i.etsystatic.com/6200968/r/il/39624f/326481495/il_fullxfull.326481495.jpg\"]', '[{\"name\":\"Jewelry\",\"url\":\"https://www.etsy.com/c/jewelry?explicit=1&ref=breadcrumb_listing\"},{\"name\":\"Necklaces\",\"url\":\"https://www.etsy.com/c/jewelry/necklaces?explicit=1&ref=breadcrumb_listing\"},{\"name\":\"Pendant Necklaces\",\"url\":\"https://www.etsy.com/c/jewelry/necklaces/pendant-necklaces?explicit=1&ref=breadcrumb_listing\"}]', 'Necklaces', 'Chantelle Wilson', 'whatanovelidea', '', '[\"In the 80s I was a huge Duranie. I had pictures of Simon, Nick, John, Roger, and Andy all over my walls. Today I have a confession....I\'m Still A Duranie! Are you?         Printed on durable, lightweight plastic, the 2\\\" x 2\\\" black angel wings have a second round piece attached to the centre declaring your undying dedication to the band with the words \\\"I\'m Still A Duranie\\\". I\'ve used a silver plated chain for the necklace and given you the option to choose the length you\' like.      ***** Please note that I can make a custom piece declaring your love for a celebrity, historical figure, boyfriend or that cute barista who works at Starbucks! Convo me for a reserved listing.*****                                 ** For more fun items, enter my shop here**                      http://www.etsy.com/shop/whatanovelidea?ref=si_shop\\n        \\n    \\n    \\n        \\n            Learn more about this item\"]', '[\"Order today to get by Dec 31-Jan 8\",\"Returns & exchanges accepted within 30 days\",\"Cost to ship: $8.99\\n            \\n    Enjoy free shipping to the US when you spend $35+ at this shop.\",\"Ships from: Canada\"]', '[{\"specification_name\":\"Necklace length\",\"specification_values\":\"17 Inches; 18 Inches; 20 Inches; 22 Inches; 24 Inches; 26 Inches\"}]', 'null', 'null', '[\"Jewelry\",\"Necklaces\",\"Pendant Necklaces\"]', 'null', '[\"https://i.etsystatic.com/iap/7d42f2/6429156256/iap_300x300.6429156256_cluiz27a.jpg?version=0\",\"https://i.etsystatic.com/iap/21b43a/6394967415/iap_300x300.6394967415_gc8h1hlt.jpg?version=0\",\"https://i.etsystatic.com/iap/c91be5/6273558686/iap_300x300.6273558686_dsmqgm5v.jpg?version=0\",\"https://i.etsystatic.com/iap/de1a28/6216255660/iap_300x300.6216255660_9xweux1f.jpg?version=0\",\"https://i.etsystatic.com/iap/6acfa6/6185613363/iap_300x300.6185613363_4832pvfy.jpg?version=0\",\"https://i.etsystatic.com/iap/81ff2c/6057754132/iap_300x300.6057754132_tmksmdip.jpg?version=0\",\"https://i.etsystatic.com/iap/29f124/5946285614/iap_300x300.5946285614_d69886to.jpg?version=0\",\"https://i.etsystatic.com/iap/8e0ffb/5986153359/iap_300x300.5986153359_96e54o71.jpg?version=0\",\"https://i.etsystatic.com/iap/da1f8e/5969953723/iap_300x300.5969953723_gk37oy09.jpg?version=0\",\"https://i.etsystatic.com/iap/4433da/5905250322/i