INSERT INTO `etsy_sample_raw` VALUES (352, 'https://www.etsy.com/listing/1665129862/interlagos-brazil-racing-wall-art-racing?click_key=1b1487915e512c7557087dd9bcc30b46cf2386f2%3A1665129862&click_sum=b442dfb1&ga_order=most_relevant&ga_search_type=all&ga_view_type=gallery&ga_search_query=duracell&ref=search_grid-504072-5-24&pro=1&content_source=6c9bac67c725605219fc09f3e3f715712520fc7e%253A1665129862&variation0=4304238913', '1665129862', 'Interlagos Brazil Racing Wall Art Racing Art Car Wall Art Racing Car Wall Art Car Poster Art Vintage Racing Art Decor Automotive Racing Art', '4.5', '75', '0', '62.1', '15', '52.78', 'USD', '[\"https://i.etsystatic.com/14969159/r/il/c6e5e6/5765319358/il_fullxfull.5765319358_cp48.jpg\",\"https://i.etsystatic.com/14969159/r/il/e7a535/5128858638/il_fullxfull.5128858638_koph.jpg\",\"https://i.etsystatic.com/14969159/r/il/68c824/5128858652/il_fullxfull.5128858652_dvki.jpg\",\"https://i.etsystatic.com/14969159/r/il/e4f300/5128858654/il_fullxfull.5128858654_ahgk.jpg\",\"https://i.etsystatic.com/14969159/r/il/bcfcf4/5133062605/il_fullxfull.5133062605_rwhl.jpg\",\"https://i.etsystatic.com/14969159/r/il/a353ff/5165644899/il_fullxfull.5165644899_jmvx.jpg\",\"https://i.etsystatic.com/14969159/r/il/31dc59/5117474610/il_fullxfull.5117474610_s202.jpg\",\"https://i.etsystatic.com/14969159/r/il/aa6c78/5117474608/il_fullxfull.5117474608_ecbm.jpg\",\"https://i.etsystatic.com/14969159/r/il/bd515e/5117474616/il_fullxfull.5117474616_1e0r.jpg\",\"https://i.etsystatic.com/14969159/r/il/8af856/5133062603/il_fullxfull.5133062603_7mq1.jpg\"]', '[{\"name\":\"Art & Collectibles\",\"url\":\"https://www.etsy.com/c/art-and-collectibles?explicit=1&ref=breadcrumb_listing\"},{\"name\":\"Prints\",\"url\":\"https://www.etsy.com/c/art-and-collectibles/prints?explicit=1&ref=breadcrumb_listing\"},{\"name\":\"Digital Prints\",\"url\":\"https://www.etsy.com/c/art-and-collectibles/prints/digital-prints?explicit=1&ref=breadcrumb_listing\"}]', 'Prints', 'Jackson Maitner', 'CorsaCurated', '', '[\"Hello! Thank you for checking out our new collection of minimalist track posters, designed to capture the essence of the most iconic circuits. Elevate your home, office, man cave, garage, or any wall to capture the essence of racing! Our prints are a great gift for the racing fan in your life!DISCOUNT:- 5% off when you buy 2+ Prints        Code: BUY2GET5- 10% off when you buy 3+ Prints        Code: BUY3GET10SIZES:- 8x10 Inches- 12x16 Inches- 16x20 Inches- 18x24 Inches- 24x36 InchesCANVAS INFO:• Slim and trim—this Thin Canvas comes ready to hang with an attached wall mount. The canvas is stretched over pine wood and comes in 6 different sizes, suitable for different interiors and art styles.• 0.75″ (19.05 mm) thick canvas• Canvas fabric weight: 10.15 +/- 0.74 oz/yd² (344 g/m² +/- 25g/m²)• Wall mounts attached• Rubber pads on the back to avoid damage• Blank product sourced from Canada, the UK, and the US• Important: This product is available in the US, Canada, Europe, and the UK only. If your shipping address is outside these regions, please choose a different product. POSTER PRINT INFO:• Museum-quality posters made on thick matte paper. • Paper thickness: 10.3 mil• Paper weight: 189 g/m²• Opacity: 94%• ISO brightness: 104%• Paper is sourced from JapanFRAMED PRINT INFO:• Ayous wood .75″ (1.9 cm) thick frame from renewable forests• Paper thickness: 10.3 mil (0.26 mm)• Paper weight: 189 g/m²• Lightweight• Acrylite front protector• Hanging hardware included• Blank product components in the US sourced from Japan and the USWhether you\'re a dedicated fan or simply appreciate the beauty of these world-renowned circuits, our posters are a must-have addition to your decor. Thanks for your interest in my prints! If you have any questions, please reach out!- JacksonThis website is unofficial and is not associated in any way with the Formula 1 companies. F1, FORMULA ONE, FORMULA 1, FIA FORMULA ONE WORLD CHAMPIONSHIP, GRAND PRIX and related marks are trademarks of Formula One Licensing B.V.F1 Wallart\\n        \\n    \\n    \\n        \\n            Learn more about this item\"]', '[\"Order today to get by Dec 23-Jan 2\",\"Returns & exchanges accepted within 30 days\",\"Cost to ship: $5.99\\n            \\n    Enjoy free shipping to the US when you spend $35+ at this shop.\",\"Ships from: Charlotte, NC\"]', '[{\"specification_name\":\"Size\",\"specification_values\":\"Select a size; Digital Download ($11.73); 8x10 Print Only ($27.37); 12x16 Print Only ($35.19); 16x20 Print Only ($44.96); 18x24 Print Only; 24x36 Print Only ($70.38); 8x10 Framed (Black) ($54.74); 12x16 Framed (Black) ($70.38); 16x20 Framed (Black) ($95.79); 18x24 Framed (Black) ($101.66); 24x36 Framed (Black) ($172.04); 16x20 Canvas ($84.06); 18x24 Canvas ($95.79); 24x36 Canvas ($142.71)\"}]', 'null', 'null', '[\"Art & Collectibles\",\"Prints\",\"Digital Prints\"]', 'null', '[\"https://i.etsystatic.com/iap/c59d0e/6294471825/iap_300x300.6294471825_ntbjcbo3.jpg?version=0\"]', '\"2024-10-17T00:00:00.000Z\"', 'https://www.etsy.com/shop/CorsaCurated?ref=shop-header-name&listing_id=1665129862&from_page=listing', '20218854318', '[{\"type\":\"Size\",\"value\":\"18x24 Print Only\"}]', '[{\"type\":\"Size\",\"value\":[\"Digital Download ($11.73)\",\"8x10 Print Only ($27.37)\",\"12x16 Print Only ($35.19)\",\"16x20 Print Only ($44.96)\",\"18x24 Print Only\",\"24x36 Print Only ($70.38)\",\"8x10 Framed (Black) ($54.74)\",\"12x16 Framed (Black) ($70.38)\",\"16x20 Framed (Black) ($95.79)\",\"18x24 Framed (Black) ($101.66)\",\"24x36 Framed (Black) ($172.04)\",\"16x20 Canvas ($84.06)\",\"18x24 Canvas ($95.79)\",\"24x36 Canvas ($142.71)\"]}]', '2026-05-25 22:40:49');
