INSERT INTO `etsy_sample_raw` VALUES (401, 'https://www.etsy.com/listing/212898205/custom-metal-race-track-art-handmade-in?click_key=f09193af4a457f45a73c82c3decb89461ac65e63%3A212898205&click_sum=02064d97&ga_order=most_relevant&ga_search_type=all&ga_view_type=gallery&ga_search_query=duracell&ref=search_grid-140082-4-2&pro=1&frs=1&bes=1&sts=1&content_source=069046fae64d46d7dcdb36758365fa32064398ce%253A212898205&variation0=627157135&variation1=4483957135', '212898205', 'Custom Metal Race Track Art - Handmade in US, Magnetic Mounts, Local Tracks and Circuits, Man Cave, Sculpture, Ornamental, Wall Decoration', '4.9', '1556', '39', '183', '20', '146.4', 'USD', '[\"https://i.etsystatic.com/10324360/r/il/3ea538/6510692201/il_fullxfull.6510692201_f8a0.jpg\",\"https://i.etsystatic.com/10324360/r/il/e81f94/6006883401/il_fullxfull.6006883401_1q4o.jpg\",\"https://i.etsystatic.com/10324360/r/il/7a29bf/5435098109/il_fullxfull.5435098109_m6kl.jpg\",\"https://i.etsystatic.com/10324360/r/il/370498/5386942904/il_fullxfull.5386942904_qgvl.jpg\",\"https://i.etsystatic.com/10324360/r/il/b26e76/5386942922/il_fullxfull.5386942922_gpcu.jpg\",\"https://i.etsystatic.com/10324360/r/il/7fe1bb/6006875221/il_fullxfull.6006875221_fde0.jpg\",\"https://i.etsystatic.com/10324360/r/il/ed2496/5386942752/il_fullxfull.5386942752_l6wk.jpg\",\"https://i.etsystatic.com/10324360/r/il/98d02a/5386942880/il_fullxfull.5386942880_2bde.jpg\",\"https://i.etsystatic.com/10324360/r/il/6ff922/5435098029/il_fullxfull.5435098029_c7pp.jpg\",\"https://i.etsystatic.com/10324360/r/il/858e17/5958801406/il_fullxfull.5958801406_t3fb.jpg\"]', '[{\"name\":\"Home & Living\",\"url\":\"https://www.etsy.com/c/home-and-living?explicit=1&ref=breadcrumb_listing\"},{\"name\":\"Home Decor\",\"url\":\"https://www.etsy.com/c/home-and-living/home-decor?explicit=1&ref=breadcrumb_listing\"},{\"name\":\"Wall Decor\",\"url\":\"https://www.etsy.com/c/home-and-living/home-decor/wall-decor?explicit=1&ref=breadcrumb_listing\"},{\"name\":\"Wall Han