INSERT INTO `etsy_sample_raw` VALUES (603, 'https://www.etsy.com/listing/1405117740/duran-duran-necklace-1980s-inspired?click_key=3cf2c0984bb267cba2848d16ef2b9e540c3e24a2%3A1405117740&click_sum=6841ae72&ga_order=most_relevant&ga_search_type=all&ga_view_type=gallery&ga_search_query=duracell&ref=search_grid-504072-5-15&pro=1&sts=1&content_source=8dc17f8e05182ff848c26a15ed722a2eb4cd7958%253A1405117740&variation0=3248595048', '1405117740', 'Duran Duran Necklace, 1980s Inspired, Retro Duranie Fan, Kitsch Quirky, Customized Rock Star, Celebrity Funky Fun Pendant, Black Angel Wings', '4.9', '2995', '0', '32.26', '25', '24.19', 'USD', '[\"https://i.etsystatic.com/6200968/r/il/90a7c3/5568833466/il_fullxfull.5568833466_g6k2.jpg\",\"https://i.etsystatic.com/6200968/r/il/cba0d4/4683757589/il_fullxfull.4683757589_msb9.jpg\",\"https://i.etsystatic.com/6200968/r/il/daa882/4635508898/il_fullxfull.4635508898_edt9.jpg\",\"https://i.etsystatic.com/6200968/r/il/a2169f/4635507904/il_fullxfull.4635507904_42ce.jpg\",\"https://i.etsystatic.com/6200968/r/il/ed3d80/4683758849/il_fullxfull.4683758849_hkm3.jpg\",\"https://i.etsystatic.com/6200968/r/il/87679e/5568831988/il_fullxfull.5568831988_mqok.jpg\",\"https://i.etsystatic.com/6200968/r/il/39624f/326481495/il_fullxfull.326481495.jpg\"]', '[{\"name\":\"Jewelry\",\"url\":\"https://www.etsy.com/c/jewelry?explicit=1&ref=breadcrumb_listing\"},{\"name\":\"Necklaces\",\"url\":\"https://www.etsy.com/c/jewelry/necklaces?explicit=1&ref=breadcrumb_listing\"},{\"name\":\"Pendant Necklaces\",\"url\":\"https://www.etsy.com/c/jewelry/necklaces/pendant-necklaces?explicit=1&ref=breadcrumb_listing\"}]', 'Necklaces', 'Chantelle Wilson', 'whatanovelidea', '', '[\"In the 80s I was a huge Duranie. I had pictures of Simon, Nick, John, Roger, and Andy all over my walls. Today I have a confession....I\'m Still A Duranie! Are you?         Printed on durable, lightweight plastic, the 2\\\" x 2\\\" black angel wings have a second round piece attached to the centre declaring your undying dedication to the band with the words \\\"I\'m Still A Duranie\\\". I\'ve used a silver plated chain for the necklace and given you the option to choose the length you\' like.      ***** Please note that I can make a custom piece declaring your love for a celebrity, historical figure, boyfriend or that cute barista who works at Starbucks! Convo me for a reserved listing.*****                                 ** For more fun items, enter my shop here**                      http://www.etsy.com/shop/whatanovelidea?ref=si_shop\\n        \\n    \\n    \\n        \\n            Learn more about this item\"]', '[\"Order today to get by Dec 31-Jan 8\",\"Returns & exchanges accepted within 30 days\",\"Cost to ship: $8.99\\n            \\n    Enjoy free shipping to the US when you spend $35+ at this shop.\",\"Ships from: Canada\"]', '[{\"specification_name\":\"Necklace length\",\"specification_values\":\"17 Inches; 18 Inches; 20 Inches; 22 Inches; 24 Inches; 26 Inches\"}]', 'null', 'null', '[\"Jewelry\",\"Necklaces\",\"Pendant Necklaces\"]', 'null', '[\"https://i.etsystatic.com/iap/7d42f2/6429156256/iap_300x300.6429156256_cluiz27a.jpg?version=0\",\"https://i.etsystatic.com/iap/21b43a/6394967415/iap_300x300.6394967415_gc8h1hlt.jpg?version=0\",\"https://i.etsystatic.com/iap/c91be5/6273558686/iap_300x300.6273558686_dsmqgm5v.jpg?version=0\",\"https://i.etsystatic.com/iap/de1a28/6216255660/iap_300x300.6216255660_9xweux1f.jpg?version=0\",\"https://i.etsystatic.com/iap/6acfa6/6185613363/iap_300x300.6185613363_4832pvfy.jpg?version=0\",\"https://i.etsystatic.com/iap/81ff2c/6057754132/iap_300x300.6057754132_tmksmdip.jpg?version=0\",\"https://i.etsystatic.com/iap/29f124/5946285614/iap_300x300.5946285614_d69886to.jpg?version=0\",\"https://i.etsystatic.com/iap/8e0ffb/5986153359/iap_300x300.5986153359_96e54o71.jpg?version=0\",\"https://i.etsystatic.com/iap/da1f8e/5969953723/iap_300x300.5969953723_gk37oy09.jpg?version=0\",\"https://i.etsystatic.com/iap/4433da/5905250322/iap_300x300.5905250322_s1aff05g.jpg?version=0\",\"https://i.etsystatic.com/iap/a3f495/5953320035/iap_300x300.5953320035_qwes6w2c.jpg?version=0\",\"https://i.etsystatic.com/iap/499343/5871350387/iap_300x300.5871350387_dy2l3dtx.jpg?version=0\",\"https://i.etsystatic.com/iap/3d3c62/5784663709/iap_300x300.5784663709_h98bafl9.jpg?version=0\",\"https://i.etsystatic.com/iap/74aad0/5689500217/iap_300x300.5689500217_l78g0tsd.jpg?version=0\",\"https://i.etsystatic.com/iap/c008a4/5606336874/iap_300x300.5606336874_si1lqjjx.jpg?version=0\",\"https://i.etsystatic.com/iap/92f8fb/5654415465/iap_300x300.5654415465_n24kpv74.jpg?version=0\",\"https://i.etsystatic.com/iap/9916cb/5430083416/iap_300x300.5430083416_pz3lf3el.jpg?version=0\",\"https://i.etsystatic.com/iap/fc66dd/5090976852/iap_300x300.5090976852_9axov2t1.jpg?version=0\",\"https://i.etsystatic.com/iap/4cd0b9/4884922611/iap_300x300.4884922611_tfdh5sdl.jpg?version=0\",\"https://i.etsystatic.com/iap/dc1f6a/4550806018/iap_300x300.4550806018_ftb21l3g.jpg?version=0\"]', '\"2024-10-21T00:00:00.000Z\"', 'https://www.etsy.com/shop/whatanovelidea?ref=shop-header-name&listing_id=1405117740&from_page=listing', '13667434252', '[{\"type\":\"Necklace length\",\"value\":\"20 Inches\"}]', '[{\"type\":\"Necklace length\",\"value\":[\"17 Inches\",\"18 Inches\",\"20 Inches\",\"22 Inches\",\"24 Inches\",\"26 Inches\"]}]', '2026-05-25 22:40:50');
INSERT INTO `etsy_sample_raw` VALUES (604, 'https://www.etsy.com/listing/942412109/6-walts-worm-jig-euro-nymphs-fly-fishing?click_key=f01f2c3e38c74919beb52cade7fd68dfa8ddb2a9%3A942412109&click_sum=6c670f2f&ga_order=most_relevant&ga_search_type=all&ga_view_type=gallery&ga_search_query=duracell&ref=search_grid-504072-5-42&sts=1&content_source=2d8e55983d41555aa038985ffe72e0019b7e77b0%253A942412109&variation0=2755004189&variation1=1757039971', '942412109', '6 - Walt&#39;s Worm Jig - Euro Nymphs. Fly Fishing Flies. Caddis Flies. Colorado Fishing. Trout Flies. Tungsten. Barbless. Bead Head Nymph.', '5', '748', '7', '20', '0', '20', 'USD', '[\"https://i.etsystatic.com/26202727/r/il/99fe09/5567543496/il_fullxfull.5567543496_bcnr.jpg\",\"https://i.etsystatic.com/26202727/r/il/31b2fd/5615646353/il_fullxfull.5615646353_ayjo.jpg\"]', '[{\"name\":\"Toys & Games\",\"url\":\"https://www.etsy.com/c/toys-and-games?explicit=1&ref=breadcrumb_listing\"},{\"name\":\"Sports & Outdoor Recreation\",\"url\":\"https://www.etsy.com/c/toys-and-games/sports-and-outdoor-games?explicit=1&ref=breadcrumb_listing\"},{\"name\":\"Fishing\",\"url\":\"https://www.etsy.com/c/toys-and-games/sports-and-outdoor-games/fishing?explicit=1&ref=breadcrumb_listing\"}]', 'Sports & Outdoor Recreation', 'Ian', 'ColoradoFlyTyer', '', '[\"This is one of the most popular Euro Nymphing Jigs, especially in the US. It is exceptionally simple for flies these days, with the only flashiness coming from the tungsten bead head. This fly is a common imitation for free caddis larvae which are prolific in most trout streams. It can pass for a variety of other common bugs (scuds, crane fly larvae) and for this reason is popular on the competitive fly fishing scene. Flies like this fish well on their own or in tandem with a variety of other flies. This is tied with lead free wire to help get this fly down in the strike zone.These flies are tied on barbless, black nickel finished, 1x short, wide gape jig hooks. These hooks ride point up greatly reducing the risk of snagging and are far less stressful on fish during removal. This listing is for 6 flies. Please message me with any questions or custom orders. I\'m happy to use larger/smaller beads if desired. These are the hook sizes to corresponding bead sizes I use on my jig patterns:#10 - 4.mm#12 - 3.5 mm#14 - 3.0 mm#16 - 3.0 mm#18 - 2.5 mm#20 - 2.0 mm\\n        \\n    \\n    \\n        \\n            Learn more about this item\"]', '[\"Order today to get by Dec 26-Jan 2\",\"Returns & exchanges not accepted\",\"Cost to ship: $4.50\",\"Ships from: Longmont, CO\"]', '[{\"specification_name\":\"Size\",\"specification_values\":\"Select a size; #10 Barbless Jig; #12 Barbless Jig; #14 Barbless Jig; #16 Barbless Jig; #18 Barbless Jig; #20 Barbless Jig; 3 ea #10 and #12; 3 ea #12 and #14; 3 ea #14 and #16; 3 ea #16 and #18; 3 ea #18 and #20; Message Custom Order\"},{\"specification_name\":\"Primary color\",\"specification_values\":\"Select a color; Natural Hare Dubbing; Olive Hare Dubbing; 3 ea color; Message Custom Order\"}]', 'null', 'null', '[\"Toys & Games\",\"Sports & Outdoor Recreation\",\"Fishing\"]', '[{\"date\":\"2024-01-17\",\"rating\":5,\"reviewr_name\":\"Pau███erd███r\",\"the_review\":\"Great seller. Quick shipping and communication\"},{\"date\":\"2023-05-12\",\"rating\":5,\"reviewr_name\":\"Dre███hor███\",\"the_review\":\"Awesome flies! Great quality and delivered fast!\"},{\"date\":\"2022-09-08\",\"rating\":5,\"reviewr_name\":\"Jon███eid███\",\"the_review\":\"Very nice and gave bonus fly\"},{\"date\":\"2021-12-18\",\"rating\":5,\"reviewr_name\":\"Kev███T. ███tz\",\"the_review\":\"20 stars if I could!\"}]', '[\"https://i.etsystatic.com/iap/40cecb/6462641301/iap_300x300.6462641301_go7kbsnr.jpg?version=0\",\"https://i.etsystatic.com/iap/3448ad/6397486082/iap_300x300.6397486082_pt2tuend.jpg?version=0\",\"https://i.etsystatic.com/iap/53a478/6374318920/iap_300x300.6374318920_jwtbgxzo.jpg?version=0\",\"https://i.etsystatic.com/iap/21a1cc/600000