INSERT INTO `etsy_sample_raw` VALUES (707, 'https://www.etsy.com/listing/1486826244/vintage-1992-temple-tornado-meme?click_key=141c73d3d048f44769c950e16f04ff3a81e35fb3%3A1486826244&click_sum=fcad8e3d&ga_order=most_relevant&ga_search_type=all&ga_view_type=gallery&ga_search_query=duracell&ref=search_grid-40812-3-32&pro=1&content_source=bf56bbbb5904282fb95763891745a1461ad99b93%253A1486826244&variation0=3567572112&variation1=3584135489', '1486826244', 'Vintage 1992 “Temple Tornado” Meme DeSantis Dirt Modified T-Shirt, Racing T-Shirt, Racing Shirt, Gift For Father, Gift For Mother', '4.5', '255', '0', '43.99', '30', '30.79', 'USD', '[\"https://i.etsystatic.com/36589265/r/il/aa730c/5037981985/il_fullxfull.5037981985_s15b.jpg\",\"https://i.etsystatic.com/36589265/r/il/6e7793/5037981981/il_fullxfull.5037981981_48wd.jpg\",\"https://i.etsystatic.com/36589265/r/il/3e56c2/4841852561/il_fullxfull.4841852561_1mdr.jpg\",\"https://i.etsystatic.com/36589265/r/il/71e2b3/4793585902/il_fullxfull.4793585902_pj1g.jpg\"]', '[{\"name\":\"Clothing\",\"url\":\"https://www.etsy.com/c/clothing?explicit=1&ref=breadcrumb_listing\"},{\"name\":\"Gender-Neutral Adult Clothing\",\"url\":\"https://www.etsy.com/c/clothing/gender-neutral-adult-clothing?explicit=1&ref=breadcrumb_listing\"},{\"name\":\"Tops & Tees\",\"url\":\"https://www.etsy.com/c/clothing/gender-neutral-adult-clothing/tops-and-tees?explicit=1&ref=breadcrumb_listing\"},{\"name\":\"T-shirts\",\"url\":\"https://www.etsy.com/c/clothing/gender-neutral-adult-clothing/tops-and-tees/tshirts?explicit=1&ref=breadcrumb_listing\"}]', 'Gender-Neutral Adult Clothing', 'Rattan Hien', 'RattanWebbingStore', '', '[\"Thanks for being here!!! We are glad to serve you. Please contact us 24/7, we are always available! With your purchase you are helping us!. We are a small family business that believes in EQUALITY, FREEDOM and LOVE for everyone.How to order:1.- Please, check our available sizes, colors and measurements.2.- Choose your design.3.- Enter your T