INSERT INTO `etsy_sample_raw` VALUES (862, 'https://www.etsy.com/listing/942412109/6-walts-worm-jig-euro-nymphs-fly-fishing?click_key=f01f2c3e38c74919beb52cade7fd68dfa8ddb2a9%3A942412109&click_sum=6c670f2f&ga_order=most_relevant&ga_search_type=all&ga_view_type=gallery&ga_search_query=duracell&ref=search_grid-504072-5-42&sts=1&content_source=2d8e55983d41555aa038985ffe72e0019b7e77b0%253A942412109&variation0=2755004187&variation1=1988128414', '942412109', '6 - Walt&#39;s Worm Jig - Euro Nymphs. Fly Fishing Flies. Caddis Flies. Colorado Fishing. Trout Flies. Tungsten. Barbless. Bead Head Nymph.', '5', '748', '7', '20', '0', '20', 'USD', '[\"https://i.etsystatic.com/26202727/r/il/99fe09/5567543496/il_fullxfull.5567543496_bcnr.jpg\",\"https://i.etsystatic.com/26202727/r/il/31b2fd/5615646353/il_fullxfull.5615646353_ayjo.jpg\"]', '[{\"name\":\"Toys & Games\",\"url\":\"https://www.etsy.com/c/toys-and-games?explicit=1&ref=breadcrumb_listing\"},{\"name\":\"Sports & Outdoor Recreation\",\"url\":\"https://www.etsy.com/c/toys-and-games/sports-and-outdoor-games?explicit=1&ref=breadcrumb_listing\"},{\"name\":\"Fishing\",\"url\":\"https://www.etsy.com/c/toys-and-games/sports-and-outdoor-games/fishing?explicit=1&ref=breadcrumb_listing\"}]', 'Sports & Outdoor Recreation', 'Ian', 'ColoradoFlyTyer', '', '[\"This is one of the most popular Euro Nymphing Jigs, especially in the US. It is exceptionally simple for flies these days, with the only flashiness coming from the tungsten bead head. This fly is a common imitation for free caddis larvae which are prolific in most trout streams. It can pass for a variety of other common bugs (scuds, crane fly larvae) and for this reason is popular on the competitive fly fishing scene. Flies like this fish well on their own or in tandem with a variety of other flies. This is tied with lead free wire to help get this fly down in the strike zone.These flies are tied on barbless, black nickel finished, 1x short, wide gape jig hooks. These hooks ride point up greatly reducing the risk of snagging and are far less stressful on fish during removal. This listing is for 6 flies. Please message me with any questions or custom orders. I\'m happy to use larger/smaller beads if desired. These are the hook sizes to corresponding bead sizes I use on my jig patterns:#10 - 4.mm#12 - 3.5 mm#14 - 3.0 mm#16 - 3.0 mm#18 - 2.5 mm#20 - 2.0 mm\\n        \\n    \\n    \\n        \\n            Learn more about this item\"]', '[\"Order today to get by Dec 26-Jan 2\",\"Returns & exchanges not accepted\",\"Cost to ship: $4.50\",\"Ships from: Longmont, CO\"]', '[{\"specification_name\":\"Size\",\"specification_values\":\"Select a size; #10 Barbless Jig; #12 Barbless Jig; #14 Barbless Jig; #16 Barbless Jig; #18 Barbless Jig; #20 Barbless Jig; 3 ea #10 and #12; 3 ea #12 and #14; 3 ea #14 and #16; 3 ea #16 and #18; 3 ea #18 and #20; Message Custom Order\"},{\"specification_name\":\"Primary color\",\"specification_values\":\"Select a color; Natural Hare Dubbing; Olive Hare Dubbing; 3 ea color; Message Custom Order\"}]', 'null', 'null', '[\"Toys & Games\",\"Sports & Outdoor Recreation\",\"Fishing\"]', '[{\"date\":\"2024-01-17\",\"rating\":5,\"reviewr_name\":\"Pau███erd███r\",\"the_review\":\"Great seller. Quick shipping and communication\"},{\"date\":\"2023-05-12\",\"rating\":5,\"reviewr_name\":\"Dre███hor███\",\"the_review\":\"Awesome flies! Great quality and delivered fast!\"},{\"date\":\"2022-09-08\",\"rating\":5,\"reviewr_name\":\"Jon███eid███\",\"the_review\":\"Very nice and gave bonus fly\"},{\"date\":\"2021-12-18\",\"rating\":5,\"reviewr_name\":\"Kev███T. ███tz\",\"the_review\":\"20 stars if I could!\"}]', '[\"https://i.etsystatic.com/iap/40cecb/6462641301/iap_300x300.6462641301_go7kbsnr.jpg?version=0\",\"https://i.etsystatic.com/iap/3448ad/6397486082/iap_300x300.6397486082_pt2tuend.jpg?version=0\",\"https://i.etsystatic.com/iap/53a478/6374318920/iap_300x300.6374318920_jwtbgxzo.jpg?version=0\",\"https://i.etsystatic.com/iap/21a1cc/600000