INSERT INTO `product` VALUES (1, 'Vòng tay Dumortierite 6 mm- Chất lượng AAA: Kiên nhẫn, Tinh thần minh mẫn & Hỗ trợ', 425000, 425000, 100, 98, 2, '[\"--> Vui lòng cuộn xuống cuối mô tả để biết chi tiết đầy đủ về mặt hàng <--Dumortierite là gì?Dumortierite là một viên đá dạy bạn tự đứng lên và nó sẽ giúp bạn kiểm soát cuộc sống của chính mình và tăng mức độ kiên nhẫn của bạn. Tinh thể này rất kích thích não bộ và nâng cao khả năng trí tuệ vì nó hỗ trợ tất cả các kỹ năng tinh thần, cả về toán học và ngôn ngữ. Nó có tính kích thích cao đối với tuyến tùng nằm phía sau con mắt thứ ba ở phía trước.', 'active', 'vong_tay', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, '2026-07-11 11:45:15.000000', '2026-05-26 17:37:29.000000');
INSERT INTO `product` VALUES (2, 'Cờ đua, Vòng tay chúc cờ đua, Quà tặng đua xe cá nhân, Đua xe, Vòng tay đua, Quà tặng cờ đua', 125000, 125000, 100, 100, 0, '[\"Vòng tay hoặc vòng chân hình lá cờ đua Hãy tặng món quà là một điều ước! Những chiếc vòng tay điều ước truyền thống này là món quà hoàn hảo cho bất kỳ dịp nào hoặc một món quà đặc biệt cho chính bạn! ☆ TẠO ĐIỀU KIỆN CỦA BẠN ☆1. Chọn màu dây của bạnĐỏ, nam việt quất, cam, vàng, xanh lục sáng, xanh lục, xanh nhạt, xanh nước biển, xanh lam, xanh mòng két, xanh nước biển, tím, tím nhạt, hồng, hồng nhạt, san hô, hạnh nhân, kẹo bơ cứng, nâu, đen, xám nhạt, xám và trắng2. Chọn của bạn Thẻ -Vòng tay ước nguyện -Từ ngữ tùy chỉnh3.', 'active', 'vong_tay', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:37:31.000000');
INSERT INTO `product` VALUES (3, 'MIỄN PHÍ VẬN CHUYỂN-Vòng tay dành cho nam giới,Trang sức nam tùy chỉnh,Vòng tay da cá nhân,Vòng tay tùy chỉnh Unisex,Dây da khắc,Ngày của Cha', 800000, 800000, 100, 100, 0, '[\"Vòng tay thông điệp ẩn, Vòng tay dành cho nam giới, Vòng tay nam tùy chỉnh, Vòng tay da cá nhân hóa, Dây đeo cổ tay bằng da khắc cho bố. Vòng tay HỢP TRANG, ĐƠN GIẢN, HIỆN ĐẠI và THOẢI MÁI này rất phù hợp để đeo trong bất kỳ dịp nào. Nó có thể được khắc ở bên trong da như một lời nhắn bí mật, ở bên ngoài như trong hình hoặc cả hai mặt của dây da.- ĐỂ ĐẶT HÀNG KÍCH THƯỚC ĐÚNG: Vui lòng tham khảo Hình ảnh danh sách.-Lưu ý: -Menu thả xuống tùy chọn cho Màu da, mặt khắc, nơi bạn', 'active', 'vong_tay', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 4.8, b'0', NULL, NULL, NULL, '2026-05-26 17:37:33.000000');
INSERT INTO `product` VALUES (4, 'Vòng cổ Duran Duran, Lấy cảm hứng từ những năm 1980, Quạt Duranie cổ điển, Kitsch Quirky, Ngôi sao nhạc rock tùy chỉnh, Mặt dây chuyền vui nhộn dành cho người nổi tiếng, Đôi cánh thiên thần đen', 806500, 604750, 100, 100, 0, '[\"Vào những năm 80, tôi là một Duranie khổng lồ. Tôi dán ảnh Simon, Nick, John, Roger và Andy khắp các bức tường của mình. Hôm nay tôi phải thú nhận...Tôi vẫn là Duranie! Bạn có phải không? Được in trên nhựa bền, nhẹ, đôi cánh thiên thần đen 2\\\" x 2\\\" có một mảnh tròn thứ hai được gắn vào giữa tuyên bố sự cống hiến bất diệt của bạn cho ban nhạc với dòng chữ \\\"I\'m Still A Duranie\\\". Tôi đã sử dụng một dây chuyền mạ bạc cho chiếc vòng cổ và cho bạn tùy chọn để chọn độ dài mà bạn thích. ***** P', 'active', 'day_chuyen', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 4.9, b'0', NULL, NULL, NULL, '2026-05-26 17:37:35.000000');
INSERT INTO `product` VALUES (5, 'Ruby Terp Pearl 10 gói', 187500, 150000, 100, 100, 0, '[\"Ngọc trai terp ruby/sapphire (100% tổng hợp AAA) 3mm hoặc 4mm được trồng trong phòng thí nghiệm. Danh sách dành cho 10 gói. Xin lưu ý: tùy chọn giao hàng miễn phí là thư tiêu chuẩn (có tem) và KHÔNG bao gồm theo dõi. Nếu bạn cần theo dõi, hãy chọn tùy chọn \\\"vận chuyển trả phí\\\" và gói hàng của bạn sẽ được gửi qua thư Hạng nhất.\\n \\n \\n \\n \\n Tìm hiểu thêm về mặt hàng này\"]', 'active', 'do_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 4.8, b'0', NULL, NULL, NULL, '2026-05-26 17:37:37.000000');
INSERT INTO `product` VALUES (6, 'Vintage 1992 “Temple Tornado” Meme DeSantis Dirt Sửa Đổi Áo Thun, Áo Thun Đua Xe, Áo Đua Xe, Quà Tặng Cho Cha, Quà Tặng Cho Mẹ', 1049750, 734750, 100, 100, 0, '[\"Cảm ơn bạn đã ở đây!!! Chúng tôi rất vui được phục vụ bạn. Vui lòng liên hệ với chúng tôi 24/7, chúng tôi luôn sẵn sàng! Với việc mua hàng của bạn, bạn đang giúp chúng tôi!. Chúng tôi là một doanh nghiệp gia đình nhỏ tin tưởng vào SỰ BÌNH ĐẲNG, TỰ DO và TÌNH YÊU cho mọi người. Cách đặt hàng:1.- Vui lòng kiểm tra kích thước, màu sắc và số đo có sẵn của chúng tôi.2.- Chọn thiết kế của bạn.3.- Nhập màu áo phông của bạn (Màu cơ bản) Ví dụ: Trắng4.- Nhập kích thước của bạn (Chúng khá vừa vặn với kích thước!) 5.- Sử dụng hộp cá nhân hóa của chúng tôi để viết chi tiết, cho', 'active', 'quan_ao_nguoi_lon_trung_tinh_ve_gioi_tinh', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 4.5, b'0', NULL, NULL, NULL, '2026-05-26 17:37:38.000000');
INSERT INTO `product` VALUES (7, 'Vòng cổ mặt dây chuyền vàng/bạc của Circuit of the America có dây chuyền', 400000, 400000, 100, 100, 0, '[\"Mặt dây chuyền này là một cách hoàn hảo để thể hiện tình yêu của bạn đối với thế giới đua xe nhanh và khốc liệt. Tác phẩm độc đáo này được chế tạo với độ chính xác và sự chú ý đến từng chi tiết, giống như chính đường đua COTA mang tính biểu tượng. Circuit of the Americas (COTA) là một đường đua đẳng cấp thế giới nằm ở Austin, Texas, Hoa Kỳ. Nó được biết đến là nơi tổ chức nhiều sự kiện đua xe thể thao khác nhau, bao gồm cả Giải đua xe Công thức Một United States Grand Prix. Bố cục của COTA được thiết kế đặc biệt để khuyến khích các cơ hội vượt, với phạm vi rộng', 'active', 'day_chuyen', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 4.8, b'0', NULL, NULL, NULL, '2026-05-26 17:37:42.000000');
INSERT INTO `product` VALUES (8, 'Gorillaz Pac-Man | Móc khóa acrylic hai mặt 7,5cm (~2,95 in.)', 350000, 350000, 100, 100, 0, '[\"🌟 Về những móc khóa này:→ Lớp bảo vệ bằng epoxy ở mặt trước • Cao 7,5 cm (khoảng 2,95 inch)\\n \\n \\n \\n \\n Tìm hiểu thêm về mặt hàng này\"]', 'active', 'moc_khoa_day_buoc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:37:44.000000');
INSERT INTO `product` VALUES (9, 'Vòng tay thắt nút cá tính cho Nam - Quà Giáng Sinh Tùy Chỉnh Cho Bố/Chồng/Con Trai/Anh/Bố Vợ - Quà Tặng Ý Nghĩa Cho Nam Giới', 1475000, 1475000, 100, 100, 0, '[\"Vòng tay nút thắt vô cực này là món quà Giáng sinh hoàn hảo cho những người đàn ông đặc biệt trong cuộc đời bạn—cho dù đó là chồng, cha hay con trai của bạn. Được chế tác tinh xảo với sự kết hợp giữa chất liệu da sang trọng và nút thắt nút vô cực bằng thép không gỉ, chiếc vòng tay này tượng trưng cho tình yêu bất tận và phong cách vượt thời gian.★ CHI TIẾT MỤC: • Chất liệu chất lượng: Được chế tác từ Da Nappa cao cấp, loại da này được làm có độ bền cao, không thấm nước và mịn màng, khiến nó trở thành lựa chọn lý tưởng cho đồ trang sức cao cấp. cl', 'active', 'vong_tay', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 4.8, b'0', NULL, NULL, NULL, '2026-05-26 17:37:45.000000');
INSERT INTO `product` VALUES (10, 'Interlagos Brazil Racing Wall Art Racing Art Car Wall Art Racing Car Wall Art Poster Art Vintage Racing Art Decor Ôtô Racing Art', 2817500, 2394750, 100, 100, 0, '[\"Xin chào! Cảm ơn bạn đã xem qua bộ sưu tập áp phích đường đua tối giản mới của chúng tôi, được thiết kế để nắm bắt được bản chất của các đường đua mang tính biểu tượng nhất. Nâng cao ngôi nhà, văn phòng, hang động, nhà để xe hoặc bất kỳ bức tường nào của bạn để nắm bắt được bản chất của cuộc đua! Các bản in của chúng tôi là một món quà tuyệt vời cho những người hâm mộ đua xe trong cuộc sống của bạn! GIẢM GIÁ:- Giảm 5% khi bạn mua 2+ Mã bản in: BUY2GET5- Giảm 10% khi bạn mua 3+ Mã bản in: KÍCH THƯỚC MUA3GET10:- 8x10 Inch- 12x16 Inch- 16x20 Inch- 18x24 Inch- 24x36 Inch THÔNG TIN CANVAS:', 'active', 'ban_in', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 4.5, b'0', NULL, NULL, NULL, '2026-05-26 17:37:47.000000');
INSERT INTO `product` VALUES (11, 'Bản in nghệ thuật Dundalk, Poster du lịch treo tường Dundalk, Trang trí tường Ireland, Tranh treo tường Dundalk, Bản in thành phố Ireland', 1577000, 1182750, 100, 99, 1, '[\"Đắm chìm trong sự quyến rũ rực rỡ của Dundalk với tác phẩm nghệ thuật tuyệt đẹp này. Ghi lại những con đường đẹp như tranh vẽ, các địa danh lịch sử và phong cảnh tuyệt đẹp của thành phố Ireland quyến rũ này, tác phẩm nghệ thuật này mang sức hấp dẫn độc đáo của Dundalk vào ngôi nhà của bạn. Hoàn hảo cho những ai đánh giá cao di sản Ireland và các thành phố sôi động, tác phẩm in này như một lời nhắc nhở thường xuyên về vẻ đẹp quyến rũ của Dundalk. Trưng bày nó trong phòng khách, phòng ngủ hoặc văn phòng của bạn để truyền cảm giác thích phiêu lưu và một mối quan hệ sâu sắc.', 'active', 'ban_in', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 4.8, b'0', NULL, NULL, '2026-07-11 11:45:15.000000', '2026-05-26 17:37:49.000000');
INSERT INTO `product` VALUES (12, 'Tên cá nhân Vòng tay đính cườm tùy chỉnh, Vòng tay da nam cho chồng Bạn trai Bố, Vòng tay khắc cho anh ấy, Quà Giáng sinh cho anh ấy', 2348000, 1174000, 100, 100, 0, '[\"Giới thiệu Vòng tay da nam cá tính có khắc tên trẻ em của chúng tôi, một món đồ trang sức tùy chỉnh được thiết kế để trở thành một món quà ý nghĩa dành cho những người đàn ông đặc biệt trong cuộc đời bạn. Chiếc vòng tay trang nhã này được chế tác từ da chất lượng cao, đảm bảo độ bền và sự thoải mái, khiến nó trở thành phụ kiện lý tưởng để đeo hàng ngày. Điều làm nên sự khác biệt của chiếc vòng tay này là khả năng cá nhân hóa tên của những người thân yêu, đặc biệt là trẻ em, khiến nó trở thành vật kỷ niệm quý giá và có giá trị tình cảm.', 'active', 'vong_tay', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 4.8, b'0', NULL, NULL, NULL, '2026-05-26 17:37:51.000000');
INSERT INTO `product` VALUES (13, 'Áp phích phim Bull Durham, áp phích phim cổ điển, in canvas, nghệ thuật treo tường, trang trí phòng, trang trí nhà cửa, quà tặng, áp phích bọc', 529750, 344500, 100, 100, 0, '[\"✨Chú ý: Bạn có thể chọn giữa áp phích Poster có khung và áp phích bọc.⭐Áp phích không khung không hiển thị khung trong ảnh.🌈Chúng tôi cẩn thận tạo ra từng áp phích để đảm bảo màu sắc rực rỡ và các chi tiết sống động như thật, tăng thêm bầu không khí và cảm giác không gian cho căn phòng của bạn.🏡Bạn có thể thay đổi bầu không khí trong không gian của mình với những áp phích này. Bạn có thể sử dụng nó ở nhiều khu vực như phòng trò chơi, hang người, phòng khách, văn phòng, trong nhà và ngoài trời.🎁Bạn có thể cho những người thân yêu của mình xem giá trị của chúng bằng cách tặng những bài đăng này', 'active', 'ban_in', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 4.7, b'0', NULL, NULL, NULL, '2026-05-26 17:37:54.000000');
INSERT INTO `product` VALUES (14, 'Vòng tay cá tính - Vòng tay vàng cuộn 14kt - Vòng tay tên - Vòng tay dây - Made to Order size 6 đến 8 Dây quấn - Thủ công', 2125000, 2125000, 100, 100, 0, '[\"ĐỪNG ĐOÁN KÍCH THƯỚC CỦA BẠN!!! -------- Vui lòng cung cấp kích thước cổ tay tính bằng inch chứ không phải kích thước mà bạn nghĩ rằng bạn muốn cho chiếc vòng tay.-----Truy cập https://print-ruler.com/ nơi bạn có thể in ra một chiếc thước ---Và độ chính xác của nó+++Vòng tay NÀY LÀ CHỐNG NƯỚC VÀ CHỐNG ố+++TÊN VÒNG TAY (MỌI TÊN E GỬI CHO TÔI VỚI TÊN) THỜI TRANG CAO CẤP ĐỘC ĐÁO THỦ CÔNG 14KT VÀNG CÁN TRONG THIẾT KẾ ĐỘC ĐÁO MẢNH THỦ CÔNG ĐỘC QUYỀN SẼ LÀM BẠN ĐƯỢC GHI NHẬN! TRỌNG LƯỢNG NHẸ VÀ DỄ DÀNG ĐEO VÒNG TAY LÀ 10MM', 'active', 'vong_tay', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 4.8, b'0', NULL, NULL, NULL, '2026-05-26 17:37:57.000000');
INSERT INTO `product` VALUES (15, 'Vòng tay mô-men xoắn cho nam, Quà tặng đầu bi cho anh ấy, Vòng tay cho chồng hoặc con trai, Quà tặng khắc theo yêu cầu, Đồ trang sức nam xu hướng, Cá nhân hóa', 1987750, 1987750, 100, 100, 0, '[\"Vòng tay mô-men xoắn dành cho nam, Quà tặng đầu bi cho anh ấy, Vòng tay chồng hoặc cha, Quà tặng khắc tùy chỉnh, Đồ trang sức của người đàn ông thịnh hành, Được cá nhân hóa. Vòng tay nam phong cách này đi kèm với khắc miễn phí. Chọn từ 5 phông chữ và thêm văn bản của bạn vào hộp được cung cấp. Nếu không chọn phông chữ, chúng tôi sẽ sử dụng phông chữ 3. Bao gồm 30 ký tự. Nếu \'bên trong/bên ngoài\' không được chỉ định, chúng tôi sẽ khắc bên trong. Chiều rộng bên trong 64mm và chiều cao bên trong 45mm. Linh hoạt. để phù hợp với mọi kích cỡ cổ tay. Không thấm nước và không bị xỉn màu.________________', 'active', 'vong_tay', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 4.8, b'0', NULL, NULL, NULL, '2026-05-26 17:37:59.000000');
INSERT INTO `product` VALUES (16, 'Nghệ thuật đường đua kim loại tùy chỉnh - Được làm thủ công tại Hoa Kỳ, Giá đỡ từ tính, Đường đua và mạch địa phương, Hang người, Điêu khắc, Trang trí, Trang trí tường', 2200000, 1760000, 100, 100, 0, '[\"**Trong quá trình mua hàng, vui lòng để lại tên bản nhạc bạn muốn trong ghi chú đơn hàng. Nếu bạn muốn tên bản nhạc được đính kèm với bản nhạc và có bất kỳ yêu cầu đặc biệt nào khác, vui lòng để lại tên bản nhạc đó trong phần ghi chú của đơn đặt hàng, cảm ơn bạn!!** Nếu không được chỉ định, bản nhạc sẽ mặc định không có tên bản nhạc. Nếu có kích thước bạn không muốn nhìn thấy, vui lòng gửi tin nhắn cho tôi. Mặt hàng này dành cho một bản phác thảo bản nhạc duy nhất mà bạn chọn với phần cứng gắn từ tính để dễ dàng sử dụng', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 4.9, b'0', NULL, NULL, NULL, '2026-05-26 17:38:01.000000');
INSERT INTO `product` VALUES (17, 'Vòng tay chúc thỏ, Quà tặng người yêu thỏ, Thẻ tình bạn dễ thương, Chúc mừng bùa thỏ, Vòng tay dây', 97750, 87750, 100, 100, 0, '[\"Vòng tay ước nguyện thỏ, Quà tặng người yêu thỏ, Thẻ tình bạn dễ thương, Giấy chúc mừng thỏ quyến rũ, Vòng tay dây. Thẻ vòng tay ước mơ thủ công này có nội dung - Nhìn thấy điều này và nghĩ đến bạn! Mặc dù hoàn hảo như một món quà nhỏ, chiếc vòng tay ước nguyện nhỏ này cũng có thể được nhét vào một tấm thiệp hoặc gửi cùng với một món quà. Ý tưởng đằng sau một chiếc vòng tay ước mơ là bạn thực hiện một điều ước khi đặt nó trên cổ tay. Theo thời gian, dây sẽ mòn và điều ước của bạn thành hiện thực! Vòng tay này được thiết kế để buộc vào và không có dây buộc. đóng cửa.Ea', 'active', 'vong_tay', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 4.9, b'0', NULL, NULL, NULL, '2026-05-26 17:38:03.000000');
INSERT INTO `product` VALUES (18, '29 Màu, Vòng tay tạ, Vòng tay quyến rũ tạ, Vòng tay nam - nữ, Quà tặng cho nam và nữ, Nâng tạ CrossFit Fitness', 265250, 265250, 100, 100, 0, '[\"Độ dài của chiếc vòng tay này có thể điều chỉnh được và có thể điều chỉnh nút trượt đóng lại. Nếu cổ tay của bạn từ 15 cm đến 20 cm - chiếc vòng tay này sẽ vừa vặn với bạn mà không gặp vấn đề gì. Vui lòng duyệt qua cửa hàng của chúng tôi để biết thêm tình bạn phù hợp vòng tay!https://www.etsy.com/uk/shop/CharmingDesignCrafts?ref=seller-platform-mcnav§ion_id=27396964https://www.etsy.com/uk/shop/CharmingDesignCrafts?ref=seller-platform-mcnav\\n \\n \\n \\n \\n Tìm hiểu thêm về mặt hàng này\"]', 'active', 'vong_tay', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 4.9, b'0', NULL, NULL, NULL, '2026-05-26 17:38:06.000000');
INSERT INTO `product` VALUES (19, 'Vòng tay liên kết Cuba bạc 925 nam nữ 1mm-15mm 7\" 8&quot; 9&quot; QUÀ TẶNG CHO Nam Nữ ĐỘ DÀI TÙY CHỈNH CUNG CẤP', 4525000, 3846250, 100, 100, 0, '[\"Những chiếc vòng tay này được làm bằng bạc 925. Vòng tay liên kết Cuba được biết đến với độ bền và độ sáng bóng. Trọng lượng gần đúng của vòng tay 9\" như sau: 1mm 0,7 gram1,5mm 1,8 gram2mm 2,4 gram3mm 3,2 gram4mm 4,6 gram4,5mm 7,3 gram6mm 11,7 gram7mm 16,1 gram8mm 21,3 gram10mm 24,6 gram11mm 40,1 gram13mm 50,8 gram15mm 59,9 gram Có sẵn ở kích thước 7\\\" 8\\\" hoặc 9\\\"Các vòng tay được đánh dấu 925 để đảm bảo tính xác thực của kim loại. Đi kèm với một hộp. Để trả lại hoặc trao đổi, vui lòng liên hệ với tôi vớii', 'active', 'day_chuyen', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 4.9, b'0', NULL, NULL, NULL, '2026-05-26 17:38:08.000000');
INSERT INTO `product` VALUES (20, '6 - Walt\'s Worm Jig - Euro Nymphs. Ruồi câu cá. Ruồi Caddis. Câu cá Colorado. Ruồi cá hồi. Vonfram. Không có lông. Nữ thần đầu hạt.', 500000, 500000, 100, 100, 0, '[\"Đây là một trong những loại Jigs Euro Nymphing phổ biến nhất, đặc biệt là ở Hoa Kỳ. Ngày nay, nó cực kỳ đơn giản đối với ruồi, với điểm sáng duy nhất đến từ đầu hạt vonfram. Loại ruồi này thường bắt chước ấu trùng caddis tự do sinh sôi nảy nở ở hầu hết các dòng cá hồi. Nó có thể truyền sang nhiều loại bọ phổ biến khác (ấu trùng, ấu trùng ruồi sếu) và vì lý do này rất phổ biến trong hoạt động câu cá bằng ruồi có tính cạnh tranh. Ruồi như loài cá này tự hoạt động hoặc kết hợp với nhiều loại khác', 'active', 'the_thao_giai_tri_ngoai_troi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:38:10.000000');
INSERT INTO `product` VALUES (21, 'Vòng cổ mặt dây chuyền đá mặt trăng Aurora thủ công', 1376750, 1376750, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng aurora chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:38:13.000000');
INSERT INTO `product` VALUES (22, 'Tên tùy chỉnh Vòng cổ lấp đầy vàng Chạng vạng', 1250250, 1250250, 100, 100, 0, 'Vòng cổ tên chạng vạng được cá nhân hóa được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:38:15.000000');
INSERT INTO `product` VALUES (23, 'Vòng cổ thạch anh phong cách cổ điển', 1402250, 1402250, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thạch nam lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:38:17.000000');
INSERT INTO `product` VALUES (24, 'Vòng tay tình bạn lũa dệt thủ công', 324250, 324250, 100, 100, 0, 'Vòng tay tình bạn bằng gỗ lũa dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:38:20.000000');
INSERT INTO `product` VALUES (25, 'Vòng đeo tay bằng đồng rèn Riverstone', 1461750, 1461750, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ bằng đá ven sông. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:38:22.000000');
INSERT INTO `product` VALUES (26, 'Vòng tay đá quý Pebble Beach đính cườm', 745000, 745000, 100, 100, 0, 'Vòng tay hạt đá quý bãi biển được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:38:24.000000');
INSERT INTO `product` VALUES (27, 'Bông tai bạc Foxglove được rèn bằng tay', 758000, 758000, 100, 100, 0, 'Khuyên tai dạng đinh tán bằng bạc được rèn thủ công với họa tiết hình găng tay cáo. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:38:26.000000');
INSERT INTO `product` VALUES (28, 'Bông tai pha lê Blackberry có dây', 1441000, 1441000, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê blackberry. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:38:29.000000');
INSERT INTO `product` VALUES (29, 'Vòng xếp quế được đóng dấu bằng tay', 744250, 744250, 100, 100, 0, 'Chiếc nhẫn xếp chồng quế được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:38:31.000000');
INSERT INTO `product` VALUES (30, 'Nhẫn bạch đậu khấu pha lê thô', 1915250, 1915250, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê bạch đậu khấu thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với lớp vỏ bạch đậu khấu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:38:33.000000');
INSERT INTO `product` VALUES (31, 'Nến sáp ong cỏ ba lá đổ tay', 618000, 618000, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu cỏ ba lá. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:38:35.000000');
INSERT INTO `product` VALUES (32, 'Nến thơm cây kế sáp dừa', 645250, 645250, 100, 100, 0, 'Nến thơm cây kế lô nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:38:36.000000');
INSERT INTO `product` VALUES (33, 'Macramé Wisteria treo tường', 2513750, 2513750, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo treo trên dây bông tự nhiên hoa tử đằng. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:38:38.000000');
INSERT INTO `product` VALUES (34, 'Vòng hoa hồng tước khô', 1173000, 1173000, 100, 100, 0, 'Vòng hoa khô thủ công có hình các loài thực vật theo mùa. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:38:39.000000');
INSERT INTO `product` VALUES (35, 'Kệ Gỗ Falcon Chạm Khắc Bằng Tay', 3718250, 3718250, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh chim ưng. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:38:41.000000');
INSERT INTO `product` VALUES (36, 'Thớt quả óc chó Osprey cuối hạt', 2543750, 2543750, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó chim ưng và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:38:44.000000');
INSERT INTO `product` VALUES (37, 'Bộ bát sứ Hawkweed ném tay', 1995750, 1995750, 100, 100, 0, 'Bộ 4 chiếc bát gốm sứ thủ công phủ men phản ứng hawkweed. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:38:46.000000');
INSERT INTO `product` VALUES (38, 'Mũ len Merino Dogwood dệt kim bằng tay', 1334750, 1334750, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu sơn thù du. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:38:48.000000');
INSERT INTO `product` VALUES (39, 'Dây buộc tóc bằng ren Sweetgrass', 195750, 195750, 100, 100, 0, 'Dây buộc móc thủ công với họa tiết ren bông cỏ ngọt. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:38:51.000000');
INSERT INTO `product` VALUES (40, 'Khăn choàng lụa đuôi mèo nhuộm tay', 3439250, 3439250, 100, 100, 0, 'Khăn choàng lụa nhuộm tay sang trọng họa tiết màu nước đuôi mèo. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:38:53.000000');
INSERT INTO `product` VALUES (41, 'Ly hợp da Bullrush khâu tay', 3143750, 3143750, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay bằng da bò. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:38:56.000000');
INSERT INTO `product` VALUES (42, 'Ba lô vải cói sáp', 3268500, 3268500, 100, 100, 0, 'Balo vải sáp dày dặn viền da cói. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:38:58.000000');
INSERT INTO `product` VALUES (43, 'Tranh sáp Encaustic Bracken nguyên bản', 6714250, 6714250, 100, 100, 0, 'Bức tranh sơn dầu nguyên bản (sáp nóng) với bố cục trừu tượng dương xỉ. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:39:01.000000');
INSERT INTO `product` VALUES (44, 'Tượng gốm me chua điêu khắc bằng tay', 1609250, 1609250, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết được tráng men màu me chua. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:39:03.000000');
INSERT INTO `product` VALUES (45, 'In ảnh thiên nhiên hoa cúc thiên nhiên mỹ thuật', 1553500, 1553500, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên hoa cúc nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:39:05.000000');
INSERT INTO `product` VALUES (46, 'Xà phòng nghệ nhân cỏ thi sữa dê', 327500, 327500, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm cỏ thi và các tạp chất thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:39:07.000000');
INSERT INTO `product` VALUES (47, 'Dầu gội Solid Valerian', 376000, 376000, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược valerian. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:39:10.000000');
INSERT INTO `product` VALUES (48, 'Tẩy tế bào chết toàn thân bằng đường Mugwort', 398250, 398250, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường ngải cứu thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu ngải cứu. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:39:12.000000');
INSERT INTO `product` VALUES (49, 'Tạp chí da cây tầm ma đóng bìa tay', 710750, 710750, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da cây tầm ma và sợi vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:39:14.000000');
INSERT INTO `product` VALUES (50, 'Thiệp cưới cây ngưu bàng màu nước', 170750, 170750, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật cây ngưu bàng. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:39:16.000000');
INSERT INTO `product` VALUES (51, 'Câu đố bằng gỗ hình bông tuyết vẽ tay', 1613750, 1613750, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay hình giọt nước tuyết. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:39:19.000000');
INSERT INTO `product` VALUES (52, 'Đũa phép đồ chơi cho mèo Crocus bện bằng tay', 387000, 387000, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây bông bện hoa nghệ tây và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:39:21.000000');
INSERT INTO `product` VALUES (53, 'Vòng cổ mặt dây chuyền đá mặt trăng Trillium thủ công', 1474000, 1474000, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng trillium chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:39:23.000000');
INSERT INTO `product` VALUES (54, 'Tên tùy chỉnh Vòng cổ lấp đầy vàng Bloodroot', 2563000, 2563000, 100, 100, 0, 'Vòng cổ tên Bloodroot cá nhân hóa được đóng dấu thủ công trên đĩa phủ vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:39:26.000000');
INSERT INTO `product` VALUES (55, 'Vòng cổ mặt dây chuyền Hepatica phong cách cổ điển', 2362500, 2362500, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng Hepatica lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:39:28.000000');
INSERT INTO `product` VALUES (56, 'Vòng tay tình bạn Mayapple dệt tay', 688250, 688250, 100, 100, 0, 'Vòng tay tình bạn mayapple dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:39:30.000000');
INSERT INTO `product` VALUES (57, 'Vòng đeo tay bằng đồng rèn Elderflower', 979000, 979000, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ hình hoa cơm cháy. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:39:33.000000');
INSERT INTO `product` VALUES (58, 'Vòng tay đá quý Hawthorn đính cườm', 703500, 703500, 100, 100, 0, 'Vòng tay hạt đá quý táo gai được xâu chuỗi bằng dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:39:35.000000');
INSERT INTO `product` VALUES (59, 'Bông tai bạc Blackthorn được rèn thủ công', 1295750, 1295750, 100, 100, 0, 'Bông tai đinh tán bằng bạc sterling được rèn thủ công với kết cấu gai đen. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:39:37.000000');
INSERT INTO `product` VALUES (60, 'Bông tai pha lê Rowan có dây', 721000, 721000, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê thanh lương trà. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:39:39.000000');
INSERT INTO `product` VALUES (61, 'Vòng xếp chồng Sloe được đóng dấu bằng tay', 953250, 953250, 100, 100, 0, 'Chiếc nhẫn xếp chồng sloe được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:39:42.000000');
INSERT INTO `product` VALUES (62, 'Nhẫn pha lê Damson thô', 1443750, 1443750, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê Damson thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với lớp gỉ dadamson.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:39:44.000000');
INSERT INTO `product` VALUES (63, 'Nến sáp ong hồng đổ bằng tay', 939000, 939000, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu hồng. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:39:46.000000');
INSERT INTO `product` VALUES (64, 'Nến thơm mộc qua sáp dừa', 1010750, 1010750, 100, 100, 0, 'Nến thơm mộc qua lô nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:39:48.000000');
INSERT INTO `product` VALUES (65, 'Treo tường Macramé Medlar', 2633750, 2633750, 100, 100, 0, 'Bức tường macramé thắt nút thủ công phức tạp treo bằng dây bông tự nhiên sơn tra. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:39:49.000000');
INSERT INTO `product` VALUES (66, 'Vòng hoa dâu tằm khô', 926000, 926000, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa dâu tằm. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:39:51.000000');
INSERT INTO `product` VALUES (67, 'Kệ Gỗ Ngỗng Chạm Khắc Bằng Tay', 1192000, 1192000, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh quả lý gai. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:39:53.000000');
INSERT INTO `product` VALUES (68, 'Thớt quả óc chó việt quất cuối hạt', 2855500, 2855500, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó việt quất và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:39:54.000000');
INSERT INTO `product` VALUES (69, 'Bộ bát gốm Crowberry ném tay', 2880250, 2880250, 100, 100, 0, 'Bộ 4 chiếc bát sứ cầm tay phủ men phản ứng quả quạ. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:39:56.000000');
INSERT INTO `product` VALUES (70, 'Mũ len Merino Cloudberry dệt kim bằng tay', 643250, 643250, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ 100% len merino superwash với màu sắc dâu tây. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:39:58.000000');
INSERT INTO `product` VALUES (71, 'Dây buộc tóc bằng ren Lingonberry', 277750, 277750, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông lingonberry. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:40:00.000000');
INSERT INTO `product` VALUES (72, 'Khăn choàng lụa Bearberry nhuộm tay', 1643750, 1643750, 100, 100, 0, 'Khăn choàng lụa quấn tay sang trọng họa tiết màu nước Bearberry. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:40:02.000000');
INSERT INTO `product` VALUES (73, 'Ly hợp da Hackberry khâu tay', 1860750, 1860750, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay hackberry. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:40:04.000000');
INSERT INTO `product` VALUES (74, 'Ba lô Buffaloberry vải sáp', 2144250, 2144250, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da trâu. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:40:07.000000');
INSERT INTO `product` VALUES (75, 'Tranh sáp Aurora nguyên bản', 3397250, 3397250, 100, 100, 0, 'Bức tranh sơn dầu nguyên bản (sáp nóng) với bố cục trừu tượng cực quang. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:40:09.000000');
INSERT INTO `product` VALUES (76, 'Tượng gốm Chạng vạng được điêu khắc bằng tay', 1600500, 1600500, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết được tráng men chạng vạng. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:40:12.000000');
INSERT INTO `product` VALUES (77, 'Mỹ thuật Heather Nature Ảnh In', 736250, 736250, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên cây thạch nam nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:40:14.000000');
INSERT INTO `product` VALUES (78, 'Xà Phòng Nghệ Nhân Gỗ Lũa Sữa Dê', 430750, 430750, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm gỗ lũa và các tạp chất thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:40:16.000000');
INSERT INTO `product` VALUES (79, 'Thanh gội đầu Solid Riverstone', 245750, 245750, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược riverstone. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:40:18.000000');
INSERT INTO `product` VALUES (80, 'Tẩy tế bào chết Sugar Pebble Beach', 366250, 366250, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường sỏi bãi biển thủ công với gốc dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu bãi biển sỏi. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:40:21.000000');
INSERT INTO `product` VALUES (81, 'Tạp chí da Foxglove ràng buộc bằng tay', 1067000, 1067000, 100, 100, 0, 'Nhật ký đóng bìa tay với bìa da mao địa hoàng và dây vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:40:23.000000');
INSERT INTO `product` VALUES (82, 'Thiệp cưới Blackberry màu nước', 216000, 216000, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật dâu đen. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:40:25.000000');
INSERT INTO `product` VALUES (83, 'Câu đố bằng gỗ quế vẽ tay', 1371000, 1371000, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay bằng quế. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:40:28.000000');
INSERT INTO `product` VALUES (84, 'Cây đũa phép đồ chơi cho mèo bạch đậu khấu bện tay', 323750, 323750, 100, 100, 0, 'Đồ chơi đũa phép mèo thủ công với dây bông bện bạch đậu khấu và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:40:30.000000');
INSERT INTO `product` VALUES (85, 'Vòng cổ mặt dây chuyền đá mặt trăng Clover thủ công', 1864000, 1864000, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng cỏ ba lá chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:40:32.000000');
INSERT INTO `product` VALUES (86, 'Tên tùy chỉnh Vòng cổ mạ vàng Thistle', 2604000, 2604000, 100, 100, 0, 'Vòng cổ tên cây kế được cá nhân hóa được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:40:35.000000');
INSERT INTO `product` VALUES (87, 'Vòng cổ mặt dây chuyền Wisteria phong cách cổ điển', 1294500, 1294500, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:40:37.000000');
INSERT INTO `product` VALUES (88, 'Vòng tay tình bạn Wren dệt tay', 632000, 632000, 100, 100, 0, 'Vòng tay tình bạn wren dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:40:39.000000');
INSERT INTO `product` VALUES (89, 'Vòng đeo tay bằng đồng hình chim ưng rèn', 1269500, 1269500, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ hình chim ưng. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:40:41.000000');
INSERT INTO `product` VALUES (90, 'Vòng tay đá quý Osprey đính cườm', 1328000, 1328000, 100, 100, 0, 'Vòng tay hạt đá quý chim ưng được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:40:43.000000');
INSERT INTO `product` VALUES (91, 'Bông tai bạc Hawkweed được rèn thủ công', 983000, 983000, 100, 100, 0, 'Bông tai đinh tán bằng bạc sterling được rèn thủ công với họa tiết hawkweed. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:40:46.000000');
INSERT INTO `product` VALUES (92, 'Bông tai pha lê Dogwood bọc dây', 1061500, 1061500, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê bằng gỗ sơn thù du. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:40:48.000000');
INSERT INTO `product` VALUES (93, 'Vòng xếp cỏ ngọt được đóng dấu bằng tay', 379500, 379500, 100, 100, 0, 'Chiếc nhẫn xếp chồng cỏ ngọt được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:40:50.000000');
INSERT INTO `product` VALUES (94, 'Nhẫn tuyên bố Cattail pha lê thô', 822500, 822500, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê cattail thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thiện với patina đuôi mèo.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:40:52.000000');
INSERT INTO `product` VALUES (95, 'Nến sáp ong Bullrush đổ bằng tay', 413250, 413250, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu cây bách xù. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:40:54.000000');
INSERT INTO `product` VALUES (96, 'Nến thơm cói sáp dừa', 474250, 474250, 100, 100, 0, 'Nến thơm cói số lượng nhỏ làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:40:56.000000');
INSERT INTO `product` VALUES (97, 'Treo tường Macramé Bracken', 1321000, 1321000, 100, 100, 0, 'Bức tường macramé được thắt nút bằng tay phức tạp treo bằng dây bông tự nhiên dương xỉ. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:40:57.000000');
INSERT INTO `product` VALUES (98, 'Vòng hoa sầu riêng khô', 1160500, 1160500, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa màu me chua. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:40:59.000000');
INSERT INTO `product` VALUES (99, 'Kệ Gỗ Hoa Cúc Chạm Khắc Bằng Tay', 2737750, 2737750, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết viền hoa cúc. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:41:00.000000');
INSERT INTO `product` VALUES (100, 'Thớt quả óc chó Yarrow cuối hạt', 3783000, 3783000, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó yarrow và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:41:02.000000');
INSERT INTO `product` VALUES (101, 'Bộ bát sứ Valerian ném tay', 2835750, 2835750, 100, 100, 0, 'Bộ 4 bát gốm sứ tráng men phản ứng valerian. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:41:04.000000');
INSERT INTO `product` VALUES (102, 'Mũ len Merino Mugwort dệt kim bằng tay', 1523000, 1523000, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu ngải cứu. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:41:06.000000');
INSERT INTO `product` VALUES (103, 'Dây buộc tóc bằng ren cây tầm ma', 185250, 185250, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông tầm ma. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:41:08.000000');
INSERT INTO `product` VALUES (104, 'Khăn choàng lụa ngưu bàng nhuộm tay', 3944750, 3944750, 100, 100, 0, 'Khăn choàng quấn lụa nhuộm tay sang trọng họa tiết màu nước cây ngưu bàng. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:41:10.000000');
INSERT INTO `product` VALUES (105, 'Ly hợp da Snowdrop khâu tay', 1566750, 1566750, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay hình giọt nước tuyết. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:41:12.000000');
INSERT INTO `product` VALUES (106, 'Ba lô vải Crocus sáp', 2369250, 2369250, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da crocus. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:41:15.000000');
INSERT INTO `product` VALUES (107, 'Tranh sáp gốc Trillium Encaustic', 3171500, 3171500, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng trillium. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:41:17.000000');
INSERT INTO `product` VALUES (108, 'Tượng gốm Bloodroot điêu khắc bằng tay', 1701750, 1701750, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết men đỏ. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:41:20.000000');
INSERT INTO `product` VALUES (109, 'Mỹ Thuật In Ảnh Thiên Nhiên Hepatica', 518000, 518000, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên Hepatica nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:41:22.000000');
INSERT INTO `product` VALUES (110, 'Xà Phòng Thủ Công Mayapple Sữa Dê', 245250, 245250, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm mayapple và các chất thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:41:24.000000');
INSERT INTO `product` VALUES (111, 'Thanh dầu gội Solid Elderflower', 374750, 374750, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược hoa cơm cháy. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:41:26.000000');
INSERT INTO `product` VALUES (112, 'Tẩy tế bào chết toàn thân Sugar Hawthorn', 702250, 702250, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường táo gai thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu táo gai. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:41:29.000000');
INSERT INTO `product` VALUES (113, 'Tạp chí da Blackthorn đóng bìa tay', 1269250, 1269250, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da mận gai và dây vải lanh đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:41:31.000000');
INSERT INTO `product` VALUES (114, 'Thiệp cưới màu nước Rowan', 218250, 218250, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật thanh lương trà. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:41:33.000000');
INSERT INTO `product` VALUES (115, 'Câu đố bằng gỗ Sloe vẽ tay', 948750, 948750, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay sloe. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:41:35.000000');
INSERT INTO `product` VALUES (116, 'Đũa phép đồ chơi cho mèo Damson bện tay', 232500, 232500, 100, 100, 0, 'Đồ chơi đũa phép cho mèo được làm thủ công với dây cotton bện damson và phần đính kèm lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:41:38.000000');
INSERT INTO `product` VALUES (117, 'Vòng cổ mặt dây chuyền đá mặt trăng hình trái hồng thủ công', 2173250, 2173250, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng hồng chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:41:40.000000');
INSERT INTO `product` VALUES (118, 'Tên tùy chỉnh Vòng cổ Quince Gold-Fill', 2605750, 2605750, 100, 100, 0, 'Vòng cổ tên mộc qua được cá nhân hóa được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:41:42.000000');
INSERT INTO `product` VALUES (119, 'Vòng cổ Medlar theo phong cách cổ điển', 2623750, 2623750, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:41:44.000000');
INSERT INTO `product` VALUES (120, 'Vòng tay tình bạn dâu tằm dệt tay', 399250, 399250, 100, 100, 0, 'Vòng tay tình bạn dâu tằm dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:41:47.000000');
INSERT INTO `product` VALUES (121, 'Vòng đeo tay bằng đồng rèn quả lý gai', 1082750, 1082750, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ màu quả lý gai. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:41:49.000000');
INSERT INTO `product` VALUES (122, 'Vòng tay đá quý việt quất đính cườm', 816000, 816000, 100, 100, 0, 'Vòng tay hạt đá quý việt quất được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:41:51.000000');
INSERT INTO `product` VALUES (123, 'Bông tai bạc Crowberry được rèn bằng tay', 1029250, 1029250, 100, 100, 0, 'Bông tai đinh tán bằng bạc được rèn thủ công với kết cấu quả quạ. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:41:53.000000');
INSERT INTO `product` VALUES (124, 'Bông tai pha lê Cloudberry có dây', 1398500, 1398500, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn là pha lê hình quả mâm xôi. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:41:55.000000');
INSERT INTO `product` VALUES (125, 'Vòng xếp chồng Lingonberry được đóng dấu bằng tay', 556250, 556250, 100, 100, 0, 'Nhẫn xếp chồng lingonberry được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:41:59.000000');
INSERT INTO `product` VALUES (126, 'Nhẫn tuyên bố Bearberry pha lê thô', 1827000, 1827000, 100, 100, 0, 'Chiếc nhẫn nổi bật có pha lê Bearberry thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với lớp vỏ Bearberry.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:42:01.000000');
INSERT INTO `product` VALUES (127, 'Nến sáp ong Hackberry đổ bằng tay', 768500, 768500, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu hackberry. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:42:03.000000');
INSERT INTO `product` VALUES (128, 'Nến thơm sáp dừa Buffaloberry', 503000, 503000, 100, 100, 0, 'Nến thơm trâu hàng loạt nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:42:05.000000');
INSERT INTO `product` VALUES (129, 'Treo tường Macramé Aurora', 3013750, 3013750, 100, 100, 0, 'Bức tường macramé thắt nút thủ công phức tạp treo bằng dây bông tự nhiên aurora. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:42:07.000000');
INSERT INTO `product` VALUES (130, 'Vòng Hoa Chạng Vạng Hoa Khô', 1802250, 1802250, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa chạng vạng. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:42:08.000000');
INSERT INTO `product` VALUES (131, 'Kệ Gỗ Thạch Anh Chạm Khắc Bằng Tay', 1843000, 1843000, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh thạch nam. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:42:10.000000');
INSERT INTO `product` VALUES (132, 'Thớt gỗ óc chó lũa cuối hạt', 2301250, 2301250, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ gỗ óc chó và gỗ phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:42:12.000000');
INSERT INTO `product` VALUES (133, 'Bộ bát sứ Riverstone ném tay', 2740500, 2740500, 100, 100, 0, 'Bộ 4 bát gốm sứ tráng men phản ứng riverstone. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:42:14.000000');
INSERT INTO `product` VALUES (134, 'Mũ len Merino Beach dệt kim bằng tay', 642250, 642250, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ 100% len merino siêu giặt với màu sắc bãi biển sỏi. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:42:17.000000');
INSERT INTO `product` VALUES (135, 'Móc buộc tóc ren Foxglove', 281250, 281250, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông foxglove. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:42:19.000000');
INSERT INTO `product` VALUES (136, 'Khăn choàng lụa Blackberry nhuộm tay', 4387000, 4387000, 100, 100, 0, 'Khăn choàng quấn lụa nhuộm tay sang trọng họa tiết màu nước dâu đen. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:42:21.000000');
INSERT INTO `product` VALUES (137, 'Ly hợp da quế khâu tay', 1733500, 1733500, 100, 100, 0, 'Ví cầm tay da thủ công với chi tiết khâu tay màu quế. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:42:24.000000');
INSERT INTO `product` VALUES (138, 'Ba lô vải bạch đậu khấu', 3823250, 3823250, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da bạch đậu khấu. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:42:26.000000');
INSERT INTO `product` VALUES (139, 'Tranh sáp cỏ ba lá nguyên bản', 6501250, 6501250, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng cỏ ba lá. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:42:28.000000');
INSERT INTO `product` VALUES (140, 'Tượng gốm Thistle điêu khắc bằng tay', 2171250, 2171250, 100, 100, 0, 'Tượng gốm bằng đá được điêu khắc thủ công với các chi tiết tráng men cây kế. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:42:30.000000');
INSERT INTO `product` VALUES (141, 'Mỹ thuật In ảnh thiên nhiên Wisteria', 1573250, 1573250, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên hoa đậu tía nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:42:32.000000');
INSERT INTO `product` VALUES (142, 'Xà Phòng Nghệ Nhân Wren Sữa Dê', 348250, 348250, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm chim hồng tước và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:42:35.000000');
INSERT INTO `product` VALUES (143, 'Thanh gội đầu Solid Falcon', 573750, 573750, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược chim ưng. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:42:37.000000');
INSERT INTO `product` VALUES (144, 'Tẩy tế bào chết toàn thân Sugar Osprey', 391250, 391250, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường osprey thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu chim ưng. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:42:39.000000');
INSERT INTO `product` VALUES (145, 'Tạp chí da Hawkweed ràng buộc bằng tay', 1956250, 1956250, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da diều hâu và sợi vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:42:42.000000');
INSERT INTO `product` VALUES (146, 'Thiệp cưới màu nước Dogwood', 217000, 217000, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật cây dương đào. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:42:44.000000');
INSERT INTO `product` VALUES (147, 'Câu đố bằng gỗ Sweetgrass vẽ tay', 1257500, 1257500, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay bằng cỏ ngọt. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:42:47.000000');
INSERT INTO `product` VALUES (148, 'Đũa phép đồ chơi cho mèo đuôi mèo bện bằng tay', 413750, 413750, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây cotton bện đuôi mèo và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:42:49.000000');
INSERT INTO `product` VALUES (149, 'Vòng cổ mặt dây chuyền đá mặt trăng Bullrush thủ công', 1172750, 1172750, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:42:51.000000');
INSERT INTO `product` VALUES (150, 'Tên Tùy Chỉnh Vòng Cổ Cói Vàng Lấp Lánh', 2146750, 2146750, 100, 100, 0, 'Dây chuyền tên cói cá tính được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:42:53.000000');
INSERT INTO `product` VALUES (151, 'Vòng cổ mặt dây chuyền Bracken theo phong cách cổ điển', 2359500, 2359500, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng dương xỉ lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:42:55.000000');
INSERT INTO `product` VALUES (152, 'Vòng tay tình bạn cây me chua dệt tay', 693750, 693750, 100, 100, 0, 'Vòng tay tình bạn màu me chua dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:43:00.000000');
INSERT INTO `product` VALUES (153, 'Vòng đeo tay bằng đồng hoa cúc rèn', 1350250, 1350250, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ màu hoa cúc. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:43:02.000000');
INSERT INTO `product` VALUES (154, 'Vòng tay đá quý Yarrow đính cườm', 967000, 967000, 100, 100, 0, 'Vòng tay hạt đá quý cỏ thi được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:43:05.000000');
INSERT INTO `product` VALUES (155, 'Bông tai bạc Valerian được rèn thủ công', 754750, 754750, 100, 100, 0, 'Bông tai đinh tán bằng bạc được rèn thủ công với họa tiết cây nữ lang. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:43:07.000000');
INSERT INTO `product` VALUES (156, 'Bông tai pha lê Mugwort có dây', 1720250, 1720250, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn là pha lê ngải cứu. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:43:08.000000');
INSERT INTO `product` VALUES (157, 'Vòng xếp chồng cây tầm ma được đóng dấu bằng tay', 585000, 585000, 100, 100, 0, 'Chiếc nhẫn xếp chồng cây tầm ma được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:43:10.000000');
INSERT INTO `product` VALUES (158, 'Vòng tuyên bố cây ngưu bàng pha lê thô', 1542250, 1542250, 100, 100, 0, 'Chiếc nhẫn nổi bật có pha lê cây ngưu bàng thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với patina cây ngưu bàng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:43:12.000000');
INSERT INTO `product` VALUES (159, 'Nến sáp ong hình giọt nước đổ bằng tay', 751250, 751250, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu giọt tuyết. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:43:13.000000');
INSERT INTO `product` VALUES (160, 'Nến thơm sáp dừa Crocus', 1025250, 1025250, 100, 100, 0, 'Nến thơm hoa nghệ tây số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:43:14.000000');
INSERT INTO `product` VALUES (161, 'Treo tường Macramé Trillium', 1442750, 1442750, 100, 100, 0, 'Bức tường macramé thắt nút bằng tay phức tạp treo bằng dây bông tự nhiên trillium. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:43:15.000000');
INSERT INTO `product` VALUES (162, 'Vòng hoa huyết hoa khô', 1789500, 1789500, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa từ rễ huyết. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:43:17.000000');
INSERT INTO `product` VALUES (163, 'Kệ Gỗ Hepatica Chạm Khắc Bằng Tay', 1618500, 1618500, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết viền gan. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:43:18.000000');
INSERT INTO `product` VALUES (164, 'Thớt quả óc chó Mayapple cuối hạt', 3375250, 3375250, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó mayapple và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:43:19.000000');
INSERT INTO `product` VALUES (165, 'Bộ bát gốm hoa cơm cháy cầm tay', 2547250, 2547250, 100, 100, 0, 'Bộ 4 bát gốm sứ tráng men phản ứng hoa cơm cháy. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:43:20.000000');
INSERT INTO `product` VALUES (166, 'Mũ len Merino Hawthorn dệt kim bằng tay', 1404500, 1404500, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu táo gai. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:43:22.000000');
INSERT INTO `product` VALUES (167, 'Dây buộc tóc ren gai đen móc', 410000, 410000, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren cotton gai đen. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:43:24.000000');
INSERT INTO `product` VALUES (168, 'Khăn choàng lụa Rowan nhuộm tay', 2097500, 2097500, 100, 100, 0, 'Khăn choàng quấn lụa nhuộm tay sang trọng họa tiết màu nước thanh lương trà. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:43:25.000000');
INSERT INTO `product` VALUES (169, 'Ly Hợp Da Sloe Khâu Tay', 3168750, 3168750, 100, 100, 0, 'Ví cầm tay bằng da có chi tiết khâu tay. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:43:27.000000');
INSERT INTO `product` VALUES (170, 'Ba lô vải sáp Damson', 3291250, 3291250, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da damson. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:43:29.000000');
INSERT INTO `product` VALUES (171, 'Tranh sáp màu quả hồng nguyên chất', 3774500, 3774500, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng quả hồng. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:43:32.000000');
INSERT INTO `product` VALUES (172, 'Tượng gốm mộc qua điêu khắc bằng tay', 932500, 932500, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết tráng men mộc qua. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:43:34.000000');
INSERT INTO `product` VALUES (173, 'In ảnh thiên nhiên Mỹ thuật Medlar', 1207750, 1207750, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên sơn tra gốc. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:43:36.000000');
INSERT INTO `product` VALUES (174, 'Xà phòng thủ công dâu tằm sữa dê', 175500, 175500, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm dâu tằm và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:43:39.000000');
INSERT INTO `product` VALUES (175, 'Thanh gội đầu Gooseberry rắn', 341500, 341500, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo mộc quả lý gai. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:43:41.000000');
INSERT INTO `product` VALUES (176, 'Tẩy tế bào chết toàn thân bằng đường việt quất', 619750, 619750, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường việt quất thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu việt quất. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:43:43.000000');
INSERT INTO `product` VALUES (177, 'Tạp chí da Crowberry đóng bìa tay', 1765250, 1765250, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da quạ và sợi vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:43:46.000000');
INSERT INTO `product` VALUES (178, 'Thiệp cưới màu nước Cloudberry', 162750, 162750, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật cây mâm xôi. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:43:49.000000');
INSERT INTO `product` VALUES (179, 'Câu đố bằng gỗ Lingonberry vẽ tay', 1393750, 1393750, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay lingonberry. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:43:51.000000');
INSERT INTO `product` VALUES (180, 'Cây đũa phép đồ chơi cho mèo Bearberry bện tay', 355500, 355500, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây cotton bện hình quả dâu và phần đính kèm lông tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:43:53.000000');
INSERT INTO `product` VALUES (181, 'Vòng cổ mặt dây chuyền đá mặt trăng Hackberry thủ công', 1043750, 1043750, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng hackberry chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:43:56.000000');
INSERT INTO `product` VALUES (182, 'Tên tùy chỉnh Vòng cổ lấp đầy vàng Buffaloberry', 2278500, 2278500, 100, 100, 0, 'Vòng cổ tên Buffaloberry cá tính được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:43:58.000000');
INSERT INTO `product` VALUES (183, 'Vòng cổ Aurora Locket theo phong cách cổ điển', 2662500, 2662500, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau aurora lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:44:01.000000');
INSERT INTO `product` VALUES (184, 'Vòng tay tình bạn Chạng vạng dệt tay', 434000, 434000, 100, 100, 0, 'Vòng tay tình bạn chạng vạng dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:44:03.000000');
INSERT INTO `product` VALUES (185, 'Vòng đeo tay bằng đồng rèn thạch cao', 1187250, 1187250, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ màu thạch nam. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:44:06.000000');
INSERT INTO `product` VALUES (186, 'Vòng tay đá quý lũa đính cườm', 1178250, 1178250, 100, 100, 0, 'Vòng tay hạt đá quý bằng gỗ lũa được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:44:08.000000');
INSERT INTO `product` VALUES (187, 'Bông tai bạc Riverstone được rèn thủ công', 1006750, 1006750, 100, 100, 0, 'Khuyên tai dạng đinh tán bằng bạc được rèn thủ công với kết cấu bằng đá ven sông. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:44:10.000000');
INSERT INTO `product` VALUES (188, 'Bông tai pha lê Pebble Beach có dây', 1552000, 1552000, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn là pha lê bãi biển sỏi. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:44:12.000000');
INSERT INTO `product` VALUES (189, 'Vòng xếp chồng Foxglove được đóng dấu bằng tay', 934250, 934250, 100, 100, 0, 'Chiếc nhẫn xếp chồng hình cáo được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:44:14.000000');
INSERT INTO `product` VALUES (190, 'Nhẫn tuyên bố Blackberry pha lê thô', 900500, 900500, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê blackberry thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với lớp vỏ blackberry.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:44:17.000000');
INSERT INTO `product` VALUES (191, 'Nến sáp ong quế đổ bằng tay', 313500, 313500, 100, 100, 0, 'Nến sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu quế. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:44:18.000000');
INSERT INTO `product` VALUES (192, 'Nến thơm sáp dừa bạch đậu khấu', 423500, 423500, 100, 100, 0, 'Nến thơm thảo quả lô nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:44:20.000000');
INSERT INTO `product` VALUES (193, 'Macramé Cỏ Ba Lá Treo Tường', 1734250, 1734250, 100, 100, 0, 'Bức tường macramé được thắt nút bằng tay phức tạp treo bằng dây bông tự nhiên hình cỏ ba lá. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:44:22.000000');
INSERT INTO `product` VALUES (194, 'Vòng hoa kế khô', 1673250, 1673250, 100, 100, 0, 'Vòng hoa khô thủ công có hình cây kế theo mùa. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:44:23.000000');
INSERT INTO `product` VALUES (195, 'Kệ gỗ hoa tử đằng chạm khắc thủ công', 3888250, 3888250, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh hoa tử đằng. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:44:25.000000');
INSERT INTO `product` VALUES (196, 'Thớt quả óc chó Wren cuối hạt', 2677500, 2677500, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó wren và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:44:27.000000');
INSERT INTO `product` VALUES (197, 'Bộ Bát Sứ Falcon Ném Tay', 1957000, 1957000, 100, 100, 0, 'Bộ 4 bát gốm sứ cầm tay phủ men phản ứng hình chim ưng. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:44:28.000000');
INSERT INTO `product` VALUES (198, 'Mũ len Osprey Merino dệt kim bằng tay', 1190750, 1190750, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ 100% len merino superwash với màu sắc chim ưng. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:44:31.000000');
INSERT INTO `product` VALUES (199, 'Móc buộc tóc ren Hawkweed', 434500, 434500, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông hawkweed. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:44:33.000000');
INSERT INTO `product` VALUES (200, 'Khăn choàng lụa Dogwood nhuộm tay', 3212500, 3212500, 100, 100, 0, 'Khăn choàng quấn lụa nhuộm tay sang trọng với hoa văn màu nước bằng gỗ sơn thù du. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:44:37.000000');
INSERT INTO `product` VALUES (201, 'Ly hợp da Sweetgrass khâu tay', 1826000, 1826000, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay sweetgrass. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:44:39.000000');
INSERT INTO `product` VALUES (202, 'Ba lô Cattail vải sáp', 4678750, 4678750, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da đuôi mèo. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:44:41.000000');
INSERT INTO `product` VALUES (203, 'Tranh sáp Encaustic Bullrush nguyên bản', 6956000, 6956000, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng của cây bò tót. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:44:43.000000');
INSERT INTO `product` VALUES (204, 'Tượng gốm cói điêu khắc bằng tay', 2039750, 2039750, 100, 100, 0, 'Tượng gốm sứ điêu khắc thủ công với các chi tiết bằng men cói. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:44:46.000000');
INSERT INTO `product` VALUES (205, 'Mỹ Thuật In Ảnh Thiên Nhiên Bracken', 1017750, 1017750, 100, 100, 0, 'Lưu trữ bản in mỹ thuật của bức ảnh thiên nhiên dương xỉ nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:44:48.000000');
INSERT INTO `product` VALUES (206, 'Xà Phòng Thủ Công Sữa Dê Sorrel', 231000, 231000, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm cây me chua và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:44:50.000000');
INSERT INTO `product` VALUES (207, 'Thanh gội đầu hoa cúc rắn', 397750, 397750, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược hoa cúc. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:44:53.000000');
INSERT INTO `product` VALUES (208, 'Tẩy tế bào chết Sugar Yarrow', 320750, 320750, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường cỏ thi thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu cỏ thi. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:44:55.000000');
INSERT INTO `product` VALUES (209, 'Tạp chí da Valerian ràng buộc tay', 886250, 886250, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da valerian và sợi vải lanh đóng bìa bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:44:58.000000');
INSERT INTO `product` VALUES (210, 'Thiệp cưới màu nước ngải cứu', 225500, 225500, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật ngải cứu. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:45:00.000000');
INSERT INTO `product` VALUES (211, 'Câu đố bằng gỗ cây tầm ma vẽ tay', 1464000, 1464000, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay bằng cây tầm ma. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:45:02.000000');
INSERT INTO `product` VALUES (212, 'Đũa phép đồ chơi cho mèo ngưu bàng bện bằng tay', 445750, 445750, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây cotton bện cây ngưu bàng và phần đính kèm lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:45:05.000000');
INSERT INTO `product` VALUES (213, 'Vòng cổ mặt dây chuyền đá mặt trăng hình giọt nước thủ công', 1400500, 1400500, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng hình giọt nước chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:45:07.000000');
INSERT INTO `product` VALUES (214, 'Tên tùy chỉnh Vòng cổ Crocus Gold-Fill', 2664250, 2664250, 100, 100, 0, 'Vòng cổ tên crocus cá tính được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:45:09.000000');
INSERT INTO `product` VALUES (215, 'Vòng cổ Trillium Locket theo phong cách cổ điển', 1402500, 1402500, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng trillium lấy cảm hứng từ cổ. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:45:12.000000');
INSERT INTO `product` VALUES (216, 'Vòng tay tình bạn Bloodroot dệt tay', 325000, 325000, 100, 100, 0, 'Vòng tay tình bạn rễ cây máu được dệt thủ công bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:45:14.000000');
INSERT INTO `product` VALUES (217, 'Vòng đeo tay bằng đồng Hepatica rèn', 878250, 878250, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ màu Hepatica. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:45:16.000000');
INSERT INTO `product` VALUES (218, 'Vòng tay đá quý Mayapple đính cườm', 1123000, 1123000, 100, 100, 0, 'Vòng tay hạt đá quý mayapple được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:45:18.000000');
INSERT INTO `product` VALUES (219, 'Bông tai bạc hình hoa cơm cháy được rèn thủ công', 1264750, 1264750, 100, 100, 0, 'Bông tai bạc sterling được rèn thủ công với họa tiết hoa cơm cháy. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:45:21.000000');
INSERT INTO `product` VALUES (220, 'Bông tai pha lê Hawthorn có dây', 1026250, 1026250, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê táo gai. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:45:23.000000');
INSERT INTO `product` VALUES (221, 'Vòng xếp chồng Blackthorn được đóng dấu bằng tay', 982000, 982000, 100, 100, 0, 'Chiếc nhẫn xếp chồng cây gai đen được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:45:25.000000');
INSERT INTO `product` VALUES (222, 'Nhẫn pha lê Rowan thô', 1913250, 1913250, 100, 100, 0, 'Chiếc nhẫn nổi bật có pha lê thanh lương trà thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với lớp vỏ thanh lương trà.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:45:28.000000');
INSERT INTO `product` VALUES (223, 'Nến sáp ong Sloe đổ bằng tay', 611500, 611500, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu sloe. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:45:30.000000');
INSERT INTO `product` VALUES (224, 'Nến thơm sáp dừa Damson', 975000, 975000, 100, 100, 0, 'Nến thơm Damson số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:45:31.000000');
INSERT INTO `product` VALUES (225, 'Quả Hồng Macramé Treo Tường', 3217750, 3217750, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo treo trên dây bông tự nhiên màu hồng. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:45:33.000000');
INSERT INTO `product` VALUES (226, 'Vòng hoa mộc qua khô', 1530000, 1530000, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa mộc qua. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:45:34.000000');
INSERT INTO `product` VALUES (227, 'Kệ gỗ Medlar chạm khắc thủ công', 1612250, 1612250, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh sơn tra. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:45:36.000000');
INSERT INTO `product` VALUES (228, 'Thớt quả óc chó dâu tằm cuối hạt', 1608500, 1608500, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó dâu và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:45:37.000000');
INSERT INTO `product` VALUES (229, 'Bộ bát sứ ném quả lý gai bằng tay', 1691000, 1691000, 100, 100, 0, 'Bộ 4 chiếc bát sứ cầm tay phủ men phản ứng quả lý gai. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:45:39.000000');
INSERT INTO `product` VALUES (230, 'Mũ len Merino Bilberry đan tay', 1078750, 1078750, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu việt quất. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:45:42.000000');
INSERT INTO `product` VALUES (231, 'Dây buộc tóc bằng ren Crochet Crowberry', 154500, 154500, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren cotton dâu tây. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:45:44.000000');
INSERT INTO `product` VALUES (232, 'Khăn choàng lụa Cloudberry nhuộm tay', 2405500, 2405500, 100, 100, 0, 'Khăn choàng lụa nhuộm tay sang trọng họa tiết màu nước mâm xôi. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:45:47.000000');
INSERT INTO `product` VALUES (233, 'Ly hợp da Lingonberry khâu tay', 2298500, 2298500, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay lingonberry. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:45:49.000000');
INSERT INTO `product` VALUES (234, 'Ba lô Bearberry vải sáp', 3258250, 3258250, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da Bearberry. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:45:51.000000');
INSERT INTO `product` VALUES (235, 'Tranh sáp nguyên chất Hackberry', 5568750, 5568750, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng hackberry. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:45:54.000000');
INSERT INTO `product` VALUES (236, 'Tượng gốm Buffaloberry điêu khắc bằng tay', 1675750, 1675750, 100, 100, 0, 'Tượng gốm bằng đá được điêu khắc thủ công với các chi tiết tráng men dâu. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:45:56.000000');
INSERT INTO `product` VALUES (237, 'In ảnh thiên nhiên cực quang mỹ thuật', 1209500, 1209500, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên cực quang nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:45:59.000000');
INSERT INTO `product` VALUES (238, 'Xà phòng nghệ nhân Twilight Artisan sữa dê', 381000, 381000, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm hoàng hôn và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:46:01.000000');
INSERT INTO `product` VALUES (239, 'Thanh gội đầu Solid Heather', 443500, 443500, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược thạch nam. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:46:04.000000');
INSERT INTO `product` VALUES (240, 'Tẩy tế bào chết bằng gỗ lũa đường', 477750, 477750, 100, 100, 0, 'Tẩy tế bào chết bằng đường gỗ lũa thủ công gốc dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu gỗ lũa. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:46:06.000000');
INSERT INTO `product` VALUES (241, 'Tạp chí da Riverstone đóng bìa tay', 936500, 936500, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da bằng đá ven sông và dây vải lanh được đóng bằng đường khâu kiểu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:46:08.000000');
INSERT INTO `product` VALUES (242, 'Thiệp cưới màu nước trên bãi biển Pebble', 257250, 257250, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật trên bãi biển sỏi. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:46:11.000000');
INSERT INTO `product` VALUES (243, 'Câu đố bằng gỗ Foxglove vẽ tay', 601000, 601000, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay foxglove. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:46:13.000000');
INSERT INTO `product` VALUES (244, 'Cây đũa phép đồ chơi cho mèo Blackberry bện tay', 212750, 212750, 100, 100, 0, 'Đồ chơi đũa phép mèo thủ công với dây cotton bện dâu đen và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:46:15.000000');
INSERT INTO `product` VALUES (245, 'Vòng cổ mặt dây chuyền đá mặt trăng quế thủ công', 1273500, 1273500, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng quế chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:46:17.000000');
INSERT INTO `product` VALUES (246, 'Tên tùy chỉnh Vòng cổ lấp đầy vàng bạch đậu khấu', 1306250, 1306250, 100, 100, 0, 'Vòng cổ tên bạch đậu khấu được cá nhân hóa được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:46:20.000000');
INSERT INTO `product` VALUES (247, 'Vòng cổ Mề đay cỏ ba lá phong cách cổ điển', 2700000, 2700000, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng cỏ ba lá lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:46:22.000000');
INSERT INTO `product` VALUES (248, 'Vòng tay tình bạn cây kế dệt tay', 279250, 279250, 100, 100, 0, 'Vòng tay tình bạn cây kế dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:46:24.000000');
INSERT INTO `product` VALUES (249, 'Vòng đeo tay bằng đồng Wisteria rèn', 1077000, 1077000, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn bằng tay với lớp gỉ hoa tử đằng. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:46:26.000000');
INSERT INTO `product` VALUES (250, 'Vòng tay đá quý Wren đính cườm', 1267250, 1267250, 100, 100, 0, 'Vòng tay hạt đá quý wren được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:46:29.000000');
INSERT INTO `product` VALUES (251, 'Bông tai bạc hình chim ưng được rèn thủ công', 792750, 792750, 100, 100, 0, 'Bông tai bạc sterling được rèn thủ công với họa tiết chim ưng. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:46:31.000000');
INSERT INTO `product` VALUES (252, 'Bông tai pha lê Osprey có dây', 1607250, 1607250, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn là pha lê chim ưng. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:46:33.000000');
INSERT INTO `product` VALUES (253, 'Vòng xếp chồng Hawkweed được đóng dấu bằng tay', 396750, 396750, 100, 100, 0, 'Chiếc nhẫn xếp chồng diều hâu được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:46:36.000000');
INSERT INTO `product` VALUES (254, 'Nhẫn pha lê thô Dogwood', 861250, 861250, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê gỗ sơn thù du thô được đặt bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thiện với lớp gỉ gỗ sơn thù du.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:46:38.000000');
INSERT INTO `product` VALUES (255, 'Nến sáp ong Sweetgrass đổ bằng tay', 479000, 479000, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu cỏ ngọt. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:46:39.000000');
INSERT INTO `product` VALUES (256, 'Nến thơm Cattail sáp dừa', 605500, 605500, 100, 100, 0, 'Nến thơm đuôi mèo số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:46:41.000000');
INSERT INTO `product` VALUES (257, 'Treo tường Macramé Bullrush', 2377250, 2377250, 100, 100, 0, 'Bức tường macramé được thắt nút bằng tay phức tạp treo bằng dây bông tự nhiên có màu nâu đỏ. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:46:42.000000');
INSERT INTO `product` VALUES (258, 'Vòng hoa cói khô', 1147500, 1147500, 100, 100, 0, 'Vòng hoa khô được làm thủ công có các loại thực vật cói theo mùa. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:46:43.000000');
INSERT INTO `product` VALUES (259, 'Kệ Gỗ Bracken Chạm Khắc Bằng Tay', 2732250, 2732250, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết viền dương xỉ. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:46:44.000000');
INSERT INTO `product` VALUES (260, 'Thớt quả óc chó sầu riêng cuối hạt', 3568250, 3568250, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó me chua và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:46:46.000000');
INSERT INTO `product` VALUES (261, 'Bộ bát sứ hoa cúc ném tay', 2537750, 2537750, 100, 100, 0, 'Bộ 4 bát gốm sứ tráng men phản ứng hoa cúc. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:46:47.000000');
INSERT INTO `product` VALUES (262, 'Mũ len Yarrow Merino dệt kim bằng tay', 1487500, 1487500, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu yarrow. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:46:49.000000');
INSERT INTO `product` VALUES (263, 'Móc dây buộc tóc bằng ren Valerian', 174500, 174500, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông nữ lang. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:46:51.000000');
INSERT INTO `product` VALUES (264, 'Khăn choàng lụa Mugwort nhuộm tay', 3493250, 3493250, 100, 100, 0, 'Khăn choàng lụa nhuộm tay sang trọng họa tiết màu nước ngải cứu. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:46:52.000000');
INSERT INTO `product` VALUES (265, 'Ly hợp da cây tầm ma khâu tay', 2846250, 2846250, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay bằng cây tầm ma. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:46:54.000000');
INSERT INTO `product` VALUES (266, 'Ba lô vải cây ngưu bàng sáp', 4909500, 4909500, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da cây ngưu bàng. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:46:56.000000');
INSERT INTO `product` VALUES (267, 'Tranh sáp bông tuyết nguyên bản', 2432250, 2432250, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng giọt tuyết. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:46:58.000000');
INSERT INTO `product` VALUES (268, 'Tượng gốm Crocus điêu khắc bằng tay', 890500, 890500, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết bằng men nghệ. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:47:00.000000');
INSERT INTO `product` VALUES (269, 'In ảnh thiên nhiên Trillium mỹ thuật', 1531750, 1531750, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên trillium nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:47:02.000000');
INSERT INTO `product` VALUES (270, 'Xà phòng thủ công Bloodroot sữa dê', 385250, 385250, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm rễ cây và các tạp chất thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:47:05.000000');
INSERT INTO `product` VALUES (271, 'Thanh gội đầu Solid Hepatica', 287500, 287500, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược Hepatica. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:47:08.000000');
INSERT INTO `product` VALUES (272, 'Tẩy tế bào chết toàn thân Sugar Mayapple', 729000, 729000, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường mayapple thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu mayapple. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:47:11.000000');
INSERT INTO `product` VALUES (273, 'Tạp chí da Elderflower ràng buộc bằng tay', 1721750, 1721750, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da hoa cơm cháy và dây vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:47:13.000000');
INSERT INTO `product` VALUES (274, 'Thiệp cưới màu nước táo gai', 263250, 263250, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật táo gai. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:47:15.000000');
INSERT INTO `product` VALUES (275, 'Câu đố bằng gỗ cây mâm xôi vẽ tay', 1367500, 1367500, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay cây mận gai. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:47:18.000000');
INSERT INTO `product` VALUES (276, 'Cây đũa phép đồ chơi mèo Rowan bện bằng tay', 414000, 414000, 100, 100, 0, 'Đồ chơi đũa phép mèo thủ công với dây bông bện thanh lương trà và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:47:20.000000');
INSERT INTO `product` VALUES (277, 'Vòng cổ mặt dây chuyền đá mặt trăng Sloe thủ công', 1269750, 1269750, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng sloe chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:47:22.000000');
INSERT INTO `product` VALUES (278, 'Tên tùy chỉnh Vòng cổ lấp đầy vàng Damson', 974000, 974000, 100, 100, 0, 'Vòng cổ tên Damson cá tính được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:47:24.000000');
INSERT INTO `product` VALUES (279, 'Vòng cổ mặt dây chuyền quả hồng theo phong cách cổ điển', 1770500, 1770500, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng hồng lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:47:27.000000');
INSERT INTO `product` VALUES (280, 'Vòng tay tình bạn mộc qua dệt tay', 512500, 512500, 100, 100, 0, 'Vòng tay tình bạn mộc qua dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:47:29.000000');
INSERT INTO `product` VALUES (281, 'Vòng đeo tay bằng đồng Medlar rèn', 775500, 775500, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ màu sơn tra. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:47:31.000000');
INSERT INTO `product` VALUES (282, 'Vòng tay đá quý dâu tằm đính cườm', 661000, 661000, 100, 100, 0, 'Vòng tay hạt đá quý dâu tằm được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:47:34.000000');
INSERT INTO `product` VALUES (283, 'Bông tai bạc hình quả lý gai được rèn thủ công', 486250, 486250, 100, 100, 0, 'Bông tai đinh tán bằng bạc được rèn thủ công với kết cấu quả lý gai. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:47:36.000000');
INSERT INTO `product` VALUES (284, 'Bông tai pha lê hình quả việt quất có dây', 1182750, 1182750, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn là pha lê việt quất. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:47:39.000000');
INSERT INTO `product` VALUES (285, 'Vòng xếp chồng Crowberry được đóng dấu bằng tay', 1097500, 1097500, 100, 100, 0, 'Nhẫn xếp chồng quả quạ được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:47:41.000000');
INSERT INTO `product` VALUES (286, 'Nhẫn pha lê Cloudberry thô', 1629750, 1629750, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê mâm xôi thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với lớp vỏ mây.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:47:43.000000');
INSERT INTO `product` VALUES (287, 'Nến sáp ong Lingonberry đổ bằng tay', 308250, 308250, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu nam việt quất. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:47:45.000000');
INSERT INTO `product` VALUES (288, 'Nến thơm Bearberry sáp dừa', 613750, 613750, 100, 100, 0, 'Nến thơm Bearberry số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:47:46.000000');
INSERT INTO `product` VALUES (289, 'Macramé Hackberry treo tường', 2689500, 2689500, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo được treo bằng dây cotton tự nhiên hackberry. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:47:48.000000');
INSERT INTO `product` VALUES (290, 'Vòng Hoa Trâu Khô', 1008250, 1008250, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa từ quả trâu. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:47:50.000000');
INSERT INTO `product` VALUES (291, 'Kệ Gỗ Aurora Chạm Khắc Bằng Tay', 3410250, 3410250, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh cực quang. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:47:51.000000');
INSERT INTO `product` VALUES (292, 'Thớt quả óc chó Chạng vạng cuối hạt', 2110500, 2110500, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ gỗ óc chó chạng vạng và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:47:53.000000');
INSERT INTO `product` VALUES (293, 'Bộ bát sứ thạch anh ném tay', 2110000, 2110000, 100, 100, 0, 'Bộ 4 chiếc bát sứ thủ công phủ men phản ứng thạch nam. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:47:54.000000');
INSERT INTO `product` VALUES (294, 'Mũ len Merino bằng gỗ lũa dệt kim thủ công', 1462000, 1462000, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu gỗ lũa. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:47:57.000000');
INSERT INTO `product` VALUES (295, 'Dây buộc tóc ren Riverstone Crochet', 412250, 412250, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren cotton riverstone. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:48:01.000000');
INSERT INTO `product` VALUES (296, 'Khăn choàng quấn lụa bãi biển Pebble nhuộm tay', 1625500, 1625500, 100, 100, 0, 'Khăn choàng lụa nhuộm tay sang trọng họa tiết màu nước bãi biển sỏi. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:48:03.000000');
INSERT INTO `product` VALUES (297, 'Ly hợp da Foxglove khâu tay', 3066000, 3066000, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay hình mao địa hoàng. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:48:05.000000');
INSERT INTO `product` VALUES (298, 'Ba lô Blackberry vải sáp', 5079500, 5079500, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da blackberry. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:48:08.000000');
INSERT INTO `product` VALUES (299, 'Tranh sáp quế nguyên chất', 6132250, 6132250, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với thành phần trừu tượng quế. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:48:10.000000');
INSERT INTO `product` VALUES (300, 'Tượng gốm thảo quả điêu khắc bằng tay', 2007750, 2007750, 100, 100, 0, 'Tượng gốm bằng đá được điêu khắc thủ công với các chi tiết tráng men bạch đậu khấu. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:48:12.000000');
INSERT INTO `product` VALUES (301, 'In ảnh nghệ thuật cỏ ba lá thiên nhiên', 981750, 981750, 100, 100, 0, 'Lưu trữ bản in mỹ thuật của bức ảnh thiên nhiên cỏ ba lá nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:48:15.000000');
INSERT INTO `product` VALUES (302, 'Xà phòng thủ công cây kế sữa dê', 276750, 276750, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm cây kế và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:48:17.000000');
INSERT INTO `product` VALUES (303, 'Thanh gội đầu rắn Wisteria', 242000, 242000, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược hoa tử đằng. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:48:19.000000');
INSERT INTO `product` VALUES (304, 'Sugar Wren Tẩy Tế Bào Chết Toàn Thân', 468000, 468000, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường wren thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu chim hồng tước. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:48:22.000000');
INSERT INTO `product` VALUES (305, 'Tạp chí da chim ưng ràng buộc bằng tay', 1128500, 1128500, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da chim ưng và dây vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:48:24.000000');
INSERT INTO `product` VALUES (306, 'Thiệp cưới màu nước Osprey', 160750, 160750, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật chim ưng biển. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:48:26.000000');
INSERT INTO `product` VALUES (307, 'Câu đố bằng gỗ Hawkweed vẽ tay', 1564500, 1564500, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay hawkweed. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:48:30.000000');
INSERT INTO `product` VALUES (308, 'Đũa phép đồ chơi cho mèo Dogwood bện bằng tay', 508250, 508250, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây bông bện bằng gỗ cây chó đẻ và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:48:32.000000');
INSERT INTO `product` VALUES (309, 'Vòng cổ mặt dây chuyền đá mặt trăng Sweetgrass thủ công', 2056250, 2056250, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng sweetgrass chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:48:35.000000');
INSERT INTO `product` VALUES (310, 'Tên tùy chỉnh Vòng cổ lấp đầy vàng Cattail', 1429500, 1429500, 100, 100, 0, 'Vòng cổ tên cattail cá tính được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:48:37.000000');
INSERT INTO `product` VALUES (311, 'Vòng cổ Mề đay Bullrush theo phong cách cổ điển', 1278000, 1278000, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:48:40.000000');
INSERT INTO `product` VALUES (312, 'Vòng tay tình bạn cói dệt tay', 413750, 413750, 100, 100, 0, 'Vòng tay tình bạn cói dệt thủ công bằng sợi cotton sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:48:42.000000');
INSERT INTO `product` VALUES (313, 'Vòng đeo tay bằng đồng Bracken rèn', 636750, 636750, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ màu dương xỉ. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:48:45.000000');
INSERT INTO `product` VALUES (314, 'Vòng tay đá quý đính cườm', 865750, 865750, 100, 100, 0, 'Vòng tay hạt đá quý màu me chua được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:48:47.000000');
INSERT INTO `product` VALUES (315, 'Bông tai bạc hoa cúc được rèn thủ công', 981500, 981500, 100, 100, 0, 'Bông tai bạc sterling được rèn thủ công với họa tiết hoa cúc. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:48:49.000000');
INSERT INTO `product` VALUES (316, 'Bông tai Hoop pha lê Yarrow có dây', 936250, 936250, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê yarrow. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:48:51.000000');
INSERT INTO `product` VALUES (317, 'Vòng xếp chồng Valerian được đóng dấu bằng tay', 576000, 576000, 100, 100, 0, 'Chiếc nhẫn xếp chồng nữ lang được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:48:54.000000');
INSERT INTO `product` VALUES (318, 'Vòng tuyên bố Mugwort pha lê thô', 1074500, 1074500, 100, 100, 0, 'Chiếc nhẫn nổi bật có pha lê ngải cứu thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với lớp vỏ ngải cứu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:48:56.000000');
INSERT INTO `product` VALUES (319, 'Nến sáp ong cây tầm ma đổ bằng tay', 839000, 839000, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay với hỗn hợp tinh dầu cây tầm ma. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:48:58.000000');
INSERT INTO `product` VALUES (320, 'Nến thơm sáp dừa cây ngưu bàng', 374250, 374250, 100, 100, 0, 'Nến thơm cây ngưu bàng số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:48:59.000000');
INSERT INTO `product` VALUES (321, 'Treo tường hình giọt nước Macramé', 3025500, 3025500, 100, 100, 0, 'Bức tường macramé được thắt nút bằng tay phức tạp treo trên sợi dây bông tự nhiên hình giọt tuyết. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:49:01.000000');
INSERT INTO `product` VALUES (322, 'Vòng hoa nghệ tây khô', 1714000, 1714000, 100, 100, 0, 'Vòng hoa khô thủ công có hình hoa nghệ tây theo mùa. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:49:03.000000');
INSERT INTO `product` VALUES (323, 'Kệ Gỗ Trillium Chạm Khắc Bằng Tay', 2700500, 2700500, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết viền trillium. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:49:04.000000');
INSERT INTO `product` VALUES (324, 'Thớt cắt quả óc chó Bloodroot cuối hạt', 3542500, 3542500, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:49:06.000000');
INSERT INTO `product` VALUES (325, 'Bộ bát sứ Hepatica ném tay', 1238000, 1238000, 100, 100, 0, 'Bộ 4 bát gốm sứ tráng men phản ứng Hepatica. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:49:08.000000');
INSERT INTO `product` VALUES (326, 'Mũ len Mayapple Merino dệt kim bằng tay', 1542500, 1542500, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu mayapple. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:49:10.000000');
INSERT INTO `product` VALUES (327, 'Dây buộc tóc ren hoa cơm cháy', 236750, 236750, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông hoa cơm cháy. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:49:13.000000');
INSERT INTO `product` VALUES (328, 'Khăn choàng lụa Hawthorn nhuộm tay', 2623500, 2623500, 100, 100, 0, 'Khăn choàng lụa quấn tay sang trọng họa tiết màu nước táo gai. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:49:15.000000');
INSERT INTO `product` VALUES (329, 'Ly hợp da Blackthorn khâu tay', 2341750, 2341750, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay bằng cây gai đen. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:49:17.000000');
INSERT INTO `product` VALUES (330, 'Ba lô vải Rowan sáp', 5166750, 5166750, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da thanh lương trà. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:49:20.000000');
INSERT INTO `product` VALUES (331, 'Tranh sáp nguyên bản Sloe', 2849500, 2849500, 100, 100, 0, 'Bức tranh sơn dầu nguyên bản (sáp nóng) với bố cục trừu tượng sloe. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:49:22.000000');
INSERT INTO `product` VALUES (332, 'Tượng gốm Damson điêu khắc bằng tay', 1601750, 1601750, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết tráng men Damson. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:49:25.000000');
INSERT INTO `product` VALUES (333, 'Tranh In Tranh Thiên Nhiên Quả Hồng Mỹ Nghệ', 1863000, 1863000, 100, 100, 0, 'Lưu trữ bản in mỹ thuật của bức ảnh thiên nhiên quả hồng gốc. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:49:27.000000');
INSERT INTO `product` VALUES (334, 'Xà phòng nghệ mộc mộc qua sữa dê', 244000, 244000, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm mộc qua và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:49:29.000000');
INSERT INTO `product` VALUES (335, 'Thanh dầu gội rắn Medlar', 468000, 468000, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược sơn tra. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:49:32.000000');
INSERT INTO `product` VALUES (336, 'Tẩy tế bào chết toàn thân dâu tằm đường', 340000, 340000, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường dâu tằm thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu dâu tằm. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:49:34.000000');
INSERT INTO `product` VALUES (337, 'Tạp chí da ngỗng ràng buộc bằng tay', 1508250, 1508250, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da quả lý gai và dây vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:49:36.000000');
INSERT INTO `product` VALUES (338, 'Thiệp cưới màu nước việt quất', 222750, 222750, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật việt quất. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:49:38.000000');
INSERT INTO `product` VALUES (339, 'Câu đố bằng gỗ Crowberry vẽ tay', 1158000, 1158000, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay bằng quả quạ. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:49:41.000000');
INSERT INTO `product` VALUES (340, 'Đũa phép đồ chơi cho mèo Cloudberry bện bằng tay', 210000, 210000, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây bông bện hình quả mâm xôi và phần gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:49:43.000000');
INSERT INTO `product` VALUES (341, 'Vòng cổ mặt dây chuyền đá mặt trăng Lingonberry thủ công', 1038500, 1038500, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng lingonberry chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:49:45.000000');
INSERT INTO `product` VALUES (342, 'Tên tùy chỉnh Vòng cổ Bearberry Gold-Fill', 2563500, 2563500, 100, 100, 0, 'Vòng cổ tên Bearberry cá tính được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:49:48.000000');
INSERT INTO `product` VALUES (343, 'Vòng cổ Hackberry Locket theo phong cách cổ điển', 1404500, 1404500, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau hackberry lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:49:50.000000');
INSERT INTO `product` VALUES (344, 'Vòng tay tình bạn Buffaloberry dệt tay', 350250, 350250, 100, 100, 0, 'Vòng tay tình bạn trâu rừng dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:49:52.000000');
INSERT INTO `product` VALUES (345, 'Vòng đeo tay bằng đồng Aurora được rèn', 1737000, 1737000, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp sơn aurora. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:49:54.000000');
INSERT INTO `product` VALUES (346, 'Vòng tay đá quý Chạng vạng đính cườm', 749250, 749250, 100, 100, 0, 'Vòng tay hạt đá quý chạng vạng được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:49:57.000000');
INSERT INTO `product` VALUES (347, 'Bông tai bạc thạch anh rèn thủ công', 954750, 954750, 100, 100, 0, 'Bông tai đinh tán bằng bạc được rèn thủ công với kết cấu thạch nam. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:49:59.000000');
INSERT INTO `product` VALUES (348, 'Bông tai pha lê bằng gỗ lũa có dây', 1092000, 1092000, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê bằng gỗ lũa. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:50:02.000000');
INSERT INTO `product` VALUES (349, 'Vòng xếp chồng Riverstone được đóng dấu bằng tay', 302750, 302750, 100, 100, 0, 'Chiếc nhẫn xếp chồng bằng đá ven sông được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:50:04.000000');
INSERT INTO `product` VALUES (350, 'Nhẫn tuyên bố bãi biển Pebble pha lê thô', 1510000, 1510000, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê bãi biển đá cuội thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thiện với lớp gỉ trên bãi biển sỏi.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:50:06.000000');
INSERT INTO `product` VALUES (351, 'Nến sáp ong Foxglove đổ bằng tay', 627000, 627000, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu mao địa hoàng. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:50:08.000000');
INSERT INTO `product` VALUES (352, 'Nến thơm Blackberry sáp dừa', 1005750, 1005750, 100, 100, 0, 'Nến thơm dâu đen số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:50:09.000000');
INSERT INTO `product` VALUES (353, 'Macramé Quế Treo Tường', 3440500, 3440500, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo treo trên dây bông quế tự nhiên. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:50:11.000000');
INSERT INTO `product` VALUES (354, 'Vòng hoa bạch đậu khấu khô', 976750, 976750, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa bạch đậu khấu. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:50:13.000000');
INSERT INTO `product` VALUES (355, 'Kệ Gỗ Cỏ Ba Lá Chạm Khắc Bằng Tay', 2816250, 2816250, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc bằng tay với chi tiết cạnh hình cỏ ba lá. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:50:14.000000');
INSERT INTO `product` VALUES (356, 'Thớt quả óc chó kế cuối hạt', 2441500, 2441500, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ cây kế và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:50:16.000000');
INSERT INTO `product` VALUES (357, 'Bộ bát gốm hoa tử đằng ném tay', 1470750, 1470750, 100, 100, 0, 'Bộ 4 chiếc bát gốm sứ tráng men phản ứng hoa tử đằng. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:50:17.000000');
INSERT INTO `product` VALUES (358, 'Mũ len Wren Merino dệt kim bằng tay', 1604500, 1604500, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ 100% len merino superwash với màu sắc màu hồng tước. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:50:20.000000');
INSERT INTO `product` VALUES (359, 'Dây buộc tóc bằng ren Crochet Falcon', 177250, 177250, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông chim ưng. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:50:22.000000');
INSERT INTO `product` VALUES (360, 'Khăn choàng lụa Osprey nhuộm tay', 2943750, 2943750, 100, 100, 0, 'Khăn choàng quấn lụa nhuộm tay sang trọng họa tiết màu nước chim ưng. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:50:25.000000');
INSERT INTO `product` VALUES (361, 'Ly hợp da Hawkweed khâu tay', 1677500, 1677500, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay hawkweed. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:50:27.000000');
INSERT INTO `product` VALUES (362, 'Ba lô vải Dogwood bằng vải sáp', 4058500, 4058500, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da bằng gỗ chó. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:50:29.000000');
INSERT INTO `product` VALUES (363, 'Tranh sáp nghệ thuật Sweetgrass nguyên bản', 2745250, 2745250, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng cỏ ngọt. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:50:31.000000');
INSERT INTO `product` VALUES (364, 'Tượng gốm Cattail điêu khắc bằng tay', 2139000, 2139000, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết tráng men đuôi mèo. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:50:34.000000');
INSERT INTO `product` VALUES (365, 'Mỹ thuật Bullrush In ảnh thiên nhiên', 1071750, 1071750, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên bò tót nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:50:36.000000');
INSERT INTO `product` VALUES (366, 'Xà Phòng Nghệ Nhân Cói Sữa Dê', 240500, 240500, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm cói và tạp chất thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:50:38.000000');
INSERT INTO `product` VALUES (367, 'Thanh gội đầu rắn Bracken', 525250, 525250, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược dương xỉ. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:50:40.000000');
INSERT INTO `product` VALUES (368, 'Tẩy tế bào chết toàn thân Sugar Sorrel', 324000, 324000, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường cây me chua thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu cây me chua. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:50:43.000000');
INSERT INTO `product` VALUES (369, 'Tạp chí da hoa cúc đóng tay', 1751750, 1751750, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da hoa cúc và chỉ khâu bằng vải lanh. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:50:45.000000');
INSERT INTO `product` VALUES (370, 'Thiệp cưới màu nước Yarrow', 181000, 181000, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật cỏ thi. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:50:48.000000');
INSERT INTO `product` VALUES (371, 'Câu đố bằng gỗ Valerian vẽ tay', 1454000, 1454000, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay cây nữ lang. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:50:51.000000');
INSERT INTO `product` VALUES (372, 'Đũa đồ chơi cho mèo Mugwort bện bằng tay', 289750, 289750, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây bông bện ngải cứu và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:50:54.000000');
INSERT INTO `product` VALUES (373, 'Vòng cổ mặt dây chuyền đá mặt trăng cây tầm ma thủ công', 1791250, 1791250, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng cây tầm ma chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:50:56.000000');
INSERT INTO `product` VALUES (374, 'Tên tùy chỉnh Vòng cổ Burdock Gold-Fill', 2135500, 2135500, 100, 100, 0, 'Vòng cổ tên ngưu bàng được cá nhân hóa được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:50:59.000000');
INSERT INTO `product` VALUES (375, 'Vòng cổ hình giọt nước phong cách cổ điển', 2135250, 2135250, 100, 100, 0, 'Vòng cổ mặt dây chuyền hình giọt nước bằng đồng thau lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:51:01.000000');
INSERT INTO `product` VALUES (376, 'Vòng tay tình bạn Crocus dệt tay', 635250, 635250, 100, 100, 0, 'Vòng tay tình bạn nghệ tây dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:51:04.000000');
INSERT INTO `product` VALUES (377, 'Vòng đeo tay bằng đồng Trillium rèn', 1201750, 1201750, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ trillium. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:51:07.000000');
INSERT INTO `product` VALUES (378, 'Vòng tay đá quý Bloodroot đính cườm', 725750, 725750, 100, 100, 0, 'Vòng tay hạt đá quý rễ cây máu được xâu chuỗi bằng dây co giãn bền bỉ. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:51:09.000000');
INSERT INTO `product` VALUES (379, 'Bông tai bạc Hepatica được rèn thủ công', 899500, 899500, 100, 100, 0, 'Bông tai đinh tán bằng bạc sterling được rèn thủ công với kết cấu Hepatica. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:51:11.000000');
INSERT INTO `product` VALUES (380, 'Bông tai pha lê Mayapple bọc dây', 1444750, 1444750, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê mayapple. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:51:14.000000');
INSERT INTO `product` VALUES (381, 'Vòng xếp chồng hoa cơm cháy được đóng dấu bằng tay', 647250, 647250, 100, 100, 0, 'Nhẫn xếp hình hoa cơm cháy được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:51:16.000000');
INSERT INTO `product` VALUES (382, 'Nhẫn pha lê thô Hawthorn', 1346000, 1346000, 100, 100, 0, 'Chiếc nhẫn nổi bật có pha lê táo gai thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với patina táo gai.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:51:18.000000');
INSERT INTO `product` VALUES (383, 'Nến sáp ong Blackthorn đổ bằng tay', 347000, 347000, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu mận gai. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:51:20.000000');
INSERT INTO `product` VALUES (384, 'Nến thơm sáp dừa Rowan', 525250, 525250, 100, 100, 0, 'Nến thơm thanh lương trà số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:51:22.000000');
INSERT INTO `product` VALUES (385, 'Treo tường Macramé Sloe', 2906250, 2906250, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo treo bằng dây cotton tự nhiên. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:51:23.000000');
INSERT INTO `product` VALUES (386, 'Vòng hoa khô Damson', 1334500, 1334500, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa của Damson. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:51:25.000000');
INSERT INTO `product` VALUES (387, 'Kệ gỗ hồng chạm khắc thủ công', 1668750, 1668750, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh quả hồng. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:51:27.000000');
INSERT INTO `product` VALUES (388, 'Thớt quả óc chó mộc qua cuối hạt', 3854500, 3854500, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó mộc qua và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:51:28.000000');
INSERT INTO `product` VALUES (389, 'Bộ bát sứ Medlar ném tay', 1260750, 1260750, 100, 100, 0, 'Bộ 4 bát gốm sứ tráng men phản ứng sơn tra. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:51:30.000000');
INSERT INTO `product` VALUES (390, 'Mũ len Merino dâu tằm dệt tay', 594000, 594000, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ 100% len merino superwash với màu dâu tằm. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:51:32.000000');
INSERT INTO `product` VALUES (391, 'Dây buộc tóc bằng ren quả dâu tằm', 168750, 168750, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông quả lý gai. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:51:34.000000');
INSERT INTO `product` VALUES (392, 'Khăn choàng lụa việt quất nhuộm tay', 1967500, 1967500, 100, 100, 0, 'Khăn choàng quấn lụa nhuộm tay sang trọng họa tiết màu nước việt quất. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:51:37.000000');
INSERT INTO `product` VALUES (393, 'Ly hợp da Crowberry khâu tay', 1243750, 1243750, 100, 100, 0, 'Ví cầm tay bằng da có chi tiết khâu tay hình quả dâu tây. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:51:39.000000');
INSERT INTO `product` VALUES (394, 'Ba lô mây vải sáp', 3113500, 3113500, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da màu mây. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:51:42.000000');
INSERT INTO `product` VALUES (395, 'Tranh sáp sơn gốc Lingonberry nguyên bản', 3066750, 3066750, 100, 100, 0, 'Bức tranh sơn dầu nguyên bản (sáp nóng) với bố cục trừu tượng của quả nam việt quất. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:51:46.000000');
INSERT INTO `product` VALUES (396, 'Tượng gốm Bearberry điêu khắc bằng tay', 2250000, 2250000, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết tráng men dâu tây. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:51:49.000000');
INSERT INTO `product` VALUES (397, 'Mỹ Thuật Hackberry In Ảnh Thiên Nhiên', 813250, 813250, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên hackberry gốc. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:51:52.000000');
INSERT INTO `product` VALUES (398, 'Xà Phòng Thủ Công Buffaloberry Sữa Dê', 362500, 362500, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm dâu rừng và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:51:54.000000');
INSERT INTO `product` VALUES (399, 'Thanh gội đầu Solid Aurora', 335750, 335750, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược aurora. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:51:56.000000');
INSERT INTO `product` VALUES (400, 'Tẩy tế bào chết Sugar Twilight', 649250, 649250, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường chạng vạng thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu chạng vạng. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:51:58.000000');
INSERT INTO `product` VALUES (401, 'Tạp chí da Heather ràng buộc bằng tay', 862500, 862500, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa bằng da thạch nam và dây vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:52:01.000000');
INSERT INTO `product` VALUES (402, 'Thiệp cưới lũa màu nước', 202500, 202500, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật bằng gỗ lũa. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:52:03.000000');
INSERT INTO `product` VALUES (403, 'Câu đố bằng gỗ Riverstone vẽ tay', 703000, 703000, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay bằng đá riverstone. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:52:05.000000');
INSERT INTO `product` VALUES (404, 'Đũa phép đồ chơi cho mèo Pebble Beach bện bằng tay', 306750, 306750, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây bông bện trên bãi biển và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:52:07.000000');
INSERT INTO `product` VALUES (405, 'Vòng cổ mặt dây chuyền đá mặt trăng Foxglove được làm thủ công', 1136250, 1136250, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng hình găng tay cáo chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:52:09.000000');
INSERT INTO `product` VALUES (406, 'Tên tùy chỉnh Vòng cổ Blackberry Gold-Fill', 1723250, 1723250, 100, 100, 0, 'Vòng cổ tên blackberry cá tính được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:52:12.000000');
INSERT INTO `product` VALUES (407, 'Vòng cổ mặt dây chuyền quế phong cách cổ điển', 3123000, 3123000, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng quế lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:52:14.000000');
INSERT INTO `product` VALUES (408, 'Vòng tay tình bạn bạch đậu khấu dệt tay', 213500, 213500, 100, 100, 0, 'Vòng tay tình bạn bạch đậu khấu dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:52:16.000000');
INSERT INTO `product` VALUES (409, 'Vòng đeo tay bằng đồng rèn cỏ ba lá', 828000, 828000, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ hình cỏ ba lá. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:52:18.000000');
INSERT INTO `product` VALUES (410, 'Vòng tay đá quý Thistle đính cườm', 1164750, 1164750, 100, 100, 0, 'Vòng tay hạt đá quý cây kế được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:52:21.000000');
INSERT INTO `product` VALUES (411, 'Bông tai bạc Wisteria được rèn thủ công', 1209750, 1209750, 100, 100, 0, 'Bông tai đinh tán bằng bạc được rèn thủ công với họa tiết hoa tử đằng. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:52:23.000000');
INSERT INTO `product` VALUES (412, 'Bông tai pha lê Wren có dây', 1022000, 1022000, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê hình chim hồng tước. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:52:25.000000');
INSERT INTO `product` VALUES (413, 'Vòng xếp chim ưng được đóng dấu bằng tay', 596000, 596000, 100, 100, 0, 'Nhẫn xếp hình chim ưng được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:52:27.000000');
INSERT INTO `product` VALUES (414, 'Nhẫn pha lê thô Osprey', 1062250, 1062250, 100, 100, 0, 'Chiếc nhẫn nổi bật có pha lê osprey thô bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với patina chim ưng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:52:30.000000');
INSERT INTO `product` VALUES (415, 'Nến sáp ong Hawkweed đổ bằng tay', 544000, 544000, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu diều hâu. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:52:31.000000');
INSERT INTO `product` VALUES (416, 'Nến thơm sáp dừa Dogwood', 726750, 726750, 100, 100, 0, 'Nến thơm gỗ cây sơn thùa số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:52:33.000000');
INSERT INTO `product` VALUES (417, 'Macramé Sweetgrass treo tường', 2938500, 2938500, 100, 100, 0, 'Bức tường macramé thắt nút thủ công phức tạp treo trên dây bông tự nhiên cỏ ngọt. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:52:35.000000');
INSERT INTO `product` VALUES (418, 'Vòng hoa đuôi mèo khô', 904500, 904500, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa ở đuôi mèo. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:52:37.000000');
INSERT INTO `product` VALUES (419, 'Kệ gỗ Bullrush chạm khắc bằng tay', 1630750, 1630750, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh bằng gỗ óc chó. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:52:38.000000');
INSERT INTO `product` VALUES (420, 'Thớt óc chó cói cuối hạt', 2069000, 2069000, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ gỗ óc chó cói và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:52:40.000000');
INSERT INTO `product` VALUES (421, 'Bộ bát sứ Bracken ném tay', 2472500, 2472500, 100, 100, 0, 'Bộ 4 chiếc bát sứ thủ công phủ men phản ứng dương xỉ. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:52:41.000000');
INSERT INTO `product` VALUES (422, 'Mũ len merino merino dệt kim bằng tay', 1424500, 1424500, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu màu nâu đất. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:52:44.000000');
INSERT INTO `product` VALUES (423, 'Dây buộc tóc ren hoa cúc móc', 171250, 171250, 100, 100, 0, 'Dây buộc tóc móc thủ công có họa tiết ren bông hoa cúc. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:52:46.000000');
INSERT INTO `product` VALUES (424, 'Khăn choàng quấn lụa Yarrow nhuộm tay', 1377250, 1377250, 100, 100, 0, 'Khăn choàng quấn lụa nhuộm tay sang trọng họa tiết màu nước cỏ thi. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:52:48.000000');
INSERT INTO `product` VALUES (425, 'Ly hợp da Valerian khâu tay', 1395750, 1395750, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay nữ lang. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:52:51.000000');
INSERT INTO `product` VALUES (426, 'Ba lô vải bạt Mugwort', 3596000, 3596000, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da ngải cứu. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:52:53.000000');
INSERT INTO `product` VALUES (427, 'Tranh sáp cây tầm ma nguyên bản', 5343750, 5343750, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng từ cây tầm ma. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:52:56.000000');
INSERT INTO `product` VALUES (428, 'Tượng gốm ngưu bàng điêu khắc bằng tay', 2330500, 2330500, 100, 100, 0, 'Tượng gốm bằng đá được điêu khắc thủ công với các chi tiết tráng men ngưu bàng. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:52:58.000000');
INSERT INTO `product` VALUES (429, 'In ảnh thiên nhiên giọt nước tuyết mỹ thuật', 977000, 977000, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên giọt tuyết nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:53:02.000000');
INSERT INTO `product` VALUES (430, 'Xà Phòng Nghệ Nghệ Crocus Sữa Dê', 312750, 312750, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm hoa nghệ tây và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:53:05.000000');
INSERT INTO `product` VALUES (431, 'Thanh gội đầu Trillium rắn', 553500, 553500, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo mộc trillium. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:53:08.000000');
INSERT INTO `product` VALUES (432, 'Tẩy tế bào chết toàn thân Sugar Bloodroot', 672250, 672250, 100, 100, 0, 'Tẩy tế bào chết bằng đường huyết thủ công với gốc dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu rễ huyết. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:53:11.000000');
INSERT INTO `product` VALUES (433, 'Tạp chí da Hepatica đóng bìa tay', 1988750, 1988750, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da Hepatica và dây buộc bằng chỉ khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:53:13.000000');
INSERT INTO `product` VALUES (434, 'Thiệp cưới Mayapple màu nước', 184250, 184250, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật mayapple. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:53:16.000000');
INSERT INTO `product` VALUES (435, 'Câu đố bằng gỗ hoa cơm cháy vẽ tay', 1315500, 1315500, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay hoa cơm cháy. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:53:18.000000');
INSERT INTO `product` VALUES (436, 'Cây đũa phép đồ chơi cho mèo Hawthorn bện bằng tay', 483000, 483000, 100, 100, 0, 'Đồ chơi đũa phép mèo thủ công với dây bông bện táo gai và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:53:20.000000');
INSERT INTO `product` VALUES (437, 'Vòng cổ mặt dây chuyền đá mặt trăng Blackthorn thủ công', 1157750, 1157750, 100, 100, 0, 'Vòng cổ có mặt dây chuyền thủ công tinh tế đính đá mặt trăng gai đen chính hãng được đặt bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:53:23.000000');
INSERT INTO `product` VALUES (438, 'Tên tùy chỉnh Vòng cổ Rowan Gold-Fill', 1331500, 1331500, 100, 100, 0, 'Vòng cổ tên thanh lương trà được cá nhân hóa được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:53:25.000000');
INSERT INTO `product` VALUES (439, 'Vòng cổ Mề đay Sloe theo phong cách cổ điển', 3093250, 3093250, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:53:27.000000');
INSERT INTO `product` VALUES (440, 'Vòng tay tình bạn Damson dệt tay', 309750, 309750, 100, 100, 0, 'Vòng tay tình bạn Damson dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:53:29.000000');
INSERT INTO `product` VALUES (441, 'Vòng đeo tay bằng đồng hình quả hồng rèn', 941250, 941250, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ màu hồng. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:53:32.000000');
INSERT INTO `product` VALUES (442, 'Vòng tay đá quý mộc qua đính cườm', 570500, 570500, 100, 100, 0, 'Vòng tay hạt đá quý mộc qua được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:53:34.000000');
INSERT INTO `product` VALUES (443, 'Bông tai bạc Medlar được rèn bằng tay', 1251250, 1251250, 100, 100, 0, 'Bông tai đinh tán bằng bạc sterling được rèn thủ công với kết cấu màu sơn tra. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:53:37.000000');
INSERT INTO `product` VALUES (444, 'Bông tai pha lê dâu tằm có dây', 1354250, 1354250, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê dâu tằm. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:53:40.000000');
INSERT INTO `product` VALUES (445, 'Vòng xếp chồng ngỗng được đóng dấu bằng tay', 500500, 500500, 100, 100, 0, 'Nhẫn xếp chồng quả lý gai được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:53:43.000000');
INSERT INTO `product` VALUES (446, 'Nhẫn tuyên bố quả việt quất pha lê thô', 1233000, 1233000, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê việt quất thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với patina cây nham lê.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:53:46.000000');
INSERT INTO `product` VALUES (447, 'Nến sáp ong Crowberry đổ bằng tay', 589000, 589000, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ thủ công với hỗn hợp tinh dầu quả quạ. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:53:49.000000');
INSERT INTO `product` VALUES (448, 'Nến thơm sáp dừa Cloudberry', 361750, 361750, 100, 100, 0, 'Nến thơm mâm xôi số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:53:52.000000');
INSERT INTO `product` VALUES (449, 'Macramé Lingonberry treo tường', 2846500, 2846500, 100, 100, 0, 'Bức tường macramé thắt nút thủ công phức tạp treo bằng dây bông tự nhiên lingonberry. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:53:53.000000');
INSERT INTO `product` VALUES (450, 'Vòng hoa Bearberry khô', 981750, 981750, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa dâu tây. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:53:56.000000');
INSERT INTO `product` VALUES (451, 'Kệ Gỗ Hackberry Chạm Khắc Bằng Tay', 2227250, 2227250, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh hackberry. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:53:58.000000');
INSERT INTO `product` VALUES (452, 'Thớt quả óc chó Buffaloberry cuối hạt', 3680250, 3680250, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó trâu và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:53:59.000000');
INSERT INTO `product` VALUES (453, 'Bộ bát sứ Aurora ném tay', 1778750, 1778750, 100, 100, 0, 'Bộ 4 bát gốm sứ tráng men phản ứng aurora. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:54:01.000000');
INSERT INTO `product` VALUES (454, 'Mũ len Merino Chạng vạng dệt kim bằng tay', 1429250, 1429250, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ 100% len merino siêu giặt với màu chạng vạng. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:54:04.000000');
INSERT INTO `product` VALUES (455, 'Dây buộc tóc bằng ren đan móc Heather', 420750, 420750, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông thạch nam. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:54:06.000000');
INSERT INTO `product` VALUES (456, 'Khăn lụa quấn gỗ lũa nhuộm tay', 3574750, 3574750, 100, 100, 0, 'Khăn choàng lụa nhuộm tay sang trọng họa tiết màu nước bằng gỗ lũa. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:54:08.000000');
INSERT INTO `product` VALUES (457, 'Ly hợp da Riverstone khâu tay', 2136250, 2136250, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay bằng đá riverstone. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:54:10.000000');
INSERT INTO `product` VALUES (458, 'Ba lô vải sáp Pebble Beach', 5262000, 5262000, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền bằng da cuội đi biển. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:54:13.000000');
INSERT INTO `product` VALUES (459, 'Tranh sáp nguyên bản Foxglove', 3349750, 3349750, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng bao tay cáo. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:54:16.000000');
INSERT INTO `product` VALUES (460, 'Tượng gốm Blackberry điêu khắc bằng tay', 2369000, 2369000, 100, 100, 0, 'Tượng gốm bằng đá được điêu khắc bằng tay với các chi tiết tráng men dâu đen. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:54:18.000000');
INSERT INTO `product` VALUES (461, 'In Ảnh Nghệ Thuật Quế Thiên Nhiên', 1312000, 1312000, 100, 100, 0, 'Lưu trữ bản in mỹ thuật của bức ảnh thiên nhiên quế nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:54:21.000000');
INSERT INTO `product` VALUES (462, 'Xà phòng thủ công bạch đậu khấu sữa dê', 348750, 348750, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm bạch đậu khấu và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:54:23.000000');
INSERT INTO `product` VALUES (463, 'Thanh gội đầu Solid Clover', 551750, 551750, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược cỏ ba lá. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:54:27.000000');
INSERT INTO `product` VALUES (464, 'Tẩy tế bào chết toàn thân Sugar Thistle', 308250, 308250, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường cây kế thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu cây kế. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:54:30.000000');
INSERT INTO `product` VALUES (465, 'Tạp chí da Wisteria ràng buộc bằng tay', 1108250, 1108250, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da hoa đậu tía và dây vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:54:32.000000');
INSERT INTO `product` VALUES (466, 'Thiệp cưới Wren màu nước', 299500, 299500, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật chim hồng tước. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:54:35.000000');
INSERT INTO `product` VALUES (467, 'Câu đố bằng gỗ chim ưng vẽ tay', 623250, 623250, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay chim ưng. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:54:37.000000');
INSERT INTO `product` VALUES (468, 'Đũa đồ chơi cho mèo Osprey bện tay', 523750, 523750, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây bông bện chim ưng và phần đính kèm lông tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:54:39.000000');
INSERT INTO `product` VALUES (469, 'Vòng cổ mặt dây chuyền đá mặt trăng Hawkweed được làm thủ công', 1460000, 1460000, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng hawkweed chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:54:42.000000');
INSERT INTO `product` VALUES (470, 'Tên tùy chỉnh Vòng cổ mạ vàng Dogwood', 1794000, 1794000, 100, 100, 0, 'Vòng cổ tên bằng gỗ chó được cá nhân hóa được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:54:44.000000');
INSERT INTO `product` VALUES (471, 'Vòng cổ Sweetgrass Locket theo phong cách cổ điển', 3241250, 3241250, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau Sweetgrass lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:54:46.000000');
INSERT INTO `product` VALUES (472, 'Vòng tay tình bạn Cattail dệt tay', 242500, 242500, 100, 100, 0, 'Vòng tay tình bạn đuôi mèo dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:54:49.000000');
INSERT INTO `product` VALUES (473, 'Vòng đeo tay bằng đồng rèn Bullrush', 573750, 573750, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ màu bullrush. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:54:51.000000');
INSERT INTO `product` VALUES (474, 'Vòng tay đá quý cói đính cườm', 1111750, 1111750, 100, 100, 0, 'Vòng tay hạt đá quý cói được xâu chuỗi trên dây co giãn bền chắc. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:54:53.000000');
INSERT INTO `product` VALUES (475, 'Bông tai bạc Bracken được rèn thủ công', 1009250, 1009250, 100, 100, 0, 'Bông tai đinh tán bằng bạc được rèn thủ công với kết cấu dương xỉ. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:54:56.000000');
INSERT INTO `product` VALUES (476, 'Bông tai pha lê hình cây me chua có dây', 1685750, 1685750, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn là pha lê màu me chua. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:54:58.000000');
INSERT INTO `product` VALUES (477, 'Vòng xếp chồng hoa cúc được đóng dấu bằng tay', 458750, 458750, 100, 100, 0, 'Nhẫn xếp hình hoa cúc được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:55:00.000000');
INSERT INTO `product` VALUES (478, 'Nhẫn tuyên bố pha lê thô Yarrow', 1839500, 1839500, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê yarrow thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với patina yarrow.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:55:03.000000');
INSERT INTO `product` VALUES (479, 'Nến sáp ong Valerian đổ bằng tay', 727500, 727500, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ thủ công với hỗn hợp tinh dầu cây nữ lang. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:55:05.000000');
INSERT INTO `product` VALUES (480, 'Nến thơm ngải cứu sáp dừa', 755000, 755000, 100, 100, 0, 'Nến thơm ngải cứu số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:55:07.000000');
INSERT INTO `product` VALUES (481, 'Cây tầm ma treo tường Macramé', 1000000, 1000000, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo được treo bằng dây bông tự nhiên hình cây tầm ma. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:55:08.000000');
INSERT INTO `product` VALUES (482, 'Vòng hoa ngưu bàng khô', 1974000, 1974000, 100, 100, 0, 'Vòng hoa khô thủ công có hình cây ngưu bàng theo mùa. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:55:10.000000');
INSERT INTO `product` VALUES (483, 'Kệ gỗ hình giọt nước tuyết chạm khắc thủ công', 1752000, 1752000, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh hình giọt nước tuyết. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:55:11.000000');
INSERT INTO `product` VALUES (484, 'Thớt quả óc chó Crocus cuối hạt', 3461750, 3461750, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:55:13.000000');
INSERT INTO `product` VALUES (485, 'Bộ bát sứ Trillium ném tay', 3236250, 3236250, 100, 100, 0, 'Bộ 4 bát gốm sứ tráng men phản ứng trillium. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:55:15.000000');
INSERT INTO `product` VALUES (486, 'Mũ len Merino Bloodroot dệt kim bằng tay', 564750, 564750, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu sắc máu. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:55:17.000000');
INSERT INTO `product` VALUES (487, 'Dây buộc tóc ren Hepatica', 279000, 279000, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông Hepatica. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:55:19.000000');
INSERT INTO `product` VALUES (488, 'Khăn choàng lụa Mayapple nhuộm tay', 4308000, 4308000, 100, 100, 0, 'Khăn choàng quấn lụa nhuộm tay sang trọng họa tiết màu nước mayapple. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:55:21.000000');
INSERT INTO `product` VALUES (489, 'Ly hợp da Elderflower khâu tay', 1806250, 1806250, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay hoa cơm cháy. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:55:24.000000');
INSERT INTO `product` VALUES (490, 'Ba lô vải táo gai sáp', 4953000, 4953000, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da táo gai. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:55:26.000000');
INSERT INTO `product` VALUES (491, 'Tranh sáp sơn dầu Blackthorn nguyên bản', 6026750, 6026750, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng của cây gai đen. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:55:28.000000');
INSERT INTO `product` VALUES (492, 'Tượng gốm Rowan điêu khắc bằng tay', 1872500, 1872500, 100, 100, 0, 'Tượng gốm bằng đá được điêu khắc thủ công với các chi tiết tráng men thanh lương trà. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:55:31.000000');
INSERT INTO `product` VALUES (493, 'Mỹ Thuật Sloe Thiên Nhiên In Ảnh', 1872500, 1872500, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên sloe nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:55:33.000000');
INSERT INTO `product` VALUES (494, 'Sữa Dê Xà Phòng Thủ Công Damson', 404250, 404250, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm Damson và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:55:35.000000');
INSERT INTO `product` VALUES (495, 'Thanh gội đầu hồng đặc', 264250, 264250, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược hồng. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:55:38.000000');
INSERT INTO `product` VALUES (496, 'Tẩy tế bào chết cơ thể Sugar Quince', 713000, 713000, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường mộc qua thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu mộc qua. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:55:41.000000');
INSERT INTO `product` VALUES (497, 'Tạp chí da Medlar ràng buộc bằng tay', 1771250, 1771250, 100, 100, 0, 'Nhật ký đóng bìa tay với bìa da sơn tra và dây vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:55:44.000000');
INSERT INTO `product` VALUES (498, 'Thiệp cưới màu nước dâu tằm', 212000, 212000, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật dâu tằm. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:55:46.000000');
INSERT INTO `product` VALUES (499, 'Câu đố bằng gỗ Gooseberry vẽ tay', 653500, 653500, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay bằng quả lý gai. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:55:49.000000');
INSERT INTO `product` VALUES (500, 'Đũa phép đồ chơi cho mèo Bilberry bện bằng tay', 294250, 294250, 100, 100, 0, 'Đồ chơi đũa phép mèo thủ công với dây bông bện quả việt quất và phần đính kèm lông tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:55:52.000000');
INSERT INTO `product` VALUES (501, 'Vòng cổ mặt dây chuyền đá mặt trăng Crowberry thủ công', 1581750, 1581750, 100, 100, 0, 'Vòng cổ có mặt dây chuyền thủ công tinh tế có đính đá mặt trăng quả quạ chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:55:55.000000');
INSERT INTO `product` VALUES (502, 'Tên tùy chỉnh Vòng cổ Cloudberry Gold-Fill', 1344000, 1344000, 100, 100, 0, 'Vòng cổ tên quả mâm xôi được cá nhân hóa được đóng dấu thủ công trên đĩa phủ vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:55:57.000000');
INSERT INTO `product` VALUES (503, 'Vòng cổ mặt dây chuyền Lingonberry phong cách cổ điển', 3220000, 3220000, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng lingonberry lấy cảm hứng từ cổ. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:55:59.000000');
INSERT INTO `product` VALUES (504, 'Vòng tay tình bạn Bearberry dệt tay', 279250, 279250, 100, 100, 0, 'Vòng tay tình bạn Bearberry dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:56:01.000000');
INSERT INTO `product` VALUES (505, 'Vòng đeo tay bằng đồng Hackberry rèn', 879000, 879000, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ sắt hackberry. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:56:04.000000');
INSERT INTO `product` VALUES (506, 'Vòng tay đá quý Buffaloberry đính cườm', 595250, 595250, 100, 100, 0, 'Vòng tay hạt đá quý trâu được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:56:06.000000');
INSERT INTO `product` VALUES (507, 'Bông tai bạc Aurora được rèn thủ công', 1123500, 1123500, 100, 100, 0, 'Bông tai đinh tán bằng bạc được rèn thủ công với kết cấu cực quang. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:56:08.000000');
INSERT INTO `product` VALUES (508, 'Bông tai Hoop Pha lê Chạng vạng có dây', 1639000, 1639000, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê màu chạng vạng. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:56:10.000000');
INSERT INTO `product` VALUES (509, 'Nhẫn xếp chồng thạch cao được đóng dấu bằng tay', 507000, 507000, 100, 100, 0, 'Chiếc nhẫn xếp chồng thạch nam được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:56:13.000000');
INSERT INTO `product` VALUES (510, 'Nhẫn gỗ lũa pha lê thô', 1162750, 1162750, 100, 100, 0, 'Chiếc nhẫn nổi bật có pha lê gỗ lũa thô được đặt bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thiện với lớp gỉ lũa.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:56:15.000000');
INSERT INTO `product` VALUES (511, 'Nến sáp ong Riverstone đổ bằng tay', 877500, 877500, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu riverstone. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:56:17.000000');
INSERT INTO `product` VALUES (512, 'Nến thơm sáp dừa Pebble Beach', 768500, 768500, 100, 100, 0, 'Nến thơm bãi biển sỏi số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:56:19.000000');
INSERT INTO `product` VALUES (513, 'Treo tường Macramé Foxglove', 1504750, 1504750, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo được treo bằng dây bông tự nhiên hình mao địa hoàng. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:56:21.000000');
INSERT INTO `product` VALUES (514, 'Vòng hoa mâm xôi khô', 2245500, 2245500, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa của dâu đen. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:56:23.000000');
INSERT INTO `product` VALUES (515, 'Kệ Gỗ Quế Chạm Khắc Bằng Tay', 3337750, 3337750, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết viền quế. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:56:24.000000');
INSERT INTO `product` VALUES (516, 'Thớt quả óc chó bạch đậu khấu cuối hạt', 2333250, 2333250, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó bạch đậu khấu và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:56:26.000000');
INSERT INTO `product` VALUES (517, 'Bộ bát sứ ném cỏ ba lá bằng tay', 2118250, 2118250, 100, 100, 0, 'Bộ 4 chiếc bát gốm sứ ném bằng tay phủ men phản ứng cỏ ba lá. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:56:28.000000');
INSERT INTO `product` VALUES (518, 'Mũ len Merino dệt kim bằng tay', 1125000, 1125000, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu sắc cây kế. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:56:30.000000');
INSERT INTO `product` VALUES (519, 'Dây buộc tóc bằng ren móc Wisteria', 340250, 340250, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông hoa tử đằng. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:56:32.000000');
INSERT INTO `product` VALUES (520, 'Khăn choàng lụa Wren nhuộm tay', 2810750, 2810750, 100, 100, 0, 'Khăn choàng lụa quấn tay sang trọng họa tiết màu nước chim hồng tước. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:56:35.000000');
INSERT INTO `product` VALUES (521, 'Ly hợp da Falcon khâu tay', 1479000, 1479000, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay hình chim ưng. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:56:37.000000');
INSERT INTO `product` VALUES (522, 'Ba lô Osprey vải sáp', 3235750, 3235750, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da chim ưng. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:56:39.000000');
INSERT INTO `product` VALUES (523, 'Tranh sáp nguyên bản Hawkweed', 2317000, 2317000, 100, 100, 0, 'Bức tranh sơn dầu nguyên bản (sáp nóng) với bố cục trừu tượng hawkweed. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:56:42.000000');
INSERT INTO `product` VALUES (524, 'Tượng gốm Dogwood điêu khắc bằng tay', 1566500, 1566500, 100, 100, 0, 'Tượng gốm bằng đá được điêu khắc thủ công với các chi tiết được tráng men bằng gỗ sơn thù du. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:56:44.000000');
INSERT INTO `product` VALUES (525, 'Mỹ thuật Sweetgrass In ảnh thiên nhiên', 1324500, 1324500, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên cỏ ngọt nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:56:46.000000');
INSERT INTO `product` VALUES (526, 'Xà phòng thủ công Cattail sữa dê', 370500, 370500, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm đuôi mèo và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:56:48.000000');
INSERT INTO `product` VALUES (527, 'Thanh gội đầu rắn Bullrush', 251500, 251500, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo mộc bullrush. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:56:51.000000');
INSERT INTO `product` VALUES (528, 'Tẩy tế bào chết bằng đường cói', 555750, 555750, 100, 100, 0, 'Tẩy tế bào chết bằng đường cói handmade gốc dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm từ đường mía hữu cơ và tinh dầu cói. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:56:53.000000');
INSERT INTO `product` VALUES (529, 'Tạp chí da Bracken đóng bìa tay', 1813500, 1813500, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da dương xỉ và dây vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:56:55.000000');
INSERT INTO `product` VALUES (530, 'Thiệp cưới màu nước cây me chua', 254000, 254000, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật cây me chua. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:56:57.000000');
INSERT INTO `product` VALUES (531, 'Câu đố bằng gỗ hoa cúc bằng tay', 913000, 913000, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay hoa cúc. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:56:59.000000');
INSERT INTO `product` VALUES (532, 'Cây đũa phép đồ chơi cho mèo Yarrow bện bằng tay', 475000, 475000, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây bông bện cỏ thi và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:57:02.000000');
INSERT INTO `product` VALUES (533, 'Vòng cổ mặt dây chuyền đá mặt trăng Valerian thủ công', 1369250, 1369250, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng valerian chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:57:04.000000');
INSERT INTO `product` VALUES (534, 'Tên tùy chỉnh Vòng cổ Mugwort mạ vàng', 2362750, 2362750, 100, 100, 0, 'Vòng cổ tên ngải cứu cá nhân được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:57:06.000000');
INSERT INTO `product` VALUES (535, 'Vòng cổ Mề đay cây tầm ma phong cách cổ điển', 1023750, 1023750, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:57:08.000000');
INSERT INTO `product` VALUES (536, 'Vòng tay tình bạn cây ngưu bàng dệt tay', 244250, 244250, 100, 100, 0, 'Vòng tay tình bạn ngưu bàng dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:57:10.000000');
INSERT INTO `product` VALUES (537, 'Vòng đeo tay bằng đồng hình giọt nước bằng búa rèn', 1099500, 1099500, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ hình giọt nước tuyết. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:57:13.000000');
INSERT INTO `product` VALUES (538, 'Vòng tay đá quý Crocus đính cườm', 548250, 548250, 100, 100, 0, 'Vòng tay hạt đá quý crocus được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:57:15.000000');
INSERT INTO `product` VALUES (539, 'Bông tai bạc Trillium được rèn thủ công', 570000, 570000, 100, 100, 0, 'Bông tai đinh tán bằng bạc được rèn thủ công với kết cấu trillium. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:57:17.000000');
INSERT INTO `product` VALUES (540, 'Bông tai pha lê Bloodroot có dây', 1783250, 1783250, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn là pha lê hình rễ máu. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:57:20.000000');
INSERT INTO `product` VALUES (541, 'Vòng xếp chồng Hepatica được đóng dấu bằng tay', 940750, 940750, 100, 100, 0, 'Chiếc nhẫn xếp chồng Hexica được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:57:22.000000');
INSERT INTO `product` VALUES (542, 'Nhẫn tuyên bố Mayapple pha lê thô', 1035750, 1035750, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê mayapple thô bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với patina mayapple.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:57:24.000000');
INSERT INTO `product` VALUES (543, 'Nến sáp ong hoa cơm cháy bằng tay', 374500, 374500, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu hoa cơm cháy. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:57:26.000000');
INSERT INTO `product` VALUES (544, 'Nến thơm sáp dừa táo gai', 862000, 862000, 100, 100, 0, 'Nến thơm táo gai số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:57:27.000000');
INSERT INTO `product` VALUES (545, 'Treo tường Macramé Blackthorn', 2755500, 2755500, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo treo bằng dây bông tự nhiên gai đen. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:57:29.000000');
INSERT INTO `product` VALUES (546, 'Vòng hoa thanh lương hoa khô', 1113250, 1113250, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa thanh lương trà. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:57:30.000000');
INSERT INTO `product` VALUES (547, 'Kệ Gỗ Sloe Chạm Khắc Bằng Tay', 2720500, 2720500, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh dốc. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:57:32.000000');
INSERT INTO `product` VALUES (548, 'Thớt quả óc chó Damson cuối hạt', 3378500, 3378500, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó Damson và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:57:33.000000');
INSERT INTO `product` VALUES (549, 'Bộ bát sứ ném hồng bằng tay', 1382500, 1382500, 100, 100, 0, 'Bộ 4 bát gốm sứ tráng men phản ứng hình quả hồng. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:57:35.000000');
INSERT INTO `product` VALUES (550, 'Mũ len mộc qua Merino dệt kim bằng tay', 678250, 678250, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu mộc qua. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:57:37.000000');
INSERT INTO `product` VALUES (551, 'Dây buộc tóc bằng ren móc Medlar', 157500, 157500, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông sơn tra. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:57:40.000000');
INSERT INTO `product` VALUES (552, 'Khăn choàng lụa dâu tằm nhuộm tay', 3992250, 3992250, 100, 100, 0, 'Khăn choàng lụa nhuộm tay sang trọng họa tiết màu nước dâu tằm. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:57:42.000000');
INSERT INTO `product` VALUES (553, 'Ly hợp da ngỗng khâu tay', 1832250, 1832250, 100, 100, 0, 'Ví cầm tay bằng da có chi tiết khâu bằng tay hình quả lý gai. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:57:45.000000');
INSERT INTO `product` VALUES (554, 'Ba lô vải việt quất sáp', 3255000, 3255000, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da việt quất. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:57:47.000000');
INSERT INTO `product` VALUES (555, 'Tranh sáp Crowberry nguyên bản', 1855250, 1855250, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng của cây dâu tây. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:57:49.000000');
INSERT INTO `product` VALUES (556, 'Tượng gốm Cloudberry điêu khắc bằng tay', 1804250, 1804250, 100, 100, 0, 'Tượng gốm bằng đá được điêu khắc thủ công với các chi tiết tráng men mâm xôi. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:57:51.000000');
INSERT INTO `product` VALUES (557, 'Mỹ Thuật Lingonberry Chụp Ảnh Thiên Nhiên', 806500, 806500, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên lingonberry gốc. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:57:53.000000');
INSERT INTO `product` VALUES (558, 'Xà Phòng Thủ Công Bearberry Sữa Dê', 351250, 351250, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm dâu tây và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:57:56.000000');
INSERT INTO `product` VALUES (559, 'Thanh dầu gội Hackberry rắn', 356000, 356000, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược hackberry. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:57:58.000000');
INSERT INTO `product` VALUES (560, 'Tẩy tế bào chết toàn thân Sugar Buffaloberry', 441500, 441500, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường dâu tằm thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu trâu. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:58:00.000000');
INSERT INTO `product` VALUES (561, 'Tạp chí da Aurora đóng bìa tay', 761250, 761250, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da cực quang và dây vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:58:04.000000');
INSERT INTO `product` VALUES (562, 'Thiệp cưới màu nước chạng vạng', 198250, 198250, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật chạng vạng. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:58:07.000000');
INSERT INTO `product` VALUES (563, 'Câu đố bằng gỗ thạch nam vẽ tay', 1531000, 1531000, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay bằng thạch nam. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:58:09.000000');
INSERT INTO `product` VALUES (564, 'Đũa đồ chơi cho mèo lũa bện bằng tay', 530250, 530250, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây bông bện bằng gỗ lũa và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:58:13.000000');
INSERT INTO `product` VALUES (565, 'Vòng cổ mặt dây chuyền đá mặt trăng Riverstone thủ công', 2230750, 2230750, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đá mặt trăng bằng đá sông chính hãng được đặt bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:58:16.000000');
INSERT INTO `product` VALUES (566, 'Tên tùy chỉnh Vòng cổ lấp đầy vàng Pebble Beach', 2470250, 2470250, 100, 100, 0, 'Vòng cổ tên bãi biển sỏi được cá nhân hóa được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:58:19.000000');
INSERT INTO `product` VALUES (567, 'Vòng cổ mặt dây chuyền Foxglove phong cách cổ điển', 2824750, 2824750, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng foxglove lấy cảm hứng từ cổ. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:58:22.000000');
INSERT INTO `product` VALUES (568, 'Vòng tay tình bạn Blackberry dệt tay', 514000, 514000, 100, 100, 0, 'Vòng tay tình bạn blackberry dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:58:26.000000');
INSERT INTO `product` VALUES (569, 'Vòng đeo tay bằng đồng quế rèn', 1275750, 1275750, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ màu quế. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:58:29.000000');
INSERT INTO `product` VALUES (570, 'Vòng tay đá quý bạch đậu khấu đính cườm', 1294000, 1294000, 100, 100, 0, 'Vòng tay hạt đá quý bạch đậu khấu được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:58:32.000000');
INSERT INTO `product` VALUES (571, 'Bông tai bạc hình cỏ ba lá được rèn thủ công', 1335500, 1335500, 100, 100, 0, 'Bông tai bạc sterling được rèn bằng tay với kết cấu cỏ ba lá. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:58:35.000000');
INSERT INTO `product` VALUES (572, 'Bông tai pha lê Thistle có dây', 1330250, 1330250, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê hình cây kế. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:58:37.000000');
INSERT INTO `product` VALUES (573, 'Vòng xếp chồng Wisteria được đóng dấu bằng tay', 759750, 759750, 100, 100, 0, 'Chiếc nhẫn xếp chồng hoa tử đằng được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:58:40.000000');
INSERT INTO `product` VALUES (574, 'Nhẫn tuyên bố pha lê thô', 1626750, 1626750, 100, 100, 0, 'Chiếc nhẫn nổi bật có pha lê wren thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với patina wren.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:58:43.000000');
INSERT INTO `product` VALUES (575, 'Nến sáp ong Falcon đổ bằng tay', 849250, 849250, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu chim ưng. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:58:45.000000');
INSERT INTO `product` VALUES (576, 'Nến thơm sáp dừa Osprey', 723750, 723750, 100, 100, 0, 'Nến thơm chim ưng biển số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:58:47.000000');
INSERT INTO `product` VALUES (577, 'Treo tường Macramé Hawkweed', 1002500, 1002500, 100, 100, 0, 'Bức tường macramé được thắt nút bằng tay phức tạp treo bằng dây bông tự nhiên hawkweed. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:58:49.000000');
INSERT INTO `product` VALUES (578, 'Vòng hoa Dogwood khô', 1708000, 1708000, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa bằng gỗ sơn thù du. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:58:51.000000');
INSERT INTO `product` VALUES (579, 'Kệ Gỗ Sweetgrass Chạm Khắc Bằng Tay', 2114000, 2114000, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết viền cỏ ngọt. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:58:53.000000');
INSERT INTO `product` VALUES (580, 'Thớt quả óc chó đuôi mèo cuối hạt', 1776000, 1776000, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó đuôi mèo và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:58:54.000000');
INSERT INTO `product` VALUES (581, 'Bộ bát sứ ném bằng tay Bullrush', 1293750, 1293750, 100, 100, 0, 'Bộ 4 chiếc bát gốm sứ thủ công phủ men phản ứng bullrush. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:58:56.000000');
INSERT INTO `product` VALUES (582, 'Mũ len Merino cói dệt kim bằng tay', 1164000, 1164000, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu sắc cói. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:58:59.000000');
INSERT INTO `product` VALUES (583, 'Dây buộc tóc bằng ren Crochet Bracken', 436500, 436500, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông dương xỉ. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:59:02.000000');
INSERT INTO `product` VALUES (584, 'Khăn choàng lụa màu sầu riêng nhuộm tay', 3119000, 3119000, 100, 100, 0, 'Khăn choàng quấn lụa nhuộm tay sang trọng họa tiết màu nước cây me chua. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:59:05.000000');
INSERT INTO `product` VALUES (585, 'Ly hợp da hoa cúc khâu tay', 3105750, 3105750, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay hình hoa cúc. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:59:07.000000');
INSERT INTO `product` VALUES (586, 'Ba lô vải cỏ thi sáp', 2708750, 2708750, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền bằng da yarrow. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:59:10.000000');
INSERT INTO `product` VALUES (587, 'Tranh sáp nghệ thuật Valerian nguyên bản', 3392750, 3392750, 100, 100, 0, 'Bức tranh sơn dầu nguyên bản (sáp nóng) với bố cục trừu tượng của cây nữ lang. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:59:12.000000');
INSERT INTO `product` VALUES (588, 'Tượng gốm Mugwort điêu khắc bằng tay', 2302250, 2302250, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết tráng men ngải cứu. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:59:15.000000');
INSERT INTO `product` VALUES (589, 'In ảnh nghệ thuật cây tầm ma thiên nhiên', 1431500, 1431500, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên cây tầm ma nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:59:18.000000');
INSERT INTO `product` VALUES (590, 'Xà phòng nghệ nhân ngưu bàng sữa dê', 411250, 411250, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm cây ngưu bàng và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:59:21.000000');
INSERT INTO `product` VALUES (591, 'Thanh gội đầu Snowdrop rắn', 335750, 335750, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược hình giọt nước tuyết. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:59:24.000000');
INSERT INTO `product` VALUES (592, 'Sugar Crocus Tẩy Tế Bào Chết Toàn Thân', 617500, 617500, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường nghệ thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu nghệ tây. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:59:26.000000');
INSERT INTO `product` VALUES (593, 'Tạp chí Da Trillium ràng buộc bằng tay', 1189000, 1189000, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da trillium và dây vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:59:29.000000');
INSERT INTO `product` VALUES (594, 'Thiệp cưới màu nước Bloodroot', 169750, 169750, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật có rễ máu. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:59:31.000000');
INSERT INTO `product` VALUES (595, 'Câu đố bằng gỗ Hepatica vẽ tay', 719500, 719500, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay bằng tay. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:59:33.000000');
INSERT INTO `product` VALUES (596, 'Đũa phép đồ chơi cho mèo Mayapple bện tay', 261500, 261500, 100, 100, 0, 'Đồ chơi đũa phép mèo thủ công với dây bông bện mayapple và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:59:36.000000');
INSERT INTO `product` VALUES (597, 'Vòng cổ mặt dây chuyền đá mặt trăng Elderflower thủ công', 855000, 855000, 100, 100, 0, 'Vòng cổ có mặt dây chuyền thủ công tinh tế đính đá mặt trăng hoa cơm cháy chính hãng được làm bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:59:38.000000');
INSERT INTO `product` VALUES (598, 'Tên tùy chỉnh Vòng cổ lấp đầy vàng Hawthorn', 1608250, 1608250, 100, 100, 0, 'Vòng cổ tên táo gai cá tính được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:59:41.000000');
INSERT INTO `product` VALUES (599, 'Vòng cổ Mề đay Blackthorn theo phong cách cổ điển', 2952000, 2952000, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau blackthorn lấy cảm hứng từ cổ. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:59:43.000000');
INSERT INTO `product` VALUES (600, 'Vòng tay tình bạn Rowan dệt tay', 472500, 472500, 100, 100, 0, 'Vòng tay tình bạn thanh lương trà dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:59:46.000000');
INSERT INTO `product` VALUES (601, 'Vòng đeo tay bằng đồng rèn Sloe', 997250, 997250, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ dạng rãnh. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:59:48.000000');
INSERT INTO `product` VALUES (602, 'Vòng tay đá quý Damson đính cườm', 1203750, 1203750, 100, 100, 0, 'Vòng tay hạt đá quý Damson được xâu chuỗi bằng dây co giãn bền bỉ. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:59:50.000000');
INSERT INTO `product` VALUES (603, 'Bông tai bạc hình quả hồng rèn thủ công', 1297250, 1297250, 100, 100, 0, 'Bông tai bạc sterling được rèn thủ công với họa tiết quả hồng. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:59:52.000000');
INSERT INTO `product` VALUES (604, 'Bông tai pha lê mộc qua có dây', 856000, 856000, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê mộc qua. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:59:54.000000');
INSERT INTO `product` VALUES (605, 'Vòng xếp chồng Medlar được đóng dấu bằng tay', 1057750, 1057750, 100, 100, 0, 'Chiếc nhẫn xếp chồng cây sơn tra được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:59:56.000000');
INSERT INTO `product` VALUES (606, 'Nhẫn dâu tằm pha lê thô', 1975000, 1975000, 100, 100, 0, 'Chiếc nhẫn nổi bật có pha lê dâu tằm thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với lớp vỏ dâu tằm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:59:58.000000');
INSERT INTO `product` VALUES (607, 'Nến sáp ong Gooseberry được đổ bằng tay', 528750, 528750, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ thủ công với hỗn hợp tinh dầu quả lý gai. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 17:59:59.000000');
INSERT INTO `product` VALUES (608, 'Nến thơm cây việt quất sáp dừa', 394250, 394250, 100, 100, 0, 'Nến thơm việt quất số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:00:00.000000');
INSERT INTO `product` VALUES (609, 'Treo tường Macramé Crowberry', 2686750, 2686750, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo được treo bằng dây bông tự nhiên màu dâu tây. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:00:01.000000');
INSERT INTO `product` VALUES (610, 'Vòng hoa mâm xôi khô', 2138750, 2138750, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa của cây mâm xôi. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:00:02.000000');
INSERT INTO `product` VALUES (611, 'Kệ gỗ Lingonberry chạm khắc thủ công', 2182250, 2182250, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh quả việt quất. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:00:04.000000');
INSERT INTO `product` VALUES (612, 'Thớt quả óc chó Bearberry cuối hạt', 2354500, 2354500, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó Bearberry và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:00:05.000000');
INSERT INTO `product` VALUES (613, 'Bộ bát sứ Hackberry ném tay', 1685750, 1685750, 100, 100, 0, 'Bộ 4 bát gốm sứ tráng men phản ứng hackberry. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:00:06.000000');
INSERT INTO `product` VALUES (614, 'Mũ len Buffaloberry Merino dệt kim bằng tay', 692750, 692750, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu sắc trâu. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:00:08.000000');
INSERT INTO `product` VALUES (615, 'Dây buộc tóc bằng ren Aurora Crochet', 349250, 349250, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren cotton cực quang. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:00:10.000000');
INSERT INTO `product` VALUES (616, 'Khăn choàng lụa Chạng vạng nhuộm tay', 2279000, 2279000, 100, 100, 0, 'Khăn choàng quấn lụa nhuộm tay sang trọng với họa tiết màu nước chạng vạng. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:00:13.000000');
INSERT INTO `product` VALUES (617, 'Ly hợp da Heather khâu tay', 3341500, 3341500, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay bằng thạch nam. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:00:15.000000');
INSERT INTO `product` VALUES (618, 'Ba lô gỗ lũa vải sáp', 3501500, 3501500, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da lũa. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:00:18.000000');
INSERT INTO `product` VALUES (619, 'Tranh sáp nghệ thuật Riverstone nguyên bản', 2318000, 2318000, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng bằng đá ven sông. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:00:20.000000');
INSERT INTO `product` VALUES (620, 'Tượng gốm sứ bãi biển Pebble được điêu khắc bằng tay', 1833750, 1833750, 100, 100, 0, 'Tượng gốm bằng đá được điêu khắc thủ công với các chi tiết tráng men trên bãi biển bằng đá cuội. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:00:22.000000');
INSERT INTO `product` VALUES (621, 'Mỹ thuật Foxglove Ảnh thiên nhiên In', 1848750, 1848750, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên foxglove nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:00:24.000000');
INSERT INTO `product` VALUES (622, 'Xà Phòng Nghệ Nhân Blackberry Sữa Dê', 217250, 217250, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm dâu đen và các chất thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:00:27.000000');
INSERT INTO `product` VALUES (623, 'Thanh dầu gội quế đặc', 588750, 588750, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược quế. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:00:29.000000');
INSERT INTO `product` VALUES (624, 'Tẩy tế bào chết toàn thân bằng đường bạch đậu khấu', 613750, 613750, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường bạch đậu khấu thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu bạch đậu khấu. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:00:31.000000');
INSERT INTO `product` VALUES (625, 'Tạp chí da cỏ ba lá buộc tay', 1794000, 1794000, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da cỏ ba lá và sợi vải lanh đóng bìa bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:00:33.000000');
INSERT INTO `product` VALUES (626, 'Thiệp cưới màu nước cây kế', 337750, 337750, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật cây kế. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:00:35.000000');
INSERT INTO `product` VALUES (627, 'Câu đố bằng gỗ Wisteria vẽ tay', 1139250, 1139250, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay hoa đậu tía. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:00:38.000000');
INSERT INTO `product` VALUES (628, 'Cây đũa phép đồ chơi cho mèo Wren bện tay', 387250, 387250, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây cotton bện và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:00:40.000000');
INSERT INTO `product` VALUES (629, 'Vòng cổ mặt dây chuyền đá mặt trăng Falcon thủ công', 938500, 938500, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng hình chim ưng chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:00:42.000000');
INSERT INTO `product` VALUES (630, 'Tên tùy chỉnh Vòng cổ Osprey mạ vàng', 1646250, 1646250, 100, 100, 0, 'Vòng cổ tên chim ưng cá nhân được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:00:45.000000');
INSERT INTO `product` VALUES (631, 'Vòng cổ mặt dây chuyền Hawkweed theo phong cách cổ điển', 2243000, 2243000, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau hawkweed lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:00:47.000000');
INSERT INTO `product` VALUES (632, 'Vòng tay tình bạn Dogwood dệt thủ công', 332500, 332500, 100, 100, 0, 'Vòng tay tình bạn bằng gỗ chó dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:00:49.000000');
INSERT INTO `product` VALUES (633, 'Vòng đeo tay bằng đồng rèn Sweetgrass', 1071000, 1071000, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ bằng cỏ ngọt. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:00:52.000000');
INSERT INTO `product` VALUES (634, 'Vòng tay đá quý Cattail đính cườm', 901000, 901000, 100, 100, 0, 'Vòng tay hạt đá quý cattail được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:00:54.000000');
INSERT INTO `product` VALUES (635, 'Bông tai bạc Bullrush được rèn thủ công', 1212750, 1212750, 100, 100, 0, 'Bông tai đinh tán bằng bạc sterling được rèn thủ công với kết cấu màu hồng phấn. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:00:56.000000');
INSERT INTO `product` VALUES (636, 'Bông tai pha lê cói bọc dây', 975250, 975250, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn là pha lê cói. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:00:58.000000');
INSERT INTO `product` VALUES (637, 'Vòng xếp chồng Bracken được đóng dấu bằng tay', 1039500, 1039500, 100, 100, 0, 'Chiếc nhẫn xếp chồng dương xỉ được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:01:00.000000');
INSERT INTO `product` VALUES (638, 'Nhẫn pha lê thô', 939250, 939250, 100, 100, 0, 'Chiếc nhẫn nổi bật có pha lê màu me chua thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với patina cây me chua.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:01:03.000000');
INSERT INTO `product` VALUES (639, 'Nến sáp ong hoa cúc đổ bằng tay', 723250, 723250, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ thủ công với hỗn hợp tinh dầu hoa cúc. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:01:05.000000');
INSERT INTO `product` VALUES (640, 'Nến thơm Sáp dừa Yarrow', 699750, 699750, 100, 100, 0, 'Nến thơm cỏ thi số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:01:07.000000');
INSERT INTO `product` VALUES (641, 'Treo tường Macramé Valerian', 1719000, 1719000, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo được treo bằng dây bông tự nhiên cây nữ lang. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:01:08.000000');
INSERT INTO `product` VALUES (642, 'Vòng hoa ngải cứu khô', 1946750, 1946750, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa ngải cứu. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:01:10.000000');
INSERT INTO `product` VALUES (643, 'Kệ gỗ cây tầm ma chạm khắc thủ công', 3968000, 3968000, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh cây tầm ma. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:01:12.000000');
INSERT INTO `product` VALUES (644, 'Thớt cắt quả óc chó ngưu bàng cuối hạt', 1771500, 1771500, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó cây ngưu bàng và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:01:14.000000');
INSERT INTO `product` VALUES (645, 'Bộ bát sứ hình giọt nước ném bằng tay', 2863000, 2863000, 100, 100, 0, 'Bộ 4 chiếc bát gốm sứ tráng men phản ứng hình giọt nước bằng tay. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:01:16.000000');
INSERT INTO `product` VALUES (646, 'Mũ len Crocus Merino dệt kim bằng tay', 630250, 630250, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ 100% len merino superwash với màu hoa nghệ tây. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:01:18.000000');
INSERT INTO `product` VALUES (647, 'Dây buộc tóc bằng ren Trillium', 256500, 256500, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông trillium. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:01:20.000000');
INSERT INTO `product` VALUES (648, 'Khăn choàng quấn lụa Bloodroot nhuộm tay', 4365500, 4365500, 100, 100, 0, 'Khăn choàng lụa quấn tay sang trọng họa tiết màu nước máu. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:01:23.000000');
INSERT INTO `product` VALUES (649, 'Ly hợp da Hepatica khâu tay', 3417250, 3417250, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:01:26.000000');
INSERT INTO `product` VALUES (650, 'Ba lô Mayapple vải sáp', 5253500, 5253500, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da mayapple. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:01:28.000000');
INSERT INTO `product` VALUES (651, 'Tranh sáp hoa Elderflower nguyên bản', 3534500, 3534500, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng hoa cơm cháy. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:01:32.000000');
INSERT INTO `product` VALUES (652, 'Tượng gốm táo gai điêu khắc bằng tay', 1953000, 1953000, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết tráng men táo gai. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:01:34.000000');
INSERT INTO `product` VALUES (653, 'Mỹ thuật In ảnh thiên nhiên Blackthorn', 1842500, 1842500, 100, 100, 0, 'Lưu trữ bản in mỹ thuật của bức ảnh thiên nhiên cây gai đen nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:01:38.000000');
INSERT INTO `product` VALUES (654, 'Xà phòng nghệ nhân Rowan sữa dê', 196000, 196000, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm thanh lương trà và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:01:41.000000');
INSERT INTO `product` VALUES (655, 'Thanh gội đầu Solid Sloe', 535500, 535500, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược sloe. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:01:43.000000');
INSERT INTO `product` VALUES (656, 'Tẩy tế bào chết Sugar Damson', 648250, 648250, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường Damson thủ công gốc dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu Damson. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:01:46.000000');
INSERT INTO `product` VALUES (657, 'Nhật ký da hồng đóng tay', 2028250, 2028250, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da màu hồng và sợi vải lanh đóng bìa bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:01:49.000000');
INSERT INTO `product` VALUES (658, 'Thiệp cưới mộc qua màu nước', 226500, 226500, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật mộc qua. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:01:51.000000');
INSERT INTO `product` VALUES (659, 'Câu đố bằng gỗ Medlar vẽ tay', 1241500, 1241500, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay bằng sơn tra. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:01:53.000000');
INSERT INTO `product` VALUES (660, 'Đũa phép đồ chơi mèo dâu bện bằng tay', 466750, 466750, 100, 100, 0, 'Đồ chơi đũa phép cho mèo được làm thủ công với dây cotton bện dâu tằm và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:01:55.000000');
INSERT INTO `product` VALUES (661, 'Vòng cổ mặt dây chuyền đá mặt trăng Gooseberry thủ công', 1531750, 1531750, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng quả lý gai chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:01:58.000000');
INSERT INTO `product` VALUES (662, 'Tên tùy chỉnh Vòng cổ lấp đầy vàng việt quất', 2221750, 2221750, 100, 100, 0, 'Vòng cổ tên việt quất được cá nhân hóa được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:02:00.000000');
INSERT INTO `product` VALUES (663, 'Vòng cổ Crowberry phong cách cổ điển', 1487500, 1487500, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:02:02.000000');
INSERT INTO `product` VALUES (664, 'Vòng tay tình bạn Cloudberry dệt tay', 222250, 222250, 100, 100, 0, 'Vòng tay tình bạn hình quả mâm xôi dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:02:05.000000');
INSERT INTO `product` VALUES (665, 'Vòng đeo tay bằng đồng Lingonberry rèn', 814250, 814250, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ lingonberry. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:02:06.000000');
INSERT INTO `product` VALUES (666, 'Vòng tay đá quý Bearberry đính cườm', 1607750, 1607750, 100, 100, 0, 'Vòng tay hạt đá quý Bearberry được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:02:09.000000');
INSERT INTO `product` VALUES (667, 'Bông tai bạc Hackberry được rèn bằng tay', 806500, 806500, 100, 100, 0, 'Bông tai đinh tán bằng bạc được rèn thủ công với kết cấu hackberry. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:02:11.000000');
INSERT INTO `product` VALUES (668, 'Bông tai pha lê Buffaloberry có dây', 1721250, 1721250, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê hình quả trâu. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:02:13.000000');
INSERT INTO `product` VALUES (669, 'Vòng xếp chồng Aurora được đóng dấu bằng tay', 1100500, 1100500, 100, 100, 0, 'Chiếc nhẫn xếp chồng cực quang được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:02:15.000000');
INSERT INTO `product` VALUES (670, 'Nhẫn tuyên bố hoàng hôn pha lê thô', 1885500, 1885500, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê chạng vạng thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với lớp gỉ màu chạng vạng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:02:17.000000');
INSERT INTO `product` VALUES (671, 'Nến sáp ong Heather đổ bằng tay', 657000, 657000, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ thủ công với hỗn hợp tinh dầu thạch nam. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:02:19.000000');
INSERT INTO `product` VALUES (672, 'Nến thơm gỗ lũa sáp dừa', 552000, 552000, 100, 100, 0, 'Nến thơm lũa số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:02:21.000000');
INSERT INTO `product` VALUES (673, 'Tranh treo tường Macramé Riverstone', 2502500, 2502500, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo treo bằng dây bông tự nhiên bằng đá ven sông. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:02:22.000000');
INSERT INTO `product` VALUES (674, 'Vòng Hoa Bãi Biển Sỏi Khô', 1934000, 1934000, 100, 100, 0, 'Vòng hoa khô thủ công có hình thực vật theo mùa trên bãi biển sỏi. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:02:24.000000');
INSERT INTO `product` VALUES (675, 'Kệ gỗ Foxglove chạm khắc bằng tay', 3201750, 3201750, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh hình bao tay cáo. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:02:30.000000');
INSERT INTO `product` VALUES (676, 'Thớt quả óc chó Blackberry cuối hạt', 1477000, 1477000, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó dâu đen và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:02:32.000000');
INSERT INTO `product` VALUES (677, 'Bộ bát sứ quế ném tay', 1316000, 1316000, 100, 100, 0, 'Bộ 4 bát sứ thủ công phủ men phản ứng quế. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:02:35.000000');
INSERT INTO `product` VALUES (678, 'Mũ len Merino dệt kim bằng tay thảo quả', 587500, 587500, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu bạch đậu khấu. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:02:37.000000');
INSERT INTO `product` VALUES (679, 'Dây buộc tóc bằng ren Crochet Clover', 224750, 224750, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông cỏ ba lá. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:02:40.000000');
INSERT INTO `product` VALUES (680, 'Khăn choàng quấn lụa Thistle nhuộm tay', 2604500, 2604500, 100, 100, 0, 'Khăn choàng lụa quấn tay sang trọng họa tiết màu nước cây kế. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:02:43.000000');
INSERT INTO `product` VALUES (681, 'Ly hợp da Wisteria khâu tay', 2007000, 2007000, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay hoa tử đằng. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:02:46.000000');
INSERT INTO `product` VALUES (682, 'Ba lô Wren vải sáp', 4689000, 4689000, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da màu đỏ. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:02:49.000000');
INSERT INTO `product` VALUES (683, 'Bức tranh sáp chim ưng nguyên bản', 5733000, 5733000, 100, 100, 0, 'Bức tranh sơn dầu nguyên bản (sáp nóng) với bố cục trừu tượng chim ưng. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:02:52.000000');
INSERT INTO `product` VALUES (684, 'Tượng gốm Osprey được điêu khắc bằng tay', 1212000, 1212000, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc bằng tay với các chi tiết tráng men chim ưng. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:02:54.000000');
INSERT INTO `product` VALUES (685, 'Mỹ thuật Hawkweed In ảnh thiên nhiên', 946750, 946750, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên hawkweed nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:02:57.000000');
INSERT INTO `product` VALUES (686, 'Xà Phòng Nghệ Nhân Dogwood Sữa Dê', 464500, 464500, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm cây dương đào và các tạp chất thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:03:00.000000');
INSERT INTO `product` VALUES (687, 'Thanh gội đầu Solid Sweetgrass', 484250, 484250, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược cỏ ngọt. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:03:02.000000');
INSERT INTO `product` VALUES (688, 'Tẩy tế bào chết toàn thân Sugar Cattail', 267500, 267500, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường cattail thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu đuôi mèo. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:03:04.000000');
INSERT INTO `product` VALUES (689, 'Tạp chí da Bullrush đóng bìa tay', 1169750, 1169750, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da bò và dây vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:03:07.000000');
INSERT INTO `product` VALUES (690, 'Thiệp cưới cói màu nước', 310250, 310250, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật cói. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:03:10.000000');
INSERT INTO `product` VALUES (691, 'Câu đố bằng gỗ Bracken vẽ tay', 1126500, 1126500, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay dương xỉ. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:03:12.000000');
INSERT INTO `product` VALUES (692, 'Đũa phép đồ chơi cho mèo me chua bện bằng tay', 270250, 270250, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây bông bện cây me chua và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:03:14.000000');
INSERT INTO `product` VALUES (693, 'Vòng cổ mặt dây chuyền đá mặt trăng hoa cúc thủ công', 1395000, 1395000, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng hoa cúc chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:03:17.000000');
INSERT INTO `product` VALUES (694, 'Tên tùy chỉnh Vòng cổ lấp đầy vàng Yarrow', 2143750, 2143750, 100, 100, 0, 'Vòng cổ tên yarrow được cá nhân hóa được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:03:20.000000');
INSERT INTO `product` VALUES (695, 'Vòng cổ mặt dây chuyền Valerian theo phong cách cổ điển', 1399500, 1399500, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau valerian lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:03:22.000000');
INSERT INTO `product` VALUES (696, 'Vòng tay hữu nghị Mugwort dệt tay', 327000, 327000, 100, 100, 0, 'Vòng tay tình bạn ngải cứu dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:03:24.000000');
INSERT INTO `product` VALUES (697, 'Vòng đeo tay bằng đồng rèn cây tầm ma', 1559000, 1559000, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ màu cây tầm ma. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:03:27.000000');
INSERT INTO `product` VALUES (698, 'Vòng tay đá quý ngưu bàng đính cườm', 907250, 907250, 100, 100, 0, 'Vòng tay hạt đá quý ngưu bàng được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:03:29.000000');
INSERT INTO `product` VALUES (699, 'Bông tai bạc hình giọt nước tuyết được rèn thủ công', 787500, 787500, 100, 100, 0, 'Khuyên tai bạc sterling được rèn thủ công với họa tiết giọt tuyết. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:03:31.000000');
INSERT INTO `product` VALUES (700, 'Bông tai vòng pha lê Crocus có dây', 1860750, 1860750, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê crocus. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:03:34.000000');
INSERT INTO `product` VALUES (701, 'Vòng xếp Trillium được đóng dấu bằng tay', 1090250, 1090250, 100, 100, 0, 'Chiếc nhẫn xếp chồng trillium được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:03:36.000000');
INSERT INTO `product` VALUES (702, 'Nhẫn tuyên bố Bloodroot tinh thể thô', 1042000, 1042000, 100, 100, 0, 'Chiếc nhẫn nổi bật có pha lê gốc máu thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với patina máu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:03:38.000000');
INSERT INTO `product` VALUES (703, 'Nến sáp ong Hepatica đổ bằng tay', 300000, 300000, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ thủ công với hỗn hợp tinh dầu gan. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:03:41.000000');
INSERT INTO `product` VALUES (704, 'Nến thơm sáp dừa Mayapple', 470250, 470250, 100, 100, 0, 'Nến thơm mayapple lô nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:03:43.000000');
INSERT INTO `product` VALUES (705, 'Treo tường Macramé hoa cơm cháy', 3437500, 3437500, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo được treo bằng dây bông tự nhiên hoa cơm cháy. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:03:44.000000');
INSERT INTO `product` VALUES (706, 'Vòng hoa táo gai khô', 1840750, 1840750, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa táo gai. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:03:46.000000');
INSERT INTO `product` VALUES (707, 'Kệ gỗ mâm xôi chạm khắc thủ công', 1791500, 1791500, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh gai đen. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:03:48.000000');
INSERT INTO `product` VALUES (708, 'Thớt quả óc chó Rowan cuối hạt', 4200750, 4200750, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó thanh lương trà và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:03:50.000000');
INSERT INTO `product` VALUES (709, 'Bộ Bát Sứ Ném Tay', 2998000, 2998000, 100, 100, 0, 'Bộ 4 bát gốm sứ tráng men phản ứng sloe. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:03:51.000000');
INSERT INTO `product` VALUES (710, 'Mũ len Damson Merino dệt kim bằng tay', 1369000, 1369000, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với phối màu damson. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:03:54.000000');
INSERT INTO `product` VALUES (711, 'Dây buộc tóc ren quả hồng móc', 155250, 155250, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông màu hồng. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:03:56.000000');
INSERT INTO `product` VALUES (712, 'Khăn choàng quấn lụa mộc qua nhuộm tay', 3026750, 3026750, 100, 100, 0, 'Khăn choàng lụa nhuộm tay sang trọng họa tiết màu nước mộc qua. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:03:59.000000');
INSERT INTO `product` VALUES (713, 'Ly hợp da Medlar khâu tay', 1653250, 1653250, 100, 100, 0, 'Ly hợp da thủ công với chi tiết khâu tay bằng gỗ sơn tra. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:04:01.000000');
INSERT INTO `product` VALUES (714, 'Ba lô vải dâu tằm sáp', 2988250, 2988250, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da dâu. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:04:03.000000');
INSERT INTO `product` VALUES (715, 'Tranh sáp nghệ thuật gốc quả Gooseberry', 3739500, 3739500, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng quả lý gai. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:04:05.000000');
INSERT INTO `product` VALUES (716, 'Tượng gốm việt quất điêu khắc bằng tay', 1401750, 1401750, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết tráng men việt quất. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:04:08.000000');
INSERT INTO `product` VALUES (717, 'In ảnh nghệ thuật thiên nhiên Crowberry', 1710000, 1710000, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên cây dâu tây nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:04:10.000000');
INSERT INTO `product` VALUES (718, 'Xà phòng thủ công việt quất sữa dê', 296750, 296750, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm mâm xôi và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:04:13.000000');
INSERT INTO `product` VALUES (719, 'Thanh gội đầu Lingonberry rắn', 287250, 287250, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược lingonberry. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:04:16.000000');
INSERT INTO `product` VALUES (720, 'Tẩy tế bào chết toàn thân Sugar Bearberry', 335750, 335750, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường Bearberry thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu gấu. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:04:19.000000');
INSERT INTO `product` VALUES (721, 'Tạp chí da Hackberry đóng bìa tay', 1360750, 1360750, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da hackberry và sợi vải lanh đóng bìa bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:04:21.000000');
INSERT INTO `product` VALUES (722, 'Thiệp cưới màu nước Buffaloberry', 187500, 187500, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật trâu. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:04:23.000000');
INSERT INTO `product` VALUES (723, 'Câu đố bằng gỗ Aurora vẽ tay', 1452250, 1452250, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay cực quang. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:04:26.000000');
INSERT INTO `product` VALUES (724, 'Cây đũa phép đồ chơi cho mèo Chạng vạng bện tay', 420500, 420500, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây cotton bện màu chạng vạng và phần đính kèm lông tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:04:28.000000');
INSERT INTO `product` VALUES (725, 'Vòng cổ mặt dây chuyền đá thạch anh thủ công', 1925250, 1925250, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng thạch nam chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:04:30.000000');
INSERT INTO `product` VALUES (726, 'Tên tùy chỉnh Vòng cổ lấp đầy vàng lũa', 1207500, 1207500, 100, 100, 0, 'Vòng cổ tên gỗ lũa cá tính được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:04:32.000000');
INSERT INTO `product` VALUES (727, 'Vòng cổ mặt dây chuyền Riverstone theo phong cách cổ điển', 2275250, 2275250, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau riverstone lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:04:35.000000');
INSERT INTO `product` VALUES (728, 'Vòng tay tình bạn bãi biển Pebble dệt thủ công', 545250, 545250, 100, 100, 0, 'Vòng tay tình bạn bãi biển sỏi dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:04:37.000000');
INSERT INTO `product` VALUES (729, 'Vòng đeo tay bằng đồng rèn Foxglove', 608000, 608000, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn bằng tay với lớp gỉ hình găng tay cáo. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:04:39.000000');
INSERT INTO `product` VALUES (730, 'Vòng tay đá quý Blackberry đính cườm', 918750, 918750, 100, 100, 0, 'Vòng tay hạt đá quý blackberry được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:04:42.000000');
INSERT INTO `product` VALUES (731, 'Bông tai bạc quế được rèn thủ công', 1043000, 1043000, 100, 100, 0, 'Bông tai đinh tán bằng bạc được rèn thủ công với họa tiết quế. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:04:44.000000');
INSERT INTO `product` VALUES (732, 'Bông tai pha lê bạch đậu khấu có dây', 710750, 710750, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê bạch đậu khấu. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:04:47.000000');
INSERT INTO `product` VALUES (733, 'Vòng xếp cỏ ba lá được đóng dấu bằng tay', 1089500, 1089500, 100, 100, 0, 'Nhẫn xếp chồng cỏ ba lá được đóng dấu bằng tay xinh xắn bằng bạc. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:04:49.000000');
INSERT INTO `product` VALUES (734, 'Vòng tuyên bố cây kế pha lê thô', 916500, 916500, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê cây kế thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với lớp vỏ cây kế.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:04:51.000000');
INSERT INTO `product` VALUES (735, 'Nến sáp ong Wisteria đổ bằng tay', 376500, 376500, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu hoa tử đằng. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:04:53.000000');
INSERT INTO `product` VALUES (736, 'Nến thơm sáp dừa Wren', 831250, 831250, 100, 100, 0, 'Nến thơm chim hồng tước số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:04:55.000000');
INSERT INTO `product` VALUES (737, 'Treo tường Macramé Falcon', 3462750, 3462750, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo được treo bằng dây bông tự nhiên hình chim ưng. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:04:56.000000');
INSERT INTO `product` VALUES (738, 'Vòng hoa Osprey khô', 1938000, 1938000, 100, 100, 0, 'Vòng hoa khô được làm thủ công có hình thực vật theo mùa của chim ưng biển. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:04:58.000000');
INSERT INTO `product` VALUES (739, 'Kệ Gỗ Hawkweed Chạm Khắc Bằng Tay', 2654500, 2654500, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh diều hâu. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:04:59.000000');
INSERT INTO `product` VALUES (740, 'Thớt gỗ óc chó Dogwood hạt cuối', 2401500, 2401500, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ gỗ óc chó và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:05:01.000000');
INSERT INTO `product` VALUES (741, 'Bộ bát gốm Sweetgrass ném tay', 1641750, 1641750, 100, 100, 0, 'Bộ 4 bát gốm sứ tráng men phản ứng Sweetgrass. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:05:04.000000');
INSERT INTO `product` VALUES (742, 'Mũ len Merino dệt kim bằng tay', 624000, 624000, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu đuôi mèo. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:05:06.000000');
INSERT INTO `product` VALUES (743, 'Dây buộc tóc bằng ren Crochet Bullrush', 217250, 217250, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông bullrush. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:05:09.000000');
INSERT INTO `product` VALUES (744, 'Khăn choàng quấn cói nhuộm tay', 3339750, 3339750, 100, 100, 0, 'Khăn choàng quấn lụa nhuộm tay sang trọng họa tiết màu nước cói. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:05:11.000000');
INSERT INTO `product` VALUES (745, 'Ly hợp da Bracken khâu tay', 1712500, 1712500, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu bằng tay màu dương xỉ. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:05:13.000000');
INSERT INTO `product` VALUES (746, 'Ba lô vải màu sáp', 5461000, 5461000, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da màu nâu đỏ. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:05:16.000000');
INSERT INTO `product` VALUES (747, 'Tranh sáp hoa cúc gốc', 2467250, 2467250, 100, 100, 0, 'Bức tranh sơn dầu nguyên bản (sáp nóng) với bố cục trừu tượng hoa cúc. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:05:18.000000');
INSERT INTO `product` VALUES (748, 'Tượng gốm cỏ thi điêu khắc bằng tay', 1147250, 1147250, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết bằng men cỏ thi. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:05:20.000000');
INSERT INTO `product` VALUES (749, 'Mỹ thuật Valerian In ảnh thiên nhiên', 1030750, 1030750, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên valerian nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:05:23.000000');
INSERT INTO `product` VALUES (750, 'Xà phòng nghệ nghệ ngải cứu sữa dê', 485000, 485000, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm ngải cứu và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:05:26.000000');
INSERT INTO `product` VALUES (751, 'Thanh dầu gội cây tầm ma rắn', 353000, 353000, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược cây tầm ma. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:05:29.000000');
INSERT INTO `product` VALUES (752, 'Tẩy tế bào chết bằng đường cây ngưu bàng', 351500, 351500, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường ngưu bàng thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu cây ngưu bàng. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:05:31.000000');
INSERT INTO `product` VALUES (753, 'Nhật ký da hoa tuyết buộc tay', 1732750, 1732750, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da hình giọt nước và dây vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:05:34.000000');
INSERT INTO `product` VALUES (754, 'Thiệp cưới màu nước Crocus', 144500, 144500, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật crocus. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:05:36.000000');
INSERT INTO `product` VALUES (755, 'Câu đố bằng gỗ Trillium vẽ tay', 1056000, 1056000, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay trillium. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:05:39.000000');
INSERT INTO `product` VALUES (756, 'Đũa phép đồ chơi cho mèo Bloodroot bện bằng tay', 275250, 275250, 100, 100, 0, 'Đồ chơi đũa phép cho mèo được làm thủ công với dây bông bện bằng rễ cây và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:05:43.000000');
INSERT INTO `product` VALUES (757, 'Vòng cổ mặt dây chuyền đá mặt trăng Hepatica thủ công', 2334750, 2334750, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng Hepatica chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:05:46.000000');
INSERT INTO `product` VALUES (758, 'Tên tùy chỉnh Vòng cổ Mayapple Gold-Fill', 1695750, 1695750, 100, 100, 0, 'Vòng cổ tên mayapple cá nhân hóa được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:05:48.000000');
INSERT INTO `product` VALUES (759, 'Vòng cổ mặt dây chuyền hoa cơm cháy theo phong cách cổ điển', 2137750, 2137750, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng hoa cơm cháy lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:05:51.000000');
INSERT INTO `product` VALUES (760, 'Vòng tay tình bạn táo gai dệt tay', 678000, 678000, 100, 100, 0, 'Vòng tay tình bạn táo gai dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:05:53.000000');
INSERT INTO `product` VALUES (761, 'Vòng đeo tay bằng đồng Blackthorn rèn', 1333000, 1333000, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ màu đen gai. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:05:56.000000');
INSERT INTO `product` VALUES (762, 'Vòng tay đá quý Rowan đính cườm', 1616250, 1616250, 100, 100, 0, 'Vòng tay hạt đá quý thanh lương trà được xâu chuỗi bằng dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:05:58.000000');
INSERT INTO `product` VALUES (763, 'Bông tai bạc Sloe được rèn thủ công', 803750, 803750, 100, 100, 0, 'Bông tai đinh tán bằng bạc sterling được rèn thủ công với kết cấu sloe. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:06:00.000000');
INSERT INTO `product` VALUES (764, 'Bông tai pha lê Damson được bọc dây', 1699250, 1699250, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê Damson. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:06:03.000000');
INSERT INTO `product` VALUES (765, 'Vòng xếp hồng đóng dấu bằng tay', 658500, 658500, 100, 100, 0, 'Nhẫn xếp hình quả hồng được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:06:05.000000');
INSERT INTO `product` VALUES (766, 'Nhẫn mộc qua pha lê thô', 1006000, 1006000, 100, 100, 0, 'Chiếc nhẫn nổi bật có pha lê mộc qua thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với mộc qua patina.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:06:07.000000');
INSERT INTO `product` VALUES (767, 'Nến sáp ong Medlar đổ bằng tay', 924500, 924500, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu sơn tra. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:06:08.000000');
INSERT INTO `product` VALUES (768, 'Nến thơm dâu tằm sáp dừa', 786000, 786000, 100, 100, 0, 'Nến thơm dâu tằm số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:06:10.000000');
INSERT INTO `product` VALUES (769, 'Macramé Quả Ngỗng Treo Tường', 1315500, 1315500, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo được treo bằng dây bông tự nhiên màu quả lý gai. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:06:12.000000');
INSERT INTO `product` VALUES (770, 'Vòng hoa việt quất khô', 1657000, 1657000, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa của quả việt quất. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:06:13.000000');
INSERT INTO `product` VALUES (771, 'Kệ gỗ Crowberry chạm khắc bằng tay', 3112000, 3112000, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh quả quạ. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:06:15.000000');
INSERT INTO `product` VALUES (772, 'Thớt quả óc chó Cloudberry cuối hạt', 1799500, 1799500, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó mâm xôi và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:06:16.000000');
INSERT INTO `product` VALUES (773, 'Bộ bát gốm Lingonberry ném tay', 2191250, 2191250, 100, 100, 0, 'Bộ 4 chiếc bát gốm sứ tráng men phản ứng dâu lingonberry. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:06:18.000000');
INSERT INTO `product` VALUES (774, 'Mũ len Bearberry Merino dệt kim bằng tay', 1060500, 1060500, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ 100% len merino superwash với màu sắc dâu tây. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:06:21.000000');
INSERT INTO `product` VALUES (775, 'Móc buộc tóc ren Hackberry', 205000, 205000, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren cotton hackberry. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:06:23.000000');
INSERT INTO `product` VALUES (776, 'Khăn choàng lụa Buffaloberry nhuộm tay', 3520750, 3520750, 100, 100, 0, 'Khăn choàng lụa nhuộm tay sang trọng họa tiết màu nước trâu. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:06:25.000000');
INSERT INTO `product` VALUES (777, 'Ly hợp da Aurora khâu tay', 2282000, 2282000, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay cực quang. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:06:27.000000');
INSERT INTO `product` VALUES (778, 'Ba lô vải sáp Chạng vạng', 4135750, 4135750, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da màu chạng vạng. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:06:29.000000');
INSERT INTO `product` VALUES (779, 'Tranh sáp nguyên bản Heather Encaustic', 4504750, 4504750, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng thạch nam. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:06:32.000000');
INSERT INTO `product` VALUES (780, 'Tượng gốm bằng gỗ lũa điêu khắc bằng tay', 1748750, 1748750, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết bằng gỗ lũa. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:06:34.000000');
INSERT INTO `product` VALUES (781, 'Tranh in mỹ thuật thiên nhiên Riverstone', 1560000, 1560000, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên ven sông nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:06:36.000000');
INSERT INTO `product` VALUES (782, 'Sữa Dê Xà Phòng Nghệ Nhân Pebble Beach', 332250, 332250, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm bãi biển và các chất thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:06:38.000000');
INSERT INTO `product` VALUES (783, 'Thanh gội đầu Foxglove rắn', 586750, 586750, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược foxglove. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:06:41.000000');
INSERT INTO `product` VALUES (784, 'Tẩy tế bào chết toàn thân bằng đường Blackberry', 746250, 746250, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường dâu đen thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu dâu đen. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:06:43.000000');
INSERT INTO `product` VALUES (785, 'Tạp chí da quế đóng tay', 1347750, 1347750, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da màu quế và dây vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:06:45.000000');
INSERT INTO `product` VALUES (786, 'Thiệp cưới bạch đậu khấu màu nước', 152250, 152250, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật bạch đậu khấu. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:06:48.000000');
INSERT INTO `product` VALUES (787, 'Câu đố bằng gỗ cỏ ba lá vẽ tay', 1076500, 1076500, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay cỏ ba lá. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:06:50.000000');
INSERT INTO `product` VALUES (788, 'Cây đũa phép đồ chơi cho mèo Thistle bện bằng tay', 333250, 333250, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây bông bện cây kế và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:06:53.000000');
INSERT INTO `product` VALUES (789, 'Vòng cổ mặt dây chuyền đá mặt trăng Wisteria thủ công', 2188500, 2188500, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng hoa tử đằng chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:06:55.000000');
INSERT INTO `product` VALUES (790, 'Tên tùy chỉnh Vòng cổ Wren Gold-Fill', 1464500, 1464500, 100, 100, 0, 'Vòng cổ tên wren được cá nhân hóa được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:06:57.000000');
INSERT INTO `product` VALUES (791, 'Vòng cổ mặt dây chuyền chim ưng phong cách cổ điển', 1134500, 1134500, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau hình chim ưng lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:07:30.000000');
INSERT INTO `product` VALUES (792, 'Vòng tay tình bạn Osprey dệt tay', 297750, 297750, 100, 100, 0, 'Vòng tay tình bạn osprey dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:07:32.000000');
INSERT INTO `product` VALUES (793, 'Vòng đeo tay bằng đồng Hawkweed rèn', 1603500, 1603500, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn bằng tay với lớp gỉ hawkweed. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:07:34.000000');
INSERT INTO `product` VALUES (794, 'Vòng tay đá quý Dogwood đính cườm', 593000, 593000, 100, 100, 0, 'Vòng tay hạt đá quý bằng gỗ sơn thù du được xâu chuỗi bằng dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:07:36.000000');
INSERT INTO `product` VALUES (795, 'Bông tai bạc Sweetgrass được rèn thủ công', 1284750, 1284750, 100, 100, 0, 'Bông tai đinh tán bằng bạc được rèn thủ công với họa tiết cỏ ngọt. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:07:39.000000');
INSERT INTO `product` VALUES (796, 'Bông tai pha lê Cattail có dây', 1090750, 1090750, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn là pha lê đuôi mèo. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:07:41.000000');
INSERT INTO `product` VALUES (797, 'Vòng xếp chồng Bullrush được đóng dấu bằng tay', 746250, 746250, 100, 100, 0, 'Chiếc nhẫn xếp hình con bò tót được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:07:43.000000');
INSERT INTO `product` VALUES (798, 'Vòng tuyên bố cói pha lê thô', 1662500, 1662500, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê cói thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thiện với lớp gỉ cói.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:07:45.000000');
INSERT INTO `product` VALUES (799, 'Nến sáp ong Bracken đổ bằng tay', 863750, 863750, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ thủ công với hỗn hợp tinh dầu dương xỉ. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:07:47.000000');
INSERT INTO `product` VALUES (800, 'Nến thơm sáp dừa', 429000, 429000, 100, 100, 0, 'Nến thơm cây me chua số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:07:48.000000');
INSERT INTO `product` VALUES (801, 'Treo tường hoa cúc Macramé', 2451250, 2451250, 100, 100, 0, 'Bức tường macramé thắt nút phức tạp được treo bằng dây bông tự nhiên hoa cúc. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:07:50.000000');
INSERT INTO `product` VALUES (802, 'Vòng hoa cỏ thi khô', 1134500, 1134500, 100, 100, 0, 'Vòng hoa khô thủ công có hình thực vật theo mùa cỏ thi. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:07:51.000000');
INSERT INTO `product` VALUES (803, 'Kệ Gỗ Valerian Chạm Khắc Bằng Tay', 3869750, 3869750, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh cây nữ lang. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:07:53.000000');
INSERT INTO `product` VALUES (804, 'Thớt quả óc chó Mugwort cuối hạt', 3785500, 3785500, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó ngải cứu và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:07:55.000000');
INSERT INTO `product` VALUES (805, 'Bộ bát sứ ném cây tầm ma', 1720500, 1720500, 100, 100, 0, 'Bộ 4 chiếc bát gốm sứ thủ công phủ men phản ứng cây tầm ma. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:07:56.000000');
INSERT INTO `product` VALUES (806, 'Mũ len Merino ngưu bàng dệt kim bằng tay', 947750, 947750, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ 100% len merino superwash với màu sắc cây ngưu bàng. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:07:59.000000');
INSERT INTO `product` VALUES (807, 'Dây buộc tóc ren hình giọt nước tuyết móc', 442750, 442750, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren cotton hình giọt nước. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:08:01.000000');
INSERT INTO `product` VALUES (808, 'Khăn choàng lụa Crocus nhuộm tay', 4369250, 4369250, 100, 100, 0, 'Khăn choàng lụa quấn tay sang trọng có hoa văn màu nước nghệ tây. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:08:03.000000');
INSERT INTO `product` VALUES (809, 'Ly hợp da Trillium khâu tay', 2946500, 2946500, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay trillium. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:08:05.000000');
INSERT INTO `product` VALUES (810, 'Ba lô Bloodroot vải sáp', 2256500, 2256500, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da Bloodroot. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:08:08.000000');
INSERT INTO `product` VALUES (811, 'Tranh sáp Encaustic Hepatica nguyên bản', 2806000, 2806000, 100, 100, 0, 'Bức tranh sơn dầu nguyên bản (sáp nóng) với bố cục trừu tượng Hepatica. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:08:10.000000');
INSERT INTO `product` VALUES (812, 'Tượng gốm Mayapple điêu khắc bằng tay', 1730500, 1730500, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết tráng men mayapple. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:08:12.000000');
INSERT INTO `product` VALUES (813, 'Mỹ Thuật In Ảnh Thiên Nhiên Hoa Elderflower', 744500, 744500, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên hoa cơm cháy nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:08:14.000000');
INSERT INTO `product` VALUES (814, 'Xà phòng thủ công táo gai sữa dê', 343000, 343000, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm táo gai và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:08:17.000000');
INSERT INTO `product` VALUES (815, 'Thanh gội đầu Blackthorn rắn', 227500, 227500, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược cây gai đen. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:08:19.000000');
INSERT INTO `product` VALUES (816, 'Tẩy tế bào chết toàn thân Sugar Rowan', 503750, 503750, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường thanh lương trà thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu thanh lương trà. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:08:22.000000');
INSERT INTO `product` VALUES (817, 'Tạp chí da Sloe ràng buộc bằng tay', 1378750, 1378750, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da sloe và sợi lanh đóng bìa bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:08:24.000000');
INSERT INTO `product` VALUES (818, 'Thiệp cưới Damson màu nước', 311500, 311500, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật Damson. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:08:26.000000');
INSERT INTO `product` VALUES (819, 'Câu đố bằng gỗ hồng vẽ tay', 922750, 922750, 100, 100, 0, 'Trò chơi ghép hình thủ công bằng gỗ với thiết kế vẽ tay bằng quả hồng. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:08:29.000000');
INSERT INTO `product` VALUES (820, 'Đũa phép đồ chơi mèo Quince bện bằng tay', 515000, 515000, 100, 100, 0, 'Đồ chơi đũa phép mèo thủ công với dây bông bện mộc qua và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:08:31.000000');
INSERT INTO `product` VALUES (821, 'Vòng cổ mặt dây chuyền đá mặt trăng Medlar thủ công', 1108500, 1108500, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:08:34.000000');
INSERT INTO `product` VALUES (822, 'Tên tùy chỉnh Vòng cổ Mulberry Gold-Fill', 907500, 907500, 100, 100, 0, 'Dây chuyền khắc tên dâu tằm cá tính được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:08:36.000000');
INSERT INTO `product` VALUES (823, 'Vòng cổ Mề đay Gooseberry phong cách cổ điển', 2016750, 2016750, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:08:38.000000');
INSERT INTO `product` VALUES (824, 'Vòng tay tình bạn việt quất dệt tay', 283750, 283750, 100, 100, 0, 'Vòng tay tình bạn việt quất dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:08:40.000000');
INSERT INTO `product` VALUES (825, 'Vòng đeo tay bằng đồng Crowberry rèn', 1696000, 1696000, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ màu quả dâu tây. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:08:42.000000');
INSERT INTO `product` VALUES (826, 'Vòng tay đá quý Cloudberry đính cườm', 1416000, 1416000, 100, 100, 0, 'Vòng tay hạt đá quý quả mâm xôi được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:08:45.000000');
INSERT INTO `product` VALUES (827, 'Bông tai bạc Lingonberry được rèn thủ công', 1311000, 1311000, 100, 100, 0, 'Bông tai đinh tán bằng bạc được rèn thủ công với họa tiết quả nam việt quất. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:08:47.000000');
INSERT INTO `product` VALUES (828, 'Bông tai pha lê Bearberry có dây', 793500, 793500, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê Bearberry. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:08:50.000000');
INSERT INTO `product` VALUES (829, 'Vòng xếp chồng Hackberry được đóng dấu bằng tay', 1021750, 1021750, 100, 100, 0, 'Chiếc nhẫn xếp chồng hackberry được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:08:52.000000');
INSERT INTO `product` VALUES (830, 'Nhẫn tuyên bố Buffaloberry pha lê thô', 1882000, 1882000, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê Buffaloberry thô bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với patina trâu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:08:54.000000');
INSERT INTO `product` VALUES (831, 'Nến sáp ong Aurora đổ bằng tay', 483500, 483500, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu aurora. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:08:56.000000');
INSERT INTO `product` VALUES (832, 'Nến thơm Chạng vạng sáp dừa', 920500, 920500, 100, 100, 0, 'Nến thơm chạng vạng số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:08:57.000000');
INSERT INTO `product` VALUES (833, 'Macramé Heather Treo Tường', 1890500, 1890500, 100, 100, 0, 'Bức tường macramé được thắt nút bằng tay phức tạp treo trên dây bông thạch nam tự nhiên. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:08:59.000000');
INSERT INTO `product` VALUES (834, 'Vòng Gỗ Lũa Hoa Khô', 1131000, 1131000, 100, 100, 0, 'Vòng hoa khô thủ công có các loài thực vật theo mùa bằng gỗ lũa. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:09:01.000000');
INSERT INTO `product` VALUES (835, 'Kệ Gỗ Riverstone Chạm Khắc Bằng Tay', 3070000, 3070000, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh bằng đá ven sông. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:09:02.000000');
INSERT INTO `product` VALUES (836, 'Thớt cắt quả óc chó End-Grain Pebble Beach', 2419750, 2419750, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó và cây phong trên bãi biển sỏi. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:09:04.000000');
INSERT INTO `product` VALUES (837, 'Bộ bát sứ ném tay Foxglove', 1818250, 1818250, 100, 100, 0, 'Bộ 4 chiếc bát gốm sứ thủ công phủ men phản ứng foxglove. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:09:05.000000');
INSERT INTO `product` VALUES (838, 'Mũ len Blackberry Merino dệt kim bằng tay', 1291250, 1291250, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu dâu đen. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:09:07.000000');
INSERT INTO `product` VALUES (839, 'Móc buộc tóc ren quế', 344500, 344500, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông quế. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:09:10.000000');
INSERT INTO `product` VALUES (840, 'Khăn choàng lụa bạch đậu khấu nhuộm tay', 1420500, 1420500, 100, 100, 0, 'Khăn choàng lụa quấn tay sang trọng họa tiết màu nước bạch đậu khấu. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:09:12.000000');
INSERT INTO `product` VALUES (841, 'Ly hợp da cỏ ba lá khâu tay', 1193000, 1193000, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay hình cỏ ba lá. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:09:14.000000');
INSERT INTO `product` VALUES (842, 'Ba lô vải cây kế sáp', 3933750, 3933750, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da cây kế. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:09:17.000000');
INSERT INTO `product` VALUES (843, 'Tranh sáp hoa tử đằng gốc', 2109750, 2109750, 100, 100, 0, 'Bức tranh sơn dầu nguyên bản (sáp nóng) với bố cục trừu tượng hoa đậu tía. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:09:20.000000');
INSERT INTO `product` VALUES (844, 'Tượng gốm sứ Wren điêu khắc bằng tay', 925750, 925750, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết được tráng men. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:09:22.000000');
INSERT INTO `product` VALUES (845, 'In ảnh nghệ thuật chim ưng thiên nhiên', 1781750, 1781750, 100, 100, 0, 'Lưu trữ bản in mỹ thuật của bức ảnh thiên nhiên chim ưng nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:09:24.000000');
INSERT INTO `product` VALUES (846, 'Xà phòng thủ công Osprey sữa dê', 484500, 484500, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm chim ưng và các chất thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:09:27.000000');
INSERT INTO `product` VALUES (847, 'Thanh gội đầu rắn Hawkweed', 492000, 492000, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược hawkweed. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:09:29.000000');
INSERT INTO `product` VALUES (848, 'Tẩy tế bào chết bằng Sugar Dogwood', 758000, 758000, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường gỗ thù du thủ công với gốc dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu cây dương đào. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:09:31.000000');
INSERT INTO `product` VALUES (849, 'Tạp chí da Sweetgrass đóng bìa tay', 1683250, 1683250, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da Sweetgrass và dây vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:09:33.000000');
INSERT INTO `product` VALUES (850, 'Thiệp cưới Cattail màu nước', 333500, 333500, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật đuôi mèo. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:09:36.000000');
INSERT INTO `product` VALUES (851, 'Câu đố bằng gỗ Bullrush vẽ tay', 553750, 553750, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay bằng tay. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:09:38.000000');
INSERT INTO `product` VALUES (852, 'Đũa đồ chơi cho mèo cói bện tay', 330500, 330500, 100, 100, 0, 'Đồ chơi đũa phép mèo handmade với dây bông bện cói và đính kèm lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:09:40.000000');
INSERT INTO `product` VALUES (853, 'Vòng cổ mặt dây chuyền đá mặt trăng Bracken thủ công', 1312000, 1312000, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng dương xỉ chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:09:42.000000');
INSERT INTO `product` VALUES (854, 'Tên tùy chỉnh Vòng cổ màu vàng me chua', 1510750, 1510750, 100, 100, 0, 'Vòng cổ tên cây me chua được cá nhân hóa được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:09:45.000000');
INSERT INTO `product` VALUES (855, 'Vòng cổ mặt dây chuyền hoa cúc phong cách cổ điển', 1606500, 1606500, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng hoa cúc lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:09:47.000000');
INSERT INTO `product` VALUES (856, 'Vòng tay tình bạn Yarrow dệt tay', 360000, 360000, 100, 100, 0, 'Vòng tay tình bạn yarrow dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:09:50.000000');
INSERT INTO `product` VALUES (857, 'Vòng đeo tay bằng đồng rèn Valerian', 1442500, 1442500, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ bằng cây nữ lang. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:09:52.000000');
INSERT INTO `product` VALUES (858, 'Vòng tay đá quý Mugwort đính cườm', 1565500, 1565500, 100, 100, 0, 'Vòng tay hạt đá quý ngải cứu được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:09:54.000000');
INSERT INTO `product` VALUES (859, 'Bông tai bạc hình cây tầm ma được rèn thủ công', 1297000, 1297000, 100, 100, 0, 'Bông tai đinh tán bằng bạc được rèn thủ công với họa tiết cây tầm ma. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:09:57.000000');
INSERT INTO `product` VALUES (860, 'Bông tai pha lê hình cây ngưu bàng có dây', 1036500, 1036500, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê cây ngưu bàng. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:09:59.000000');
INSERT INTO `product` VALUES (861, 'Vòng xếp chồng bông tuyết được đóng dấu bằng tay', 797500, 797500, 100, 100, 0, 'Nhẫn xếp chồng hình giọt tuyết được đóng dấu bằng tay xinh xắn bằng bạc. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:10:01.000000');
INSERT INTO `product` VALUES (862, 'Nhẫn tuyên bố Crocus pha lê thô', 942250, 942250, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê crocus thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với crocus patina.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:10:05.000000');
INSERT INTO `product` VALUES (863, 'Nến sáp ong Trillium đổ bằng tay', 500750, 500750, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu trillium. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:10:07.000000');
INSERT INTO `product` VALUES (864, 'Nến thơm lọ sáp dừa', 988000, 988000, 100, 100, 0, 'Nến thơm rễ huyết lô nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:10:08.000000');
INSERT INTO `product` VALUES (865, 'Treo tường Macramé Hepatica', 2323250, 2323250, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo được treo bằng dây bông tự nhiên Hepatica. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:10:10.000000');
INSERT INTO `product` VALUES (866, 'Vòng hoa Mayapple khô', 995750, 995750, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa mayapple. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:10:11.000000');
INSERT INTO `product` VALUES (867, 'Kệ gỗ hoa cơm cháy chạm khắc thủ công', 2510250, 2510250, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh hoa cơm cháy. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:10:13.000000');
INSERT INTO `product` VALUES (868, 'Thớt quả óc chó táo gai cuối hạt', 3840750, 3840750, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó táo gai và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:10:15.000000');
INSERT INTO `product` VALUES (869, 'Bộ bát gốm Blackthorn ném tay', 2595750, 2595750, 100, 100, 0, 'Bộ 4 bát gốm sứ tráng men phản ứng gai đen. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:10:16.000000');
INSERT INTO `product` VALUES (870, 'Mũ len Merino Rowan dệt kim bằng tay', 678250, 678250, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu thanh lương trà. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:10:19.000000');
INSERT INTO `product` VALUES (871, 'Dây buộc tóc ren Crochet Sloe', 266750, 266750, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông sloe. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:10:21.000000');
INSERT INTO `product` VALUES (872, 'Khăn choàng lụa Damson nhuộm tay', 2377750, 2377750, 100, 100, 0, 'Khăn choàng quấn lụa nhuộm tay sang trọng họa tiết màu nước Damson. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:10:23.000000');
INSERT INTO `product` VALUES (873, 'Ly hợp da hồng khâu tay', 1649500, 1649500, 100, 100, 0, 'Ví cầm tay bằng da có chi tiết khâu tay hình quả hồng. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:10:25.000000');
INSERT INTO `product` VALUES (874, 'Ba lô vải mộc qua sáp', 2954000, 2954000, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da mộc qua. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:10:28.000000');
INSERT INTO `product` VALUES (875, 'Tranh sáp sơn gốc Medlar', 6128000, 6128000, 100, 100, 0, 'Bức tranh sơn dầu nguyên bản (sáp nóng) với thành phần trừu tượng sơn tra. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:10:30.000000');
INSERT INTO `product` VALUES (876, 'Tượng gốm dâu tằm điêu khắc bằng tay', 1649250, 1649250, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết tráng men dâu tằm. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:10:32.000000');
INSERT INTO `product` VALUES (877, 'Mỹ Thuật In Ảnh Thiên Nhiên Cây Ngỗng', 1594250, 1594250, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên nguyên bản của quả lý gai. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:10:34.000000');
INSERT INTO `product` VALUES (878, 'Xà phòng thủ công việt quất sữa dê', 304000, 304000, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm việt quất và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:10:37.000000');
INSERT INTO `product` VALUES (879, 'Thanh gội đầu Crowberry rắn', 540750, 540750, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo mộc quả quạ. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:10:39.000000');
INSERT INTO `product` VALUES (880, 'Tẩy tế bào chết toàn thân Sugar Cloudberry', 254000, 254000, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường mâm xôi thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu mâm xôi. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:10:41.000000');
INSERT INTO `product` VALUES (881, 'Tạp chí da Lingonberry đóng bìa tay', 1186250, 1186250, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da lingonberry và sợi vải lanh đóng bìa bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:10:44.000000');
INSERT INTO `product` VALUES (882, 'Thiệp cưới màu nước Bearberry', 168000, 168000, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật Bearberry. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:10:46.000000');
INSERT INTO `product` VALUES (883, 'Câu đố bằng gỗ Hackberry vẽ tay', 838750, 838750, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay hackberry. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:10:49.000000');
INSERT INTO `product` VALUES (884, 'Đũa đồ chơi cho mèo Buffaloberry bện bằng tay', 457250, 457250, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây bông bện hình quả trâu và phần đính kèm lông tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:10:50.000000');
INSERT INTO `product` VALUES (885, 'Vòng cổ mặt dây chuyền đá mặt trăng Aurora thủ công', 999500, 999500, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng aurora chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:10:54.000000');
INSERT INTO `product` VALUES (886, 'Tên tùy chỉnh Vòng cổ lấp đầy vàng Chạng vạng', 2521250, 2521250, 100, 100, 0, 'Vòng cổ tên chạng vạng được cá nhân hóa được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:10:56.000000');
INSERT INTO `product` VALUES (887, 'Vòng cổ thạch anh phong cách cổ điển', 2303250, 2303250, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thạch nam lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:10:58.000000');
INSERT INTO `product` VALUES (888, 'Vòng tay tình bạn lũa dệt thủ công', 637750, 637750, 100, 100, 0, 'Vòng tay tình bạn bằng gỗ lũa dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:11:01.000000');
INSERT INTO `product` VALUES (889, 'Vòng đeo tay bằng đồng rèn Riverstone', 577500, 577500, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ bằng đá ven sông. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:11:03.000000');
INSERT INTO `product` VALUES (890, 'Vòng tay đá quý Pebble Beach đính cườm', 522500, 522500, 100, 100, 0, 'Vòng tay hạt đá quý bãi biển được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:11:05.000000');
INSERT INTO `product` VALUES (891, 'Bông tai bạc Foxglove được rèn bằng tay', 408000, 408000, 100, 100, 0, 'Khuyên tai dạng đinh tán bằng bạc được rèn thủ công với họa tiết hình găng tay cáo. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:11:08.000000');
INSERT INTO `product` VALUES (892, 'Bông tai pha lê Blackberry có dây', 1857250, 1857250, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê blackberry. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:11:10.000000');
INSERT INTO `product` VALUES (893, 'Vòng xếp quế được đóng dấu bằng tay', 687250, 687250, 100, 100, 0, 'Chiếc nhẫn xếp chồng quế được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:11:12.000000');
INSERT INTO `product` VALUES (894, 'Nhẫn bạch đậu khấu pha lê thô', 707000, 707000, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê bạch đậu khấu thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với lớp vỏ bạch đậu khấu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:11:14.000000');
INSERT INTO `product` VALUES (895, 'Nến sáp ong cỏ ba lá đổ tay', 487000, 487000, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu cỏ ba lá. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:11:16.000000');
INSERT INTO `product` VALUES (896, 'Nến thơm cây kế sáp dừa', 597750, 597750, 100, 100, 0, 'Nến thơm cây kế lô nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:11:17.000000');
INSERT INTO `product` VALUES (897, 'Macramé Wisteria treo tường', 1610250, 1610250, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo treo trên dây bông tự nhiên hoa tử đằng. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:11:19.000000');
INSERT INTO `product` VALUES (898, 'Vòng hoa hồng tước khô', 1308250, 1308250, 100, 100, 0, 'Vòng hoa khô thủ công có hình các loài thực vật theo mùa. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:11:20.000000');
INSERT INTO `product` VALUES (899, 'Kệ Gỗ Falcon Chạm Khắc Bằng Tay', 1812500, 1812500, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh chim ưng. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:11:22.000000');
INSERT INTO `product` VALUES (900, 'Thớt quả óc chó Osprey cuối hạt', 2151250, 2151250, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó chim ưng và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:11:23.000000');
INSERT INTO `product` VALUES (901, 'Bộ bát sứ Hawkweed ném tay', 2084750, 2084750, 100, 100, 0, 'Bộ 4 chiếc bát gốm sứ thủ công phủ men phản ứng hawkweed. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:11:25.000000');
INSERT INTO `product` VALUES (902, 'Mũ len Merino Dogwood dệt kim bằng tay', 680000, 680000, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu sơn thù du. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:11:27.000000');
INSERT INTO `product` VALUES (903, 'Dây buộc tóc bằng ren Sweetgrass', 329500, 329500, 100, 100, 0, 'Dây buộc móc thủ công với họa tiết ren bông cỏ ngọt. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:11:29.000000');
INSERT INTO `product` VALUES (904, 'Khăn choàng lụa đuôi mèo nhuộm tay', 3897500, 3897500, 100, 100, 0, 'Khăn choàng lụa nhuộm tay sang trọng họa tiết màu nước đuôi mèo. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:11:32.000000');
INSERT INTO `product` VALUES (905, 'Ly hợp da Bullrush khâu tay', 1543000, 1543000, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay bằng da bò. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:11:34.000000');
INSERT INTO `product` VALUES (906, 'Ba lô vải cói sáp', 4275250, 4275250, 100, 100, 0, 'Balo vải sáp dày dặn viền da cói. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:11:36.000000');
INSERT INTO `product` VALUES (907, 'Tranh sáp Encaustic Bracken nguyên bản', 5311250, 5311250, 100, 100, 0, 'Bức tranh sơn dầu nguyên bản (sáp nóng) với bố cục trừu tượng dương xỉ. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:11:38.000000');
INSERT INTO `product` VALUES (908, 'Tượng gốm me chua điêu khắc bằng tay', 1264750, 1264750, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết được tráng men màu me chua. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:11:40.000000');
INSERT INTO `product` VALUES (909, 'In ảnh thiên nhiên hoa cúc thiên nhiên mỹ thuật', 997750, 997750, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên hoa cúc nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:11:43.000000');
INSERT INTO `product` VALUES (910, 'Xà phòng nghệ nhân cỏ thi sữa dê', 220500, 220500, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm cỏ thi và các tạp chất thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:11:45.000000');
INSERT INTO `product` VALUES (911, 'Dầu gội Solid Valerian', 456000, 456000, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược valerian. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:11:47.000000');
INSERT INTO `product` VALUES (912, 'Tẩy tế bào chết toàn thân bằng đường Mugwort', 788000, 788000, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường ngải cứu thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu ngải cứu. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:11:50.000000');
INSERT INTO `product` VALUES (913, 'Tạp chí da cây tầm ma đóng bìa tay', 1806750, 1806750, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da cây tầm ma và sợi vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:11:52.000000');
INSERT INTO `product` VALUES (914, 'Thiệp cưới cây ngưu bàng màu nước', 173250, 173250, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật cây ngưu bàng. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:11:54.000000');
INSERT INTO `product` VALUES (915, 'Câu đố bằng gỗ hình bông tuyết vẽ tay', 1010250, 1010250, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay hình giọt nước tuyết. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:11:57.000000');
INSERT INTO `product` VALUES (916, 'Đũa phép đồ chơi cho mèo Crocus bện bằng tay', 378250, 378250, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây bông bện hoa nghệ tây và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:12:00.000000');
INSERT INTO `product` VALUES (917, 'Vòng cổ mặt dây chuyền đá mặt trăng Trillium thủ công', 1170250, 1170250, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng trillium chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:12:02.000000');
INSERT INTO `product` VALUES (918, 'Tên tùy chỉnh Vòng cổ lấp đầy vàng Bloodroot', 2681000, 2681000, 100, 100, 0, 'Vòng cổ tên Bloodroot cá nhân hóa được đóng dấu thủ công trên đĩa phủ vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:12:04.000000');
INSERT INTO `product` VALUES (919, 'Vòng cổ mặt dây chuyền Hepatica phong cách cổ điển', 2975750, 2975750, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng Hepatica lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:12:07.000000');
INSERT INTO `product` VALUES (920, 'Vòng tay tình bạn Mayapple dệt tay', 423250, 423250, 100, 100, 0, 'Vòng tay tình bạn mayapple dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:12:09.000000');
INSERT INTO `product` VALUES (921, 'Vòng đeo tay bằng đồng rèn Elderflower', 822000, 822000, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ hình hoa cơm cháy. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:12:11.000000');
INSERT INTO `product` VALUES (922, 'Vòng tay đá quý Hawthorn đính cườm', 1334500, 1334500, 100, 100, 0, 'Vòng tay hạt đá quý táo gai được xâu chuỗi bằng dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:12:14.000000');
INSERT INTO `product` VALUES (923, 'Bông tai bạc Blackthorn được rèn thủ công', 893500, 893500, 100, 100, 0, 'Bông tai đinh tán bằng bạc sterling được rèn thủ công với kết cấu gai đen. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:12:16.000000');
INSERT INTO `product` VALUES (924, 'Bông tai pha lê Rowan có dây', 1483000, 1483000, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê thanh lương trà. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:12:19.000000');
INSERT INTO `product` VALUES (925, 'Vòng xếp chồng Sloe được đóng dấu bằng tay', 1021500, 1021500, 100, 100, 0, 'Chiếc nhẫn xếp chồng sloe được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:12:21.000000');
INSERT INTO `product` VALUES (926, 'Nhẫn pha lê Damson thô', 1961000, 1961000, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê Damson thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với lớp gỉ dadamson.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:12:23.000000');
INSERT INTO `product` VALUES (927, 'Nến sáp ong hồng đổ bằng tay', 810250, 810250, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu hồng. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:12:25.000000');
INSERT INTO `product` VALUES (928, 'Nến thơm mộc qua sáp dừa', 493750, 493750, 100, 100, 0, 'Nến thơm mộc qua lô nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:12:26.000000');
INSERT INTO `product` VALUES (929, 'Treo tường Macramé Medlar', 2362000, 2362000, 100, 100, 0, 'Bức tường macramé thắt nút thủ công phức tạp treo bằng dây bông tự nhiên sơn tra. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:12:28.000000');
INSERT INTO `product` VALUES (930, 'Vòng hoa dâu tằm khô', 1861750, 1861750, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa dâu tằm. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:12:29.000000');
INSERT INTO `product` VALUES (931, 'Kệ Gỗ Ngỗng Chạm Khắc Bằng Tay', 1627250, 1627250, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh quả lý gai. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:12:31.000000');
INSERT INTO `product` VALUES (932, 'Thớt quả óc chó việt quất cuối hạt', 4466250, 4466250, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó việt quất và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:12:33.000000');
INSERT INTO `product` VALUES (933, 'Bộ bát gốm Crowberry ném tay', 1757750, 1757750, 100, 100, 0, 'Bộ 4 chiếc bát sứ cầm tay phủ men phản ứng quả quạ. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:12:34.000000');
INSERT INTO `product` VALUES (934, 'Mũ len Merino Cloudberry dệt kim bằng tay', 1525750, 1525750, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ 100% len merino superwash với màu sắc dâu tây. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:12:37.000000');
INSERT INTO `product` VALUES (935, 'Dây buộc tóc bằng ren Lingonberry', 154500, 154500, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông lingonberry. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:12:39.000000');
INSERT INTO `product` VALUES (936, 'Khăn choàng lụa Bearberry nhuộm tay', 1647000, 1647000, 100, 100, 0, 'Khăn choàng lụa quấn tay sang trọng họa tiết màu nước Bearberry. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:12:41.000000');
INSERT INTO `product` VALUES (937, 'Ly hợp da Hackberry khâu tay', 1162250, 1162250, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay hackberry. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:12:43.000000');
INSERT INTO `product` VALUES (938, 'Ba lô Buffaloberry vải sáp', 2420750, 2420750, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da trâu. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:12:45.000000');
INSERT INTO `product` VALUES (939, 'Tranh sáp Aurora nguyên bản', 2025500, 2025500, 100, 100, 0, 'Bức tranh sơn dầu nguyên bản (sáp nóng) với bố cục trừu tượng cực quang. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:12:48.000000');
INSERT INTO `product` VALUES (940, 'Tượng gốm Chạng vạng được điêu khắc bằng tay', 878250, 878250, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết được tráng men chạng vạng. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:12:50.000000');
INSERT INTO `product` VALUES (941, 'Mỹ thuật Heather Nature Ảnh In', 1480750, 1480750, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên cây thạch nam nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:12:52.000000');
INSERT INTO `product` VALUES (942, 'Xà Phòng Nghệ Nhân Gỗ Lũa Sữa Dê', 474250, 474250, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm gỗ lũa và các tạp chất thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:12:54.000000');
INSERT INTO `product` VALUES (943, 'Thanh gội đầu Solid Riverstone', 524000, 524000, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược riverstone. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:12:57.000000');
INSERT INTO `product` VALUES (944, 'Tẩy tế bào chết Sugar Pebble Beach', 700000, 700000, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường sỏi bãi biển thủ công với gốc dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu bãi biển sỏi. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:12:59.000000');
INSERT INTO `product` VALUES (945, 'Tạp chí da Foxglove ràng buộc bằng tay', 1810500, 1810500, 100, 100, 0, 'Nhật ký đóng bìa tay với bìa da mao địa hoàng và dây vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:13:01.000000');
INSERT INTO `product` VALUES (946, 'Thiệp cưới Blackberry màu nước', 164250, 164250, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật dâu đen. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:13:04.000000');
INSERT INTO `product` VALUES (947, 'Câu đố bằng gỗ quế vẽ tay', 964250, 964250, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay bằng quế. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:13:06.000000');
INSERT INTO `product` VALUES (948, 'Cây đũa phép đồ chơi cho mèo bạch đậu khấu bện tay', 216500, 216500, 100, 100, 0, 'Đồ chơi đũa phép mèo thủ công với dây bông bện bạch đậu khấu và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:13:08.000000');
INSERT INTO `product` VALUES (949, 'Vòng cổ mặt dây chuyền đá mặt trăng Clover thủ công', 1001000, 1001000, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng cỏ ba lá chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:13:11.000000');
INSERT INTO `product` VALUES (950, 'Tên tùy chỉnh Vòng cổ mạ vàng Thistle', 1242500, 1242500, 100, 100, 0, 'Vòng cổ tên cây kế được cá nhân hóa được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:13:13.000000');
INSERT INTO `product` VALUES (951, 'Vòng cổ mặt dây chuyền Wisteria phong cách cổ điển', 2042000, 2042000, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:13:15.000000');
INSERT INTO `product` VALUES (952, 'Vòng tay tình bạn Wren dệt tay', 661750, 661750, 100, 100, 0, 'Vòng tay tình bạn wren dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:13:18.000000');
INSERT INTO `product` VALUES (953, 'Vòng đeo tay bằng đồng hình chim ưng rèn', 975250, 975250, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ hình chim ưng. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:13:20.000000');
INSERT INTO `product` VALUES (954, 'Vòng tay đá quý Osprey đính cườm', 1259500, 1259500, 100, 100, 0, 'Vòng tay hạt đá quý chim ưng được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:13:22.000000');
INSERT INTO `product` VALUES (955, 'Bông tai bạc Hawkweed được rèn thủ công', 1034250, 1034250, 100, 100, 0, 'Bông tai đinh tán bằng bạc sterling được rèn thủ công với họa tiết hawkweed. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:13:24.000000');
INSERT INTO `product` VALUES (956, 'Bông tai pha lê Dogwood bọc dây', 922500, 922500, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê bằng gỗ sơn thù du. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:13:26.000000');
INSERT INTO `product` VALUES (957, 'Vòng xếp cỏ ngọt được đóng dấu bằng tay', 335250, 335250, 100, 100, 0, 'Chiếc nhẫn xếp chồng cỏ ngọt được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:13:29.000000');
INSERT INTO `product` VALUES (958, 'Nhẫn tuyên bố Cattail pha lê thô', 922500, 922500, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê cattail thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thiện với patina đuôi mèo.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:13:31.000000');
INSERT INTO `product` VALUES (959, 'Nến sáp ong Bullrush đổ bằng tay', 430250, 430250, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu cây bách xù. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:13:33.000000');
INSERT INTO `product` VALUES (960, 'Nến thơm cói sáp dừa', 710750, 710750, 100, 100, 0, 'Nến thơm cói số lượng nhỏ làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:13:34.000000');
INSERT INTO `product` VALUES (961, 'Treo tường Macramé Bracken', 1756250, 1756250, 100, 100, 0, 'Bức tường macramé được thắt nút bằng tay phức tạp treo bằng dây bông tự nhiên dương xỉ. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:13:36.000000');
INSERT INTO `product` VALUES (962, 'Vòng hoa sầu riêng khô', 1771250, 1771250, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa màu me chua. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:13:38.000000');
INSERT INTO `product` VALUES (963, 'Kệ Gỗ Hoa Cúc Chạm Khắc Bằng Tay', 2885250, 2885250, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết viền hoa cúc. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:13:39.000000');
INSERT INTO `product` VALUES (964, 'Thớt quả óc chó Yarrow cuối hạt', 1721000, 1721000, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó yarrow và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:13:41.000000');
INSERT INTO `product` VALUES (965, 'Bộ bát sứ Valerian ném tay', 2963000, 2963000, 100, 100, 0, 'Bộ 4 bát gốm sứ tráng men phản ứng valerian. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:13:43.000000');
INSERT INTO `product` VALUES (966, 'Mũ len Merino Mugwort dệt kim bằng tay', 1028750, 1028750, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu ngải cứu. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:13:47.000000');
INSERT INTO `product` VALUES (967, 'Dây buộc tóc bằng ren cây tầm ma', 213500, 213500, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông tầm ma. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:13:49.000000');
INSERT INTO `product` VALUES (968, 'Khăn choàng lụa ngưu bàng nhuộm tay', 1480250, 1480250, 100, 100, 0, 'Khăn choàng quấn lụa nhuộm tay sang trọng họa tiết màu nước cây ngưu bàng. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:13:51.000000');
INSERT INTO `product` VALUES (969, 'Ly hợp da Snowdrop khâu tay', 2266250, 2266250, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay hình giọt nước tuyết. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:13:54.000000');
INSERT INTO `product` VALUES (970, 'Ba lô vải Crocus sáp', 2527250, 2527250, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da crocus. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:13:56.000000');
INSERT INTO `product` VALUES (971, 'Tranh sáp gốc Trillium Encaustic', 5672250, 5672250, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng trillium. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:13:58.000000');
INSERT INTO `product` VALUES (972, 'Tượng gốm Bloodroot điêu khắc bằng tay', 1077750, 1077750, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết men đỏ. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:14:00.000000');
INSERT INTO `product` VALUES (973, 'Mỹ Thuật In Ảnh Thiên Nhiên Hepatica', 694000, 694000, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên Hepatica nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:14:03.000000');
INSERT INTO `product` VALUES (974, 'Xà Phòng Thủ Công Mayapple Sữa Dê', 313500, 313500, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm mayapple và các chất thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:14:05.000000');
INSERT INTO `product` VALUES (975, 'Thanh dầu gội Solid Elderflower', 254000, 254000, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược hoa cơm cháy. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:14:07.000000');
INSERT INTO `product` VALUES (976, 'Tẩy tế bào chết toàn thân Sugar Hawthorn', 750500, 750500, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường táo gai thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu táo gai. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:14:10.000000');
INSERT INTO `product` VALUES (977, 'Tạp chí da Blackthorn đóng bìa tay', 1919500, 1919500, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da mận gai và dây vải lanh đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:14:12.000000');
INSERT INTO `product` VALUES (978, 'Thiệp cưới màu nước Rowan', 143000, 143000, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật thanh lương trà. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:14:14.000000');
INSERT INTO `product` VALUES (979, 'Câu đố bằng gỗ Sloe vẽ tay', 810250, 810250, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay sloe. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:14:17.000000');
INSERT INTO `product` VALUES (980, 'Đũa phép đồ chơi cho mèo Damson bện tay', 491500, 491500, 100, 100, 0, 'Đồ chơi đũa phép cho mèo được làm thủ công với dây cotton bện damson và phần đính kèm lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:14:19.000000');
INSERT INTO `product` VALUES (981, 'Vòng cổ mặt dây chuyền đá mặt trăng hình trái hồng thủ công', 1986250, 1986250, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng hồng chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:14:22.000000');
INSERT INTO `product` VALUES (982, 'Tên tùy chỉnh Vòng cổ Quince Gold-Fill', 1879500, 1879500, 100, 100, 0, 'Vòng cổ tên mộc qua được cá nhân hóa được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:14:24.000000');
INSERT INTO `product` VALUES (983, 'Vòng cổ Medlar theo phong cách cổ điển', 2523250, 2523250, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:14:26.000000');
INSERT INTO `product` VALUES (984, 'Vòng tay tình bạn dâu tằm dệt tay', 420250, 420250, 100, 100, 0, 'Vòng tay tình bạn dâu tằm dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:14:29.000000');
INSERT INTO `product` VALUES (985, 'Vòng đeo tay bằng đồng rèn quả lý gai', 1280000, 1280000, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ màu quả lý gai. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:14:31.000000');
INSERT INTO `product` VALUES (986, 'Vòng tay đá quý việt quất đính cườm', 1177750, 1177750, 100, 100, 0, 'Vòng tay hạt đá quý việt quất được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:14:33.000000');
INSERT INTO `product` VALUES (987, 'Bông tai bạc Crowberry được rèn bằng tay', 1119000, 1119000, 100, 100, 0, 'Bông tai đinh tán bằng bạc được rèn thủ công với kết cấu quả quạ. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:14:35.000000');
INSERT INTO `product` VALUES (988, 'Bông tai pha lê Cloudberry có dây', 1836250, 1836250, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn là pha lê hình quả mâm xôi. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:14:38.000000');
INSERT INTO `product` VALUES (989, 'Vòng xếp chồng Lingonberry được đóng dấu bằng tay', 728250, 728250, 100, 100, 0, 'Nhẫn xếp chồng lingonberry được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:14:40.000000');
INSERT INTO `product` VALUES (990, 'Nhẫn tuyên bố Bearberry pha lê thô', 803750, 803750, 100, 100, 0, 'Chiếc nhẫn nổi bật có pha lê Bearberry thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với lớp vỏ Bearberry.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:14:42.000000');
INSERT INTO `product` VALUES (991, 'Nến sáp ong Hackberry đổ bằng tay', 800750, 800750, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu hackberry. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:14:44.000000');
INSERT INTO `product` VALUES (992, 'Nến thơm sáp dừa Buffaloberry', 1032000, 1032000, 100, 100, 0, 'Nến thơm trâu hàng loạt nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:14:45.000000');
INSERT INTO `product` VALUES (993, 'Treo tường Macramé Aurora', 2320000, 2320000, 100, 100, 0, 'Bức tường macramé thắt nút thủ công phức tạp treo bằng dây bông tự nhiên aurora. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:14:47.000000');
INSERT INTO `product` VALUES (994, 'Vòng Hoa Chạng Vạng Hoa Khô', 2159000, 2159000, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa chạng vạng. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:14:49.000000');
INSERT INTO `product` VALUES (995, 'Kệ Gỗ Thạch Anh Chạm Khắc Bằng Tay', 3287000, 3287000, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh thạch nam. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:14:50.000000');
INSERT INTO `product` VALUES (996, 'Thớt gỗ óc chó lũa cuối hạt', 3721000, 3721000, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ gỗ óc chó và gỗ phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:14:52.000000');
INSERT INTO `product` VALUES (997, 'Bộ bát sứ Riverstone ném tay', 2825500, 2825500, 100, 100, 0, 'Bộ 4 bát gốm sứ tráng men phản ứng riverstone. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:14:53.000000');
INSERT INTO `product` VALUES (998, 'Mũ len Merino Beach dệt kim bằng tay', 1249000, 1249000, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ 100% len merino siêu giặt với màu sắc bãi biển sỏi. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:14:56.000000');
INSERT INTO `product` VALUES (999, 'Móc buộc tóc ren Foxglove', 182500, 182500, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông foxglove. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:14:58.000000');
INSERT INTO `product` VALUES (1000, 'Khăn choàng lụa Blackberry nhuộm tay', 1797250, 1797250, 100, 100, 0, 'Khăn choàng quấn lụa nhuộm tay sang trọng họa tiết màu nước dâu đen. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:15:00.000000');
INSERT INTO `product` VALUES (1001, 'Ly hợp da quế khâu tay', 3187250, 3187250, 100, 100, 0, 'Ví cầm tay da thủ công với chi tiết khâu tay màu quế. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:15:03.000000');
INSERT INTO `product` VALUES (1002, 'Ba lô vải bạch đậu khấu', 4293250, 4293250, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da bạch đậu khấu. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:15:06.000000');
INSERT INTO `product` VALUES (1003, 'Tranh sáp cỏ ba lá nguyên bản', 2546250, 2546250, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng cỏ ba lá. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:15:08.000000');
INSERT INTO `product` VALUES (1004, 'Tượng gốm Thistle điêu khắc bằng tay', 1132750, 1132750, 100, 100, 0, 'Tượng gốm bằng đá được điêu khắc thủ công với các chi tiết tráng men cây kế. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:15:10.000000');
INSERT INTO `product` VALUES (1005, 'Mỹ thuật In ảnh thiên nhiên Wisteria', 1696500, 1696500, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên hoa đậu tía nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:15:13.000000');
INSERT INTO `product` VALUES (1006, 'Xà Phòng Nghệ Nhân Wren Sữa Dê', 215750, 215750, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm chim hồng tước và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:15:15.000000');
INSERT INTO `product` VALUES (1007, 'Thanh gội đầu Solid Falcon', 444500, 444500, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược chim ưng. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:15:17.000000');
INSERT INTO `product` VALUES (1008, 'Tẩy tế bào chết toàn thân Sugar Osprey', 668250, 668250, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường osprey thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu chim ưng. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:15:20.000000');
INSERT INTO `product` VALUES (1009, 'Tạp chí da Hawkweed ràng buộc bằng tay', 1114750, 1114750, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da diều hâu và sợi vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:15:22.000000');
INSERT INTO `product` VALUES (1010, 'Thiệp cưới màu nước Dogwood', 128750, 128750, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật cây dương đào. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:15:25.000000');
INSERT INTO `product` VALUES (1011, 'Câu đố bằng gỗ Sweetgrass vẽ tay', 964000, 964000, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay bằng cỏ ngọt. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:15:27.000000');
INSERT INTO `product` VALUES (1012, 'Đũa phép đồ chơi cho mèo đuôi mèo bện bằng tay', 435000, 435000, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây cotton bện đuôi mèo và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:15:30.000000');
INSERT INTO `product` VALUES (1013, 'Vòng cổ mặt dây chuyền đá mặt trăng Bullrush thủ công', 2171000, 2171000, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:15:32.000000');
INSERT INTO `product` VALUES (1014, 'Tên Tùy Chỉnh Vòng Cổ Cói Vàng Lấp Lánh', 1997000, 1997000, 100, 100, 0, 'Dây chuyền tên cói cá tính được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:15:35.000000');
INSERT INTO `product` VALUES (1015, 'Vòng cổ mặt dây chuyền Bracken theo phong cách cổ điển', 1162250, 1162250, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng dương xỉ lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:15:37.000000');
INSERT INTO `product` VALUES (1016, 'Vòng tay tình bạn cây me chua dệt tay', 299000, 299000, 100, 100, 0, 'Vòng tay tình bạn màu me chua dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:15:39.000000');
INSERT INTO `product` VALUES (1017, 'Vòng đeo tay bằng đồng hoa cúc rèn', 1161000, 1161000, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ màu hoa cúc. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:15:42.000000');
INSERT INTO `product` VALUES (1018, 'Vòng tay đá quý Yarrow đính cườm', 746250, 746250, 100, 100, 0, 'Vòng tay hạt đá quý cỏ thi được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:15:44.000000');
INSERT INTO `product` VALUES (1019, 'Bông tai bạc Valerian được rèn thủ công', 507750, 507750, 100, 100, 0, 'Bông tai đinh tán bằng bạc được rèn thủ công với họa tiết cây nữ lang. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:15:47.000000');
INSERT INTO `product` VALUES (1020, 'Bông tai pha lê Mugwort có dây', 712500, 712500, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn là pha lê ngải cứu. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:15:49.000000');
INSERT INTO `product` VALUES (1021, 'Vòng xếp chồng cây tầm ma được đóng dấu bằng tay', 944000, 944000, 100, 100, 0, 'Chiếc nhẫn xếp chồng cây tầm ma được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:15:52.000000');
INSERT INTO `product` VALUES (1022, 'Vòng tuyên bố cây ngưu bàng pha lê thô', 1104750, 1104750, 100, 100, 0, 'Chiếc nhẫn nổi bật có pha lê cây ngưu bàng thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với patina cây ngưu bàng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:15:54.000000');
INSERT INTO `product` VALUES (1023, 'Nến sáp ong hình giọt nước đổ bằng tay', 853500, 853500, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu giọt tuyết. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:15:55.000000');
INSERT INTO `product` VALUES (1024, 'Nến thơm sáp dừa Crocus', 1019750, 1019750, 100, 100, 0, 'Nến thơm hoa nghệ tây số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:15:57.000000');
INSERT INTO `product` VALUES (1025, 'Treo tường Macramé Trillium', 1825500, 1825500, 100, 100, 0, 'Bức tường macramé thắt nút bằng tay phức tạp treo bằng dây bông tự nhiên trillium. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:15:58.000000');
INSERT INTO `product` VALUES (1026, 'Vòng hoa huyết hoa khô', 1801000, 1801000, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa từ rễ huyết. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:16:00.000000');
INSERT INTO `product` VALUES (1027, 'Kệ Gỗ Hepatica Chạm Khắc Bằng Tay', 1728000, 1728000, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết viền gan. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:16:02.000000');
INSERT INTO `product` VALUES (1028, 'Thớt quả óc chó Mayapple cuối hạt', 2244250, 2244250, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó mayapple và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:16:03.000000');
INSERT INTO `product` VALUES (1029, 'Bộ bát gốm hoa cơm cháy cầm tay', 1655250, 1655250, 100, 100, 0, 'Bộ 4 bát gốm sứ tráng men phản ứng hoa cơm cháy. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:16:05.000000');
INSERT INTO `product` VALUES (1030, 'Mũ len Merino Hawthorn dệt kim bằng tay', 1133250, 1133250, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu táo gai. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:16:07.000000');
INSERT INTO `product` VALUES (1031, 'Dây buộc tóc ren gai đen móc', 180500, 180500, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren cotton gai đen. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:16:10.000000');
INSERT INTO `product` VALUES (1032, 'Khăn choàng lụa Rowan nhuộm tay', 3895250, 3895250, 100, 100, 0, 'Khăn choàng quấn lụa nhuộm tay sang trọng họa tiết màu nước thanh lương trà. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:16:12.000000');
INSERT INTO `product` VALUES (1033, 'Ly Hợp Da Sloe Khâu Tay', 2783250, 2783250, 100, 100, 0, 'Ví cầm tay bằng da có chi tiết khâu tay. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:16:14.000000');
INSERT INTO `product` VALUES (1034, 'Ba lô vải sáp Damson', 2547500, 2547500, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da damson. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:16:17.000000');
INSERT INTO `product` VALUES (1035, 'Tranh sáp màu quả hồng nguyên chất', 3120500, 3120500, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng quả hồng. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:16:19.000000');
INSERT INTO `product` VALUES (1036, 'Tượng gốm mộc qua điêu khắc bằng tay', 1167750, 1167750, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết tráng men mộc qua. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:16:21.000000');
INSERT INTO `product` VALUES (1037, 'In ảnh thiên nhiên Mỹ thuật Medlar', 1795250, 1795250, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên sơn tra gốc. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:16:23.000000');
INSERT INTO `product` VALUES (1038, 'Xà phòng thủ công dâu tằm sữa dê', 467500, 467500, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm dâu tằm và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:16:25.000000');
INSERT INTO `product` VALUES (1039, 'Thanh gội đầu Gooseberry rắn', 305750, 305750, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo mộc quả lý gai. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:16:28.000000');
INSERT INTO `product` VALUES (1040, 'Tẩy tế bào chết toàn thân bằng đường việt quất', 592250, 592250, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường việt quất thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu việt quất. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:16:30.000000');
INSERT INTO `product` VALUES (1041, 'Tạp chí da Crowberry đóng bìa tay', 1770750, 1770750, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da quạ và sợi vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:16:32.000000');
INSERT INTO `product` VALUES (1042, 'Thiệp cưới màu nước Cloudberry', 242500, 242500, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật cây mâm xôi. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:16:34.000000');
INSERT INTO `product` VALUES (1043, 'Câu đố bằng gỗ Lingonberry vẽ tay', 851500, 851500, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay lingonberry. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:16:36.000000');
INSERT INTO `product` VALUES (1044, 'Cây đũa phép đồ chơi cho mèo Bearberry bện tay', 497500, 497500, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây cotton bện hình quả dâu và phần đính kèm lông tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:16:38.000000');
INSERT INTO `product` VALUES (1045, 'Vòng cổ mặt dây chuyền đá mặt trăng Hackberry thủ công', 724000, 724000, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng hackberry chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:16:40.000000');
INSERT INTO `product` VALUES (1046, 'Tên tùy chỉnh Vòng cổ lấp đầy vàng Buffaloberry', 2631250, 2631250, 100, 100, 0, 'Vòng cổ tên Buffaloberry cá tính được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:16:43.000000');
INSERT INTO `product` VALUES (1047, 'Vòng cổ Aurora Locket theo phong cách cổ điển', 2695000, 2695000, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau aurora lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:16:45.000000');
INSERT INTO `product` VALUES (1048, 'Vòng tay tình bạn Chạng vạng dệt tay', 511000, 511000, 100, 100, 0, 'Vòng tay tình bạn chạng vạng dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:16:49.000000');
INSERT INTO `product` VALUES (1049, 'Vòng đeo tay bằng đồng rèn thạch cao', 876500, 876500, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ màu thạch nam. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:16:51.000000');
INSERT INTO `product` VALUES (1050, 'Vòng tay đá quý lũa đính cườm', 556000, 556000, 100, 100, 0, 'Vòng tay hạt đá quý bằng gỗ lũa được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:16:55.000000');
INSERT INTO `product` VALUES (1051, 'Bông tai bạc Riverstone được rèn thủ công', 764250, 764250, 100, 100, 0, 'Khuyên tai dạng đinh tán bằng bạc được rèn thủ công với kết cấu bằng đá ven sông. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:16:57.000000');
INSERT INTO `product` VALUES (1052, 'Bông tai pha lê Pebble Beach có dây', 1205500, 1205500, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn là pha lê bãi biển sỏi. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:16:59.000000');
INSERT INTO `product` VALUES (1053, 'Vòng xếp chồng Foxglove được đóng dấu bằng tay', 772750, 772750, 100, 100, 0, 'Chiếc nhẫn xếp chồng hình cáo được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:17:01.000000');
INSERT INTO `product` VALUES (1054, 'Nhẫn tuyên bố Blackberry pha lê thô', 874750, 874750, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê blackberry thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với lớp vỏ blackberry.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:17:04.000000');
INSERT INTO `product` VALUES (1055, 'Nến sáp ong quế đổ bằng tay', 541750, 541750, 100, 100, 0, 'Nến sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu quế. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:17:05.000000');
INSERT INTO `product` VALUES (1056, 'Nến thơm sáp dừa bạch đậu khấu', 459250, 459250, 100, 100, 0, 'Nến thơm thảo quả lô nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:17:07.000000');
INSERT INTO `product` VALUES (1057, 'Macramé Cỏ Ba Lá Treo Tường', 1012000, 1012000, 100, 100, 0, 'Bức tường macramé được thắt nút bằng tay phức tạp treo bằng dây bông tự nhiên hình cỏ ba lá. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:17:09.000000');
INSERT INTO `product` VALUES (1058, 'Vòng hoa kế khô', 1578750, 1578750, 100, 100, 0, 'Vòng hoa khô thủ công có hình cây kế theo mùa. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:17:10.000000');
INSERT INTO `product` VALUES (1059, 'Kệ gỗ hoa tử đằng chạm khắc thủ công', 2510250, 2510250, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh hoa tử đằng. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:17:12.000000');
INSERT INTO `product` VALUES (1060, 'Thớt quả óc chó Wren cuối hạt', 3269000, 3269000, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó wren và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:17:13.000000');
INSERT INTO `product` VALUES (1061, 'Bộ Bát Sứ Falcon Ném Tay', 2089500, 2089500, 100, 100, 0, 'Bộ 4 bát gốm sứ cầm tay phủ men phản ứng hình chim ưng. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:17:15.000000');
INSERT INTO `product` VALUES (1062, 'Mũ len Osprey Merino dệt kim bằng tay', 1314750, 1314750, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ 100% len merino superwash với màu sắc chim ưng. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:17:17.000000');
INSERT INTO `product` VALUES (1063, 'Móc buộc tóc ren Hawkweed', 432750, 432750, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông hawkweed. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:17:20.000000');
INSERT INTO `product` VALUES (1064, 'Khăn choàng lụa Dogwood nhuộm tay', 2621750, 2621750, 100, 100, 0, 'Khăn choàng quấn lụa nhuộm tay sang trọng với hoa văn màu nước bằng gỗ sơn thù du. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:17:22.000000');
INSERT INTO `product` VALUES (1065, 'Ly hợp da Sweetgrass khâu tay', 2512500, 2512500, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay sweetgrass. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:17:24.000000');
INSERT INTO `product` VALUES (1066, 'Ba lô Cattail vải sáp', 3879000, 3879000, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da đuôi mèo. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:17:26.000000');
INSERT INTO `product` VALUES (1067, 'Tranh sáp Encaustic Bullrush nguyên bản', 4239000, 4239000, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng của cây bò tót. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:17:29.000000');
INSERT INTO `product` VALUES (1068, 'Tượng gốm cói điêu khắc bằng tay', 754750, 754750, 100, 100, 0, 'Tượng gốm sứ điêu khắc thủ công với các chi tiết bằng men cói. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:17:31.000000');
INSERT INTO `product` VALUES (1069, 'Mỹ Thuật In Ảnh Thiên Nhiên Bracken', 569500, 569500, 100, 100, 0, 'Lưu trữ bản in mỹ thuật của bức ảnh thiên nhiên dương xỉ nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:17:33.000000');
INSERT INTO `product` VALUES (1070, 'Xà Phòng Thủ Công Sữa Dê Sorrel', 363000, 363000, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm cây me chua và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:17:36.000000');
INSERT INTO `product` VALUES (1071, 'Thanh gội đầu hoa cúc rắn', 445500, 445500, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược hoa cúc. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:17:38.000000');
INSERT INTO `product` VALUES (1072, 'Tẩy tế bào chết Sugar Yarrow', 452750, 452750, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường cỏ thi thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu cỏ thi. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:17:40.000000');
INSERT INTO `product` VALUES (1073, 'Tạp chí da Valerian ràng buộc tay', 1191250, 1191250, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da valerian và sợi vải lanh đóng bìa bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:17:43.000000');
INSERT INTO `product` VALUES (1074, 'Thiệp cưới màu nước ngải cứu', 148250, 148250, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật ngải cứu. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:17:46.000000');
INSERT INTO `product` VALUES (1075, 'Câu đố bằng gỗ cây tầm ma vẽ tay', 1278250, 1278250, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay bằng cây tầm ma. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:17:49.000000');
INSERT INTO `product` VALUES (1076, 'Đũa phép đồ chơi cho mèo ngưu bàng bện bằng tay', 425250, 425250, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây cotton bện cây ngưu bàng và phần đính kèm lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:17:51.000000');
INSERT INTO `product` VALUES (1077, 'Vòng cổ mặt dây chuyền đá mặt trăng hình giọt nước thủ công', 900000, 900000, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng hình giọt nước chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:17:54.000000');
INSERT INTO `product` VALUES (1078, 'Tên tùy chỉnh Vòng cổ Crocus Gold-Fill', 1177500, 1177500, 100, 100, 0, 'Vòng cổ tên crocus cá tính được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:17:56.000000');
INSERT INTO `product` VALUES (1079, 'Vòng cổ Trillium Locket theo phong cách cổ điển', 1549000, 1549000, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng trillium lấy cảm hứng từ cổ. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:17:58.000000');
INSERT INTO `product` VALUES (1080, 'Vòng tay tình bạn Bloodroot dệt tay', 342250, 342250, 100, 100, 0, 'Vòng tay tình bạn rễ cây máu được dệt thủ công bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:18:00.000000');
INSERT INTO `product` VALUES (1081, 'Vòng đeo tay bằng đồng Hepatica rèn', 1225250, 1225250, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ màu Hepatica. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:18:02.000000');
INSERT INTO `product` VALUES (1082, 'Vòng tay đá quý Mayapple đính cườm', 1386750, 1386750, 100, 100, 0, 'Vòng tay hạt đá quý mayapple được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:18:04.000000');
INSERT INTO `product` VALUES (1083, 'Bông tai bạc hình hoa cơm cháy được rèn thủ công', 941250, 941250, 100, 100, 0, 'Bông tai bạc sterling được rèn thủ công với họa tiết hoa cơm cháy. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:18:07.000000');
INSERT INTO `product` VALUES (1084, 'Bông tai pha lê Hawthorn có dây', 1585750, 1585750, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê táo gai. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:18:09.000000');
INSERT INTO `product` VALUES (1085, 'Vòng xếp chồng Blackthorn được đóng dấu bằng tay', 555000, 555000, 100, 100, 0, 'Chiếc nhẫn xếp chồng cây gai đen được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:18:11.000000');
INSERT INTO `product` VALUES (1086, 'Nhẫn pha lê Rowan thô', 1151250, 1151250, 100, 100, 0, 'Chiếc nhẫn nổi bật có pha lê thanh lương trà thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với lớp vỏ thanh lương trà.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:18:13.000000');
INSERT INTO `product` VALUES (1087, 'Nến sáp ong Sloe đổ bằng tay', 735000, 735000, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu sloe. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:18:15.000000');
INSERT INTO `product` VALUES (1088, 'Nến thơm sáp dừa Damson', 937250, 937250, 100, 100, 0, 'Nến thơm Damson số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:18:17.000000');
INSERT INTO `product` VALUES (1089, 'Quả Hồng Macramé Treo Tường', 3281500, 3281500, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo treo trên dây bông tự nhiên màu hồng. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:18:19.000000');
INSERT INTO `product` VALUES (1090, 'Vòng hoa mộc qua khô', 1865500, 1865500, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa mộc qua. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:18:20.000000');
INSERT INTO `product` VALUES (1091, 'Kệ gỗ Medlar chạm khắc thủ công', 1632250, 1632250, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh sơn tra. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:18:22.000000');
INSERT INTO `product` VALUES (1092, 'Thớt quả óc chó dâu tằm cuối hạt', 3218000, 3218000, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó dâu và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:18:24.000000');
INSERT INTO `product` VALUES (1093, 'Bộ bát sứ ném quả lý gai bằng tay', 1371250, 1371250, 100, 100, 0, 'Bộ 4 chiếc bát sứ cầm tay phủ men phản ứng quả lý gai. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:18:25.000000');
INSERT INTO `product` VALUES (1094, 'Mũ len Merino Bilberry đan tay', 761750, 761750, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu việt quất. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:18:27.000000');
INSERT INTO `product` VALUES (1095, 'Dây buộc tóc bằng ren Crochet Crowberry', 281000, 281000, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren cotton dâu tây. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:18:30.000000');
INSERT INTO `product` VALUES (1096, 'Khăn choàng lụa Cloudberry nhuộm tay', 3323500, 3323500, 100, 100, 0, 'Khăn choàng lụa nhuộm tay sang trọng họa tiết màu nước mâm xôi. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:18:32.000000');
INSERT INTO `product` VALUES (1097, 'Ly hợp da Lingonberry khâu tay', 1622000, 1622000, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay lingonberry. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:18:34.000000');
INSERT INTO `product` VALUES (1098, 'Ba lô Bearberry vải sáp', 3567750, 3567750, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da Bearberry. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:18:36.000000');
INSERT INTO `product` VALUES (1099, 'Tranh sáp nguyên chất Hackberry', 3228250, 3228250, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng hackberry. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:18:39.000000');
INSERT INTO `product` VALUES (1100, 'Tượng gốm Buffaloberry điêu khắc bằng tay', 922750, 922750, 100, 100, 0, 'Tượng gốm bằng đá được điêu khắc thủ công với các chi tiết tráng men dâu. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:18:42.000000');
INSERT INTO `product` VALUES (1101, 'In ảnh thiên nhiên cực quang mỹ thuật', 1718500, 1718500, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên cực quang nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:18:44.000000');
INSERT INTO `product` VALUES (1102, 'Xà phòng nghệ nhân Twilight Artisan sữa dê', 444250, 444250, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm hoàng hôn và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:18:47.000000');
INSERT INTO `product` VALUES (1103, 'Thanh gội đầu Solid Heather', 519250, 519250, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược thạch nam. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:18:50.000000');
INSERT INTO `product` VALUES (1104, 'Tẩy tế bào chết bằng gỗ lũa đường', 329250, 329250, 100, 100, 0, 'Tẩy tế bào chết bằng đường gỗ lũa thủ công gốc dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu gỗ lũa. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:18:52.000000');
INSERT INTO `product` VALUES (1105, 'Tạp chí da Riverstone đóng bìa tay', 1878750, 1878750, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da bằng đá ven sông và dây vải lanh được đóng bằng đường khâu kiểu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:18:54.000000');
INSERT INTO `product` VALUES (1106, 'Thiệp cưới màu nước trên bãi biển Pebble', 334000, 334000, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật trên bãi biển sỏi. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:18:56.000000');
INSERT INTO `product` VALUES (1107, 'Câu đố bằng gỗ Foxglove vẽ tay', 624250, 624250, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay foxglove. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:18:58.000000');
INSERT INTO `product` VALUES (1108, 'Cây đũa phép đồ chơi cho mèo Blackberry bện tay', 286500, 286500, 100, 100, 0, 'Đồ chơi đũa phép mèo thủ công với dây cotton bện dâu đen và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:19:00.000000');
INSERT INTO `product` VALUES (1109, 'Vòng cổ mặt dây chuyền đá mặt trăng quế thủ công', 1189750, 1189750, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng quế chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:19:03.000000');
INSERT INTO `product` VALUES (1110, 'Tên tùy chỉnh Vòng cổ lấp đầy vàng bạch đậu khấu', 1248500, 1248500, 100, 100, 0, 'Vòng cổ tên bạch đậu khấu được cá nhân hóa được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:19:05.000000');
INSERT INTO `product` VALUES (1111, 'Vòng cổ Mề đay cỏ ba lá phong cách cổ điển', 2260250, 2260250, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng cỏ ba lá lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:19:07.000000');
INSERT INTO `product` VALUES (1112, 'Vòng tay tình bạn cây kế dệt tay', 565750, 565750, 100, 100, 0, 'Vòng tay tình bạn cây kế dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:19:09.000000');
INSERT INTO `product` VALUES (1113, 'Vòng đeo tay bằng đồng Wisteria rèn', 1254000, 1254000, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn bằng tay với lớp gỉ hoa tử đằng. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:19:12.000000');
INSERT INTO `product` VALUES (1114, 'Vòng tay đá quý Wren đính cườm', 1504250, 1504250, 100, 100, 0, 'Vòng tay hạt đá quý wren được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:19:14.000000');
INSERT INTO `product` VALUES (1115, 'Bông tai bạc hình chim ưng được rèn thủ công', 979000, 979000, 100, 100, 0, 'Bông tai bạc sterling được rèn thủ công với họa tiết chim ưng. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:19:16.000000');
INSERT INTO `product` VALUES (1116, 'Bông tai pha lê Osprey có dây', 1507000, 1507000, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn là pha lê chim ưng. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:19:19.000000');
INSERT INTO `product` VALUES (1117, 'Vòng xếp chồng Hawkweed được đóng dấu bằng tay', 670000, 670000, 100, 100, 0, 'Chiếc nhẫn xếp chồng diều hâu được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:19:21.000000');
INSERT INTO `product` VALUES (1118, 'Nhẫn pha lê thô Dogwood', 1647000, 1647000, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê gỗ sơn thù du thô được đặt bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thiện với lớp gỉ gỗ sơn thù du.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:19:23.000000');
INSERT INTO `product` VALUES (1119, 'Nến sáp ong Sweetgrass đổ bằng tay', 392250, 392250, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu cỏ ngọt. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:19:24.000000');
INSERT INTO `product` VALUES (1120, 'Nến thơm Cattail sáp dừa', 675000, 675000, 100, 100, 0, 'Nến thơm đuôi mèo số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:19:27.000000');
INSERT INTO `product` VALUES (1121, 'Treo tường Macramé Bullrush', 1594250, 1594250, 100, 100, 0, 'Bức tường macramé được thắt nút bằng tay phức tạp treo bằng dây bông tự nhiên có màu nâu đỏ. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:19:28.000000');
INSERT INTO `product` VALUES (1122, 'Vòng hoa cói khô', 1389000, 1389000, 100, 100, 0, 'Vòng hoa khô được làm thủ công có các loại thực vật cói theo mùa. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:19:30.000000');
INSERT INTO `product` VALUES (1123, 'Kệ Gỗ Bracken Chạm Khắc Bằng Tay', 2216250, 2216250, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết viền dương xỉ. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:19:31.000000');
INSERT INTO `product` VALUES (1124, 'Thớt quả óc chó sầu riêng cuối hạt', 1610750, 1610750, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó me chua và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:19:33.000000');
INSERT INTO `product` VALUES (1125, 'Bộ bát sứ hoa cúc ném tay', 2255500, 2255500, 100, 100, 0, 'Bộ 4 bát gốm sứ tráng men phản ứng hoa cúc. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:19:35.000000');
INSERT INTO `product` VALUES (1126, 'Mũ len Yarrow Merino dệt kim bằng tay', 795750, 795750, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu yarrow. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:19:37.000000');
INSERT INTO `product` VALUES (1127, 'Móc dây buộc tóc bằng ren Valerian', 306000, 306000, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông nữ lang. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:19:40.000000');
INSERT INTO `product` VALUES (1128, 'Khăn choàng lụa Mugwort nhuộm tay', 3044000, 3044000, 100, 100, 0, 'Khăn choàng lụa nhuộm tay sang trọng họa tiết màu nước ngải cứu. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:19:42.000000');
INSERT INTO `product` VALUES (1129, 'Ly hợp da cây tầm ma khâu tay', 2175250, 2175250, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay bằng cây tầm ma. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:19:44.000000');
INSERT INTO `product` VALUES (1130, 'Ba lô vải cây ngưu bàng sáp', 5084750, 5084750, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da cây ngưu bàng. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:19:47.000000');
INSERT INTO `product` VALUES (1131, 'Tranh sáp bông tuyết nguyên bản', 4481750, 4481750, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng giọt tuyết. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:19:50.000000');
INSERT INTO `product` VALUES (1132, 'Tượng gốm Crocus điêu khắc bằng tay', 1846000, 1846000, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết bằng men nghệ. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:19:52.000000');
INSERT INTO `product` VALUES (1133, 'In ảnh thiên nhiên Trillium mỹ thuật', 1783750, 1783750, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên trillium nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:19:54.000000');
INSERT INTO `product` VALUES (1134, 'Xà phòng thủ công Bloodroot sữa dê', 318500, 318500, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm rễ cây và các tạp chất thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:19:57.000000');
INSERT INTO `product` VALUES (1135, 'Thanh gội đầu Solid Hepatica', 548750, 548750, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược Hepatica. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:19:59.000000');
INSERT INTO `product` VALUES (1136, 'Tẩy tế bào chết toàn thân Sugar Mayapple', 475750, 475750, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường mayapple thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu mayapple. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:20:02.000000');
INSERT INTO `product` VALUES (1137, 'Tạp chí da Elderflower ràng buộc bằng tay', 726250, 726250, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da hoa cơm cháy và dây vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:20:04.000000');
INSERT INTO `product` VALUES (1138, 'Thiệp cưới màu nước táo gai', 175500, 175500, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật táo gai. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:20:06.000000');
INSERT INTO `product` VALUES (1139, 'Câu đố bằng gỗ cây mâm xôi vẽ tay', 816750, 816750, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay cây mận gai. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:20:08.000000');
INSERT INTO `product` VALUES (1140, 'Cây đũa phép đồ chơi mèo Rowan bện bằng tay', 426750, 426750, 100, 100, 0, 'Đồ chơi đũa phép mèo thủ công với dây bông bện thanh lương trà và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:20:11.000000');
INSERT INTO `product` VALUES (1141, 'Vòng cổ mặt dây chuyền đá mặt trăng Sloe thủ công', 987000, 987000, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng sloe chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:20:13.000000');
INSERT INTO `product` VALUES (1142, 'Tên tùy chỉnh Vòng cổ lấp đầy vàng Damson', 2091250, 2091250, 100, 100, 0, 'Vòng cổ tên Damson cá tính được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:20:15.000000');
INSERT INTO `product` VALUES (1143, 'Vòng cổ mặt dây chuyền quả hồng theo phong cách cổ điển', 1704500, 1704500, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng hồng lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:20:18.000000');
INSERT INTO `product` VALUES (1144, 'Vòng tay tình bạn mộc qua dệt tay', 525000, 525000, 100, 100, 0, 'Vòng tay tình bạn mộc qua dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:20:20.000000');
INSERT INTO `product` VALUES (1145, 'Vòng đeo tay bằng đồng Medlar rèn', 1638250, 1638250, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ màu sơn tra. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:20:22.000000');
INSERT INTO `product` VALUES (1146, 'Vòng tay đá quý dâu tằm đính cườm', 1223500, 1223500, 100, 100, 0, 'Vòng tay hạt đá quý dâu tằm được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:20:25.000000');
INSERT INTO `product` VALUES (1147, 'Bông tai bạc hình quả lý gai được rèn thủ công', 1071750, 1071750, 100, 100, 0, 'Bông tai đinh tán bằng bạc được rèn thủ công với kết cấu quả lý gai. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:20:27.000000');
INSERT INTO `product` VALUES (1148, 'Bông tai pha lê hình quả việt quất có dây', 1304250, 1304250, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn là pha lê việt quất. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:20:29.000000');
INSERT INTO `product` VALUES (1149, 'Vòng xếp chồng Crowberry được đóng dấu bằng tay', 772250, 772250, 100, 100, 0, 'Nhẫn xếp chồng quả quạ được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:20:32.000000');
INSERT INTO `product` VALUES (1150, 'Nhẫn pha lê Cloudberry thô', 1284000, 1284000, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê mâm xôi thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với lớp vỏ mây.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:20:34.000000');
INSERT INTO `product` VALUES (1151, 'Nến sáp ong Lingonberry đổ bằng tay', 790500, 790500, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu nam việt quất. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:20:35.000000');
INSERT INTO `product` VALUES (1152, 'Nến thơm Bearberry sáp dừa', 639000, 639000, 100, 100, 0, 'Nến thơm Bearberry số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:20:37.000000');
INSERT INTO `product` VALUES (1153, 'Macramé Hackberry treo tường', 1979750, 1979750, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo được treo bằng dây cotton tự nhiên hackberry. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:20:39.000000');
INSERT INTO `product` VALUES (1154, 'Vòng Hoa Trâu Khô', 1985000, 1985000, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa từ quả trâu. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:20:40.000000');
INSERT INTO `product` VALUES (1155, 'Kệ Gỗ Aurora Chạm Khắc Bằng Tay', 3271000, 3271000, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh cực quang. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:20:41.000000');
INSERT INTO `product` VALUES (1156, 'Thớt quả óc chó Chạng vạng cuối hạt', 1406750, 1406750, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ gỗ óc chó chạng vạng và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:20:43.000000');
INSERT INTO `product` VALUES (1157, 'Bộ bát sứ thạch anh ném tay', 1846250, 1846250, 100, 100, 0, 'Bộ 4 chiếc bát sứ thủ công phủ men phản ứng thạch nam. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:20:45.000000');
INSERT INTO `product` VALUES (1158, 'Mũ len Merino bằng gỗ lũa dệt kim thủ công', 919250, 919250, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu gỗ lũa. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:20:48.000000');
INSERT INTO `product` VALUES (1159, 'Dây buộc tóc ren Riverstone Crochet', 230750, 230750, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren cotton riverstone. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:20:51.000000');
INSERT INTO `product` VALUES (1160, 'Khăn choàng quấn lụa bãi biển Pebble nhuộm tay', 1756500, 1756500, 100, 100, 0, 'Khăn choàng lụa nhuộm tay sang trọng họa tiết màu nước bãi biển sỏi. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:20:53.000000');
INSERT INTO `product` VALUES (1161, 'Ly hợp da Foxglove khâu tay', 2247250, 2247250, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay hình mao địa hoàng. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:20:56.000000');
INSERT INTO `product` VALUES (1162, 'Ba lô Blackberry vải sáp', 3677000, 3677000, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da blackberry. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:20:58.000000');
INSERT INTO `product` VALUES (1163, 'Tranh sáp quế nguyên chất', 4980250, 4980250, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với thành phần trừu tượng quế. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:21:00.000000');
INSERT INTO `product` VALUES (1164, 'Tượng gốm thảo quả điêu khắc bằng tay', 1385000, 1385000, 100, 100, 0, 'Tượng gốm bằng đá được điêu khắc thủ công với các chi tiết tráng men bạch đậu khấu. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:21:03.000000');
INSERT INTO `product` VALUES (1165, 'In ảnh nghệ thuật cỏ ba lá thiên nhiên', 1570750, 1570750, 100, 100, 0, 'Lưu trữ bản in mỹ thuật của bức ảnh thiên nhiên cỏ ba lá nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:21:06.000000');
INSERT INTO `product` VALUES (1166, 'Xà phòng thủ công cây kế sữa dê', 415750, 415750, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm cây kế và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:21:08.000000');
INSERT INTO `product` VALUES (1167, 'Thanh gội đầu rắn Wisteria', 575000, 575000, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược hoa tử đằng. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:21:11.000000');
INSERT INTO `product` VALUES (1168, 'Sugar Wren Tẩy Tế Bào Chết Toàn Thân', 265250, 265250, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường wren thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu chim hồng tước. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:21:14.000000');
INSERT INTO `product` VALUES (1169, 'Tạp chí da chim ưng ràng buộc bằng tay', 1873750, 1873750, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da chim ưng và dây vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:21:16.000000');
INSERT INTO `product` VALUES (1170, 'Thiệp cưới màu nước Osprey', 342750, 342750, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật chim ưng biển. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:21:18.000000');
INSERT INTO `product` VALUES (1171, 'Câu đố bằng gỗ Hawkweed vẽ tay', 1101250, 1101250, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay hawkweed. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:21:20.000000');
INSERT INTO `product` VALUES (1172, 'Đũa phép đồ chơi cho mèo Dogwood bện bằng tay', 383000, 383000, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây bông bện bằng gỗ cây chó đẻ và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:21:23.000000');
INSERT INTO `product` VALUES (1173, 'Vòng cổ mặt dây chuyền đá mặt trăng Sweetgrass thủ công', 2219250, 2219250, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng sweetgrass chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:21:25.000000');
INSERT INTO `product` VALUES (1174, 'Tên tùy chỉnh Vòng cổ lấp đầy vàng Cattail', 1470250, 1470250, 100, 100, 0, 'Vòng cổ tên cattail cá tính được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:21:27.000000');
INSERT INTO `product` VALUES (1175, 'Vòng cổ Mề đay Bullrush theo phong cách cổ điển', 2845500, 2845500, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:21:30.000000');
INSERT INTO `product` VALUES (1176, 'Vòng tay tình bạn cói dệt tay', 431500, 431500, 100, 100, 0, 'Vòng tay tình bạn cói dệt thủ công bằng sợi cotton sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:21:32.000000');
INSERT INTO `product` VALUES (1177, 'Vòng đeo tay bằng đồng Bracken rèn', 1573500, 1573500, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ màu dương xỉ. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:21:34.000000');
INSERT INTO `product` VALUES (1178, 'Vòng tay đá quý đính cườm', 1317500, 1317500, 100, 100, 0, 'Vòng tay hạt đá quý màu me chua được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:21:36.000000');
INSERT INTO `product` VALUES (1179, 'Bông tai bạc hoa cúc được rèn thủ công', 847500, 847500, 100, 100, 0, 'Bông tai bạc sterling được rèn thủ công với họa tiết hoa cúc. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:21:38.000000');
INSERT INTO `product` VALUES (1180, 'Bông tai Hoop pha lê Yarrow có dây', 715500, 715500, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê yarrow. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:21:40.000000');
INSERT INTO `product` VALUES (1181, 'Vòng xếp chồng Valerian được đóng dấu bằng tay', 537500, 537500, 100, 100, 0, 'Chiếc nhẫn xếp chồng nữ lang được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:21:43.000000');
INSERT INTO `product` VALUES (1182, 'Vòng tuyên bố Mugwort pha lê thô', 1496500, 1496500, 100, 100, 0, 'Chiếc nhẫn nổi bật có pha lê ngải cứu thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với lớp vỏ ngải cứu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:21:47.000000');
INSERT INTO `product` VALUES (1183, 'Nến sáp ong cây tầm ma đổ bằng tay', 513500, 513500, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay với hỗn hợp tinh dầu cây tầm ma. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:21:48.000000');
INSERT INTO `product` VALUES (1184, 'Nến thơm sáp dừa cây ngưu bàng', 485250, 485250, 100, 100, 0, 'Nến thơm cây ngưu bàng số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:21:50.000000');
INSERT INTO `product` VALUES (1185, 'Treo tường hình giọt nước Macramé', 1636500, 1636500, 100, 100, 0, 'Bức tường macramé được thắt nút bằng tay phức tạp treo trên sợi dây bông tự nhiên hình giọt tuyết. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:21:52.000000');
INSERT INTO `product` VALUES (1186, 'Vòng hoa nghệ tây khô', 1534250, 1534250, 100, 100, 0, 'Vòng hoa khô thủ công có hình hoa nghệ tây theo mùa. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:21:54.000000');
INSERT INTO `product` VALUES (1187, 'Kệ Gỗ Trillium Chạm Khắc Bằng Tay', 2792250, 2792250, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết viền trillium. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:21:56.000000');
INSERT INTO `product` VALUES (1188, 'Thớt cắt quả óc chó Bloodroot cuối hạt', 3657250, 3657250, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:21:58.000000');
INSERT INTO `product` VALUES (1189, 'Bộ bát sứ Hepatica ném tay', 1269500, 1269500, 100, 100, 0, 'Bộ 4 bát gốm sứ tráng men phản ứng Hepatica. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:21:59.000000');
INSERT INTO `product` VALUES (1190, 'Mũ len Mayapple Merino dệt kim bằng tay', 1237500, 1237500, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu mayapple. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:22:01.000000');
INSERT INTO `product` VALUES (1191, 'Dây buộc tóc ren hoa cơm cháy', 176250, 176250, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông hoa cơm cháy. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:22:04.000000');
INSERT INTO `product` VALUES (1192, 'Khăn choàng lụa Hawthorn nhuộm tay', 3031500, 3031500, 100, 100, 0, 'Khăn choàng lụa quấn tay sang trọng họa tiết màu nước táo gai. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:22:06.000000');
INSERT INTO `product` VALUES (1193, 'Ly hợp da Blackthorn khâu tay', 1639500, 1639500, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay bằng cây gai đen. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:22:09.000000');
INSERT INTO `product` VALUES (1194, 'Ba lô vải Rowan sáp', 4540000, 4540000, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da thanh lương trà. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:22:12.000000');
INSERT INTO `product` VALUES (1195, 'Tranh sáp nguyên bản Sloe', 4179000, 4179000, 100, 100, 0, 'Bức tranh sơn dầu nguyên bản (sáp nóng) với bố cục trừu tượng sloe. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:22:14.000000');
INSERT INTO `product` VALUES (1196, 'Tượng gốm Damson điêu khắc bằng tay', 940500, 940500, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết tráng men Damson. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:22:16.000000');
INSERT INTO `product` VALUES (1197, 'Tranh In Tranh Thiên Nhiên Quả Hồng Mỹ Nghệ', 1162500, 1162500, 100, 100, 0, 'Lưu trữ bản in mỹ thuật của bức ảnh thiên nhiên quả hồng gốc. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:22:19.000000');
INSERT INTO `product` VALUES (1198, 'Xà phòng nghệ mộc mộc qua sữa dê', 321750, 321750, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm mộc qua và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:22:21.000000');
INSERT INTO `product` VALUES (1199, 'Thanh dầu gội rắn Medlar', 492000, 492000, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược sơn tra. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:22:23.000000');
INSERT INTO `product` VALUES (1200, 'Tẩy tế bào chết toàn thân dâu tằm đường', 744750, 744750, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường dâu tằm thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu dâu tằm. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:22:25.000000');
INSERT INTO `product` VALUES (1201, 'Tạp chí da ngỗng ràng buộc bằng tay', 2123250, 2123250, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da quả lý gai và dây vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:22:27.000000');
INSERT INTO `product` VALUES (1202, 'Thiệp cưới màu nước việt quất', 343250, 343250, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật việt quất. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:22:30.000000');
INSERT INTO `product` VALUES (1203, 'Câu đố bằng gỗ Crowberry vẽ tay', 612750, 612750, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay bằng quả quạ. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:22:32.000000');
INSERT INTO `product` VALUES (1204, 'Đũa phép đồ chơi cho mèo Cloudberry bện bằng tay', 385000, 385000, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây bông bện hình quả mâm xôi và phần gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:22:34.000000');
INSERT INTO `product` VALUES (1205, 'Vòng cổ mặt dây chuyền đá mặt trăng Lingonberry thủ công', 1357250, 1357250, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng lingonberry chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:22:36.000000');
INSERT INTO `product` VALUES (1206, 'Tên tùy chỉnh Vòng cổ Bearberry Gold-Fill', 2402750, 2402750, 100, 100, 0, 'Vòng cổ tên Bearberry cá tính được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:22:38.000000');
INSERT INTO `product` VALUES (1207, 'Vòng cổ Hackberry Locket theo phong cách cổ điển', 1571500, 1571500, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau hackberry lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:22:40.000000');
INSERT INTO `product` VALUES (1208, 'Vòng tay tình bạn Buffaloberry dệt tay', 658500, 658500, 100, 100, 0, 'Vòng tay tình bạn trâu rừng dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:22:43.000000');
INSERT INTO `product` VALUES (1209, 'Vòng đeo tay bằng đồng Aurora được rèn', 713750, 713750, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp sơn aurora. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:22:45.000000');
INSERT INTO `product` VALUES (1210, 'Vòng tay đá quý Chạng vạng đính cườm', 617750, 617750, 100, 100, 0, 'Vòng tay hạt đá quý chạng vạng được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:22:47.000000');
INSERT INTO `product` VALUES (1211, 'Bông tai bạc thạch anh rèn thủ công', 632500, 632500, 100, 100, 0, 'Bông tai đinh tán bằng bạc được rèn thủ công với kết cấu thạch nam. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:22:49.000000');
INSERT INTO `product` VALUES (1212, 'Bông tai pha lê bằng gỗ lũa có dây', 977500, 977500, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê bằng gỗ lũa. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:22:52.000000');
INSERT INTO `product` VALUES (1213, 'Vòng xếp chồng Riverstone được đóng dấu bằng tay', 966750, 966750, 100, 100, 0, 'Chiếc nhẫn xếp chồng bằng đá ven sông được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:22:54.000000');
INSERT INTO `product` VALUES (1214, 'Nhẫn tuyên bố bãi biển Pebble pha lê thô', 1150750, 1150750, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê bãi biển đá cuội thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thiện với lớp gỉ trên bãi biển sỏi.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:22:56.000000');
INSERT INTO `product` VALUES (1215, 'Nến sáp ong Foxglove đổ bằng tay', 668250, 668250, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu mao địa hoàng. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:22:58.000000');
INSERT INTO `product` VALUES (1216, 'Nến thơm Blackberry sáp dừa', 948500, 948500, 100, 100, 0, 'Nến thơm dâu đen số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:22:59.000000');
INSERT INTO `product` VALUES (1217, 'Macramé Quế Treo Tường', 1195500, 1195500, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo treo trên dây bông quế tự nhiên. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:23:01.000000');
INSERT INTO `product` VALUES (1218, 'Vòng hoa bạch đậu khấu khô', 1562000, 1562000, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa bạch đậu khấu. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:23:03.000000');
INSERT INTO `product` VALUES (1219, 'Kệ Gỗ Cỏ Ba Lá Chạm Khắc Bằng Tay', 2957000, 2957000, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc bằng tay với chi tiết cạnh hình cỏ ba lá. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:23:05.000000');
INSERT INTO `product` VALUES (1220, 'Thớt quả óc chó kế cuối hạt', 3629250, 3629250, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ cây kế và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:23:06.000000');
INSERT INTO `product` VALUES (1221, 'Bộ bát gốm hoa tử đằng ném tay', 1308000, 1308000, 100, 100, 0, 'Bộ 4 chiếc bát gốm sứ tráng men phản ứng hoa tử đằng. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:23:08.000000');
INSERT INTO `product` VALUES (1222, 'Mũ len Wren Merino dệt kim bằng tay', 975500, 975500, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ 100% len merino superwash với màu sắc màu hồng tước. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:23:11.000000');
INSERT INTO `product` VALUES (1223, 'Dây buộc tóc bằng ren Crochet Falcon', 343750, 343750, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông chim ưng. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:23:13.000000');
INSERT INTO `product` VALUES (1224, 'Khăn choàng lụa Osprey nhuộm tay', 1774750, 1774750, 100, 100, 0, 'Khăn choàng quấn lụa nhuộm tay sang trọng họa tiết màu nước chim ưng. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:23:16.000000');
INSERT INTO `product` VALUES (1225, 'Ly hợp da Hawkweed khâu tay', 1151250, 1151250, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay hawkweed. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:23:18.000000');
INSERT INTO `product` VALUES (1226, 'Ba lô vải Dogwood bằng vải sáp', 4805000, 4805000, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da bằng gỗ chó. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:23:21.000000');
INSERT INTO `product` VALUES (1227, 'Tranh sáp nghệ thuật Sweetgrass nguyên bản', 2338500, 2338500, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng cỏ ngọt. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:23:24.000000');
INSERT INTO `product` VALUES (1228, 'Tượng gốm Cattail điêu khắc bằng tay', 1583250, 1583250, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết tráng men đuôi mèo. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:23:26.000000');
INSERT INTO `product` VALUES (1229, 'Mỹ thuật Bullrush In ảnh thiên nhiên', 937250, 937250, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên bò tót nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:23:29.000000');
INSERT INTO `product` VALUES (1230, 'Xà Phòng Nghệ Nhân Cói Sữa Dê', 316500, 316500, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm cói và tạp chất thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:23:31.000000');
INSERT INTO `product` VALUES (1231, 'Thanh gội đầu rắn Bracken', 541500, 541500, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược dương xỉ. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:23:33.000000');
INSERT INTO `product` VALUES (1232, 'Tẩy tế bào chết toàn thân Sugar Sorrel', 679500, 679500, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường cây me chua thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu cây me chua. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:23:35.000000');
INSERT INTO `product` VALUES (1233, 'Tạp chí da hoa cúc đóng tay', 1724500, 1724500, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da hoa cúc và chỉ khâu bằng vải lanh. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:23:37.000000');
INSERT INTO `product` VALUES (1234, 'Thiệp cưới màu nước Yarrow', 315000, 315000, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật cỏ thi. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:23:41.000000');
INSERT INTO `product` VALUES (1235, 'Câu đố bằng gỗ Valerian vẽ tay', 1485250, 1485250, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay cây nữ lang. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:23:43.000000');
INSERT INTO `product` VALUES (1236, 'Đũa đồ chơi cho mèo Mugwort bện bằng tay', 468750, 468750, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây bông bện ngải cứu và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:23:45.000000');
INSERT INTO `product` VALUES (1237, 'Vòng cổ mặt dây chuyền đá mặt trăng cây tầm ma thủ công', 812750, 812750, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng cây tầm ma chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:23:48.000000');
INSERT INTO `product` VALUES (1238, 'Tên tùy chỉnh Vòng cổ Burdock Gold-Fill', 1958250, 1958250, 100, 100, 0, 'Vòng cổ tên ngưu bàng được cá nhân hóa được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:23:50.000000');
INSERT INTO `product` VALUES (1239, 'Vòng cổ hình giọt nước phong cách cổ điển', 1369250, 1369250, 100, 100, 0, 'Vòng cổ mặt dây chuyền hình giọt nước bằng đồng thau lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:23:53.000000');
INSERT INTO `product` VALUES (1240, 'Vòng tay tình bạn Crocus dệt tay', 650750, 650750, 100, 100, 0, 'Vòng tay tình bạn nghệ tây dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:23:55.000000');
INSERT INTO `product` VALUES (1241, 'Vòng đeo tay bằng đồng Trillium rèn', 1464750, 1464750, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ trillium. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:23:58.000000');
INSERT INTO `product` VALUES (1242, 'Vòng tay đá quý Bloodroot đính cườm', 1401250, 1401250, 100, 100, 0, 'Vòng tay hạt đá quý rễ cây máu được xâu chuỗi bằng dây co giãn bền bỉ. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:24:01.000000');
INSERT INTO `product` VALUES (1243, 'Bông tai bạc Hepatica được rèn thủ công', 920500, 920500, 100, 100, 0, 'Bông tai đinh tán bằng bạc sterling được rèn thủ công với kết cấu Hepatica. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:24:03.000000');
INSERT INTO `product` VALUES (1244, 'Bông tai pha lê Mayapple bọc dây', 1051250, 1051250, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê mayapple. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:24:06.000000');
INSERT INTO `product` VALUES (1245, 'Vòng xếp chồng hoa cơm cháy được đóng dấu bằng tay', 569750, 569750, 100, 100, 0, 'Nhẫn xếp hình hoa cơm cháy được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:24:08.000000');
INSERT INTO `product` VALUES (1246, 'Nhẫn pha lê thô Hawthorn', 1913250, 1913250, 100, 100, 0, 'Chiếc nhẫn nổi bật có pha lê táo gai thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với patina táo gai.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:24:10.000000');
INSERT INTO `product` VALUES (1247, 'Nến sáp ong Blackthorn đổ bằng tay', 876750, 876750, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu mận gai. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:24:13.000000');
INSERT INTO `product` VALUES (1248, 'Nến thơm sáp dừa Rowan', 453750, 453750, 100, 100, 0, 'Nến thơm thanh lương trà số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:24:14.000000');
INSERT INTO `product` VALUES (1249, 'Treo tường Macramé Sloe', 1148750, 1148750, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo treo bằng dây cotton tự nhiên. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:24:16.000000');
INSERT INTO `product` VALUES (1250, 'Vòng hoa khô Damson', 1777750, 1777750, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa của Damson. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:24:17.000000');
INSERT INTO `product` VALUES (1251, 'Kệ gỗ hồng chạm khắc thủ công', 1948500, 1948500, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh quả hồng. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:24:21.000000');
INSERT INTO `product` VALUES (1252, 'Thớt quả óc chó mộc qua cuối hạt', 3037500, 3037500, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó mộc qua và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:24:23.000000');
INSERT INTO `product` VALUES (1253, 'Bộ bát sứ Medlar ném tay', 2459750, 2459750, 100, 100, 0, 'Bộ 4 bát gốm sứ tráng men phản ứng sơn tra. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:24:25.000000');
INSERT INTO `product` VALUES (1254, 'Mũ len Merino dâu tằm dệt tay', 1052500, 1052500, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ 100% len merino superwash với màu dâu tằm. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:24:28.000000');
INSERT INTO `product` VALUES (1255, 'Dây buộc tóc bằng ren quả dâu tằm', 181750, 181750, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông quả lý gai. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:24:31.000000');
INSERT INTO `product` VALUES (1256, 'Khăn choàng lụa việt quất nhuộm tay', 2952250, 2952250, 100, 100, 0, 'Khăn choàng quấn lụa nhuộm tay sang trọng họa tiết màu nước việt quất. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:24:33.000000');
INSERT INTO `product` VALUES (1257, 'Ly hợp da Crowberry khâu tay', 3270750, 3270750, 100, 100, 0, 'Ví cầm tay bằng da có chi tiết khâu tay hình quả dâu tây. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:24:36.000000');
INSERT INTO `product` VALUES (1258, 'Ba lô mây vải sáp', 3685500, 3685500, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da màu mây. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:24:38.000000');
INSERT INTO `product` VALUES (1259, 'Tranh sáp sơn gốc Lingonberry nguyên bản', 2458250, 2458250, 100, 100, 0, 'Bức tranh sơn dầu nguyên bản (sáp nóng) với bố cục trừu tượng của quả nam việt quất. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:24:40.000000');
INSERT INTO `product` VALUES (1260, 'Tượng gốm Bearberry điêu khắc bằng tay', 971000, 971000, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết tráng men dâu tây. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:24:43.000000');
INSERT INTO `product` VALUES (1261, 'Mỹ Thuật Hackberry In Ảnh Thiên Nhiên', 1825250, 1825250, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên hackberry gốc. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:24:45.000000');
INSERT INTO `product` VALUES (1262, 'Xà Phòng Thủ Công Buffaloberry Sữa Dê', 398250, 398250, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm dâu rừng và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:24:48.000000');
INSERT INTO `product` VALUES (1263, 'Thanh gội đầu Solid Aurora', 347250, 347250, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược aurora. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:24:50.000000');
INSERT INTO `product` VALUES (1264, 'Tẩy tế bào chết Sugar Twilight', 530250, 530250, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường chạng vạng thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu chạng vạng. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:24:52.000000');
INSERT INTO `product` VALUES (1265, 'Tạp chí da Heather ràng buộc bằng tay', 1959250, 1959250, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa bằng da thạch nam và dây vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:24:55.000000');
INSERT INTO `product` VALUES (1266, 'Thiệp cưới lũa màu nước', 221750, 221750, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật bằng gỗ lũa. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:24:57.000000');
INSERT INTO `product` VALUES (1267, 'Câu đố bằng gỗ Riverstone vẽ tay', 779250, 779250, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay bằng đá riverstone. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:24:59.000000');
INSERT INTO `product` VALUES (1268, 'Đũa phép đồ chơi cho mèo Pebble Beach bện bằng tay', 491500, 491500, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây bông bện trên bãi biển và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:25:02.000000');
INSERT INTO `product` VALUES (1269, 'Vòng cổ mặt dây chuyền đá mặt trăng Foxglove được làm thủ công', 1686750, 1686750, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng hình găng tay cáo chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:25:04.000000');
INSERT INTO `product` VALUES (1270, 'Tên tùy chỉnh Vòng cổ Blackberry Gold-Fill', 1795000, 1795000, 100, 100, 0, 'Vòng cổ tên blackberry cá tính được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:25:07.000000');
INSERT INTO `product` VALUES (1271, 'Vòng cổ mặt dây chuyền quế phong cách cổ điển', 1420750, 1420750, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng quế lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:25:09.000000');
INSERT INTO `product` VALUES (1272, 'Vòng tay tình bạn bạch đậu khấu dệt tay', 521250, 521250, 100, 100, 0, 'Vòng tay tình bạn bạch đậu khấu dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:25:11.000000');
INSERT INTO `product` VALUES (1273, 'Vòng đeo tay bằng đồng rèn cỏ ba lá', 1200750, 1200750, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ hình cỏ ba lá. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:25:13.000000');
INSERT INTO `product` VALUES (1274, 'Vòng tay đá quý Thistle đính cườm', 766500, 766500, 100, 100, 0, 'Vòng tay hạt đá quý cây kế được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:25:15.000000');
INSERT INTO `product` VALUES (1275, 'Bông tai bạc Wisteria được rèn thủ công', 1374500, 1374500, 100, 100, 0, 'Bông tai đinh tán bằng bạc được rèn thủ công với họa tiết hoa tử đằng. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:25:18.000000');
INSERT INTO `product` VALUES (1276, 'Bông tai pha lê Wren có dây', 1167000, 1167000, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê hình chim hồng tước. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:25:20.000000');
INSERT INTO `product` VALUES (1277, 'Vòng xếp chim ưng được đóng dấu bằng tay', 819250, 819250, 100, 100, 0, 'Nhẫn xếp hình chim ưng được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:25:23.000000');
INSERT INTO `product` VALUES (1278, 'Nhẫn pha lê thô Osprey', 1451750, 1451750, 100, 100, 0, 'Chiếc nhẫn nổi bật có pha lê osprey thô bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với patina chim ưng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:25:25.000000');
INSERT INTO `product` VALUES (1279, 'Nến sáp ong Hawkweed đổ bằng tay', 405000, 405000, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu diều hâu. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:25:26.000000');
INSERT INTO `product` VALUES (1280, 'Nến thơm sáp dừa Dogwood', 377750, 377750, 100, 100, 0, 'Nến thơm gỗ cây sơn thùa số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:25:28.000000');
INSERT INTO `product` VALUES (1281, 'Macramé Sweetgrass treo tường', 3184000, 3184000, 100, 100, 0, 'Bức tường macramé thắt nút thủ công phức tạp treo trên dây bông tự nhiên cỏ ngọt. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:25:30.000000');
INSERT INTO `product` VALUES (1282, 'Vòng hoa đuôi mèo khô', 1348500, 1348500, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa ở đuôi mèo. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:25:31.000000');
INSERT INTO `product` VALUES (1283, 'Kệ gỗ Bullrush chạm khắc bằng tay', 2411750, 2411750, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh bằng gỗ óc chó. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:25:33.000000');
INSERT INTO `product` VALUES (1284, 'Thớt óc chó cói cuối hạt', 2053000, 2053000, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ gỗ óc chó cói và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:25:35.000000');
INSERT INTO `product` VALUES (1285, 'Bộ bát sứ Bracken ném tay', 2409000, 2409000, 100, 100, 0, 'Bộ 4 chiếc bát sứ thủ công phủ men phản ứng dương xỉ. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:25:36.000000');
INSERT INTO `product` VALUES (1286, 'Mũ len merino merino dệt kim bằng tay', 1407250, 1407250, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu màu nâu đất. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:25:38.000000');
INSERT INTO `product` VALUES (1287, 'Dây buộc tóc ren hoa cúc móc', 265000, 265000, 100, 100, 0, 'Dây buộc tóc móc thủ công có họa tiết ren bông hoa cúc. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:25:41.000000');
INSERT INTO `product` VALUES (1288, 'Khăn choàng quấn lụa Yarrow nhuộm tay', 2767750, 2767750, 100, 100, 0, 'Khăn choàng quấn lụa nhuộm tay sang trọng họa tiết màu nước cỏ thi. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:25:43.000000');
INSERT INTO `product` VALUES (1289, 'Ly hợp da Valerian khâu tay', 1594500, 1594500, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay nữ lang. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:25:45.000000');
INSERT INTO `product` VALUES (1290, 'Ba lô vải bạt Mugwort', 4163750, 4163750, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da ngải cứu. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:25:48.000000');
INSERT INTO `product` VALUES (1291, 'Tranh sáp cây tầm ma nguyên bản', 3283750, 3283750, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng từ cây tầm ma. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:25:50.000000');
INSERT INTO `product` VALUES (1292, 'Tượng gốm ngưu bàng điêu khắc bằng tay', 2031000, 2031000, 100, 100, 0, 'Tượng gốm bằng đá được điêu khắc thủ công với các chi tiết tráng men ngưu bàng. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:25:52.000000');
INSERT INTO `product` VALUES (1293, 'In ảnh thiên nhiên giọt nước tuyết mỹ thuật', 1685750, 1685750, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên giọt tuyết nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:25:55.000000');
INSERT INTO `product` VALUES (1294, 'Xà Phòng Nghệ Nghệ Crocus Sữa Dê', 175250, 175250, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm hoa nghệ tây và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:25:57.000000');
INSERT INTO `product` VALUES (1295, 'Thanh gội đầu Trillium rắn', 445750, 445750, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo mộc trillium. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:25:59.000000');
INSERT INTO `product` VALUES (1296, 'Tẩy tế bào chết toàn thân Sugar Bloodroot', 436500, 436500, 100, 100, 0, 'Tẩy tế bào chết bằng đường huyết thủ công với gốc dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu rễ huyết. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:26:02.000000');
INSERT INTO `product` VALUES (1297, 'Tạp chí da Hepatica đóng bìa tay', 1061250, 1061250, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da Hepatica và dây buộc bằng chỉ khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:26:04.000000');
INSERT INTO `product` VALUES (1298, 'Thiệp cưới Mayapple màu nước', 179000, 179000, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật mayapple. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:26:06.000000');
INSERT INTO `product` VALUES (1299, 'Câu đố bằng gỗ hoa cơm cháy vẽ tay', 877250, 877250, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay hoa cơm cháy. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:26:09.000000');
INSERT INTO `product` VALUES (1300, 'Cây đũa phép đồ chơi cho mèo Hawthorn bện bằng tay', 231750, 231750, 100, 100, 0, 'Đồ chơi đũa phép mèo thủ công với dây bông bện táo gai và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:26:11.000000');
INSERT INTO `product` VALUES (1301, 'Vòng cổ mặt dây chuyền đá mặt trăng Blackthorn thủ công', 916000, 916000, 100, 100, 0, 'Vòng cổ có mặt dây chuyền thủ công tinh tế đính đá mặt trăng gai đen chính hãng được đặt bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:26:13.000000');
INSERT INTO `product` VALUES (1302, 'Tên tùy chỉnh Vòng cổ Rowan Gold-Fill', 971750, 971750, 100, 100, 0, 'Vòng cổ tên thanh lương trà được cá nhân hóa được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:26:16.000000');
INSERT INTO `product` VALUES (1303, 'Vòng cổ Mề đay Sloe theo phong cách cổ điển', 1735000, 1735000, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:26:19.000000');
INSERT INTO `product` VALUES (1304, 'Vòng tay tình bạn Damson dệt tay', 662750, 662750, 100, 100, 0, 'Vòng tay tình bạn Damson dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:26:21.000000');
INSERT INTO `product` VALUES (1305, 'Vòng đeo tay bằng đồng hình quả hồng rèn', 957250, 957250, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ màu hồng. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:26:23.000000');
INSERT INTO `product` VALUES (1306, 'Vòng tay đá quý mộc qua đính cườm', 1443000, 1443000, 100, 100, 0, 'Vòng tay hạt đá quý mộc qua được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:26:26.000000');
INSERT INTO `product` VALUES (1307, 'Bông tai bạc Medlar được rèn bằng tay', 556750, 556750, 100, 100, 0, 'Bông tai đinh tán bằng bạc sterling được rèn thủ công với kết cấu màu sơn tra. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:26:28.000000');
INSERT INTO `product` VALUES (1308, 'Bông tai pha lê dâu tằm có dây', 1480000, 1480000, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê dâu tằm. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:26:30.000000');
INSERT INTO `product` VALUES (1309, 'Vòng xếp chồng ngỗng được đóng dấu bằng tay', 1086500, 1086500, 100, 100, 0, 'Nhẫn xếp chồng quả lý gai được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:26:33.000000');
INSERT INTO `product` VALUES (1310, 'Nhẫn tuyên bố quả việt quất pha lê thô', 913250, 913250, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê việt quất thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với patina cây nham lê.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:26:35.000000');
INSERT INTO `product` VALUES (1311, 'Nến sáp ong Crowberry đổ bằng tay', 679750, 679750, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ thủ công với hỗn hợp tinh dầu quả quạ. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:26:36.000000');
INSERT INTO `product` VALUES (1312, 'Nến thơm sáp dừa Cloudberry', 858250, 858250, 100, 100, 0, 'Nến thơm mâm xôi số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:26:38.000000');
INSERT INTO `product` VALUES (1313, 'Macramé Lingonberry treo tường', 958000, 958000, 100, 100, 0, 'Bức tường macramé thắt nút thủ công phức tạp treo bằng dây bông tự nhiên lingonberry. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:26:39.000000');
INSERT INTO `product` VALUES (1314, 'Vòng hoa Bearberry khô', 916500, 916500, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa dâu tây. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:26:41.000000');
INSERT INTO `product` VALUES (1315, 'Kệ Gỗ Hackberry Chạm Khắc Bằng Tay', 2364250, 2364250, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh hackberry. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:26:43.000000');
INSERT INTO `product` VALUES (1316, 'Thớt quả óc chó Buffaloberry cuối hạt', 2183750, 2183750, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó trâu và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:26:45.000000');
INSERT INTO `product` VALUES (1317, 'Bộ bát sứ Aurora ném tay', 1960750, 1960750, 100, 100, 0, 'Bộ 4 bát gốm sứ tráng men phản ứng aurora. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:26:47.000000');
INSERT INTO `product` VALUES (1318, 'Mũ len Merino Chạng vạng dệt kim bằng tay', 1166750, 1166750, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ 100% len merino siêu giặt với màu chạng vạng. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:26:49.000000');
INSERT INTO `product` VALUES (1319, 'Dây buộc tóc bằng ren đan móc Heather', 383500, 383500, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông thạch nam. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:26:51.000000');
INSERT INTO `product` VALUES (1320, 'Khăn lụa quấn gỗ lũa nhuộm tay', 2149750, 2149750, 100, 100, 0, 'Khăn choàng lụa nhuộm tay sang trọng họa tiết màu nước bằng gỗ lũa. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:26:54.000000');
INSERT INTO `product` VALUES (1321, 'Ly hợp da Riverstone khâu tay', 3122000, 3122000, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay bằng đá riverstone. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:26:56.000000');
INSERT INTO `product` VALUES (1322, 'Ba lô vải sáp Pebble Beach', 3049500, 3049500, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền bằng da cuội đi biển. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:26:59.000000');
INSERT INTO `product` VALUES (1323, 'Tranh sáp nguyên bản Foxglove', 5211750, 5211750, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng bao tay cáo. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:27:01.000000');
INSERT INTO `product` VALUES (1324, 'Tượng gốm Blackberry điêu khắc bằng tay', 2195250, 2195250, 100, 100, 0, 'Tượng gốm bằng đá được điêu khắc bằng tay với các chi tiết tráng men dâu đen. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:27:03.000000');
INSERT INTO `product` VALUES (1325, 'In Ảnh Nghệ Thuật Quế Thiên Nhiên', 602500, 602500, 100, 100, 0, 'Lưu trữ bản in mỹ thuật của bức ảnh thiên nhiên quế nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:27:05.000000');
INSERT INTO `product` VALUES (1326, 'Xà phòng thủ công bạch đậu khấu sữa dê', 483500, 483500, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm bạch đậu khấu và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:27:07.000000');
INSERT INTO `product` VALUES (1327, 'Thanh gội đầu Solid Clover', 225750, 225750, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược cỏ ba lá. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:27:09.000000');
INSERT INTO `product` VALUES (1328, 'Tẩy tế bào chết toàn thân Sugar Thistle', 295000, 295000, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường cây kế thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu cây kế. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:27:12.000000');
INSERT INTO `product` VALUES (1329, 'Tạp chí da Wisteria ràng buộc bằng tay', 1567750, 1567750, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da hoa đậu tía và dây vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:27:15.000000');
INSERT INTO `product` VALUES (1330, 'Thiệp cưới Wren màu nước', 261250, 261250, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật chim hồng tước. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:27:17.000000');
INSERT INTO `product` VALUES (1331, 'Câu đố bằng gỗ chim ưng vẽ tay', 1536000, 1536000, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay chim ưng. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:27:20.000000');
INSERT INTO `product` VALUES (1332, 'Đũa đồ chơi cho mèo Osprey bện tay', 432000, 432000, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây bông bện chim ưng và phần đính kèm lông tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:27:22.000000');
INSERT INTO `product` VALUES (1333, 'Vòng cổ mặt dây chuyền đá mặt trăng Hawkweed được làm thủ công', 1005250, 1005250, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng hawkweed chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:27:25.000000');
INSERT INTO `product` VALUES (1334, 'Tên tùy chỉnh Vòng cổ mạ vàng Dogwood', 1888250, 1888250, 100, 100, 0, 'Vòng cổ tên bằng gỗ chó được cá nhân hóa được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:27:27.000000');
INSERT INTO `product` VALUES (1335, 'Vòng cổ Sweetgrass Locket theo phong cách cổ điển', 3176500, 3176500, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau Sweetgrass lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:27:29.000000');
INSERT INTO `product` VALUES (1336, 'Vòng tay tình bạn Cattail dệt tay', 610750, 610750, 100, 100, 0, 'Vòng tay tình bạn đuôi mèo dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:27:31.000000');
INSERT INTO `product` VALUES (1337, 'Vòng đeo tay bằng đồng rèn Bullrush', 1407500, 1407500, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ màu bullrush. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:27:33.000000');
INSERT INTO `product` VALUES (1338, 'Vòng tay đá quý cói đính cườm', 743500, 743500, 100, 100, 0, 'Vòng tay hạt đá quý cói được xâu chuỗi trên dây co giãn bền chắc. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:27:35.000000');
INSERT INTO `product` VALUES (1339, 'Bông tai bạc Bracken được rèn thủ công', 816500, 816500, 100, 100, 0, 'Bông tai đinh tán bằng bạc được rèn thủ công với kết cấu dương xỉ. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:27:37.000000');
INSERT INTO `product` VALUES (1340, 'Bông tai pha lê hình cây me chua có dây', 1299000, 1299000, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn là pha lê màu me chua. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:27:39.000000');
INSERT INTO `product` VALUES (1341, 'Vòng xếp chồng hoa cúc được đóng dấu bằng tay', 403250, 403250, 100, 100, 0, 'Nhẫn xếp hình hoa cúc được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:27:41.000000');
INSERT INTO `product` VALUES (1342, 'Nhẫn tuyên bố pha lê thô Yarrow', 1178250, 1178250, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê yarrow thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với patina yarrow.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:27:44.000000');
INSERT INTO `product` VALUES (1343, 'Nến sáp ong Valerian đổ bằng tay', 591250, 591250, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ thủ công với hỗn hợp tinh dầu cây nữ lang. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:27:45.000000');
INSERT INTO `product` VALUES (1344, 'Nến thơm ngải cứu sáp dừa', 618000, 618000, 100, 100, 0, 'Nến thơm ngải cứu số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:27:47.000000');
INSERT INTO `product` VALUES (1345, 'Cây tầm ma treo tường Macramé', 2920750, 2920750, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo được treo bằng dây bông tự nhiên hình cây tầm ma. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:27:48.000000');
INSERT INTO `product` VALUES (1346, 'Vòng hoa ngưu bàng khô', 1233750, 1233750, 100, 100, 0, 'Vòng hoa khô thủ công có hình cây ngưu bàng theo mùa. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:27:50.000000');
INSERT INTO `product` VALUES (1347, 'Kệ gỗ hình giọt nước tuyết chạm khắc thủ công', 2535750, 2535750, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh hình giọt nước tuyết. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:27:52.000000');
INSERT INTO `product` VALUES (1348, 'Thớt quả óc chó Crocus cuối hạt', 4330000, 4330000, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:27:53.000000');
INSERT INTO `product` VALUES (1349, 'Bộ bát sứ Trillium ném tay', 2434000, 2434000, 100, 100, 0, 'Bộ 4 bát gốm sứ tráng men phản ứng trillium. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:27:55.000000');
INSERT INTO `product` VALUES (1350, 'Mũ len Merino Bloodroot dệt kim bằng tay', 1148000, 1148000, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu sắc máu. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:27:57.000000');
INSERT INTO `product` VALUES (1351, 'Dây buộc tóc ren Hepatica', 369250, 369250, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông Hepatica. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:28:00.000000');
INSERT INTO `product` VALUES (1352, 'Khăn choàng lụa Mayapple nhuộm tay', 3557750, 3557750, 100, 100, 0, 'Khăn choàng quấn lụa nhuộm tay sang trọng họa tiết màu nước mayapple. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:28:02.000000');
INSERT INTO `product` VALUES (1353, 'Ly hợp da Elderflower khâu tay', 2434000, 2434000, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay hoa cơm cháy. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:28:05.000000');
INSERT INTO `product` VALUES (1354, 'Ba lô vải táo gai sáp', 3384000, 3384000, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da táo gai. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:28:08.000000');
INSERT INTO `product` VALUES (1355, 'Tranh sáp sơn dầu Blackthorn nguyên bản', 4737000, 4737000, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng của cây gai đen. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:28:10.000000');
INSERT INTO `product` VALUES (1356, 'Tượng gốm Rowan điêu khắc bằng tay', 2253250, 2253250, 100, 100, 0, 'Tượng gốm bằng đá được điêu khắc thủ công với các chi tiết tráng men thanh lương trà. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:28:12.000000');
INSERT INTO `product` VALUES (1357, 'Mỹ Thuật Sloe Thiên Nhiên In Ảnh', 1045750, 1045750, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên sloe nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:28:15.000000');
INSERT INTO `product` VALUES (1358, 'Sữa Dê Xà Phòng Thủ Công Damson', 390750, 390750, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm Damson và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:28:17.000000');
INSERT INTO `product` VALUES (1359, 'Thanh gội đầu hồng đặc', 324250, 324250, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược hồng. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:28:20.000000');
INSERT INTO `product` VALUES (1360, 'Tẩy tế bào chết cơ thể Sugar Quince', 537000, 537000, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường mộc qua thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu mộc qua. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:28:23.000000');
INSERT INTO `product` VALUES (1361, 'Tạp chí da Medlar ràng buộc bằng tay', 1128250, 1128250, 100, 100, 0, 'Nhật ký đóng bìa tay với bìa da sơn tra và dây vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:28:25.000000');
INSERT INTO `product` VALUES (1362, 'Thiệp cưới màu nước dâu tằm', 193500, 193500, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật dâu tằm. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:28:27.000000');
INSERT INTO `product` VALUES (1363, 'Câu đố bằng gỗ Gooseberry vẽ tay', 768250, 768250, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay bằng quả lý gai. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:28:29.000000');
INSERT INTO `product` VALUES (1364, 'Đũa phép đồ chơi cho mèo Bilberry bện bằng tay', 261000, 261000, 100, 100, 0, 'Đồ chơi đũa phép mèo thủ công với dây bông bện quả việt quất và phần đính kèm lông tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:28:32.000000');
INSERT INTO `product` VALUES (1365, 'Vòng cổ mặt dây chuyền đá mặt trăng Crowberry thủ công', 861750, 861750, 100, 100, 0, 'Vòng cổ có mặt dây chuyền thủ công tinh tế có đính đá mặt trăng quả quạ chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:28:34.000000');
INSERT INTO `product` VALUES (1366, 'Tên tùy chỉnh Vòng cổ Cloudberry Gold-Fill', 969000, 969000, 100, 100, 0, 'Vòng cổ tên quả mâm xôi được cá nhân hóa được đóng dấu thủ công trên đĩa phủ vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:28:37.000000');
INSERT INTO `product` VALUES (1367, 'Vòng cổ mặt dây chuyền Lingonberry phong cách cổ điển', 3150750, 3150750, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng lingonberry lấy cảm hứng từ cổ. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:28:39.000000');
INSERT INTO `product` VALUES (1368, 'Vòng tay tình bạn Bearberry dệt tay', 536500, 536500, 100, 100, 0, 'Vòng tay tình bạn Bearberry dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:28:41.000000');
INSERT INTO `product` VALUES (1369, 'Vòng đeo tay bằng đồng Hackberry rèn', 782250, 782250, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ sắt hackberry. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:28:43.000000');
INSERT INTO `product` VALUES (1370, 'Vòng tay đá quý Buffaloberry đính cườm', 977250, 977250, 100, 100, 0, 'Vòng tay hạt đá quý trâu được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:28:46.000000');
INSERT INTO `product` VALUES (1371, 'Bông tai bạc Aurora được rèn thủ công', 1216750, 1216750, 100, 100, 0, 'Bông tai đinh tán bằng bạc được rèn thủ công với kết cấu cực quang. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:28:48.000000');
INSERT INTO `product` VALUES (1372, 'Bông tai Hoop Pha lê Chạng vạng có dây', 668250, 668250, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê màu chạng vạng. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:28:50.000000');
INSERT INTO `product` VALUES (1373, 'Nhẫn xếp chồng thạch cao được đóng dấu bằng tay', 445250, 445250, 100, 100, 0, 'Chiếc nhẫn xếp chồng thạch nam được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:28:53.000000');
INSERT INTO `product` VALUES (1374, 'Nhẫn gỗ lũa pha lê thô', 757750, 757750, 100, 100, 0, 'Chiếc nhẫn nổi bật có pha lê gỗ lũa thô được đặt bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thiện với lớp gỉ lũa.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:28:55.000000');
INSERT INTO `product` VALUES (1375, 'Nến sáp ong Riverstone đổ bằng tay', 600000, 600000, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu riverstone. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:28:57.000000');
INSERT INTO `product` VALUES (1376, 'Nến thơm sáp dừa Pebble Beach', 672500, 672500, 100, 100, 0, 'Nến thơm bãi biển sỏi số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:28:59.000000');
INSERT INTO `product` VALUES (1377, 'Treo tường Macramé Foxglove', 1086500, 1086500, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo được treo bằng dây bông tự nhiên hình mao địa hoàng. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:29:00.000000');
INSERT INTO `product` VALUES (1378, 'Vòng hoa mâm xôi khô', 1648000, 1648000, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa của dâu đen. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:29:02.000000');
INSERT INTO `product` VALUES (1379, 'Kệ Gỗ Quế Chạm Khắc Bằng Tay', 2803000, 2803000, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết viền quế. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:29:03.000000');
INSERT INTO `product` VALUES (1380, 'Thớt quả óc chó bạch đậu khấu cuối hạt', 3514500, 3514500, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó bạch đậu khấu và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:29:05.000000');
INSERT INTO `product` VALUES (1381, 'Bộ bát sứ ném cỏ ba lá bằng tay', 2444250, 2444250, 100, 100, 0, 'Bộ 4 chiếc bát gốm sứ ném bằng tay phủ men phản ứng cỏ ba lá. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:29:06.000000');
INSERT INTO `product` VALUES (1382, 'Mũ len Merino dệt kim bằng tay', 589750, 589750, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu sắc cây kế. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:29:08.000000');
INSERT INTO `product` VALUES (1383, 'Dây buộc tóc bằng ren móc Wisteria', 167500, 167500, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông hoa tử đằng. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:29:10.000000');
INSERT INTO `product` VALUES (1384, 'Khăn choàng lụa Wren nhuộm tay', 2912500, 2912500, 100, 100, 0, 'Khăn choàng lụa quấn tay sang trọng họa tiết màu nước chim hồng tước. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:29:13.000000');
INSERT INTO `product` VALUES (1385, 'Ly hợp da Falcon khâu tay', 1675000, 1675000, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay hình chim ưng. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:29:15.000000');
INSERT INTO `product` VALUES (1386, 'Ba lô Osprey vải sáp', 3162250, 3162250, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da chim ưng. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:29:17.000000');
INSERT INTO `product` VALUES (1387, 'Tranh sáp nguyên bản Hawkweed', 5311000, 5311000, 100, 100, 0, 'Bức tranh sơn dầu nguyên bản (sáp nóng) với bố cục trừu tượng hawkweed. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:29:20.000000');
INSERT INTO `product` VALUES (1388, 'Tượng gốm Dogwood điêu khắc bằng tay', 1891750, 1891750, 100, 100, 0, 'Tượng gốm bằng đá được điêu khắc thủ công với các chi tiết được tráng men bằng gỗ sơn thù du. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:29:22.000000');
INSERT INTO `product` VALUES (1389, 'Mỹ thuật Sweetgrass In ảnh thiên nhiên', 922750, 922750, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên cỏ ngọt nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:29:24.000000');
INSERT INTO `product` VALUES (1390, 'Xà phòng thủ công Cattail sữa dê', 442750, 442750, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm đuôi mèo và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:29:27.000000');
INSERT INTO `product` VALUES (1391, 'Thanh gội đầu rắn Bullrush', 270000, 270000, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo mộc bullrush. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:29:29.000000');
INSERT INTO `product` VALUES (1392, 'Tẩy tế bào chết bằng đường cói', 316500, 316500, 100, 100, 0, 'Tẩy tế bào chết bằng đường cói handmade gốc dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm từ đường mía hữu cơ và tinh dầu cói. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:29:31.000000');
INSERT INTO `product` VALUES (1393, 'Tạp chí da Bracken đóng bìa tay', 945750, 945750, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da dương xỉ và dây vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:29:33.000000');
INSERT INTO `product` VALUES (1394, 'Thiệp cưới màu nước cây me chua', 325250, 325250, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật cây me chua. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:29:36.000000');
INSERT INTO `product` VALUES (1395, 'Câu đố bằng gỗ hoa cúc bằng tay', 1145750, 1145750, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay hoa cúc. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:29:38.000000');
INSERT INTO `product` VALUES (1396, 'Cây đũa phép đồ chơi cho mèo Yarrow bện bằng tay', 430000, 430000, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây bông bện cỏ thi và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:29:40.000000');
INSERT INTO `product` VALUES (1397, 'Vòng cổ mặt dây chuyền đá mặt trăng Valerian thủ công', 709500, 709500, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng valerian chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:29:42.000000');
INSERT INTO `product` VALUES (1398, 'Tên tùy chỉnh Vòng cổ Mugwort mạ vàng', 1914500, 1914500, 100, 100, 0, 'Vòng cổ tên ngải cứu cá nhân được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:29:45.000000');
INSERT INTO `product` VALUES (1399, 'Vòng cổ Mề đay cây tầm ma phong cách cổ điển', 2937500, 2937500, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:29:47.000000');
INSERT INTO `product` VALUES (1400, 'Vòng tay tình bạn cây ngưu bàng dệt tay', 454000, 454000, 100, 100, 0, 'Vòng tay tình bạn ngưu bàng dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:29:49.000000');
INSERT INTO `product` VALUES (1401, 'Vòng đeo tay bằng đồng hình giọt nước bằng búa rèn', 1405000, 1405000, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ hình giọt nước tuyết. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:29:52.000000');
INSERT INTO `product` VALUES (1402, 'Vòng tay đá quý Crocus đính cườm', 855250, 855250, 100, 100, 0, 'Vòng tay hạt đá quý crocus được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:29:54.000000');
INSERT INTO `product` VALUES (1403, 'Bông tai bạc Trillium được rèn thủ công', 671000, 671000, 100, 100, 0, 'Bông tai đinh tán bằng bạc được rèn thủ công với kết cấu trillium. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:29:56.000000');
INSERT INTO `product` VALUES (1404, 'Bông tai pha lê Bloodroot có dây', 1637500, 1637500, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn là pha lê hình rễ máu. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:29:58.000000');
INSERT INTO `product` VALUES (1405, 'Vòng xếp chồng Hepatica được đóng dấu bằng tay', 931000, 931000, 100, 100, 0, 'Chiếc nhẫn xếp chồng Hexica được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:30:01.000000');
INSERT INTO `product` VALUES (1406, 'Nhẫn tuyên bố Mayapple pha lê thô', 660500, 660500, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê mayapple thô bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với patina mayapple.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:30:04.000000');
INSERT INTO `product` VALUES (1407, 'Nến sáp ong hoa cơm cháy bằng tay', 520250, 520250, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu hoa cơm cháy. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:30:05.000000');
INSERT INTO `product` VALUES (1408, 'Nến thơm sáp dừa táo gai', 430500, 430500, 100, 100, 0, 'Nến thơm táo gai số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:30:07.000000');
INSERT INTO `product` VALUES (1409, 'Treo tường Macramé Blackthorn', 1445250, 1445250, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo treo bằng dây bông tự nhiên gai đen. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:30:08.000000');
INSERT INTO `product` VALUES (1410, 'Vòng hoa thanh lương hoa khô', 1375750, 1375750, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa thanh lương trà. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:30:10.000000');
INSERT INTO `product` VALUES (1411, 'Kệ Gỗ Sloe Chạm Khắc Bằng Tay', 1969750, 1969750, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh dốc. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:30:12.000000');
INSERT INTO `product` VALUES (1412, 'Thớt quả óc chó Damson cuối hạt', 4227500, 4227500, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó Damson và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:30:14.000000');
INSERT INTO `product` VALUES (1413, 'Bộ bát sứ ném hồng bằng tay', 3023250, 3023250, 100, 100, 0, 'Bộ 4 bát gốm sứ tráng men phản ứng hình quả hồng. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:30:15.000000');
INSERT INTO `product` VALUES (1414, 'Mũ len mộc qua Merino dệt kim bằng tay', 1269000, 1269000, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu mộc qua. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:30:18.000000');
INSERT INTO `product` VALUES (1415, 'Dây buộc tóc bằng ren móc Medlar', 247250, 247250, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông sơn tra. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:30:20.000000');
INSERT INTO `product` VALUES (1416, 'Khăn choàng lụa dâu tằm nhuộm tay', 2574500, 2574500, 100, 100, 0, 'Khăn choàng lụa nhuộm tay sang trọng họa tiết màu nước dâu tằm. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:30:22.000000');
INSERT INTO `product` VALUES (1417, 'Ly hợp da ngỗng khâu tay', 3227000, 3227000, 100, 100, 0, 'Ví cầm tay bằng da có chi tiết khâu bằng tay hình quả lý gai. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:30:25.000000');
INSERT INTO `product` VALUES (1418, 'Ba lô vải việt quất sáp', 2416750, 2416750, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da việt quất. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:30:27.000000');
INSERT INTO `product` VALUES (1419, 'Tranh sáp Crowberry nguyên bản', 3793000, 3793000, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng của cây dâu tây. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:30:29.000000');
INSERT INTO `product` VALUES (1420, 'Tượng gốm Cloudberry điêu khắc bằng tay', 903250, 903250, 100, 100, 0, 'Tượng gốm bằng đá được điêu khắc thủ công với các chi tiết tráng men mâm xôi. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:30:31.000000');
INSERT INTO `product` VALUES (1421, 'Mỹ Thuật Lingonberry Chụp Ảnh Thiên Nhiên', 1329250, 1329250, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên lingonberry gốc. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:30:34.000000');
INSERT INTO `product` VALUES (1422, 'Xà Phòng Thủ Công Bearberry Sữa Dê', 337250, 337250, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm dâu tây và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:30:36.000000');
INSERT INTO `product` VALUES (1423, 'Thanh dầu gội Hackberry rắn', 434250, 434250, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược hackberry. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:30:38.000000');
INSERT INTO `product` VALUES (1424, 'Tẩy tế bào chết toàn thân Sugar Buffaloberry', 307500, 307500, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường dâu tằm thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu trâu. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:30:40.000000');
INSERT INTO `product` VALUES (1425, 'Tạp chí da Aurora đóng bìa tay', 1205500, 1205500, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da cực quang và dây vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:30:42.000000');
INSERT INTO `product` VALUES (1426, 'Thiệp cưới màu nước chạng vạng', 166500, 166500, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật chạng vạng. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:30:45.000000');
INSERT INTO `product` VALUES (1427, 'Câu đố bằng gỗ thạch nam vẽ tay', 1558000, 1558000, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay bằng thạch nam. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:30:47.000000');
INSERT INTO `product` VALUES (1428, 'Đũa đồ chơi cho mèo lũa bện bằng tay', 363000, 363000, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây bông bện bằng gỗ lũa và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:30:50.000000');
INSERT INTO `product` VALUES (1429, 'Vòng cổ mặt dây chuyền đá mặt trăng Riverstone thủ công', 810250, 810250, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đá mặt trăng bằng đá sông chính hãng được đặt bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:30:52.000000');
INSERT INTO `product` VALUES (1430, 'Tên tùy chỉnh Vòng cổ lấp đầy vàng Pebble Beach', 1222250, 1222250, 100, 100, 0, 'Vòng cổ tên bãi biển sỏi được cá nhân hóa được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:30:54.000000');
INSERT INTO `product` VALUES (1431, 'Vòng cổ mặt dây chuyền Foxglove phong cách cổ điển', 2063500, 2063500, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng foxglove lấy cảm hứng từ cổ. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:30:57.000000');
INSERT INTO `product` VALUES (1432, 'Vòng tay tình bạn Blackberry dệt tay', 360250, 360250, 100, 100, 0, 'Vòng tay tình bạn blackberry dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:30:59.000000');
INSERT INTO `product` VALUES (1433, 'Vòng đeo tay bằng đồng quế rèn', 1281250, 1281250, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ màu quế. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:31:01.000000');
INSERT INTO `product` VALUES (1434, 'Vòng tay đá quý bạch đậu khấu đính cườm', 1541250, 1541250, 100, 100, 0, 'Vòng tay hạt đá quý bạch đậu khấu được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:31:03.000000');
INSERT INTO `product` VALUES (1435, 'Bông tai bạc hình cỏ ba lá được rèn thủ công', 811500, 811500, 100, 100, 0, 'Bông tai bạc sterling được rèn bằng tay với kết cấu cỏ ba lá. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:31:06.000000');
INSERT INTO `product` VALUES (1436, 'Bông tai pha lê Thistle có dây', 1307250, 1307250, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê hình cây kế. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:31:09.000000');
INSERT INTO `product` VALUES (1437, 'Vòng xếp chồng Wisteria được đóng dấu bằng tay', 515000, 515000, 100, 100, 0, 'Chiếc nhẫn xếp chồng hoa tử đằng được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:31:11.000000');
INSERT INTO `product` VALUES (1438, 'Nhẫn tuyên bố pha lê thô', 1805750, 1805750, 100, 100, 0, 'Chiếc nhẫn nổi bật có pha lê wren thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với patina wren.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:31:14.000000');
INSERT INTO `product` VALUES (1439, 'Nến sáp ong Falcon đổ bằng tay', 679250, 679250, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu chim ưng. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:31:15.000000');
INSERT INTO `product` VALUES (1440, 'Nến thơm sáp dừa Osprey', 1042250, 1042250, 100, 100, 0, 'Nến thơm chim ưng biển số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:31:17.000000');
INSERT INTO `product` VALUES (1441, 'Treo tường Macramé Hawkweed', 2207500, 2207500, 100, 100, 0, 'Bức tường macramé được thắt nút bằng tay phức tạp treo bằng dây bông tự nhiên hawkweed. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:31:19.000000');
INSERT INTO `product` VALUES (1442, 'Vòng hoa Dogwood khô', 2136250, 2136250, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa bằng gỗ sơn thù du. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:31:21.000000');
INSERT INTO `product` VALUES (1443, 'Kệ Gỗ Sweetgrass Chạm Khắc Bằng Tay', 1611750, 1611750, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết viền cỏ ngọt. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:31:22.000000');
INSERT INTO `product` VALUES (1444, 'Thớt quả óc chó đuôi mèo cuối hạt', 4182750, 4182750, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó đuôi mèo và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:31:24.000000');
INSERT INTO `product` VALUES (1445, 'Bộ bát sứ ném bằng tay Bullrush', 2302250, 2302250, 100, 100, 0, 'Bộ 4 chiếc bát gốm sứ thủ công phủ men phản ứng bullrush. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:31:26.000000');
INSERT INTO `product` VALUES (1446, 'Mũ len Merino cói dệt kim bằng tay', 685000, 685000, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu sắc cói. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:31:28.000000');
INSERT INTO `product` VALUES (1447, 'Dây buộc tóc bằng ren Crochet Bracken', 329000, 329000, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông dương xỉ. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:31:30.000000');
INSERT INTO `product` VALUES (1448, 'Khăn choàng lụa màu sầu riêng nhuộm tay', 2341250, 2341250, 100, 100, 0, 'Khăn choàng quấn lụa nhuộm tay sang trọng họa tiết màu nước cây me chua. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:31:32.000000');
INSERT INTO `product` VALUES (1449, 'Ly hợp da hoa cúc khâu tay', 1125250, 1125250, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay hình hoa cúc. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:31:34.000000');
INSERT INTO `product` VALUES (1450, 'Ba lô vải cỏ thi sáp', 2352250, 2352250, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền bằng da yarrow. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:31:36.000000');
INSERT INTO `product` VALUES (1451, 'Tranh sáp nghệ thuật Valerian nguyên bản', 1660750, 1660750, 100, 100, 0, 'Bức tranh sơn dầu nguyên bản (sáp nóng) với bố cục trừu tượng của cây nữ lang. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:31:39.000000');
INSERT INTO `product` VALUES (1452, 'Tượng gốm Mugwort điêu khắc bằng tay', 1441250, 1441250, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết tráng men ngải cứu. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:31:41.000000');
INSERT INTO `product` VALUES (1453, 'In ảnh nghệ thuật cây tầm ma thiên nhiên', 1628250, 1628250, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên cây tầm ma nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:31:44.000000');
INSERT INTO `product` VALUES (1454, 'Xà phòng nghệ nhân ngưu bàng sữa dê', 368750, 368750, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm cây ngưu bàng và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:31:47.000000');
INSERT INTO `product` VALUES (1455, 'Thanh gội đầu Snowdrop rắn', 471750, 471750, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược hình giọt nước tuyết. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:31:50.000000');
INSERT INTO `product` VALUES (1456, 'Sugar Crocus Tẩy Tế Bào Chết Toàn Thân', 318000, 318000, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường nghệ thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu nghệ tây. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:31:52.000000');
INSERT INTO `product` VALUES (1457, 'Tạp chí Da Trillium ràng buộc bằng tay', 1601500, 1601500, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da trillium và dây vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:31:55.000000');
INSERT INTO `product` VALUES (1458, 'Thiệp cưới màu nước Bloodroot', 224000, 224000, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật có rễ máu. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:31:58.000000');
INSERT INTO `product` VALUES (1459, 'Câu đố bằng gỗ Hepatica vẽ tay', 684250, 684250, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay bằng tay. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:32:01.000000');
INSERT INTO `product` VALUES (1460, 'Đũa phép đồ chơi cho mèo Mayapple bện tay', 358250, 358250, 100, 100, 0, 'Đồ chơi đũa phép mèo thủ công với dây bông bện mayapple và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:32:03.000000');
INSERT INTO `product` VALUES (1461, 'Vòng cổ mặt dây chuyền đá mặt trăng Elderflower thủ công', 2100750, 2100750, 100, 100, 0, 'Vòng cổ có mặt dây chuyền thủ công tinh tế đính đá mặt trăng hoa cơm cháy chính hãng được làm bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:32:06.000000');
INSERT INTO `product` VALUES (1462, 'Tên tùy chỉnh Vòng cổ lấp đầy vàng Hawthorn', 2131500, 2131500, 100, 100, 0, 'Vòng cổ tên táo gai cá tính được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:32:08.000000');
INSERT INTO `product` VALUES (1463, 'Vòng cổ Mề đay Blackthorn theo phong cách cổ điển', 2772750, 2772750, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau blackthorn lấy cảm hứng từ cổ. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:32:10.000000');
INSERT INTO `product` VALUES (1464, 'Vòng tay tình bạn Rowan dệt tay', 200500, 200500, 100, 100, 0, 'Vòng tay tình bạn thanh lương trà dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:32:13.000000');
INSERT INTO `product` VALUES (1465, 'Vòng đeo tay bằng đồng rèn Sloe', 862500, 862500, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ dạng rãnh. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:32:17.000000');
INSERT INTO `product` VALUES (1466, 'Vòng tay đá quý Damson đính cườm', 1623500, 1623500, 100, 100, 0, 'Vòng tay hạt đá quý Damson được xâu chuỗi bằng dây co giãn bền bỉ. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:32:19.000000');
INSERT INTO `product` VALUES (1467, 'Bông tai bạc hình quả hồng rèn thủ công', 423750, 423750, 100, 100, 0, 'Bông tai bạc sterling được rèn thủ công với họa tiết quả hồng. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:32:22.000000');
INSERT INTO `product` VALUES (1468, 'Bông tai pha lê mộc qua có dây', 740500, 740500, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê mộc qua. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:32:24.000000');
INSERT INTO `product` VALUES (1469, 'Vòng xếp chồng Medlar được đóng dấu bằng tay', 629000, 629000, 100, 100, 0, 'Chiếc nhẫn xếp chồng cây sơn tra được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:32:26.000000');
INSERT INTO `product` VALUES (1470, 'Nhẫn dâu tằm pha lê thô', 715250, 715250, 100, 100, 0, 'Chiếc nhẫn nổi bật có pha lê dâu tằm thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với lớp vỏ dâu tằm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:32:29.000000');
INSERT INTO `product` VALUES (1471, 'Nến sáp ong Gooseberry được đổ bằng tay', 442000, 442000, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ thủ công với hỗn hợp tinh dầu quả lý gai. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:32:31.000000');
INSERT INTO `product` VALUES (1472, 'Nến thơm cây việt quất sáp dừa', 979750, 979750, 100, 100, 0, 'Nến thơm việt quất số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:32:32.000000');
INSERT INTO `product` VALUES (1473, 'Treo tường Macramé Crowberry', 2585500, 2585500, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo được treo bằng dây bông tự nhiên màu dâu tây. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:32:34.000000');
INSERT INTO `product` VALUES (1474, 'Vòng hoa mâm xôi khô', 1785250, 1785250, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa của cây mâm xôi. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:32:35.000000');
INSERT INTO `product` VALUES (1475, 'Kệ gỗ Lingonberry chạm khắc thủ công', 3274500, 3274500, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh quả việt quất. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:32:37.000000');
INSERT INTO `product` VALUES (1476, 'Thớt quả óc chó Bearberry cuối hạt', 4100750, 4100750, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó Bearberry và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:32:39.000000');
INSERT INTO `product` VALUES (1477, 'Bộ bát sứ Hackberry ném tay', 1447750, 1447750, 100, 100, 0, 'Bộ 4 bát gốm sứ tráng men phản ứng hackberry. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:32:40.000000');
INSERT INTO `product` VALUES (1478, 'Mũ len Buffaloberry Merino dệt kim bằng tay', 843750, 843750, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu sắc trâu. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:32:43.000000');
INSERT INTO `product` VALUES (1479, 'Dây buộc tóc bằng ren Aurora Crochet', 155000, 155000, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren cotton cực quang. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:32:45.000000');
INSERT INTO `product` VALUES (1480, 'Khăn choàng lụa Chạng vạng nhuộm tay', 2424500, 2424500, 100, 100, 0, 'Khăn choàng quấn lụa nhuộm tay sang trọng với họa tiết màu nước chạng vạng. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:32:48.000000');
INSERT INTO `product` VALUES (1481, 'Ly hợp da Heather khâu tay', 2715500, 2715500, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay bằng thạch nam. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:32:50.000000');
INSERT INTO `product` VALUES (1482, 'Ba lô gỗ lũa vải sáp', 3334500, 3334500, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da lũa. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:32:52.000000');
INSERT INTO `product` VALUES (1483, 'Tranh sáp nghệ thuật Riverstone nguyên bản', 4878250, 4878250, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng bằng đá ven sông. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:32:54.000000');
INSERT INTO `product` VALUES (1484, 'Tượng gốm sứ bãi biển Pebble được điêu khắc bằng tay', 2371500, 2371500, 100, 100, 0, 'Tượng gốm bằng đá được điêu khắc thủ công với các chi tiết tráng men trên bãi biển bằng đá cuội. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:32:57.000000');
INSERT INTO `product` VALUES (1485, 'Mỹ thuật Foxglove Ảnh thiên nhiên In', 1086750, 1086750, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên foxglove nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:32:59.000000');
INSERT INTO `product` VALUES (1486, 'Xà Phòng Nghệ Nhân Blackberry Sữa Dê', 366000, 366000, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm dâu đen và các chất thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:33:01.000000');
INSERT INTO `product` VALUES (1487, 'Thanh dầu gội quế đặc', 430000, 430000, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược quế. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:33:03.000000');
INSERT INTO `product` VALUES (1488, 'Tẩy tế bào chết toàn thân bằng đường bạch đậu khấu', 501000, 501000, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường bạch đậu khấu thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu bạch đậu khấu. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:33:06.000000');
INSERT INTO `product` VALUES (1489, 'Tạp chí da cỏ ba lá buộc tay', 859250, 859250, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da cỏ ba lá và sợi vải lanh đóng bìa bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:33:09.000000');
INSERT INTO `product` VALUES (1490, 'Thiệp cưới màu nước cây kế', 213250, 213250, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật cây kế. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:33:11.000000');
INSERT INTO `product` VALUES (1491, 'Câu đố bằng gỗ Wisteria vẽ tay', 1415500, 1415500, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay hoa đậu tía. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:33:14.000000');
INSERT INTO `product` VALUES (1492, 'Cây đũa phép đồ chơi cho mèo Wren bện tay', 461000, 461000, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây cotton bện và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:33:16.000000');
INSERT INTO `product` VALUES (1493, 'Vòng cổ mặt dây chuyền đá mặt trăng Falcon thủ công', 2169500, 2169500, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng hình chim ưng chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:33:19.000000');
INSERT INTO `product` VALUES (1494, 'Tên tùy chỉnh Vòng cổ Osprey mạ vàng', 2557000, 2557000, 100, 100, 0, 'Vòng cổ tên chim ưng cá nhân được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:33:21.000000');
INSERT INTO `product` VALUES (1495, 'Vòng cổ mặt dây chuyền Hawkweed theo phong cách cổ điển', 2912750, 2912750, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau hawkweed lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:33:24.000000');
INSERT INTO `product` VALUES (1496, 'Vòng tay tình bạn Dogwood dệt thủ công', 395750, 395750, 100, 100, 0, 'Vòng tay tình bạn bằng gỗ chó dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:33:26.000000');
INSERT INTO `product` VALUES (1497, 'Vòng đeo tay bằng đồng rèn Sweetgrass', 1731500, 1731500, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ bằng cỏ ngọt. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:33:28.000000');
INSERT INTO `product` VALUES (1498, 'Vòng tay đá quý Cattail đính cườm', 860750, 860750, 100, 100, 0, 'Vòng tay hạt đá quý cattail được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:33:31.000000');
INSERT INTO `product` VALUES (1499, 'Bông tai bạc Bullrush được rèn thủ công', 701000, 701000, 100, 100, 0, 'Bông tai đinh tán bằng bạc sterling được rèn thủ công với kết cấu màu hồng phấn. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:33:34.000000');
INSERT INTO `product` VALUES (1500, 'Bông tai pha lê cói bọc dây', 732000, 732000, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn là pha lê cói. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:33:36.000000');
INSERT INTO `product` VALUES (1501, 'Vòng xếp chồng Bracken được đóng dấu bằng tay', 504750, 504750, 100, 100, 0, 'Chiếc nhẫn xếp chồng dương xỉ được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:33:38.000000');
INSERT INTO `product` VALUES (1502, 'Nhẫn pha lê thô', 1581250, 1581250, 100, 100, 0, 'Chiếc nhẫn nổi bật có pha lê màu me chua thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với patina cây me chua.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:33:41.000000');
INSERT INTO `product` VALUES (1503, 'Nến sáp ong hoa cúc đổ bằng tay', 808000, 808000, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ thủ công với hỗn hợp tinh dầu hoa cúc. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:33:43.000000');
INSERT INTO `product` VALUES (1504, 'Nến thơm Sáp dừa Yarrow', 390000, 390000, 100, 100, 0, 'Nến thơm cỏ thi số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:33:45.000000');
INSERT INTO `product` VALUES (1505, 'Treo tường Macramé Valerian', 2970250, 2970250, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo được treo bằng dây bông tự nhiên cây nữ lang. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:33:47.000000');
INSERT INTO `product` VALUES (1506, 'Vòng hoa ngải cứu khô', 2153000, 2153000, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa ngải cứu. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:33:49.000000');
INSERT INTO `product` VALUES (1507, 'Kệ gỗ cây tầm ma chạm khắc thủ công', 2713500, 2713500, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh cây tầm ma. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:33:50.000000');
INSERT INTO `product` VALUES (1508, 'Thớt cắt quả óc chó ngưu bàng cuối hạt', 1734000, 1734000, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó cây ngưu bàng và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:33:52.000000');
INSERT INTO `product` VALUES (1509, 'Bộ bát sứ hình giọt nước ném bằng tay', 2286250, 2286250, 100, 100, 0, 'Bộ 4 chiếc bát gốm sứ tráng men phản ứng hình giọt nước bằng tay. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:33:53.000000');
INSERT INTO `product` VALUES (1510, 'Mũ len Crocus Merino dệt kim bằng tay', 911500, 911500, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ 100% len merino superwash với màu hoa nghệ tây. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:33:57.000000');
INSERT INTO `product` VALUES (1511, 'Dây buộc tóc bằng ren Trillium', 329250, 329250, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông trillium. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:34:00.000000');
INSERT INTO `product` VALUES (1512, 'Khăn choàng quấn lụa Bloodroot nhuộm tay', 1406250, 1406250, 100, 100, 0, 'Khăn choàng lụa quấn tay sang trọng họa tiết màu nước máu. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:34:02.000000');
INSERT INTO `product` VALUES (1513, 'Ly hợp da Hepatica khâu tay', 1221500, 1221500, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:34:05.000000');
INSERT INTO `product` VALUES (1514, 'Ba lô Mayapple vải sáp', 3389750, 3389750, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da mayapple. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:34:08.000000');
INSERT INTO `product` VALUES (1515, 'Tranh sáp hoa Elderflower nguyên bản', 3162250, 3162250, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng hoa cơm cháy. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:34:10.000000');
INSERT INTO `product` VALUES (1516, 'Tượng gốm táo gai điêu khắc bằng tay', 1993750, 1993750, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết tráng men táo gai. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:34:13.000000');
INSERT INTO `product` VALUES (1517, 'Mỹ thuật In ảnh thiên nhiên Blackthorn', 550750, 550750, 100, 100, 0, 'Lưu trữ bản in mỹ thuật của bức ảnh thiên nhiên cây gai đen nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:34:15.000000');
INSERT INTO `product` VALUES (1518, 'Xà phòng nghệ nhân Rowan sữa dê', 219000, 219000, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm thanh lương trà và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:34:17.000000');
INSERT INTO `product` VALUES (1519, 'Thanh gội đầu Solid Sloe', 471250, 471250, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược sloe. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:34:19.000000');
INSERT INTO `product` VALUES (1520, 'Tẩy tế bào chết Sugar Damson', 638500, 638500, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường Damson thủ công gốc dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu Damson. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:34:22.000000');
INSERT INTO `product` VALUES (1521, 'Nhật ký da hồng đóng tay', 2049750, 2049750, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da màu hồng và sợi vải lanh đóng bìa bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:34:24.000000');
INSERT INTO `product` VALUES (1522, 'Thiệp cưới mộc qua màu nước', 278500, 278500, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật mộc qua. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:34:26.000000');
INSERT INTO `product` VALUES (1523, 'Câu đố bằng gỗ Medlar vẽ tay', 762500, 762500, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay bằng sơn tra. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:34:29.000000');
INSERT INTO `product` VALUES (1524, 'Đũa phép đồ chơi mèo dâu bện bằng tay', 297750, 297750, 100, 100, 0, 'Đồ chơi đũa phép cho mèo được làm thủ công với dây cotton bện dâu tằm và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:34:31.000000');
INSERT INTO `product` VALUES (1525, 'Vòng cổ mặt dây chuyền đá mặt trăng Gooseberry thủ công', 1943750, 1943750, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng quả lý gai chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:34:33.000000');
INSERT INTO `product` VALUES (1526, 'Tên tùy chỉnh Vòng cổ lấp đầy vàng việt quất', 1822500, 1822500, 100, 100, 0, 'Vòng cổ tên việt quất được cá nhân hóa được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:34:36.000000');
INSERT INTO `product` VALUES (1527, 'Vòng cổ Crowberry phong cách cổ điển', 1031500, 1031500, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:34:38.000000');
INSERT INTO `product` VALUES (1528, 'Vòng tay tình bạn Cloudberry dệt tay', 479500, 479500, 100, 100, 0, 'Vòng tay tình bạn hình quả mâm xôi dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:34:40.000000');
INSERT INTO `product` VALUES (1529, 'Vòng đeo tay bằng đồng Lingonberry rèn', 1047000, 1047000, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ lingonberry. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:34:42.000000');
INSERT INTO `product` VALUES (1530, 'Vòng tay đá quý Bearberry đính cườm', 1279750, 1279750, 100, 100, 0, 'Vòng tay hạt đá quý Bearberry được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:34:45.000000');
INSERT INTO `product` VALUES (1531, 'Bông tai bạc Hackberry được rèn bằng tay', 401750, 401750, 100, 100, 0, 'Bông tai đinh tán bằng bạc được rèn thủ công với kết cấu hackberry. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:34:48.000000');
INSERT INTO `product` VALUES (1532, 'Bông tai pha lê Buffaloberry có dây', 1268000, 1268000, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê hình quả trâu. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:34:50.000000');
INSERT INTO `product` VALUES (1533, 'Vòng xếp chồng Aurora được đóng dấu bằng tay', 1055750, 1055750, 100, 100, 0, 'Chiếc nhẫn xếp chồng cực quang được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:34:52.000000');
INSERT INTO `product` VALUES (1534, 'Nhẫn tuyên bố hoàng hôn pha lê thô', 1362000, 1362000, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê chạng vạng thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với lớp gỉ màu chạng vạng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:34:55.000000');
INSERT INTO `product` VALUES (1535, 'Nến sáp ong Heather đổ bằng tay', 556500, 556500, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ thủ công với hỗn hợp tinh dầu thạch nam. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:34:57.000000');
INSERT INTO `product` VALUES (1536, 'Nến thơm gỗ lũa sáp dừa', 482250, 482250, 100, 100, 0, 'Nến thơm lũa số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:34:58.000000');
INSERT INTO `product` VALUES (1537, 'Tranh treo tường Macramé Riverstone', 1290750, 1290750, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo treo bằng dây bông tự nhiên bằng đá ven sông. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:35:00.000000');
INSERT INTO `product` VALUES (1538, 'Vòng Hoa Bãi Biển Sỏi Khô', 1472500, 1472500, 100, 100, 0, 'Vòng hoa khô thủ công có hình thực vật theo mùa trên bãi biển sỏi. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:35:01.000000');
INSERT INTO `product` VALUES (1539, 'Kệ gỗ Foxglove chạm khắc bằng tay', 2311000, 2311000, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh hình bao tay cáo. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:35:03.000000');
INSERT INTO `product` VALUES (1540, 'Thớt quả óc chó Blackberry cuối hạt', 3163000, 3163000, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó dâu đen và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:35:04.000000');
INSERT INTO `product` VALUES (1541, 'Bộ bát sứ quế ném tay', 1396250, 1396250, 100, 100, 0, 'Bộ 4 bát sứ thủ công phủ men phản ứng quế. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:35:06.000000');
INSERT INTO `product` VALUES (1542, 'Mũ len Merino dệt kim bằng tay thảo quả', 952750, 952750, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu bạch đậu khấu. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:35:09.000000');
INSERT INTO `product` VALUES (1543, 'Dây buộc tóc bằng ren Crochet Clover', 401500, 401500, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông cỏ ba lá. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:35:11.000000');
INSERT INTO `product` VALUES (1544, 'Khăn choàng quấn lụa Thistle nhuộm tay', 1715750, 1715750, 100, 100, 0, 'Khăn choàng lụa quấn tay sang trọng họa tiết màu nước cây kế. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:35:14.000000');
INSERT INTO `product` VALUES (1545, 'Ly hợp da Wisteria khâu tay', 1666250, 1666250, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay hoa tử đằng. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:35:16.000000');
INSERT INTO `product` VALUES (1546, 'Ba lô Wren vải sáp', 4955500, 4955500, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da màu đỏ. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:35:19.000000');
INSERT INTO `product` VALUES (1547, 'Bức tranh sáp chim ưng nguyên bản', 2906750, 2906750, 100, 100, 0, 'Bức tranh sơn dầu nguyên bản (sáp nóng) với bố cục trừu tượng chim ưng. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:35:21.000000');
INSERT INTO `product` VALUES (1548, 'Tượng gốm Osprey được điêu khắc bằng tay', 1389500, 1389500, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc bằng tay với các chi tiết tráng men chim ưng. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:35:23.000000');
INSERT INTO `product` VALUES (1549, 'Mỹ thuật Hawkweed In ảnh thiên nhiên', 1319500, 1319500, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên hawkweed nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:35:25.000000');
INSERT INTO `product` VALUES (1550, 'Xà Phòng Nghệ Nhân Dogwood Sữa Dê', 475500, 475500, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm cây dương đào và các tạp chất thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:35:28.000000');
INSERT INTO `product` VALUES (1551, 'Thanh gội đầu Solid Sweetgrass', 565000, 565000, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược cỏ ngọt. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:35:30.000000');
INSERT INTO `product` VALUES (1552, 'Tẩy tế bào chết toàn thân Sugar Cattail', 480500, 480500, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường cattail thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu đuôi mèo. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:35:32.000000');
INSERT INTO `product` VALUES (1553, 'Tạp chí da Bullrush đóng bìa tay', 1419250, 1419250, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da bò và dây vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:35:34.000000');
INSERT INTO `product` VALUES (1554, 'Thiệp cưới cói màu nước', 243000, 243000, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật cói. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:35:36.000000');
INSERT INTO `product` VALUES (1555, 'Câu đố bằng gỗ Bracken vẽ tay', 880250, 880250, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay dương xỉ. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:35:39.000000');
INSERT INTO `product` VALUES (1556, 'Đũa phép đồ chơi cho mèo me chua bện bằng tay', 445750, 445750, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây bông bện cây me chua và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:35:41.000000');
INSERT INTO `product` VALUES (1557, 'Vòng cổ mặt dây chuyền đá mặt trăng hoa cúc thủ công', 768250, 768250, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng hoa cúc chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:35:44.000000');
INSERT INTO `product` VALUES (1558, 'Tên tùy chỉnh Vòng cổ lấp đầy vàng Yarrow', 2101500, 2101500, 100, 100, 0, 'Vòng cổ tên yarrow được cá nhân hóa được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:35:46.000000');
INSERT INTO `product` VALUES (1559, 'Vòng cổ mặt dây chuyền Valerian theo phong cách cổ điển', 1077250, 1077250, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau valerian lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:35:48.000000');
INSERT INTO `product` VALUES (1560, 'Vòng tay hữu nghị Mugwort dệt tay', 359000, 359000, 100, 100, 0, 'Vòng tay tình bạn ngải cứu dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:35:50.000000');
INSERT INTO `product` VALUES (1561, 'Vòng đeo tay bằng đồng rèn cây tầm ma', 930500, 930500, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ màu cây tầm ma. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:35:53.000000');
INSERT INTO `product` VALUES (1562, 'Vòng tay đá quý ngưu bàng đính cườm', 1352250, 1352250, 100, 100, 0, 'Vòng tay hạt đá quý ngưu bàng được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:35:55.000000');
INSERT INTO `product` VALUES (1563, 'Bông tai bạc hình giọt nước tuyết được rèn thủ công', 581250, 581250, 100, 100, 0, 'Khuyên tai bạc sterling được rèn thủ công với họa tiết giọt tuyết. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:35:57.000000');
INSERT INTO `product` VALUES (1564, 'Bông tai vòng pha lê Crocus có dây', 1061250, 1061250, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê crocus. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:35:59.000000');
INSERT INTO `product` VALUES (1565, 'Vòng xếp Trillium được đóng dấu bằng tay', 676750, 676750, 100, 100, 0, 'Chiếc nhẫn xếp chồng trillium được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:36:01.000000');
INSERT INTO `product` VALUES (1566, 'Nhẫn tuyên bố Bloodroot tinh thể thô', 700750, 700750, 100, 100, 0, 'Chiếc nhẫn nổi bật có pha lê gốc máu thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với patina máu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:36:04.000000');
INSERT INTO `product` VALUES (1567, 'Nến sáp ong Hepatica đổ bằng tay', 721750, 721750, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ thủ công với hỗn hợp tinh dầu gan. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:36:05.000000');
INSERT INTO `product` VALUES (1568, 'Nến thơm sáp dừa Mayapple', 478500, 478500, 100, 100, 0, 'Nến thơm mayapple lô nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:36:07.000000');
INSERT INTO `product` VALUES (1569, 'Treo tường Macramé hoa cơm cháy', 1190250, 1190250, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo được treo bằng dây bông tự nhiên hoa cơm cháy. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:36:08.000000');
INSERT INTO `product` VALUES (1570, 'Vòng hoa táo gai khô', 2201250, 2201250, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa táo gai. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:36:10.000000');
INSERT INTO `product` VALUES (1571, 'Kệ gỗ mâm xôi chạm khắc thủ công', 3790250, 3790250, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh gai đen. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:36:13.000000');
INSERT INTO `product` VALUES (1572, 'Thớt quả óc chó Rowan cuối hạt', 2891500, 2891500, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó thanh lương trà và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:36:14.000000');
INSERT INTO `product` VALUES (1573, 'Bộ Bát Sứ Ném Tay', 1699750, 1699750, 100, 100, 0, 'Bộ 4 bát gốm sứ tráng men phản ứng sloe. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:36:16.000000');
INSERT INTO `product` VALUES (1574, 'Mũ len Damson Merino dệt kim bằng tay', 1046500, 1046500, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với phối màu damson. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:36:18.000000');
INSERT INTO `product` VALUES (1575, 'Dây buộc tóc ren quả hồng móc', 300500, 300500, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông màu hồng. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:36:20.000000');
INSERT INTO `product` VALUES (1576, 'Khăn choàng quấn lụa mộc qua nhuộm tay', 3848500, 3848500, 100, 100, 0, 'Khăn choàng lụa nhuộm tay sang trọng họa tiết màu nước mộc qua. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:36:23.000000');
INSERT INTO `product` VALUES (1577, 'Ly hợp da Medlar khâu tay', 1689750, 1689750, 100, 100, 0, 'Ly hợp da thủ công với chi tiết khâu tay bằng gỗ sơn tra. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:36:25.000000');
INSERT INTO `product` VALUES (1578, 'Ba lô vải dâu tằm sáp', 2634250, 2634250, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da dâu. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:36:27.000000');
INSERT INTO `product` VALUES (1579, 'Tranh sáp nghệ thuật gốc quả Gooseberry', 6493750, 6493750, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng quả lý gai. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:36:29.000000');
INSERT INTO `product` VALUES (1580, 'Tượng gốm việt quất điêu khắc bằng tay', 2164500, 2164500, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết tráng men việt quất. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:36:31.000000');
INSERT INTO `product` VALUES (1581, 'In ảnh nghệ thuật thiên nhiên Crowberry', 1577250, 1577250, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên cây dâu tây nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:36:34.000000');
INSERT INTO `product` VALUES (1582, 'Xà phòng thủ công việt quất sữa dê', 399000, 399000, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm mâm xôi và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:36:36.000000');
INSERT INTO `product` VALUES (1583, 'Thanh gội đầu Lingonberry rắn', 408500, 408500, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược lingonberry. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:36:38.000000');
INSERT INTO `product` VALUES (1584, 'Tẩy tế bào chết toàn thân Sugar Bearberry', 679750, 679750, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường Bearberry thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu gấu. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:36:41.000000');
INSERT INTO `product` VALUES (1585, 'Tạp chí da Hackberry đóng bìa tay', 1949000, 1949000, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da hackberry và sợi vải lanh đóng bìa bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:36:43.000000');
INSERT INTO `product` VALUES (1586, 'Thiệp cưới màu nước Buffaloberry', 321000, 321000, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật trâu. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:36:45.000000');
INSERT INTO `product` VALUES (1587, 'Câu đố bằng gỗ Aurora vẽ tay', 654250, 654250, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay cực quang. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:36:48.000000');
INSERT INTO `product` VALUES (1588, 'Cây đũa phép đồ chơi cho mèo Chạng vạng bện tay', 284500, 284500, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây cotton bện màu chạng vạng và phần đính kèm lông tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:36:50.000000');
INSERT INTO `product` VALUES (1589, 'Vòng cổ mặt dây chuyền đá thạch anh thủ công', 1139500, 1139500, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng thạch nam chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:36:53.000000');
INSERT INTO `product` VALUES (1590, 'Tên tùy chỉnh Vòng cổ lấp đầy vàng lũa', 2083000, 2083000, 100, 100, 0, 'Vòng cổ tên gỗ lũa cá tính được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:36:55.000000');
INSERT INTO `product` VALUES (1591, 'Vòng cổ mặt dây chuyền Riverstone theo phong cách cổ điển', 1048750, 1048750, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau riverstone lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:36:58.000000');
INSERT INTO `product` VALUES (1592, 'Vòng tay tình bạn bãi biển Pebble dệt thủ công', 610500, 610500, 100, 100, 0, 'Vòng tay tình bạn bãi biển sỏi dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:37:00.000000');
INSERT INTO `product` VALUES (1593, 'Vòng đeo tay bằng đồng rèn Foxglove', 1599250, 1599250, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn bằng tay với lớp gỉ hình găng tay cáo. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:37:02.000000');
INSERT INTO `product` VALUES (1594, 'Vòng tay đá quý Blackberry đính cườm', 730750, 730750, 100, 100, 0, 'Vòng tay hạt đá quý blackberry được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:37:05.000000');
INSERT INTO `product` VALUES (1595, 'Bông tai bạc quế được rèn thủ công', 621000, 621000, 100, 100, 0, 'Bông tai đinh tán bằng bạc được rèn thủ công với họa tiết quế. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:37:07.000000');
INSERT INTO `product` VALUES (1596, 'Bông tai pha lê bạch đậu khấu có dây', 1622250, 1622250, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê bạch đậu khấu. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:37:09.000000');
INSERT INTO `product` VALUES (1597, 'Vòng xếp cỏ ba lá được đóng dấu bằng tay', 678750, 678750, 100, 100, 0, 'Nhẫn xếp chồng cỏ ba lá được đóng dấu bằng tay xinh xắn bằng bạc. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:37:12.000000');
INSERT INTO `product` VALUES (1598, 'Vòng tuyên bố cây kế pha lê thô', 899750, 899750, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê cây kế thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với lớp vỏ cây kế.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:37:16.000000');
INSERT INTO `product` VALUES (1599, 'Nến sáp ong Wisteria đổ bằng tay', 602000, 602000, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu hoa tử đằng. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:37:18.000000');
INSERT INTO `product` VALUES (1600, 'Nến thơm sáp dừa Wren', 427250, 427250, 100, 100, 0, 'Nến thơm chim hồng tước số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:37:19.000000');
INSERT INTO `product` VALUES (1601, 'Treo tường Macramé Falcon', 2770750, 2770750, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo được treo bằng dây bông tự nhiên hình chim ưng. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:37:21.000000');
INSERT INTO `product` VALUES (1602, 'Vòng hoa Osprey khô', 1612250, 1612250, 100, 100, 0, 'Vòng hoa khô được làm thủ công có hình thực vật theo mùa của chim ưng biển. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:37:23.000000');
INSERT INTO `product` VALUES (1603, 'Kệ Gỗ Hawkweed Chạm Khắc Bằng Tay', 2390750, 2390750, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh diều hâu. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:37:24.000000');
INSERT INTO `product` VALUES (1604, 'Thớt gỗ óc chó Dogwood hạt cuối', 4266250, 4266250, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ gỗ óc chó và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:37:26.000000');
INSERT INTO `product` VALUES (1605, 'Bộ bát gốm Sweetgrass ném tay', 2931000, 2931000, 100, 100, 0, 'Bộ 4 bát gốm sứ tráng men phản ứng Sweetgrass. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:37:27.000000');
INSERT INTO `product` VALUES (1606, 'Mũ len Merino dệt kim bằng tay', 786750, 786750, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu đuôi mèo. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:37:30.000000');
INSERT INTO `product` VALUES (1607, 'Dây buộc tóc bằng ren Crochet Bullrush', 261500, 261500, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông bullrush. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:37:32.000000');
INSERT INTO `product` VALUES (1608, 'Khăn choàng quấn cói nhuộm tay', 2796250, 2796250, 100, 100, 0, 'Khăn choàng quấn lụa nhuộm tay sang trọng họa tiết màu nước cói. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:37:34.000000');
INSERT INTO `product` VALUES (1609, 'Ly hợp da Bracken khâu tay', 1331750, 1331750, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu bằng tay màu dương xỉ. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:37:36.000000');
INSERT INTO `product` VALUES (1610, 'Ba lô vải màu sáp', 2703750, 2703750, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da màu nâu đỏ. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:37:39.000000');
INSERT INTO `product` VALUES (1611, 'Tranh sáp hoa cúc gốc', 3364000, 3364000, 100, 100, 0, 'Bức tranh sơn dầu nguyên bản (sáp nóng) với bố cục trừu tượng hoa cúc. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:37:41.000000');
INSERT INTO `product` VALUES (1612, 'Tượng gốm cỏ thi điêu khắc bằng tay', 1961000, 1961000, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết bằng men cỏ thi. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:37:44.000000');
INSERT INTO `product` VALUES (1613, 'Mỹ thuật Valerian In ảnh thiên nhiên', 1086750, 1086750, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên valerian nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:37:46.000000');
INSERT INTO `product` VALUES (1614, 'Xà phòng nghệ nghệ ngải cứu sữa dê', 250500, 250500, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm ngải cứu và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:37:48.000000');
INSERT INTO `product` VALUES (1615, 'Thanh dầu gội cây tầm ma rắn', 482000, 482000, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược cây tầm ma. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:37:51.000000');
INSERT INTO `product` VALUES (1616, 'Tẩy tế bào chết bằng đường cây ngưu bàng', 721750, 721750, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường ngưu bàng thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu cây ngưu bàng. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:37:53.000000');
INSERT INTO `product` VALUES (1617, 'Nhật ký da hoa tuyết buộc tay', 1327000, 1327000, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da hình giọt nước và dây vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:37:55.000000');
INSERT INTO `product` VALUES (1618, 'Thiệp cưới màu nước Crocus', 211250, 211250, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật crocus. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:37:57.000000');
INSERT INTO `product` VALUES (1619, 'Câu đố bằng gỗ Trillium vẽ tay', 846000, 846000, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay trillium. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:38:00.000000');
INSERT INTO `product` VALUES (1620, 'Đũa phép đồ chơi cho mèo Bloodroot bện bằng tay', 387250, 387250, 100, 100, 0, 'Đồ chơi đũa phép cho mèo được làm thủ công với dây bông bện bằng rễ cây và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:38:02.000000');
INSERT INTO `product` VALUES (1621, 'Vòng cổ mặt dây chuyền đá mặt trăng Hepatica thủ công', 922250, 922250, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng Hepatica chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:38:04.000000');
INSERT INTO `product` VALUES (1622, 'Tên tùy chỉnh Vòng cổ Mayapple Gold-Fill', 998500, 998500, 100, 100, 0, 'Vòng cổ tên mayapple cá nhân hóa được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:38:07.000000');
INSERT INTO `product` VALUES (1623, 'Vòng cổ mặt dây chuyền hoa cơm cháy theo phong cách cổ điển', 2507000, 2507000, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng hoa cơm cháy lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:38:09.000000');
INSERT INTO `product` VALUES (1624, 'Vòng tay tình bạn táo gai dệt tay', 270500, 270500, 100, 100, 0, 'Vòng tay tình bạn táo gai dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:38:11.000000');
INSERT INTO `product` VALUES (1625, 'Vòng đeo tay bằng đồng Blackthorn rèn', 1392250, 1392250, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ màu đen gai. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:38:13.000000');
INSERT INTO `product` VALUES (1626, 'Vòng tay đá quý Rowan đính cườm', 1169000, 1169000, 100, 100, 0, 'Vòng tay hạt đá quý thanh lương trà được xâu chuỗi bằng dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:38:16.000000');
INSERT INTO `product` VALUES (1627, 'Bông tai bạc Sloe được rèn thủ công', 1133000, 1133000, 100, 100, 0, 'Bông tai đinh tán bằng bạc sterling được rèn thủ công với kết cấu sloe. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:38:18.000000');
INSERT INTO `product` VALUES (1628, 'Bông tai pha lê Damson được bọc dây', 973250, 973250, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê Damson. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:38:20.000000');
INSERT INTO `product` VALUES (1629, 'Vòng xếp hồng đóng dấu bằng tay', 1065000, 1065000, 100, 100, 0, 'Nhẫn xếp hình quả hồng được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:38:23.000000');
INSERT INTO `product` VALUES (1630, 'Nhẫn mộc qua pha lê thô', 708500, 708500, 100, 100, 0, 'Chiếc nhẫn nổi bật có pha lê mộc qua thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với mộc qua patina.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:38:25.000000');
INSERT INTO `product` VALUES (1631, 'Nến sáp ong Medlar đổ bằng tay', 349500, 349500, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu sơn tra. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:38:27.000000');
INSERT INTO `product` VALUES (1632, 'Nến thơm dâu tằm sáp dừa', 712250, 712250, 100, 100, 0, 'Nến thơm dâu tằm số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:38:28.000000');
INSERT INTO `product` VALUES (1633, 'Macramé Quả Ngỗng Treo Tường', 1561750, 1561750, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo được treo bằng dây bông tự nhiên màu quả lý gai. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:38:30.000000');
INSERT INTO `product` VALUES (1634, 'Vòng hoa việt quất khô', 932000, 932000, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa của quả việt quất. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:38:31.000000');
INSERT INTO `product` VALUES (1635, 'Kệ gỗ Crowberry chạm khắc bằng tay', 2506250, 2506250, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh quả quạ. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:38:33.000000');
INSERT INTO `product` VALUES (1636, 'Thớt quả óc chó Cloudberry cuối hạt', 4155500, 4155500, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó mâm xôi và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:38:35.000000');
INSERT INTO `product` VALUES (1637, 'Bộ bát gốm Lingonberry ném tay', 2043500, 2043500, 100, 100, 0, 'Bộ 4 chiếc bát gốm sứ tráng men phản ứng dâu lingonberry. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:38:37.000000');
INSERT INTO `product` VALUES (1638, 'Mũ len Bearberry Merino dệt kim bằng tay', 1036500, 1036500, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ 100% len merino superwash với màu sắc dâu tây. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:38:39.000000');
INSERT INTO `product` VALUES (1639, 'Móc buộc tóc ren Hackberry', 392750, 392750, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren cotton hackberry. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:38:42.000000');
INSERT INTO `product` VALUES (1640, 'Khăn choàng lụa Buffaloberry nhuộm tay', 4074000, 4074000, 100, 100, 0, 'Khăn choàng lụa nhuộm tay sang trọng họa tiết màu nước trâu. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:38:44.000000');
INSERT INTO `product` VALUES (1641, 'Ly hợp da Aurora khâu tay', 1578250, 1578250, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay cực quang. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:38:47.000000');
INSERT INTO `product` VALUES (1642, 'Ba lô vải sáp Chạng vạng', 4484000, 4484000, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da màu chạng vạng. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:38:49.000000');
INSERT INTO `product` VALUES (1643, 'Tranh sáp nguyên bản Heather Encaustic', 5178750, 5178750, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng thạch nam. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:38:52.000000');
INSERT INTO `product` VALUES (1644, 'Tượng gốm bằng gỗ lũa điêu khắc bằng tay', 1219750, 1219750, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết bằng gỗ lũa. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:38:54.000000');
INSERT INTO `product` VALUES (1645, 'Tranh in mỹ thuật thiên nhiên Riverstone', 555250, 555250, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên ven sông nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:38:56.000000');
INSERT INTO `product` VALUES (1646, 'Sữa Dê Xà Phòng Nghệ Nhân Pebble Beach', 438000, 438000, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm bãi biển và các chất thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:38:59.000000');
INSERT INTO `product` VALUES (1647, 'Thanh gội đầu Foxglove rắn', 305000, 305000, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược foxglove. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:39:02.000000');
INSERT INTO `product` VALUES (1648, 'Tẩy tế bào chết toàn thân bằng đường Blackberry', 494250, 494250, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường dâu đen thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu dâu đen. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:39:04.000000');
INSERT INTO `product` VALUES (1649, 'Tạp chí da quế đóng tay', 1336000, 1336000, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da màu quế và dây vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:39:06.000000');
INSERT INTO `product` VALUES (1650, 'Thiệp cưới bạch đậu khấu màu nước', 289000, 289000, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật bạch đậu khấu. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:39:08.000000');
INSERT INTO `product` VALUES (1651, 'Câu đố bằng gỗ cỏ ba lá vẽ tay', 1168000, 1168000, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay cỏ ba lá. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:39:11.000000');
INSERT INTO `product` VALUES (1652, 'Cây đũa phép đồ chơi cho mèo Thistle bện bằng tay', 455500, 455500, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây bông bện cây kế và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:39:13.000000');
INSERT INTO `product` VALUES (1653, 'Vòng cổ mặt dây chuyền đá mặt trăng Wisteria thủ công', 2303750, 2303750, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng hoa tử đằng chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:39:16.000000');
INSERT INTO `product` VALUES (1654, 'Tên tùy chỉnh Vòng cổ Wren Gold-Fill', 2096750, 2096750, 100, 100, 0, 'Vòng cổ tên wren được cá nhân hóa được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:39:18.000000');
INSERT INTO `product` VALUES (1655, 'Vòng cổ mặt dây chuyền chim ưng phong cách cổ điển', 1037500, 1037500, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau hình chim ưng lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:39:21.000000');
INSERT INTO `product` VALUES (1656, 'Vòng tay tình bạn Osprey dệt tay', 692000, 692000, 100, 100, 0, 'Vòng tay tình bạn osprey dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:39:23.000000');
INSERT INTO `product` VALUES (1657, 'Vòng đeo tay bằng đồng Hawkweed rèn', 1012500, 1012500, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn bằng tay với lớp gỉ hawkweed. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:39:26.000000');
INSERT INTO `product` VALUES (1658, 'Vòng tay đá quý Dogwood đính cườm', 906500, 906500, 100, 100, 0, 'Vòng tay hạt đá quý bằng gỗ sơn thù du được xâu chuỗi bằng dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:39:28.000000');
INSERT INTO `product` VALUES (1659, 'Bông tai bạc Sweetgrass được rèn thủ công', 677500, 677500, 100, 100, 0, 'Bông tai đinh tán bằng bạc được rèn thủ công với họa tiết cỏ ngọt. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:39:31.000000');
INSERT INTO `product` VALUES (1660, 'Bông tai pha lê Cattail có dây', 1671250, 1671250, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn là pha lê đuôi mèo. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:39:33.000000');
INSERT INTO `product` VALUES (1661, 'Vòng xếp chồng Bullrush được đóng dấu bằng tay', 608500, 608500, 100, 100, 0, 'Chiếc nhẫn xếp hình con bò tót được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:39:36.000000');
INSERT INTO `product` VALUES (1662, 'Vòng tuyên bố cói pha lê thô', 683250, 683250, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê cói thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thiện với lớp gỉ cói.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:39:39.000000');
INSERT INTO `product` VALUES (1663, 'Nến sáp ong Bracken đổ bằng tay', 579000, 579000, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ thủ công với hỗn hợp tinh dầu dương xỉ. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:39:42.000000');
INSERT INTO `product` VALUES (1664, 'Nến thơm sáp dừa', 496750, 496750, 100, 100, 0, 'Nến thơm cây me chua số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:39:43.000000');
INSERT INTO `product` VALUES (1665, 'Treo tường hoa cúc Macramé', 2022750, 2022750, 100, 100, 0, 'Bức tường macramé thắt nút phức tạp được treo bằng dây bông tự nhiên hoa cúc. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:39:45.000000');
INSERT INTO `product` VALUES (1666, 'Vòng hoa cỏ thi khô', 895250, 895250, 100, 100, 0, 'Vòng hoa khô thủ công có hình thực vật theo mùa cỏ thi. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:39:46.000000');
INSERT INTO `product` VALUES (1667, 'Kệ Gỗ Valerian Chạm Khắc Bằng Tay', 3432500, 3432500, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh cây nữ lang. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:39:48.000000');
INSERT INTO `product` VALUES (1668, 'Thớt quả óc chó Mugwort cuối hạt', 4192000, 4192000, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó ngải cứu và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:39:50.000000');
INSERT INTO `product` VALUES (1669, 'Bộ bát sứ ném cây tầm ma', 2470500, 2470500, 100, 100, 0, 'Bộ 4 chiếc bát gốm sứ thủ công phủ men phản ứng cây tầm ma. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:39:51.000000');
INSERT INTO `product` VALUES (1670, 'Mũ len Merino ngưu bàng dệt kim bằng tay', 1010000, 1010000, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ 100% len merino superwash với màu sắc cây ngưu bàng. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:39:54.000000');
INSERT INTO `product` VALUES (1671, 'Dây buộc tóc ren hình giọt nước tuyết móc', 190500, 190500, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren cotton hình giọt nước. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:39:56.000000');
INSERT INTO `product` VALUES (1672, 'Khăn choàng lụa Crocus nhuộm tay', 1995500, 1995500, 100, 100, 0, 'Khăn choàng lụa quấn tay sang trọng có hoa văn màu nước nghệ tây. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:39:59.000000');
INSERT INTO `product` VALUES (1673, 'Ly hợp da Trillium khâu tay', 2626500, 2626500, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay trillium. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:40:02.000000');
INSERT INTO `product` VALUES (1674, 'Ba lô Bloodroot vải sáp', 2340250, 2340250, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da Bloodroot. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:40:04.000000');
INSERT INTO `product` VALUES (1675, 'Tranh sáp Encaustic Hepatica nguyên bản', 3964250, 3964250, 100, 100, 0, 'Bức tranh sơn dầu nguyên bản (sáp nóng) với bố cục trừu tượng Hepatica. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:40:06.000000');
INSERT INTO `product` VALUES (1676, 'Tượng gốm Mayapple điêu khắc bằng tay', 2202750, 2202750, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết tráng men mayapple. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:40:09.000000');
INSERT INTO `product` VALUES (1677, 'Mỹ Thuật In Ảnh Thiên Nhiên Hoa Elderflower', 1852750, 1852750, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên hoa cơm cháy nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:40:12.000000');
INSERT INTO `product` VALUES (1678, 'Xà phòng thủ công táo gai sữa dê', 445500, 445500, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm táo gai và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:40:14.000000');
INSERT INTO `product` VALUES (1679, 'Thanh gội đầu Blackthorn rắn', 427000, 427000, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược cây gai đen. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:40:17.000000');
INSERT INTO `product` VALUES (1680, 'Tẩy tế bào chết toàn thân Sugar Rowan', 441250, 441250, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường thanh lương trà thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu thanh lương trà. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:40:19.000000');
INSERT INTO `product` VALUES (1681, 'Tạp chí da Sloe ràng buộc bằng tay', 1369000, 1369000, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da sloe và sợi lanh đóng bìa bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:40:22.000000');
INSERT INTO `product` VALUES (1682, 'Thiệp cưới Damson màu nước', 287250, 287250, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật Damson. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:40:25.000000');
INSERT INTO `product` VALUES (1683, 'Câu đố bằng gỗ hồng vẽ tay', 709500, 709500, 100, 100, 0, 'Trò chơi ghép hình thủ công bằng gỗ với thiết kế vẽ tay bằng quả hồng. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:40:28.000000');
INSERT INTO `product` VALUES (1684, 'Đũa phép đồ chơi mèo Quince bện bằng tay', 522000, 522000, 100, 100, 0, 'Đồ chơi đũa phép mèo thủ công với dây bông bện mộc qua và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:40:31.000000');
INSERT INTO `product` VALUES (1685, 'Vòng cổ mặt dây chuyền đá mặt trăng Medlar thủ công', 1950750, 1950750, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:40:33.000000');
INSERT INTO `product` VALUES (1686, 'Tên tùy chỉnh Vòng cổ Mulberry Gold-Fill', 1483000, 1483000, 100, 100, 0, 'Dây chuyền khắc tên dâu tằm cá tính được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:40:36.000000');
INSERT INTO `product` VALUES (1687, 'Vòng cổ Mề đay Gooseberry phong cách cổ điển', 2932500, 2932500, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:40:38.000000');
INSERT INTO `product` VALUES (1688, 'Vòng tay tình bạn việt quất dệt tay', 319750, 319750, 100, 100, 0, 'Vòng tay tình bạn việt quất dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:40:40.000000');
INSERT INTO `product` VALUES (1689, 'Vòng đeo tay bằng đồng Crowberry rèn', 682500, 682500, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ màu quả dâu tây. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:40:42.000000');
INSERT INTO `product` VALUES (1690, 'Vòng tay đá quý Cloudberry đính cườm', 816750, 816750, 100, 100, 0, 'Vòng tay hạt đá quý quả mâm xôi được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:40:45.000000');
INSERT INTO `product` VALUES (1691, 'Bông tai bạc Lingonberry được rèn thủ công', 726750, 726750, 100, 100, 0, 'Bông tai đinh tán bằng bạc được rèn thủ công với họa tiết quả nam việt quất. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:40:47.000000');
INSERT INTO `product` VALUES (1692, 'Bông tai pha lê Bearberry có dây', 591500, 591500, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê Bearberry. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:40:49.000000');
INSERT INTO `product` VALUES (1693, 'Vòng xếp chồng Hackberry được đóng dấu bằng tay', 992250, 992250, 100, 100, 0, 'Chiếc nhẫn xếp chồng hackberry được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:40:52.000000');
INSERT INTO `product` VALUES (1694, 'Nhẫn tuyên bố Buffaloberry pha lê thô', 1854500, 1854500, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê Buffaloberry thô bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với patina trâu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:40:55.000000');
INSERT INTO `product` VALUES (1695, 'Nến sáp ong Aurora đổ bằng tay', 949500, 949500, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu aurora. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:40:57.000000');
INSERT INTO `product` VALUES (1696, 'Nến thơm Chạng vạng sáp dừa', 538000, 538000, 100, 100, 0, 'Nến thơm chạng vạng số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:40:59.000000');
INSERT INTO `product` VALUES (1697, 'Macramé Heather Treo Tường', 2542250, 2542250, 100, 100, 0, 'Bức tường macramé được thắt nút bằng tay phức tạp treo trên dây bông thạch nam tự nhiên. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:41:01.000000');
INSERT INTO `product` VALUES (1698, 'Vòng Gỗ Lũa Hoa Khô', 1500000, 1500000, 100, 100, 0, 'Vòng hoa khô thủ công có các loài thực vật theo mùa bằng gỗ lũa. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:41:03.000000');
INSERT INTO `product` VALUES (1699, 'Kệ Gỗ Riverstone Chạm Khắc Bằng Tay', 2413000, 2413000, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh bằng đá ven sông. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:41:05.000000');
INSERT INTO `product` VALUES (1700, 'Thớt cắt quả óc chó End-Grain Pebble Beach', 3284000, 3284000, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó và cây phong trên bãi biển sỏi. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:41:07.000000');
INSERT INTO `product` VALUES (1701, 'Bộ bát sứ ném tay Foxglove', 2780250, 2780250, 100, 100, 0, 'Bộ 4 chiếc bát gốm sứ thủ công phủ men phản ứng foxglove. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:41:09.000000');
INSERT INTO `product` VALUES (1702, 'Mũ len Blackberry Merino dệt kim bằng tay', 794500, 794500, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu dâu đen. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:41:12.000000');
INSERT INTO `product` VALUES (1703, 'Móc buộc tóc ren quế', 312750, 312750, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông quế. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:41:15.000000');
INSERT INTO `product` VALUES (1704, 'Khăn choàng lụa bạch đậu khấu nhuộm tay', 4103500, 4103500, 100, 100, 0, 'Khăn choàng lụa quấn tay sang trọng họa tiết màu nước bạch đậu khấu. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:41:18.000000');
INSERT INTO `product` VALUES (1705, 'Ly hợp da cỏ ba lá khâu tay', 2785000, 2785000, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay hình cỏ ba lá. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:41:20.000000');
INSERT INTO `product` VALUES (1706, 'Ba lô vải cây kế sáp', 5330250, 5330250, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da cây kế. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:41:23.000000');
INSERT INTO `product` VALUES (1707, 'Tranh sáp hoa tử đằng gốc', 1891250, 1891250, 100, 100, 0, 'Bức tranh sơn dầu nguyên bản (sáp nóng) với bố cục trừu tượng hoa đậu tía. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:41:26.000000');
INSERT INTO `product` VALUES (1708, 'Tượng gốm sứ Wren điêu khắc bằng tay', 1313000, 1313000, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết được tráng men. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:41:28.000000');
INSERT INTO `product` VALUES (1709, 'In ảnh nghệ thuật chim ưng thiên nhiên', 683250, 683250, 100, 100, 0, 'Lưu trữ bản in mỹ thuật của bức ảnh thiên nhiên chim ưng nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:41:31.000000');
INSERT INTO `product` VALUES (1710, 'Xà phòng thủ công Osprey sữa dê', 256000, 256000, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm chim ưng và các chất thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:41:33.000000');
INSERT INTO `product` VALUES (1711, 'Thanh gội đầu rắn Hawkweed', 405250, 405250, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược hawkweed. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:41:35.000000');
INSERT INTO `product` VALUES (1712, 'Tẩy tế bào chết bằng Sugar Dogwood', 534250, 534250, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường gỗ thù du thủ công với gốc dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu cây dương đào. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:41:37.000000');
INSERT INTO `product` VALUES (1713, 'Tạp chí da Sweetgrass đóng bìa tay', 1539000, 1539000, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da Sweetgrass và dây vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:41:40.000000');
INSERT INTO `product` VALUES (1714, 'Thiệp cưới Cattail màu nước', 341250, 341250, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật đuôi mèo. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:41:42.000000');
INSERT INTO `product` VALUES (1715, 'Câu đố bằng gỗ Bullrush vẽ tay', 1240500, 1240500, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay bằng tay. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:41:45.000000');
INSERT INTO `product` VALUES (1716, 'Đũa đồ chơi cho mèo cói bện tay', 391500, 391500, 100, 100, 0, 'Đồ chơi đũa phép mèo handmade với dây bông bện cói và đính kèm lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:41:48.000000');
INSERT INTO `product` VALUES (1717, 'Vòng cổ mặt dây chuyền đá mặt trăng Bracken thủ công', 788250, 788250, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng dương xỉ chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:41:50.000000');
INSERT INTO `product` VALUES (1718, 'Tên tùy chỉnh Vòng cổ màu vàng me chua', 2527250, 2527250, 100, 100, 0, 'Vòng cổ tên cây me chua được cá nhân hóa được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:41:52.000000');
INSERT INTO `product` VALUES (1719, 'Vòng cổ mặt dây chuyền hoa cúc phong cách cổ điển', 1708750, 1708750, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng hoa cúc lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:41:55.000000');
INSERT INTO `product` VALUES (1720, 'Vòng tay tình bạn Yarrow dệt tay', 478250, 478250, 100, 100, 0, 'Vòng tay tình bạn yarrow dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:41:57.000000');
INSERT INTO `product` VALUES (1721, 'Vòng đeo tay bằng đồng rèn Valerian', 752250, 752250, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ bằng cây nữ lang. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:41:59.000000');
INSERT INTO `product` VALUES (1722, 'Vòng tay đá quý Mugwort đính cườm', 1284500, 1284500, 100, 100, 0, 'Vòng tay hạt đá quý ngải cứu được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:42:03.000000');
INSERT INTO `product` VALUES (1723, 'Bông tai bạc hình cây tầm ma được rèn thủ công', 592250, 592250, 100, 100, 0, 'Bông tai đinh tán bằng bạc được rèn thủ công với họa tiết cây tầm ma. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:42:05.000000');
INSERT INTO `product` VALUES (1724, 'Bông tai pha lê hình cây ngưu bàng có dây', 1447000, 1447000, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê cây ngưu bàng. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:42:07.000000');
INSERT INTO `product` VALUES (1725, 'Vòng xếp chồng bông tuyết được đóng dấu bằng tay', 946500, 946500, 100, 100, 0, 'Nhẫn xếp chồng hình giọt tuyết được đóng dấu bằng tay xinh xắn bằng bạc. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:42:09.000000');
INSERT INTO `product` VALUES (1726, 'Nhẫn tuyên bố Crocus pha lê thô', 1437750, 1437750, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê crocus thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với crocus patina.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:42:11.000000');
INSERT INTO `product` VALUES (1727, 'Nến sáp ong Trillium đổ bằng tay', 470500, 470500, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu trillium. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:42:13.000000');
INSERT INTO `product` VALUES (1728, 'Nến thơm lọ sáp dừa', 930750, 930750, 100, 100, 0, 'Nến thơm rễ huyết lô nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:42:15.000000');
INSERT INTO `product` VALUES (1729, 'Treo tường Macramé Hepatica', 3353750, 3353750, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo được treo bằng dây bông tự nhiên Hepatica. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:42:17.000000');
INSERT INTO `product` VALUES (1730, 'Vòng hoa Mayapple khô', 917750, 917750, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa mayapple. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:42:18.000000');
INSERT INTO `product` VALUES (1731, 'Kệ gỗ hoa cơm cháy chạm khắc thủ công', 3439750, 3439750, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh hoa cơm cháy. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:42:20.000000');
INSERT INTO `product` VALUES (1732, 'Thớt quả óc chó táo gai cuối hạt', 3817500, 3817500, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó táo gai và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:42:23.000000');
INSERT INTO `product` VALUES (1733, 'Bộ bát gốm Blackthorn ném tay', 2843750, 2843750, 100, 100, 0, 'Bộ 4 bát gốm sứ tráng men phản ứng gai đen. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:42:24.000000');
INSERT INTO `product` VALUES (1734, 'Mũ len Merino Rowan dệt kim bằng tay', 1155250, 1155250, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu thanh lương trà. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:42:27.000000');
INSERT INTO `product` VALUES (1735, 'Dây buộc tóc ren Crochet Sloe', 194000, 194000, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông sloe. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:42:29.000000');
INSERT INTO `product` VALUES (1736, 'Khăn choàng lụa Damson nhuộm tay', 2502500, 2502500, 100, 100, 0, 'Khăn choàng quấn lụa nhuộm tay sang trọng họa tiết màu nước Damson. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:42:31.000000');
INSERT INTO `product` VALUES (1737, 'Ly hợp da hồng khâu tay', 2759000, 2759000, 100, 100, 0, 'Ví cầm tay bằng da có chi tiết khâu tay hình quả hồng. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:42:33.000000');
INSERT INTO `product` VALUES (1738, 'Ba lô vải mộc qua sáp', 4384750, 4384750, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da mộc qua. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:42:36.000000');
INSERT INTO `product` VALUES (1739, 'Tranh sáp sơn gốc Medlar', 2124750, 2124750, 100, 100, 0, 'Bức tranh sơn dầu nguyên bản (sáp nóng) với thành phần trừu tượng sơn tra. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:42:38.000000');
INSERT INTO `product` VALUES (1740, 'Tượng gốm dâu tằm điêu khắc bằng tay', 797250, 797250, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết tráng men dâu tằm. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:42:40.000000');
INSERT INTO `product` VALUES (1741, 'Mỹ Thuật In Ảnh Thiên Nhiên Cây Ngỗng', 614750, 614750, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên nguyên bản của quả lý gai. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:42:43.000000');
INSERT INTO `product` VALUES (1742, 'Xà phòng thủ công việt quất sữa dê', 429750, 429750, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm việt quất và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:42:46.000000');
INSERT INTO `product` VALUES (1743, 'Thanh gội đầu Crowberry rắn', 234500, 234500, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo mộc quả quạ. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:42:48.000000');
INSERT INTO `product` VALUES (1744, 'Tẩy tế bào chết toàn thân Sugar Cloudberry', 296250, 296250, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường mâm xôi thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu mâm xôi. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:42:51.000000');
INSERT INTO `product` VALUES (1745, 'Tạp chí da Lingonberry đóng bìa tay', 836000, 836000, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da lingonberry và sợi vải lanh đóng bìa bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:42:53.000000');
INSERT INTO `product` VALUES (1746, 'Thiệp cưới màu nước Bearberry', 136000, 136000, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật Bearberry. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:42:56.000000');
INSERT INTO `product` VALUES (1747, 'Câu đố bằng gỗ Hackberry vẽ tay', 661250, 661250, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay hackberry. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:42:58.000000');
INSERT INTO `product` VALUES (1748, 'Đũa đồ chơi cho mèo Buffaloberry bện bằng tay', 481250, 481250, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây bông bện hình quả trâu và phần đính kèm lông tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:43:00.000000');
INSERT INTO `product` VALUES (1749, 'Vòng cổ mặt dây chuyền đá mặt trăng Aurora thủ công', 2345500, 2345500, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng aurora chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:43:02.000000');
INSERT INTO `product` VALUES (1750, 'Tên tùy chỉnh Vòng cổ lấp đầy vàng Chạng vạng', 2402250, 2402250, 100, 100, 0, 'Vòng cổ tên chạng vạng được cá nhân hóa được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:43:04.000000');
INSERT INTO `product` VALUES (1751, 'Vòng cổ thạch anh phong cách cổ điển', 1497000, 1497000, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thạch nam lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:43:07.000000');
INSERT INTO `product` VALUES (1752, 'Vòng tay tình bạn lũa dệt thủ công', 373750, 373750, 100, 100, 0, 'Vòng tay tình bạn bằng gỗ lũa dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:43:09.000000');
INSERT INTO `product` VALUES (1753, 'Vòng đeo tay bằng đồng rèn Riverstone', 734000, 734000, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ bằng đá ven sông. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:43:11.000000');
INSERT INTO `product` VALUES (1754, 'Vòng tay đá quý Pebble Beach đính cườm', 1494500, 1494500, 100, 100, 0, 'Vòng tay hạt đá quý bãi biển được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:43:13.000000');
INSERT INTO `product` VALUES (1755, 'Bông tai bạc Foxglove được rèn bằng tay', 670750, 670750, 100, 100, 0, 'Khuyên tai dạng đinh tán bằng bạc được rèn thủ công với họa tiết hình găng tay cáo. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:43:16.000000');
INSERT INTO `product` VALUES (1756, 'Bông tai pha lê Blackberry có dây', 810000, 810000, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê blackberry. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:43:19.000000');
INSERT INTO `product` VALUES (1757, 'Vòng xếp quế được đóng dấu bằng tay', 445500, 445500, 100, 100, 0, 'Chiếc nhẫn xếp chồng quế được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:43:21.000000');
INSERT INTO `product` VALUES (1758, 'Nhẫn bạch đậu khấu pha lê thô', 1591750, 1591750, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê bạch đậu khấu thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với lớp vỏ bạch đậu khấu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:43:24.000000');
INSERT INTO `product` VALUES (1759, 'Nến sáp ong cỏ ba lá đổ tay', 713000, 713000, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu cỏ ba lá. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:43:26.000000');
INSERT INTO `product` VALUES (1760, 'Nến thơm cây kế sáp dừa', 1027000, 1027000, 100, 100, 0, 'Nến thơm cây kế lô nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:43:28.000000');
INSERT INTO `product` VALUES (1761, 'Macramé Wisteria treo tường', 3131500, 3131500, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo treo trên dây bông tự nhiên hoa tử đằng. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:43:29.000000');
INSERT INTO `product` VALUES (1762, 'Vòng hoa hồng tước khô', 1523000, 1523000, 100, 100, 0, 'Vòng hoa khô thủ công có hình các loài thực vật theo mùa. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:43:31.000000');
INSERT INTO `product` VALUES (1763, 'Kệ Gỗ Falcon Chạm Khắc Bằng Tay', 3028500, 3028500, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh chim ưng. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:43:33.000000');
INSERT INTO `product` VALUES (1764, 'Thớt quả óc chó Osprey cuối hạt', 1457500, 1457500, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó chim ưng và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:43:35.000000');
INSERT INTO `product` VALUES (1765, 'Bộ bát sứ Hawkweed ném tay', 2870500, 2870500, 100, 100, 0, 'Bộ 4 chiếc bát gốm sứ thủ công phủ men phản ứng hawkweed. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:43:36.000000');
INSERT INTO `product` VALUES (1766, 'Mũ len Merino Dogwood dệt kim bằng tay', 688500, 688500, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu sơn thù du. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:43:39.000000');
INSERT INTO `product` VALUES (1767, 'Dây buộc tóc bằng ren Sweetgrass', 395750, 395750, 100, 100, 0, 'Dây buộc móc thủ công với họa tiết ren bông cỏ ngọt. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:43:41.000000');
INSERT INTO `product` VALUES (1768, 'Khăn choàng lụa đuôi mèo nhuộm tay', 3117500, 3117500, 100, 100, 0, 'Khăn choàng lụa nhuộm tay sang trọng họa tiết màu nước đuôi mèo. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:43:43.000000');
INSERT INTO `product` VALUES (1769, 'Ly hợp da Bullrush khâu tay', 3242000, 3242000, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay bằng da bò. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:43:46.000000');
INSERT INTO `product` VALUES (1770, 'Ba lô vải cói sáp', 4679000, 4679000, 100, 100, 0, 'Balo vải sáp dày dặn viền da cói. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:43:48.000000');
INSERT INTO `product` VALUES (1771, 'Tranh sáp Encaustic Bracken nguyên bản', 3481000, 3481000, 100, 100, 0, 'Bức tranh sơn dầu nguyên bản (sáp nóng) với bố cục trừu tượng dương xỉ. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:43:50.000000');
INSERT INTO `product` VALUES (1772, 'Tượng gốm me chua điêu khắc bằng tay', 1452000, 1452000, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết được tráng men màu me chua. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:43:54.000000');
INSERT INTO `product` VALUES (1773, 'In ảnh thiên nhiên hoa cúc thiên nhiên mỹ thuật', 1466750, 1466750, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên hoa cúc nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:43:56.000000');
INSERT INTO `product` VALUES (1774, 'Xà phòng nghệ nhân cỏ thi sữa dê', 236250, 236250, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm cỏ thi và các tạp chất thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:43:58.000000');
INSERT INTO `product` VALUES (1775, 'Dầu gội Solid Valerian', 226500, 226500, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược valerian. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:44:00.000000');
INSERT INTO `product` VALUES (1776, 'Tẩy tế bào chết toàn thân bằng đường Mugwort', 775500, 775500, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường ngải cứu thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu ngải cứu. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:44:03.000000');
INSERT INTO `product` VALUES (1777, 'Tạp chí da cây tầm ma đóng bìa tay', 829000, 829000, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da cây tầm ma và sợi vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:44:05.000000');
INSERT INTO `product` VALUES (1778, 'Thiệp cưới cây ngưu bàng màu nước', 310750, 310750, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật cây ngưu bàng. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:44:07.000000');
INSERT INTO `product` VALUES (1779, 'Câu đố bằng gỗ hình bông tuyết vẽ tay', 741750, 741750, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay hình giọt nước tuyết. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:44:09.000000');
INSERT INTO `product` VALUES (1780, 'Đũa phép đồ chơi cho mèo Crocus bện bằng tay', 383250, 383250, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây bông bện hoa nghệ tây và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:44:12.000000');
INSERT INTO `product` VALUES (1781, 'Vòng cổ mặt dây chuyền đá mặt trăng Trillium thủ công', 1807250, 1807250, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng trillium chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:44:14.000000');
INSERT INTO `product` VALUES (1782, 'Tên tùy chỉnh Vòng cổ lấp đầy vàng Bloodroot', 1563000, 1563000, 100, 100, 0, 'Vòng cổ tên Bloodroot cá nhân hóa được đóng dấu thủ công trên đĩa phủ vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:44:17.000000');
INSERT INTO `product` VALUES (1783, 'Vòng cổ mặt dây chuyền Hepatica phong cách cổ điển', 1674750, 1674750, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng Hepatica lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:44:19.000000');
INSERT INTO `product` VALUES (1784, 'Vòng tay tình bạn Mayapple dệt tay', 489750, 489750, 100, 100, 0, 'Vòng tay tình bạn mayapple dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:44:21.000000');
INSERT INTO `product` VALUES (1785, 'Vòng đeo tay bằng đồng rèn Elderflower', 1348500, 1348500, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ hình hoa cơm cháy. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:44:24.000000');
INSERT INTO `product` VALUES (1786, 'Vòng tay đá quý Hawthorn đính cườm', 456750, 456750, 100, 100, 0, 'Vòng tay hạt đá quý táo gai được xâu chuỗi bằng dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:44:26.000000');
INSERT INTO `product` VALUES (1787, 'Bông tai bạc Blackthorn được rèn thủ công', 596500, 596500, 100, 100, 0, 'Bông tai đinh tán bằng bạc sterling được rèn thủ công với kết cấu gai đen. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:44:29.000000');
INSERT INTO `product` VALUES (1788, 'Bông tai pha lê Rowan có dây', 1396000, 1396000, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê thanh lương trà. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:44:31.000000');
INSERT INTO `product` VALUES (1789, 'Vòng xếp chồng Sloe được đóng dấu bằng tay', 789000, 789000, 100, 100, 0, 'Chiếc nhẫn xếp chồng sloe được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:44:33.000000');
INSERT INTO `product` VALUES (1790, 'Nhẫn pha lê Damson thô', 1554000, 1554000, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê Damson thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với lớp gỉ dadamson.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:44:36.000000');
INSERT INTO `product` VALUES (1791, 'Nến sáp ong hồng đổ bằng tay', 452750, 452750, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu hồng. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:44:37.000000');
INSERT INTO `product` VALUES (1792, 'Nến thơm mộc qua sáp dừa', 1003000, 1003000, 100, 100, 0, 'Nến thơm mộc qua lô nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:44:38.000000');
INSERT INTO `product` VALUES (1793, 'Treo tường Macramé Medlar', 2485500, 2485500, 100, 100, 0, 'Bức tường macramé thắt nút thủ công phức tạp treo bằng dây bông tự nhiên sơn tra. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:44:40.000000');
INSERT INTO `product` VALUES (1794, 'Vòng hoa dâu tằm khô', 1013500, 1013500, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa dâu tằm. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:44:41.000000');
INSERT INTO `product` VALUES (1795, 'Kệ Gỗ Ngỗng Chạm Khắc Bằng Tay', 1685750, 1685750, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh quả lý gai. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:44:43.000000');
INSERT INTO `product` VALUES (1796, 'Thớt quả óc chó việt quất cuối hạt', 4073750, 4073750, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó việt quất và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:44:45.000000');
INSERT INTO `product` VALUES (1797, 'Bộ bát gốm Crowberry ném tay', 2176000, 2176000, 100, 100, 0, 'Bộ 4 chiếc bát sứ cầm tay phủ men phản ứng quả quạ. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:44:47.000000');
INSERT INTO `product` VALUES (1798, 'Mũ len Merino Cloudberry dệt kim bằng tay', 1130750, 1130750, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ 100% len merino superwash với màu sắc dâu tây. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:44:49.000000');
INSERT INTO `product` VALUES (1799, 'Dây buộc tóc bằng ren Lingonberry', 250000, 250000, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông lingonberry. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:44:51.000000');
INSERT INTO `product` VALUES (1800, 'Khăn choàng lụa Bearberry nhuộm tay', 2921000, 2921000, 100, 100, 0, 'Khăn choàng lụa quấn tay sang trọng họa tiết màu nước Bearberry. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:44:54.000000');
INSERT INTO `product` VALUES (1801, 'Ly hợp da Hackberry khâu tay', 1739750, 1739750, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay hackberry. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:44:56.000000');
INSERT INTO `product` VALUES (1802, 'Ba lô Buffaloberry vải sáp', 5464500, 5464500, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da trâu. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:44:58.000000');
INSERT INTO `product` VALUES (1803, 'Tranh sáp Aurora nguyên bản', 4563000, 4563000, 100, 100, 0, 'Bức tranh sơn dầu nguyên bản (sáp nóng) với bố cục trừu tượng cực quang. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:45:00.000000');
INSERT INTO `product` VALUES (1804, 'Tượng gốm Chạng vạng được điêu khắc bằng tay', 1849750, 1849750, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết được tráng men chạng vạng. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:45:03.000000');
INSERT INTO `product` VALUES (1805, 'Mỹ thuật Heather Nature Ảnh In', 813750, 813750, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên cây thạch nam nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:45:06.000000');
INSERT INTO `product` VALUES (1806, 'Xà Phòng Nghệ Nhân Gỗ Lũa Sữa Dê', 244500, 244500, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm gỗ lũa và các tạp chất thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:45:08.000000');
INSERT INTO `product` VALUES (1807, 'Thanh gội đầu Solid Riverstone', 553250, 553250, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược riverstone. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:45:11.000000');
INSERT INTO `product` VALUES (1808, 'Tẩy tế bào chết Sugar Pebble Beach', 389750, 389750, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường sỏi bãi biển thủ công với gốc dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu bãi biển sỏi. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:45:13.000000');
INSERT INTO `product` VALUES (1809, 'Tạp chí da Foxglove ràng buộc bằng tay', 1569250, 1569250, 100, 100, 0, 'Nhật ký đóng bìa tay với bìa da mao địa hoàng và dây vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:45:16.000000');
INSERT INTO `product` VALUES (1810, 'Thiệp cưới Blackberry màu nước', 222000, 222000, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật dâu đen. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:45:19.000000');
INSERT INTO `product` VALUES (1811, 'Câu đố bằng gỗ quế vẽ tay', 1076750, 1076750, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay bằng quế. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:45:21.000000');
INSERT INTO `product` VALUES (1812, 'Cây đũa phép đồ chơi cho mèo bạch đậu khấu bện tay', 340750, 340750, 100, 100, 0, 'Đồ chơi đũa phép mèo thủ công với dây bông bện bạch đậu khấu và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:45:25.000000');
INSERT INTO `product` VALUES (1813, 'Vòng cổ mặt dây chuyền đá mặt trăng Clover thủ công', 2319750, 2319750, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng cỏ ba lá chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:45:27.000000');
INSERT INTO `product` VALUES (1814, 'Tên tùy chỉnh Vòng cổ mạ vàng Thistle', 891250, 891250, 100, 100, 0, 'Vòng cổ tên cây kế được cá nhân hóa được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:45:29.000000');
INSERT INTO `product` VALUES (1815, 'Vòng cổ mặt dây chuyền Wisteria phong cách cổ điển', 1284250, 1284250, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:45:31.000000');
INSERT INTO `product` VALUES (1816, 'Vòng tay tình bạn Wren dệt tay', 315250, 315250, 100, 100, 0, 'Vòng tay tình bạn wren dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:45:34.000000');
INSERT INTO `product` VALUES (1817, 'Vòng đeo tay bằng đồng hình chim ưng rèn', 1214750, 1214750, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ hình chim ưng. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:45:36.000000');
INSERT INTO `product` VALUES (1818, 'Vòng tay đá quý Osprey đính cườm', 1251750, 1251750, 100, 100, 0, 'Vòng tay hạt đá quý chim ưng được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:45:39.000000');
INSERT INTO `product` VALUES (1819, 'Bông tai bạc Hawkweed được rèn thủ công', 885250, 885250, 100, 100, 0, 'Bông tai đinh tán bằng bạc sterling được rèn thủ công với họa tiết hawkweed. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:45:41.000000');
INSERT INTO `product` VALUES (1820, 'Bông tai pha lê Dogwood bọc dây', 850000, 850000, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê bằng gỗ sơn thù du. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:45:43.000000');
INSERT INTO `product` VALUES (1821, 'Vòng xếp cỏ ngọt được đóng dấu bằng tay', 1034500, 1034500, 100, 100, 0, 'Chiếc nhẫn xếp chồng cỏ ngọt được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:45:46.000000');
INSERT INTO `product` VALUES (1822, 'Nhẫn tuyên bố Cattail pha lê thô', 1838500, 1838500, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê cattail thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thiện với patina đuôi mèo.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:45:48.000000');
INSERT INTO `product` VALUES (1823, 'Nến sáp ong Bullrush đổ bằng tay', 921500, 921500, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu cây bách xù. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:45:50.000000');
INSERT INTO `product` VALUES (1824, 'Nến thơm cói sáp dừa', 998500, 998500, 100, 100, 0, 'Nến thơm cói số lượng nhỏ làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:45:51.000000');
INSERT INTO `product` VALUES (1825, 'Treo tường Macramé Bracken', 3155500, 3155500, 100, 100, 0, 'Bức tường macramé được thắt nút bằng tay phức tạp treo bằng dây bông tự nhiên dương xỉ. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:45:53.000000');
INSERT INTO `product` VALUES (1826, 'Vòng hoa sầu riêng khô', 1854500, 1854500, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa màu me chua. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:45:55.000000');
INSERT INTO `product` VALUES (1827, 'Kệ Gỗ Hoa Cúc Chạm Khắc Bằng Tay', 3853000, 3853000, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết viền hoa cúc. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:45:56.000000');
INSERT INTO `product` VALUES (1828, 'Thớt quả óc chó Yarrow cuối hạt', 1982250, 1982250, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó yarrow và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:45:58.000000');
INSERT INTO `product` VALUES (1829, 'Bộ bát sứ Valerian ném tay', 1498000, 1498000, 100, 100, 0, 'Bộ 4 bát gốm sứ tráng men phản ứng valerian. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:46:00.000000');
INSERT INTO `product` VALUES (1830, 'Mũ len Merino Mugwort dệt kim bằng tay', 1502250, 1502250, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu ngải cứu. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:46:02.000000');
INSERT INTO `product` VALUES (1831, 'Dây buộc tóc bằng ren cây tầm ma', 434500, 434500, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông tầm ma. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:46:04.000000');
INSERT INTO `product` VALUES (1832, 'Khăn choàng lụa ngưu bàng nhuộm tay', 3050250, 3050250, 100, 100, 0, 'Khăn choàng quấn lụa nhuộm tay sang trọng họa tiết màu nước cây ngưu bàng. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:46:06.000000');
INSERT INTO `product` VALUES (1833, 'Ly hợp da Snowdrop khâu tay', 2426000, 2426000, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay hình giọt nước tuyết. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:46:09.000000');
INSERT INTO `product` VALUES (1834, 'Ba lô vải Crocus sáp', 4225750, 4225750, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da crocus. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:46:11.000000');
INSERT INTO `product` VALUES (1835, 'Tranh sáp gốc Trillium Encaustic', 5334500, 5334500, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng trillium. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:46:14.000000');
INSERT INTO `product` VALUES (1836, 'Tượng gốm Bloodroot điêu khắc bằng tay', 1482500, 1482500, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết men đỏ. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:46:16.000000');
INSERT INTO `product` VALUES (1837, 'Mỹ Thuật In Ảnh Thiên Nhiên Hepatica', 616750, 616750, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên Hepatica nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:46:19.000000');
INSERT INTO `product` VALUES (1838, 'Xà Phòng Thủ Công Mayapple Sữa Dê', 231250, 231250, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm mayapple và các chất thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:46:22.000000');
INSERT INTO `product` VALUES (1839, 'Thanh dầu gội Solid Elderflower', 391500, 391500, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược hoa cơm cháy. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:46:24.000000');
INSERT INTO `product` VALUES (1840, 'Tẩy tế bào chết toàn thân Sugar Hawthorn', 309000, 309000, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường táo gai thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu táo gai. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:46:27.000000');
INSERT INTO `product` VALUES (1841, 'Tạp chí da Blackthorn đóng bìa tay', 787000, 787000, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da mận gai và dây vải lanh đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:46:29.000000');
INSERT INTO `product` VALUES (1842, 'Thiệp cưới màu nước Rowan', 260000, 260000, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật thanh lương trà. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:46:31.000000');
INSERT INTO `product` VALUES (1843, 'Câu đố bằng gỗ Sloe vẽ tay', 1566250, 1566250, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay sloe. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:46:33.000000');
INSERT INTO `product` VALUES (1844, 'Đũa phép đồ chơi cho mèo Damson bện tay', 342250, 342250, 100, 100, 0, 'Đồ chơi đũa phép cho mèo được làm thủ công với dây cotton bện damson và phần đính kèm lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:46:35.000000');
INSERT INTO `product` VALUES (1845, 'Vòng cổ mặt dây chuyền đá mặt trăng hình trái hồng thủ công', 2029500, 2029500, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng hồng chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:46:37.000000');
INSERT INTO `product` VALUES (1846, 'Tên tùy chỉnh Vòng cổ Quince Gold-Fill', 1910250, 1910250, 100, 100, 0, 'Vòng cổ tên mộc qua được cá nhân hóa được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:46:40.000000');
INSERT INTO `product` VALUES (1847, 'Vòng cổ Medlar theo phong cách cổ điển', 1984500, 1984500, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:46:42.000000');
INSERT INTO `product` VALUES (1848, 'Vòng tay tình bạn dâu tằm dệt tay', 487000, 487000, 100, 100, 0, 'Vòng tay tình bạn dâu tằm dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:46:45.000000');
INSERT INTO `product` VALUES (1849, 'Vòng đeo tay bằng đồng rèn quả lý gai', 1747250, 1747250, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ màu quả lý gai. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:46:47.000000');
INSERT INTO `product` VALUES (1850, 'Vòng tay đá quý việt quất đính cườm', 589750, 589750, 100, 100, 0, 'Vòng tay hạt đá quý việt quất được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:46:49.000000');
INSERT INTO `product` VALUES (1851, 'Bông tai bạc Crowberry được rèn bằng tay', 940250, 940250, 100, 100, 0, 'Bông tai đinh tán bằng bạc được rèn thủ công với kết cấu quả quạ. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:46:52.000000');
INSERT INTO `product` VALUES (1852, 'Bông tai pha lê Cloudberry có dây', 873000, 873000, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn là pha lê hình quả mâm xôi. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:46:54.000000');
INSERT INTO `product` VALUES (1853, 'Vòng xếp chồng Lingonberry được đóng dấu bằng tay', 789000, 789000, 100, 100, 0, 'Nhẫn xếp chồng lingonberry được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:46:57.000000');
INSERT INTO `product` VALUES (1854, 'Nhẫn tuyên bố Bearberry pha lê thô', 1664250, 1664250, 100, 100, 0, 'Chiếc nhẫn nổi bật có pha lê Bearberry thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với lớp vỏ Bearberry.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:47:00.000000');
INSERT INTO `product` VALUES (1855, 'Nến sáp ong Hackberry đổ bằng tay', 512250, 512250, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu hackberry. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:47:02.000000');
INSERT INTO `product` VALUES (1856, 'Nến thơm sáp dừa Buffaloberry', 527750, 527750, 100, 100, 0, 'Nến thơm trâu hàng loạt nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:47:04.000000');
INSERT INTO `product` VALUES (1857, 'Treo tường Macramé Aurora', 1837000, 1837000, 100, 100, 0, 'Bức tường macramé thắt nút thủ công phức tạp treo bằng dây bông tự nhiên aurora. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:47:06.000000');
INSERT INTO `product` VALUES (1858, 'Vòng Hoa Chạng Vạng Hoa Khô', 906000, 906000, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa chạng vạng. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:47:08.000000');
INSERT INTO `product` VALUES (1859, 'Kệ Gỗ Thạch Anh Chạm Khắc Bằng Tay', 2998750, 2998750, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh thạch nam. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:47:10.000000');
INSERT INTO `product` VALUES (1860, 'Thớt gỗ óc chó lũa cuối hạt', 2035250, 2035250, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ gỗ óc chó và gỗ phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:47:12.000000');
INSERT INTO `product` VALUES (1861, 'Bộ bát sứ Riverstone ném tay', 1497500, 1497500, 100, 100, 0, 'Bộ 4 bát gốm sứ tráng men phản ứng riverstone. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:47:14.000000');
INSERT INTO `product` VALUES (1862, 'Mũ len Merino Beach dệt kim bằng tay', 833000, 833000, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ 100% len merino siêu giặt với màu sắc bãi biển sỏi. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:47:16.000000');
INSERT INTO `product` VALUES (1863, 'Móc buộc tóc ren Foxglove', 323500, 323500, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông foxglove. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:47:19.000000');
INSERT INTO `product` VALUES (1864, 'Khăn choàng lụa Blackberry nhuộm tay', 4141500, 4141500, 100, 100, 0, 'Khăn choàng quấn lụa nhuộm tay sang trọng họa tiết màu nước dâu đen. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:47:21.000000');
INSERT INTO `product` VALUES (1865, 'Ly hợp da quế khâu tay', 3210250, 3210250, 100, 100, 0, 'Ví cầm tay da thủ công với chi tiết khâu tay màu quế. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:47:24.000000');
INSERT INTO `product` VALUES (1866, 'Ba lô vải bạch đậu khấu', 3296000, 3296000, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da bạch đậu khấu. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:47:26.000000');
INSERT INTO `product` VALUES (1867, 'Tranh sáp cỏ ba lá nguyên bản', 3343500, 3343500, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng cỏ ba lá. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:47:29.000000');
INSERT INTO `product` VALUES (1868, 'Tượng gốm Thistle điêu khắc bằng tay', 2305750, 2305750, 100, 100, 0, 'Tượng gốm bằng đá được điêu khắc thủ công với các chi tiết tráng men cây kế. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:47:31.000000');
INSERT INTO `product` VALUES (1869, 'Mỹ thuật In ảnh thiên nhiên Wisteria', 1714750, 1714750, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên hoa đậu tía nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:47:33.000000');
INSERT INTO `product` VALUES (1870, 'Xà Phòng Nghệ Nhân Wren Sữa Dê', 235750, 235750, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm chim hồng tước và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:47:36.000000');
INSERT INTO `product` VALUES (1871, 'Thanh gội đầu Solid Falcon', 271750, 271750, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược chim ưng. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:47:38.000000');
INSERT INTO `product` VALUES (1872, 'Tẩy tế bào chết toàn thân Sugar Osprey', 476000, 476000, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường osprey thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu chim ưng. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:47:40.000000');
INSERT INTO `product` VALUES (1873, 'Tạp chí da Hawkweed ràng buộc bằng tay', 1829250, 1829250, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da diều hâu và sợi vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:47:42.000000');
INSERT INTO `product` VALUES (1874, 'Thiệp cưới màu nước Dogwood', 216250, 216250, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật cây dương đào. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:47:45.000000');
INSERT INTO `product` VALUES (1875, 'Câu đố bằng gỗ Sweetgrass vẽ tay', 858500, 858500, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay bằng cỏ ngọt. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:47:47.000000');
INSERT INTO `product` VALUES (1876, 'Đũa phép đồ chơi cho mèo đuôi mèo bện bằng tay', 200500, 200500, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây cotton bện đuôi mèo và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:47:50.000000');
INSERT INTO `product` VALUES (1877, 'Vòng cổ mặt dây chuyền đá mặt trăng Bullrush thủ công', 1254250, 1254250, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:47:53.000000');
INSERT INTO `product` VALUES (1878, 'Tên Tùy Chỉnh Vòng Cổ Cói Vàng Lấp Lánh', 989000, 989000, 100, 100, 0, 'Dây chuyền tên cói cá tính được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:47:56.000000');
INSERT INTO `product` VALUES (1879, 'Vòng cổ mặt dây chuyền Bracken theo phong cách cổ điển', 1707750, 1707750, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng dương xỉ lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:47:58.000000');
INSERT INTO `product` VALUES (1880, 'Vòng tay tình bạn cây me chua dệt tay', 209250, 209250, 100, 100, 0, 'Vòng tay tình bạn màu me chua dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:48:00.000000');
INSERT INTO `product` VALUES (1881, 'Vòng đeo tay bằng đồng hoa cúc rèn', 763000, 763000, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ màu hoa cúc. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:48:03.000000');
INSERT INTO `product` VALUES (1882, 'Vòng tay đá quý Yarrow đính cườm', 1032500, 1032500, 100, 100, 0, 'Vòng tay hạt đá quý cỏ thi được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:48:06.000000');
INSERT INTO `product` VALUES (1883, 'Bông tai bạc Valerian được rèn thủ công', 744250, 744250, 100, 100, 0, 'Bông tai đinh tán bằng bạc được rèn thủ công với họa tiết cây nữ lang. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:48:09.000000');
INSERT INTO `product` VALUES (1884, 'Bông tai pha lê Mugwort có dây', 1738750, 1738750, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn là pha lê ngải cứu. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:48:12.000000');
INSERT INTO `product` VALUES (1885, 'Vòng xếp chồng cây tầm ma được đóng dấu bằng tay', 711250, 711250, 100, 100, 0, 'Chiếc nhẫn xếp chồng cây tầm ma được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:48:14.000000');
INSERT INTO `product` VALUES (1886, 'Vòng tuyên bố cây ngưu bàng pha lê thô', 876500, 876500, 100, 100, 0, 'Chiếc nhẫn nổi bật có pha lê cây ngưu bàng thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với patina cây ngưu bàng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:48:16.000000');
INSERT INTO `product` VALUES (1887, 'Nến sáp ong hình giọt nước đổ bằng tay', 418250, 418250, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu giọt tuyết. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:48:18.000000');
INSERT INTO `product` VALUES (1888, 'Nến thơm sáp dừa Crocus', 620500, 620500, 100, 100, 0, 'Nến thơm hoa nghệ tây số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:48:20.000000');
INSERT INTO `product` VALUES (1889, 'Treo tường Macramé Trillium', 3031750, 3031750, 100, 100, 0, 'Bức tường macramé thắt nút bằng tay phức tạp treo bằng dây bông tự nhiên trillium. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:48:22.000000');
INSERT INTO `product` VALUES (1890, 'Vòng hoa huyết hoa khô', 1125250, 1125250, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa từ rễ huyết. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:48:23.000000');
INSERT INTO `product` VALUES (1891, 'Kệ Gỗ Hepatica Chạm Khắc Bằng Tay', 3809750, 3809750, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết viền gan. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:48:25.000000');
INSERT INTO `product` VALUES (1892, 'Thớt quả óc chó Mayapple cuối hạt', 2920500, 2920500, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó mayapple và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:48:27.000000');
INSERT INTO `product` VALUES (1893, 'Bộ bát gốm hoa cơm cháy cầm tay', 1504000, 1504000, 100, 100, 0, 'Bộ 4 bát gốm sứ tráng men phản ứng hoa cơm cháy. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:48:29.000000');
INSERT INTO `product` VALUES (1894, 'Mũ len Merino Hawthorn dệt kim bằng tay', 1149000, 1149000, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu táo gai. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:48:31.000000');
INSERT INTO `product` VALUES (1895, 'Dây buộc tóc ren gai đen móc', 229000, 229000, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren cotton gai đen. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:48:33.000000');
INSERT INTO `product` VALUES (1896, 'Khăn choàng lụa Rowan nhuộm tay', 4377750, 4377750, 100, 100, 0, 'Khăn choàng quấn lụa nhuộm tay sang trọng họa tiết màu nước thanh lương trà. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:48:36.000000');
INSERT INTO `product` VALUES (1897, 'Ly Hợp Da Sloe Khâu Tay', 1796250, 1796250, 100, 100, 0, 'Ví cầm tay bằng da có chi tiết khâu tay. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:48:38.000000');
INSERT INTO `product` VALUES (1898, 'Ba lô vải sáp Damson', 5057250, 5057250, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da damson. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:48:40.000000');
INSERT INTO `product` VALUES (1899, 'Tranh sáp màu quả hồng nguyên chất', 4484750, 4484750, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng quả hồng. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:48:43.000000');
INSERT INTO `product` VALUES (1900, 'Tượng gốm mộc qua điêu khắc bằng tay', 2086500, 2086500, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết tráng men mộc qua. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:48:45.000000');
INSERT INTO `product` VALUES (1901, 'In ảnh thiên nhiên Mỹ thuật Medlar', 1823250, 1823250, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên sơn tra gốc. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:48:48.000000');
INSERT INTO `product` VALUES (1902, 'Xà phòng thủ công dâu tằm sữa dê', 316250, 316250, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm dâu tằm và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:48:50.000000');
INSERT INTO `product` VALUES (1903, 'Thanh gội đầu Gooseberry rắn', 577750, 577750, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo mộc quả lý gai. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:48:52.000000');
INSERT INTO `product` VALUES (1904, 'Tẩy tế bào chết toàn thân bằng đường việt quất', 360000, 360000, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường việt quất thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu việt quất. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:48:55.000000');
INSERT INTO `product` VALUES (1905, 'Tạp chí da Crowberry đóng bìa tay', 908000, 908000, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da quạ và sợi vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:48:57.000000');
INSERT INTO `product` VALUES (1906, 'Thiệp cưới màu nước Cloudberry', 294500, 294500, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật cây mâm xôi. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:49:00.000000');
INSERT INTO `product` VALUES (1907, 'Câu đố bằng gỗ Lingonberry vẽ tay', 1160500, 1160500, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay lingonberry. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:49:02.000000');
INSERT INTO `product` VALUES (1908, 'Cây đũa phép đồ chơi cho mèo Bearberry bện tay', 239500, 239500, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây cotton bện hình quả dâu và phần đính kèm lông tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:49:04.000000');
INSERT INTO `product` VALUES (1909, 'Vòng cổ mặt dây chuyền đá mặt trăng Hackberry thủ công', 1555500, 1555500, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng hackberry chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:49:06.000000');
INSERT INTO `product` VALUES (1910, 'Tên tùy chỉnh Vòng cổ lấp đầy vàng Buffaloberry', 1314000, 1314000, 100, 100, 0, 'Vòng cổ tên Buffaloberry cá tính được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:49:08.000000');
INSERT INTO `product` VALUES (1911, 'Vòng cổ Aurora Locket theo phong cách cổ điển', 1670500, 1670500, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng thau aurora lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:49:10.000000');
INSERT INTO `product` VALUES (1912, 'Vòng tay tình bạn Chạng vạng dệt tay', 676750, 676750, 100, 100, 0, 'Vòng tay tình bạn chạng vạng dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:49:12.000000');
INSERT INTO `product` VALUES (1913, 'Vòng đeo tay bằng đồng rèn thạch cao', 1716000, 1716000, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ màu thạch nam. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:49:15.000000');
INSERT INTO `product` VALUES (1914, 'Vòng tay đá quý lũa đính cườm', 1295500, 1295500, 100, 100, 0, 'Vòng tay hạt đá quý bằng gỗ lũa được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:49:17.000000');
INSERT INTO `product` VALUES (1915, 'Bông tai bạc Riverstone được rèn thủ công', 546500, 546500, 100, 100, 0, 'Khuyên tai dạng đinh tán bằng bạc được rèn thủ công với kết cấu bằng đá ven sông. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:49:20.000000');
INSERT INTO `product` VALUES (1916, 'Bông tai pha lê Pebble Beach có dây', 820500, 820500, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn là pha lê bãi biển sỏi. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:49:23.000000');
INSERT INTO `product` VALUES (1917, 'Vòng xếp chồng Foxglove được đóng dấu bằng tay', 919500, 919500, 100, 100, 0, 'Chiếc nhẫn xếp chồng hình cáo được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:49:25.000000');
INSERT INTO `product` VALUES (1918, 'Nhẫn tuyên bố Blackberry pha lê thô', 1350750, 1350750, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê blackberry thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với lớp vỏ blackberry.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:49:27.000000');
INSERT INTO `product` VALUES (1919, 'Nến sáp ong quế đổ bằng tay', 603750, 603750, 100, 100, 0, 'Nến sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu quế. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:49:29.000000');
INSERT INTO `product` VALUES (1920, 'Nến thơm sáp dừa bạch đậu khấu', 573250, 573250, 100, 100, 0, 'Nến thơm thảo quả lô nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:49:31.000000');
INSERT INTO `product` VALUES (1921, 'Macramé Cỏ Ba Lá Treo Tường', 3342750, 3342750, 100, 100, 0, 'Bức tường macramé được thắt nút bằng tay phức tạp treo bằng dây bông tự nhiên hình cỏ ba lá. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:49:32.000000');
INSERT INTO `product` VALUES (1922, 'Vòng hoa kế khô', 1217000, 1217000, 100, 100, 0, 'Vòng hoa khô thủ công có hình cây kế theo mùa. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:49:34.000000');
INSERT INTO `product` VALUES (1923, 'Kệ gỗ hoa tử đằng chạm khắc thủ công', 2281750, 2281750, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh hoa tử đằng. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:49:36.000000');
INSERT INTO `product` VALUES (1924, 'Thớt quả óc chó Wren cuối hạt', 1703750, 1703750, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó wren và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:49:37.000000');
INSERT INTO `product` VALUES (1925, 'Bộ Bát Sứ Falcon Ném Tay', 3069500, 3069500, 100, 100, 0, 'Bộ 4 bát gốm sứ cầm tay phủ men phản ứng hình chim ưng. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:49:39.000000');
INSERT INTO `product` VALUES (1926, 'Mũ len Osprey Merino dệt kim bằng tay', 1323250, 1323250, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ 100% len merino superwash với màu sắc chim ưng. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:49:41.000000');
INSERT INTO `product` VALUES (1927, 'Móc buộc tóc ren Hawkweed', 198250, 198250, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông hawkweed. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:49:44.000000');
INSERT INTO `product` VALUES (1928, 'Khăn choàng lụa Dogwood nhuộm tay', 3835250, 3835250, 100, 100, 0, 'Khăn choàng quấn lụa nhuộm tay sang trọng với hoa văn màu nước bằng gỗ sơn thù du. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:49:46.000000');
INSERT INTO `product` VALUES (1929, 'Ly hợp da Sweetgrass khâu tay', 3378250, 3378250, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay sweetgrass. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:49:48.000000');
INSERT INTO `product` VALUES (1930, 'Ba lô Cattail vải sáp', 3674250, 3674250, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da đuôi mèo. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:49:50.000000');
INSERT INTO `product` VALUES (1931, 'Tranh sáp Encaustic Bullrush nguyên bản', 5323250, 5323250, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng của cây bò tót. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:49:52.000000');
INSERT INTO `product` VALUES (1932, 'Tượng gốm cói điêu khắc bằng tay', 1638000, 1638000, 100, 100, 0, 'Tượng gốm sứ điêu khắc thủ công với các chi tiết bằng men cói. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:49:54.000000');
INSERT INTO `product` VALUES (1933, 'Mỹ Thuật In Ảnh Thiên Nhiên Bracken', 1584500, 1584500, 100, 100, 0, 'Lưu trữ bản in mỹ thuật của bức ảnh thiên nhiên dương xỉ nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:49:57.000000');
INSERT INTO `product` VALUES (1934, 'Xà Phòng Thủ Công Sữa Dê Sorrel', 472750, 472750, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm cây me chua và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:49:59.000000');
INSERT INTO `product` VALUES (1935, 'Thanh gội đầu hoa cúc rắn', 238500, 238500, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược hoa cúc. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:50:01.000000');
INSERT INTO `product` VALUES (1936, 'Tẩy tế bào chết Sugar Yarrow', 364000, 364000, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường cỏ thi thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu cỏ thi. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:50:04.000000');
INSERT INTO `product` VALUES (1937, 'Tạp chí da Valerian ràng buộc tay', 831250, 831250, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da valerian và sợi vải lanh đóng bìa bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:50:06.000000');
INSERT INTO `product` VALUES (1938, 'Thiệp cưới màu nước ngải cứu', 156750, 156750, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật ngải cứu. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:50:08.000000');
INSERT INTO `product` VALUES (1939, 'Câu đố bằng gỗ cây tầm ma vẽ tay', 675000, 675000, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay bằng cây tầm ma. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:50:10.000000');
INSERT INTO `product` VALUES (1940, 'Đũa phép đồ chơi cho mèo ngưu bàng bện bằng tay', 408000, 408000, 100, 100, 0, 'Đồ chơi đũa phép mèo được làm thủ công với dây cotton bện cây ngưu bàng và phần đính kèm lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:50:12.000000');
INSERT INTO `product` VALUES (1941, 'Vòng cổ mặt dây chuyền đá mặt trăng hình giọt nước thủ công', 915500, 915500, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng hình giọt nước chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:50:15.000000');
INSERT INTO `product` VALUES (1942, 'Tên tùy chỉnh Vòng cổ Crocus Gold-Fill', 2648750, 2648750, 100, 100, 0, 'Vòng cổ tên crocus cá tính được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:50:17.000000');
INSERT INTO `product` VALUES (1943, 'Vòng cổ Trillium Locket theo phong cách cổ điển', 1681250, 1681250, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng trillium lấy cảm hứng từ cổ. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:50:20.000000');
INSERT INTO `product` VALUES (1944, 'Vòng tay tình bạn Bloodroot dệt tay', 510000, 510000, 100, 100, 0, 'Vòng tay tình bạn rễ cây máu được dệt thủ công bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:50:22.000000');
INSERT INTO `product` VALUES (1945, 'Vòng đeo tay bằng đồng Hepatica rèn', 612250, 612250, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn thủ công với lớp gỉ màu Hepatica. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:50:24.000000');
INSERT INTO `product` VALUES (1946, 'Vòng tay đá quý Mayapple đính cườm', 1105500, 1105500, 100, 100, 0, 'Vòng tay hạt đá quý mayapple được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:50:26.000000');
INSERT INTO `product` VALUES (1947, 'Bông tai bạc hình hoa cơm cháy được rèn thủ công', 703000, 703000, 100, 100, 0, 'Bông tai bạc sterling được rèn thủ công với họa tiết hoa cơm cháy. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:50:28.000000');
INSERT INTO `product` VALUES (1948, 'Bông tai pha lê Hawthorn có dây', 1828500, 1828500, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn bằng pha lê táo gai. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:50:33.000000');
INSERT INTO `product` VALUES (1949, 'Vòng xếp chồng Blackthorn được đóng dấu bằng tay', 838500, 838500, 100, 100, 0, 'Chiếc nhẫn xếp chồng cây gai đen được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:50:35.000000');
INSERT INTO `product` VALUES (1950, 'Nhẫn pha lê Rowan thô', 1522000, 1522000, 100, 100, 0, 'Chiếc nhẫn nổi bật có pha lê thanh lương trà thô được làm bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thành với lớp vỏ thanh lương trà.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:50:38.000000');
INSERT INTO `product` VALUES (1951, 'Nến sáp ong Sloe đổ bằng tay', 396750, 396750, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu sloe. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:50:39.000000');
INSERT INTO `product` VALUES (1952, 'Nến thơm sáp dừa Damson', 475750, 475750, 100, 100, 0, 'Nến thơm Damson số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:50:40.000000');
INSERT INTO `product` VALUES (1953, 'Quả Hồng Macramé Treo Tường', 2967500, 2967500, 100, 100, 0, 'Bức tường macramé thắt nút tinh xảo treo trên dây bông tự nhiên màu hồng. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:50:42.000000');
INSERT INTO `product` VALUES (1954, 'Vòng hoa mộc qua khô', 1654750, 1654750, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa mộc qua. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:50:44.000000');
INSERT INTO `product` VALUES (1955, 'Kệ gỗ Medlar chạm khắc thủ công', 3310500, 3310500, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh sơn tra. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:50:45.000000');
INSERT INTO `product` VALUES (1956, 'Thớt quả óc chó dâu tằm cuối hạt', 1648250, 1648250, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó dâu và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:50:47.000000');
INSERT INTO `product` VALUES (1957, 'Bộ bát sứ ném quả lý gai bằng tay', 2565750, 2565750, 100, 100, 0, 'Bộ 4 chiếc bát sứ cầm tay phủ men phản ứng quả lý gai. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:50:49.000000');
INSERT INTO `product` VALUES (1958, 'Mũ len Merino Bilberry đan tay', 1275250, 1275250, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu việt quất. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:50:51.000000');
INSERT INTO `product` VALUES (1959, 'Dây buộc tóc bằng ren Crochet Crowberry', 386500, 386500, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren cotton dâu tây. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:50:54.000000');
INSERT INTO `product` VALUES (1960, 'Khăn choàng lụa Cloudberry nhuộm tay', 3503000, 3503000, 100, 100, 0, 'Khăn choàng lụa nhuộm tay sang trọng họa tiết màu nước mâm xôi. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:50:56.000000');
INSERT INTO `product` VALUES (1961, 'Ly hợp da Lingonberry khâu tay', 1687500, 1687500, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay lingonberry. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:50:58.000000');
INSERT INTO `product` VALUES (1962, 'Ba lô Bearberry vải sáp', 3118750, 3118750, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da Bearberry. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:51:01.000000');
INSERT INTO `product` VALUES (1963, 'Tranh sáp nguyên chất Hackberry', 4441250, 4441250, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng hackberry. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:51:04.000000');
INSERT INTO `product` VALUES (1964, 'Tượng gốm Buffaloberry điêu khắc bằng tay', 2258500, 2258500, 100, 100, 0, 'Tượng gốm bằng đá được điêu khắc thủ công với các chi tiết tráng men dâu. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:51:06.000000');
INSERT INTO `product` VALUES (1965, 'In ảnh thiên nhiên cực quang mỹ thuật', 1237500, 1237500, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên cực quang nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:51:08.000000');
INSERT INTO `product` VALUES (1966, 'Xà phòng nghệ nhân Twilight Artisan sữa dê', 253500, 253500, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm hoàng hôn và các thành phần thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:51:10.000000');
INSERT INTO `product` VALUES (1967, 'Thanh gội đầu Solid Heather', 578500, 578500, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược thạch nam. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:51:12.000000');
INSERT INTO `product` VALUES (1968, 'Tẩy tế bào chết bằng gỗ lũa đường', 275250, 275250, 100, 100, 0, 'Tẩy tế bào chết bằng đường gỗ lũa thủ công gốc dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu gỗ lũa. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:51:15.000000');
INSERT INTO `product` VALUES (1969, 'Tạp chí da Riverstone đóng bìa tay', 1686000, 1686000, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da bằng đá ven sông và dây vải lanh được đóng bằng đường khâu kiểu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:51:17.000000');
INSERT INTO `product` VALUES (1970, 'Thiệp cưới màu nước trên bãi biển Pebble', 296500, 296500, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật trên bãi biển sỏi. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:51:20.000000');
INSERT INTO `product` VALUES (1971, 'Câu đố bằng gỗ Foxglove vẽ tay', 581250, 581250, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay foxglove. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:51:22.000000');
INSERT INTO `product` VALUES (1972, 'Cây đũa phép đồ chơi cho mèo Blackberry bện tay', 287000, 287000, 100, 100, 0, 'Đồ chơi đũa phép mèo thủ công với dây cotton bện dâu đen và gắn lông vũ tự nhiên. Đũa 12 inch có đuôi ruy băng 18 inch. Catnip truyền vào. Có lông thay thế.', 'active', 'do_dung_cho_thu_cung', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:51:25.000000');
INSERT INTO `product` VALUES (1973, 'Vòng cổ mặt dây chuyền đá mặt trăng quế thủ công', 2091250, 2091250, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng quế chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:51:28.000000');
INSERT INTO `product` VALUES (1974, 'Tên tùy chỉnh Vòng cổ lấp đầy vàng bạch đậu khấu', 2439250, 2439250, 100, 100, 0, 'Vòng cổ tên bạch đậu khấu được cá nhân hóa được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:51:30.000000');
INSERT INTO `product` VALUES (1975, 'Vòng cổ Mề đay cỏ ba lá phong cách cổ điển', 2862500, 2862500, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng cỏ ba lá lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:51:34.000000');
INSERT INTO `product` VALUES (1976, 'Vòng tay tình bạn cây kế dệt tay', 426250, 426250, 100, 100, 0, 'Vòng tay tình bạn cây kế dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:51:36.000000');
INSERT INTO `product` VALUES (1977, 'Vòng đeo tay bằng đồng Wisteria rèn', 792000, 792000, 100, 100, 0, 'Vòng đeo tay bằng đồng nguyên chất được rèn bằng tay với lớp gỉ hoa tử đằng. Có thể điều chỉnh độ mở phù hợp với hầu hết các kích cỡ cổ tay. Mỗi mảnh là duy nhất do quá trình đóng búa. Chiều rộng: 3/4 inch.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:51:39.000000');
INSERT INTO `product` VALUES (1978, 'Vòng tay đá quý Wren đính cườm', 1472000, 1472000, 100, 100, 0, 'Vòng tay hạt đá quý wren được xâu chuỗi trên dây co giãn bền. Có hạt đá tự nhiên 8mm. Phù hợp với cổ tay lên đến 7,5 inch. Mỗi hạt là đá tự nhiên chính hãng.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:51:41.000000');
INSERT INTO `product` VALUES (1979, 'Bông tai bạc hình chim ưng được rèn thủ công', 821500, 821500, 100, 100, 0, 'Bông tai bạc sterling được rèn thủ công với họa tiết chim ưng. Trụ cột được làm bằng bạc 925 có mặt sau hình con bướm. Không chứa niken và không gây dị ứng. Đường kính khoảng 10 mm.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:51:44.000000');
INSERT INTO `product` VALUES (1980, 'Bông tai pha lê Osprey có dây', 1850500, 1850500, 100, 100, 0, 'Khuyên tai dạng vòng quấn dây thủ công có điểm nhấn là pha lê chim ưng. Được làm bằng dây bạc sterling 20 thước. Đường kính vòng: 35mm. Nhẹ và thoải mái khi mặc hàng ngày.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:51:47.000000');
INSERT INTO `product` VALUES (1981, 'Vòng xếp chồng Hawkweed được đóng dấu bằng tay', 352000, 352000, 100, 100, 0, 'Chiếc nhẫn xếp chồng diều hâu được đóng dấu thủ công bằng bạc sterling. Có sẵn trong các kích cỡ 4-12 bao gồm một nửa kích cỡ. Dải rộng 2 mm. Có thể được cá nhân hóa bằng một từ hoặc ngày theo yêu cầu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:51:49.000000');
INSERT INTO `product` VALUES (1982, 'Nhẫn pha lê thô Dogwood', 769750, 769750, 100, 100, 0, 'Chiếc nhẫn táo bạo có pha lê gỗ sơn thù du thô được đặt bằng đồng thau tái chế. Dây đeo có thể điều chỉnh phù hợp với kích cỡ 6-9. Mỗi tinh thể là duy nhất về hình dạng và màu sắc. Hoàn thiện với lớp gỉ gỗ sơn thù du.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:51:52.000000');
INSERT INTO `product` VALUES (1983, 'Nến sáp ong Sweetgrass đổ bằng tay', 589250, 589250, 100, 100, 0, 'Nến trụ sáp ong nguyên chất được đổ bằng tay hỗn hợp tinh dầu cỏ ngọt. Lưu hương tới 40 giờ với hương mật ong tự nhiên. Không có chất phụ gia hoặc hương thơm nhân tạo. Đường kính: 3 inch, Chiều cao: 4 inch.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:51:54.000000');
INSERT INTO `product` VALUES (1984, 'Nến thơm Cattail sáp dừa', 935750, 935750, 100, 100, 0, 'Nến thơm đuôi mèo số lượng nhỏ được làm bằng sáp dừa bền vững. Bấc gỗ tạo ra âm thanh tanh tách nhẹ nhàng. Ném hương thơm là tuyệt vời. lọ thủy tinh 8oz. Đốt cháy hơn 55 giờ.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:51:56.000000');
INSERT INTO `product` VALUES (1985, 'Treo tường Macramé Bullrush', 2326500, 2326500, 100, 100, 0, 'Bức tường macramé được thắt nút bằng tay phức tạp treo bằng dây bông tự nhiên có màu nâu đỏ. Có nhiều lớp tua rua và các mẫu nút hình học. Bao gồm chốt gỗ lũa. Kích thước: 20\"W x 40\"L.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:51:57.000000');
INSERT INTO `product` VALUES (1986, 'Vòng hoa cói khô', 1250500, 1250500, 100, 100, 0, 'Vòng hoa khô được làm thủ công có các loại thực vật cói theo mùa. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:51:59.000000');
INSERT INTO `product` VALUES (1987, 'Kệ Gỗ Bracken Chạm Khắc Bằng Tay', 2527000, 2527000, 100, 100, 0, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết viền dương xỉ. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:52:01.000000');
INSERT INTO `product` VALUES (1988, 'Thớt quả óc chó sầu riêng cuối hạt', 2332000, 2332000, 100, 100, 0, 'Thớt gỗ cứng thớ cuối được làm thủ công từ quả óc chó me chua và cây phong. Nhẹ nhàng trên các cạnh dao. Rãnh nước ép ở một bên. Được bôi bằng dầu khoáng an toàn thực phẩm. dày 12\"x9\"x1,5\".', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:52:02.000000');
INSERT INTO `product` VALUES (1989, 'Bộ bát sứ hoa cúc ném tay', 3142500, 3142500, 100, 100, 0, 'Bộ 4 bát gốm sứ tráng men phản ứng hoa cúc. Mỗi bát chứa 16oz. Lò vi sóng, máy rửa chén và lò nướng an toàn ở nhiệt độ 350°F. Những biến thể nhỏ trong men làm cho mỗi bộ trở nên độc đáo.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:52:04.000000');
INSERT INTO `product` VALUES (1990, 'Mũ len Yarrow Merino dệt kim bằng tay', 999250, 999250, 100, 100, 0, 'Mũ len dệt kim thủ công ấm cúng được làm từ len merino 100% superwash với màu yarrow. Cấu trúc gân co giãn phù hợp với hầu hết các kích cỡ đầu. Có thể giặt bằng máy với chu kỳ nhẹ nhàng.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:52:06.000000');
INSERT INTO `product` VALUES (1991, 'Móc dây buộc tóc bằng ren Valerian', 226500, 226500, 100, 100, 0, 'Dây buộc tóc móc thủ công theo mẫu ren bông nữ lang. Nhẹ nhàng trên tóc, không gây hư tổn hay xoắn. Dây thun co giãn bên trong. Phù hợp với kiểu tóc đuôi ngựa hoặc búi tóc. Bán theo bộ 3.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:52:09.000000');
INSERT INTO `product` VALUES (1992, 'Khăn choàng lụa Mugwort nhuộm tay', 3289250, 3289250, 100, 100, 0, 'Khăn choàng lụa nhuộm tay sang trọng họa tiết màu nước ngải cứu. 100% lụa habotai. Kích thước 72\"x22\". Mỗi chiếc khăn choàng đều có một không hai do quá trình nhuộm tay.', 'active', 'quan_ao', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:52:12.000000');
INSERT INTO `product` VALUES (1993, 'Ly hợp da cây tầm ma khâu tay', 2176500, 2176500, 100, 100, 0, 'Ví cầm tay bằng da thủ công với chi tiết khâu tay bằng cây tầm ma. Da thuộc thực vật nguyên hạt. Túi có khóa kéo bên trong. Đóng cửa bằng nam châm. Kích thước: 9\"x5\". Bao gồm dây đeo cổ tay.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:52:14.000000');
INSERT INTO `product` VALUES (1994, 'Ba lô vải cây ngưu bàng sáp', 5023750, 5023750, 100, 100, 0, 'Ba lô vải sáp hạng nặng có viền da cây ngưu bàng. Bên ngoài chống thấm nước, ngăn đựng máy tính xách tay có đệm (vừa 15\"). Túi bên ngoài và bên trong. Phần cứng bằng đồng cổ. Dung tích: 20L.', 'active', 'tui_vi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:52:16.000000');
INSERT INTO `product` VALUES (1995, 'Tranh sáp bông tuyết nguyên bản', 1950500, 1950500, 100, 100, 0, 'Bức tranh vẽ nguyên bản (sáp nóng) với bố cục trừu tượng giọt tuyết. Các lớp sáp ong sắc tố kết hợp với nhiệt để tạo ra độ sáng sâu. 8\"x10\" trên bảng bạch dương. Sẵn sàng để treo.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:52:19.000000');
INSERT INTO `product` VALUES (1996, 'Tượng gốm Crocus điêu khắc bằng tay', 2212750, 2212750, 100, 100, 0, 'Tượng gốm sứ bằng đá được điêu khắc thủ công với các chi tiết bằng men nghệ. Mỗi mảnh được làm riêng và độc đáo. Lò nung để đảm bảo độ bền. Cao khoảng 4 inch.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:52:21.000000');
INSERT INTO `product` VALUES (1997, 'In ảnh thiên nhiên Trillium mỹ thuật', 855250, 855250, 100, 100, 0, 'Bản in mỹ thuật lưu trữ của bức ảnh thiên nhiên trillium nguyên bản. In trên giấy cotton 100% với mực màu. Chống phai màu trong hơn 100 năm. Có sẵn ở kích thước 5x7 đến 16x20.', 'active', 'nghe_thuat_suu_tam', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:52:23.000000');
INSERT INTO `product` VALUES (1998, 'Xà phòng thủ công Bloodroot sữa dê', 307250, 307250, 100, 100, 0, 'Xà phòng sữa dê bổ dưỡng với hương thơm rễ cây và các tạp chất thực vật. Phương pháp xử lý lạnh bảo quản glycerin tự nhiên. Không chứa sunfat, paraben và màu nhân tạo. Thanh 4,5oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:52:26.000000');
INSERT INTO `product` VALUES (1999, 'Thanh gội đầu Solid Hepatica', 540000, 540000, 100, 100, 0, 'Thanh dầu gội rắn không chất thải với hỗn hợp thảo dược Hepatica. Thay thế 2-3 chai dầu gội dạng lỏng. Không chứa sunfat, phù hợp với mọi loại tóc. Kéo dài 60-80 lần giặt. Đi kèm trong bao bì có thể phân hủy.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:52:28.000000');
INSERT INTO `product` VALUES (2000, 'Tẩy tế bào chết toàn thân Sugar Mayapple', 299250, 299250, 100, 100, 0, 'Tẩy tế bào chết toàn thân bằng đường mayapple thủ công với dầu dừa. Nhẹ nhàng tẩy tế bào chết và dưỡng ẩm trong một bước. Được làm bằng đường mía hữu cơ và tinh dầu mayapple. bình 8oz.', 'active', 'tam_lam_dep', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:52:30.000000');
INSERT INTO `product` VALUES (2001, 'Tạp chí da Elderflower ràng buộc bằng tay', 1368000, 1368000, 100, 100, 0, 'Tạp chí đóng bìa tay với bìa da hoa cơm cháy và dây vải lanh được đóng bằng đường khâu Coptic. 200 trang giấy không chứa axit 90gsm. Nằm hoàn toàn bằng phẳng khi mở. Kích thước A5 (5,8\"x8,3\").', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:52:33.000000');
INSERT INTO `product` VALUES (2002, 'Thiệp cưới màu nước táo gai', 255750, 255750, 100, 100, 0, 'Thiệp cưới màu nước được thiết kế bằng tay với hình minh họa thực vật táo gai. In trên giấy bìa tái chế nặng 130lb. Trống rỗng bên trong. Kích thước A2 với phong bì kraft tái chế. Bộ 1, 5 hoặc 10.', 'active', 'giay_tiec', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:52:35.000000');
INSERT INTO `product` VALUES (2003, 'Câu đố bằng gỗ cây mâm xôi vẽ tay', 1135500, 1135500, 100, 100, 0, 'Trò chơi ghép hình bằng gỗ thủ công với thiết kế vẽ tay cây mận gai. Cắt bằng laze từ ván ép bạch dương 1/4\". Sơn không độc hại, an toàn cho trẻ em. 30 miếng. Độ tuổi từ 3 trở lên. Đi kèm trong túi bông có thể tái sử dụng.', 'active', 'do_choi_tro_choi', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:52:37.000000');
