INSERT INTO `product` VALUES (2005, 'Vòng cổ mặt dây chuyền đá mặt trăng Sloe thủ công', 1894500, 1894500, 100, 100, 0, 'Vòng cổ mặt dây chuyền thủ công tinh tế có đính đá mặt trăng sloe chính hãng bằng bạc sterling. Dây được bọc bằng tay, mỗi mảnh là duy nhất. Chiều dài dây chuyền 18 inch với móc khóa tôm hùm. Đi kèm trong một hộp quà tặng kraft.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:52:42.000000');
INSERT INTO `product` VALUES (2006, 'Tên tùy chỉnh Vòng cổ lấp đầy vàng Damson', 1894250, 1894250, 100, 100, 0, 'Vòng cổ tên Damson cá tính được đóng dấu thủ công trên đĩa dát vàng 14k. Chọn phông chữ và độ dài chuỗi (16\", 18\", 20\"). Món quà sinh nhật hoặc kỷ niệm hoàn hảo. Chống xỉn màu.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:52:45.000000');
INSERT INTO `product` VALUES (2007, 'Vòng cổ mặt dây chuyền quả hồng theo phong cách cổ điển', 2558250, 2558250, 100, 100, 0, 'Vòng cổ mặt dây chuyền bằng đồng hồng lấy cảm hứng từ cổ điển. Mở để chứa hai bức ảnh nhỏ. Bên ngoài được chạm khắc tinh xảo. Treo trên dây chuyền đồng thau 24 inch. Bao gồm túi nhung.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:52:48.000000');
INSERT INTO `product` VALUES (2008, 'Vòng tay tình bạn mộc qua dệt tay', 235750, 235750, 100, 100, 0, 'Vòng tay tình bạn mộc qua dệt thủ công được làm bằng sợi bông sáp cao cấp. Nút đóng trượt có thể điều chỉnh phù hợp với kích thước cổ tay 5\"-8\". Không thấm nước và bền. Có sẵn trong 12 kết hợp màu sắc.', 'active', 'trang_suc', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:52:51.000000');
