INSERT INTO `product` VALUES (2018, 'Vòng Hoa Trâu Khô', 888750, 888750, 100, 100, 0, 'Vòng hoa khô thủ công có các loại thực vật theo mùa từ quả trâu. Hoa bảo quản, bạch đàn và cỏ lau được xếp trên gốc nho. Đường kính 16 inch. Kéo dài 1-2 năm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, NULL, NULL, '2026-05-26 18:53:16.000000');
INSERT INTO `product` VALUES (2019, 'Kệ Gỗ Aurora Chạm Khắc Bằng Tay', 3487750, 3487750, 100, 99, 1, 'Kệ nổi bằng gỗ óc chó nguyên khối được chạm khắc thủ công với chi tiết cạnh cực quang. Bao gồm tất cả các phần cứng gắn kết. Chiều dài: 24 inch, Độ sâu: 6 inch. Hoàn thiện bằng dầu sáp ong an toàn thực phẩm.', 'active', 'nha_cua_cuoc_song', 'bd24206e-d42f-4736-9106-16dca8c687e9', NULL, 5, b'0', NULL, '9ae5e6ec-3d7b-452b-ac1a-ea01c1d05b31', '2026-07-09 15:28:40.000000', '2026-05-26 18:53:18.000000');
